/* Product Master 1.10.40 · Why not this one? reasons (HE) · _w19/learn_build · loaded on demand by the LB block */
window.__PM_LBW_he={v:"d0bdbd9d",q:{"0":{"0":{"0":"הקורס גדול בהרבה מ-5 שלבים: 38 שלבים, מהם 23 שלבי ליבה, ועוד פרקי ספרים כהעשרה.","1":"יש הרבה יותר מ-10: הליבה לבדה היא 23 שלבים, וכל שלב נגמר במבחן, לא בתרגיל סיכום.","3":"אין 100 שלבים שמחולקים לרבעונים. בקורס 38 שלבים, מהם 23 שלבי ליבה, ו-36 פרקי ספרים."},"1":{"0":"השלבים לא בנויים רק מסרטונים. בכל שלב יש תיאוריה, קייס סטאדי סיפורי ומבחן, כך שיש תרגול.","2":"המבחן הוא רק חלק אחד. כל שלב נפתח בתיאוריה ובקייס סטאדי לפני השאלות.","3":"התיאוריה אינטראקטיבית: לוחצים על מונחים, עוקבים אחרי הקייס של מיכל ועונים על מבחן."},"2":{"0":"Cagan כותב על צוותי מוצר; השלב מציג אותו כמחבר Inspired ו-Empowered, לא כמי שיצר שפת תכנות.","2":"השלב מציין את הרקע של Cagan ב-HP, Netscape ו-eBay ואת ספריו על Product Discovery. Facebook לא חלק מזה.","3":"Cagan עבד ב-HP, Netscape ו-eBay והקים את SVPG. הוא ידוע בזכות Inspired ו-Empowered, לא בזכות Windows."},"3":{"0":"Rachitsky, לשעבר PM ב-Airbnb, כותב על Retention, Growth ו-PMF, לא על עיצוב גרפי.","2":"בקורס, AI שייך ל-Karpathy. המיקוד של Rachitsky הוא Retention, Growth ו-Product-Market Fit.","3":"Rachitsky הוא לא מומחה פיננסים. הניוזלטר שלו עוסק ב-Retention, Growth ומנופי צמיחה."},"4":{"0":"זה הופך את העיקרון של Yang. לפיו, צוות ששחרר 10 פיצ׳רים שאף אחד לא משתמש בהם נכשל.","2":"Code over Design הוא לא העיקרון של Yang. הוא מדגיש Outcome over Output, Product Sense ו-First Principles.","3":"העיקרון של Yang עוסק במדידת השפעה, לא במהירות בכל מחיר. Outcome over Output שופט לפי תוצאות."},"5":{"0":"Karpathy הוא דמות מעולם ה-AI, ממייסדי OpenAI ולשעבר ראש ה-AI ב-Tesla, לא מחבר ספרי שיווק.","2":"Design Systems הם לא התחום של Karpathy. הוא מסביר מושגי AI: Software 2.0, LLMs ו-Tokenization.","3":"אג׳ייל ו-Scrum שייכים למובילים אחרים בקורס. Karpathy מלמד AI בצורה אינטואיטיבית."},"6":{"0":"הדרגות הן תארי מוצר, לא דרגות צבאיות. סיום 23 שלבי הליבה מעניק מנהל מוצר מקצוען.","2":"אין תואר דוקטור במערכת. הדרגות סמליות: סיום 23 שלבי הליבה מעניק מנהל מוצר מקצוען.","3":"המערכת כן מעניקה דרגות, מסטודנט לניהול מוצר ועד מנהל מוצר בכיר, כדי להראות התקדמות."},"7":{"0":"דילוג על התיאוריה מפספס את הבסיס שכל סעיף נשען עליו. גם טעויות במבחן מלמדות דרך ההסברים.","2":"העתקת תשובות מדלגת על הלמידה. אין ציון עובר, כך שהציון עצמו הוא לא העניין.","3":"מרתון של יום אחד מוביל לשכחה מהירה. שלב אחד ביום נותן זמן לעכל את החומר."},"8":{"0":"יש הבדל בפורמט: הקורס מוסיף קייסים, מבחנים עם משוב ומערכת התקדמות, למידה פעילה ולא סבילה.","2":"הקורס כולל גם פרקי ספרים כהעשרה. היתרון שלו הוא למידה פעילה, לא כיסוי צר יותר.","3":"הקורס מעמיק: 23 שלבי ליבה, ועוד חלקים מתקדמים ופרקי ספרים."},"9":{"0":"הם קשורים זה בזה: הבנת התחום היא מה שמאפשר ל-PM לתרגם צרכים אמיתיים לדרישות מוצר.","2":"PM לא צריך לתפעל כל מערכת בעצמו. הוא צריך להבין את ההקשר, התהליכים והמשתמשים.","3":"קידום הוא לא הסיבה. הכרת התחום היא מה שמאפשר לבנות מוצרים שבאמת פותרים בעיות."},"10":{"0":"המטרה היא לא בידור או ציון; אין ציון עובר. קייס הופך קריאה ללמידה פעילה.","2":"הקייס לא ממלא חורים בתיאוריה. הוא מראה איך התיאוריה מיושמת בפועל.","3":"זה לא שאין חלופה. הקורס בחר בקייס כי למידה פעילה מעמיקה את ההבנה."},"11":{"0":"לוחות זמנים הם ניהול פרויקטים. העץ מחבר בין מטרות עסקיות, צרכי משתמשים ופתרונות.","2":"הוא לא מחלק תקציבים. זו מפה ויזואלית ממטרות, דרך צרכי משתמשים, אל פתרונות.","3":"זה לא כלי להערכת עובדים. הוא נותן מבנה ל-Discovery מתמשך: מטרה, צרכים ופתרונות."},"12":{"0":"המערכת לא חוסמת. אפשר להתחיל מכל שלב ולחזור מתי שרוצים; הקצב הוא המלצה.","2":"אין דרישה של 24 שעות ואין לחץ זמן. העניין הוא זמן לעכל ולשמר את הידע.","3":"אין ציון עובר, ויותר שלבים ביום לא מורידים ציון. הקצב נועד ללמידה שנשארת."},"13":{"0":"Ries טוען ההפך: לבנות גרסה מינימלית וללמוד מהר, במקום לשכלל מוצר בחלל ריק.","2":"Ries בודק ביקוש עם MVP ומחזורים מהירים, לא בהוצאת כל התקציב על שיווק מראש.","3":"צוות גדול שבונה מהר זו לא למידה. הליבה של Ries היא Build-Measure-Learn עם מוצר מינימלי."},"14":{"0":"הם עבדו במקומות שונים: Cagan ב-HP, Netscape ו-eBay, Rachitsky ב-Airbnb, Karpathy ב-OpenAI וב-Tesla.","2":"הם לא שמים את הקוד במקום הראשון. החוט המשותף הוא הבנת הלקוח והבעיה.","3":"הם לא דוחים נתונים: Rachitsky ו-Yang נשענים על מדדים. מה שמאחד אותם הוא המיקוד בלקוח ובבעיה."}},"1":{"0":{"0":"יש חמישה מספנים, לא שלושה: מטה, ים, מודיעין, ציוד (מצ״ד) וכוח אדם.","2":"המספנים לא מחולקים לפי בסיסים. החמישה הם מטה, ים, מודיעין, ציוד וכוח אדם; בבסיסים יושבות יחידות.","3":"אין מספן לכל יחידה. יחידות כמו מפת״ח או יש״י נמצאות תחת חמשת המספנים."},"1":{"0":"הקומנדו הימי הוא שייטת 13, שבסיסה בעתלית. שייטת 3 היא שייטת ספינות הטילים.","2":"הצוללות הן שייטת 7. שייטת 3 מפעילה את קורבטות סער, הכוח המכה המרכזי של הזרוע.","3":"ההכשרה מתקיימת בבה״ד 600 בחיפה. שייטת 3 היא כוח המחץ של ספינות הטילים."},"2":{"0":"תחזוקת כלי שיט היא תפקיד המספנה. גס״י מסייר מהאוויר באמצעות כטב״מים.","2":"גיוס ומיון שייכים למספן כוח אדם. גס״י בונה תמונת מצב ימית מהאוויר.","3":"השלב מגדיר לגס״י משימה אווירית: סיור, תצפית והתרעה עם כטב״ם Heron 1, לא אספקה."},"3":{"0":"מפת״ח מפתחת תוכנה ומחשוב, לא תחמושת: השם הוא מרכז פיתוח תוכנה ומחשוב.","2":"מפת״ח היא לא מפקדה. היא מרכז פיתוח תוכנה ומחשוב, תחת מספן הציוד.","3":"זו לא מחלקת פרויקטים. מפת״ח הוא מרכז פיתוח תוכנה ומחשוב."},"4":{"0":"3 זה מעט מדי: למפת״ח 7 ענפים, מפיתוח תוכנה וסייבר ועד שו״ב.","1":"יש 7, לא 5: פיתוח תוכנה, סייבר, מערכות מידע, דיגיטל, אינטגרציות, תשתיות ושו״ב.","3":"יש 7 ענפים, לא 12. כל אחד מכסה תחום, מסייבר ועד אינטגרציות ושו״ב."},"5":{"0":"השלב מדגיש שהם שונים: מספן הוא חטיבת מטה, מספנה היא המתקן הפיזי לתחזוקה.","2":"זה לא עניין של גודל. מספן הוא חטיבה ארגונית; מספנה היא מתקן תחזוקה.","3":"שניהם קיימים היום. חמשת המספנים מנהלים את המטה, והמספנה פועלת ברציפות מאז 1948."},"6":{"0":"שייטת 3 היא שייטת ספינות הטילים. הצוללות שייכות לשייטת 7.","2":"שייטת 13 היא הקומנדו הימי, בעתלית. הצוללות הן שייטת 7, שבסיסה בחיפה.","3":"השלב מתאר רק את שייטות 3, 7 ו-13, והצוללות שייכות לשייטת 7."},"7":{"0":"אכיפת הסגר היא אחת ממשימות הזרוע, אבל השלב מציין שסער 6 נבנו במיוחד להגנה על אסדות הגז.","2":"סיור שגרתי מוטל בעיקר על פלגות הבט״ש והסירות שלהן. סער 6 נבנו בשביל אסדות הגז.","3":"הובלת כוחות וציוד היא תפקיד נחתות ה-LSV. סער 6 מגנות על אסדות הגז."},"8":{"0":"מפת״ח מפתחת תוכנה מבצעית לכל הפלטפורמות, לא רק מתחזקת ציוד פיזי.","2":"למיקום יש היגיון: פיתוח מערכות הוא בניין כוח, מו״פ ורכש, התחום של מספן הציוד.","3":"מפת״ח קשורה הדוק למבצעים: היא בונה מערכות לחימה ושו״ב לספינות ולצוללות."},"9":{"0":"התפקיד של המש״רם הוא לאחד את שלוש תמונות הזירה לתמונה אחת; את ההחלטות השלב מייחס למפקד הזרוע.","2":"תמיכה בתקשורת היא תפקיד גדוד גלים 397. המש״רם בונה תמונה ארצית אחת.","3":"המספנה מתחזקת כלי שיט, תחת מספן הציוד. המש״רם יושב ביש״י ומגבש את תמונת המצב."}},"2":{"0":{"0":"חדירה היא חיפוש PMF עם מעט משתמשים. ל-Velox כבר יש Retention של 94% וצמיחה של 15% בחודש.","2":"בגרות פירושה שוק רווי וצמיחה שמאטה. 15% בחודש זו צמיחה מהירה, ו-10K משתמשים זה מעט בשוק של $20B.","3":"דעיכה פירושה ביקוש שיורד. Velox מוסיפה משתמשים בקצב של 15% בחודש, ההפך מדעיכה."},"1":{"0":"מעבר לתשלום הוא מדד המרה אחר. Activation סופר נרשמים שהגיעו לרגע הערך הראשון, משלמים או לא.","2":"סקרי שביעות רצון מודדים תחושה. Activation מודד התנהגות: האם נרשם חדש באמת הגיע ל-Aha Moment.","3":"חזרה בחודש השני היא Retention. Activation קורה מוקדם יותר: הגעה לערך הראשון מיד אחרי ההרשמה."},"2":{"0":"התקציב הוא לא העיקר. הסרטון היה ניסוי מכוון: הוא בדק ביקוש בתוך ימים, לפני חודשים של פיתוח.","2":"הבאזז היה תוצר לוואי, לא המטרה. 70,000 ההרשמות לרשימת ההמתנה היו הוכחה שהבעיה אמיתית.","3":"זמינות הצוות לא הייתה הסיבה. Video MVP בודק את הנחת הביקוש לפני שמשקיעים בבנייה."},"3":{"0":"Innovators הם 2.5% שרודפים אחרי טכנולוגיה חדשה. ההצעה של Velox היא יתרון עסקי, מחיר נמוך מ-Asana.","2":"Early Majority רוצים פתרון מוכח ויציב עם המלצות. עם 10K משתמשים בשוק של $20B, Velox עוד לא שם.","3":"Laggards מאמצים רק כשאין ברירה. מי שעוזב את Asana המוכרת לכלי צעיר לוקח סיכון, ההפך מהם."},"4":{"0":"ל-Star יש נתח שוק גבוה. כאן הנתח נמוך, כך שהמוצר עוד לא הגיע למקום של מוביל השוק.","1":"Cash Cow מחזיקה נתח גבוה בשוק שהפסיק לצמוח. כאן השוק צומח והנתח נמוך, שני הצירים הפוכים.","3":"גם ל-Dog נתח נמוך, אבל בשוק שלא צומח. כאן השוק צומח, ולכן עדיין יש סיבה לשקול השקעה."},"5":{"0":"השלב לא קושר B2B2C למחיר. מה שמגדיר אותו הוא המסלול: נמכר לעסק, ומגיע דרכו לצרכן הסופי.","2":"שום דבר ב-B2B2C לא מבטל מכירות. Stripe ו-Twilio עדיין מוכרים לעסקים; ההבדל הוא מי משתמש בסוף.","3":"B2B2C דווקא מורכב יותר: צריך לרצות גם את העסק וגם את הצרכן הסופי, לא ממשק אחד בלבד."},"6":{"0":"Functional הוא אחת משלוש הדרישות מ-MVP: הוא חייב לבצע את הפעולה המרכזית ברמה בסיסית.","1":"Reliable הוא אחת משלוש הדרישות מ-MVP: צריך שאפשר יהיה לסמוך עליו בשימוש אמיתי.","3":"Usable הוא אחת משלוש הדרישות מ-MVP: המשתמש צריך להבין איך להשתמש בו בלי הדרכה מיוחדת."},"7":{"0":"Fit דורש שכל ה-Value Map יענה על ה-Customer Profile. Gains בלי Jobs משאיר את הצורך המרכזי בלי מענה.","2":"מחיר הוא רק Pain Reliever אחד. Fit עוסק במענה ל-Jobs, Pains ו-Gains של הלקוח, לא בניצחון על מתחרים במחיר.","3":"מספר נרשמים מודד שימוש, לא Fit. הקנבס בודק אם מה שהמוצר מציע עונה על ה-Jobs, Pains ו-Gains."},"8":{"0":"50 לקוחות לא אומרים מי הם. Innovators הם סוג של אנשים, חובבי טכנולוגיה, לא מספר לקוחות.","1":"Early Adopters מוגדרים לפי הגישה שלהם, לא לפי מספר. בלי גודל השוק וזהות הלקוחות אי אפשר למקם אותם.","2":"לקוחות פרגמטיים שמחכים להוכחה יכולים להיות בין ה-50, ויכולים שלא. המספר לבדו לא חושף את השלב."},"9":{"0":"ההבדל הוא בהיקף: מוצר פותר בעיה שלמה ויש לו ערך עצמאי, Feature הוא יכולת אחת בתוכו.","2":"ההבדל הוא לא בכמות הקוד. מוצר פותר בעיה שלמה לקהל מוגדר; Feature הוא יכולת אחת בתוכו.","3":"Feature חי בתוך מוצר ואין לו ערך עצמאי. דיווח על שוטרים הוא חלק מ-Waze, לא משהו שנמכר לבד."},"10":{"0":"דעיכה פירושה ביקוש שיורד בכלל השוק. כאן המוצר משגשג בקרב סטארטאפים, והפער הוא בקהל אחד.","2":"המוצר כבר עובד מצוין לסטארטאפים. הפער מול Enterprise מתאים ל-Chasm: הם רוצים Whole Product, לא רק טכנולוגיה טובה.","3":"השלב רואה ב-Enterprise את ה-Early Majority, שמגיעים אליו בחציית ה-Chasm עם Whole Product, כולל SSO ותמיכה."},"11":{"0":"נטישה לבדה לא מוכיחה כישלון. ב-Velox רק 5 מתוך 12 נשארו, אבל לא הפסיקו להשתמש: הסימן הראשון ל-PMF.","2":"השלב לא קובע רף של 80% Retention ל-MVP. מה שקובע הוא כמה מחוברים המשתמשים שנשארו.","3":"MVP חייב להיות שמיש: Functional, Reliable ו-Usable. הוא מינימלי בהיקף, לא מוצר שאי אפשר להשתמש בו."},"12":{"0":"Cash Cow דורשת השקעה מינימלית. הזרמת משאבים להחזרת צמיחת שיא נלחמת בהאטה הטבעית של השוק.","2":"בגרות היא לא כישלון. נתח גבוה בשוק יציב הוא Cash Cow שמייצרת הכנסה קבועה.","3":"שם חדש לא משנה את קצב הצמיחה של השוק. המהלך לפי BCG הוא לקצור את ההכנסה ולממן מוצרים חדשים."},"13":{"0":"חיסכון במחסן היה יתרון צדדי. העיקר היה לבדוק אם אנשים בכלל יקנו נעליים באונליין.","2":"השלב לא טוען שידני עדיף על אוטומציה. MVP ידני הוא ניסוי זול; אחרי שהביקוש הוכח, בונים את המערכת.","3":"מהירות הבנייה היא לא העניין, והשלב לא מבטיח בנייה ביום. העניין הוא לבדוק ביקוש אמיתי בהשקעה מינימלית."},"14":{"0":"שלושת העמודים חייבים להתקיים יחד. בלי Viable אין מודל עסקי שמצדיק את ההשקעה.","2":"המתחרים הם לא הבעיה. לא Viable פירושו שאין מודל עסקי שמצדיק את ההשקעה, עם מתחרים או בלי.","3":"Viable הוא לא העמוד היחיד. בלי Desirable אין ביקוש ובלי Feasible אי אפשר לבנות; שלושתם נדרשים."}},"3":{"0":{"0":"Roadmap לרבעון כבר בשבוע הראשון פירושו להחליט לפני שמכירים את המוצר, המשתמשים והצוות.","2":"לקפוץ על באג אחד הופך את השבוע הראשון לכיבוי שריפות. השבוע הזה נועד ללמוד לפני שפועלים.","3":"לסדר מחדש עדיפויות לפני שמבינים את המוצר והצוות זו החלטה בעיניים עצומות. השבוע הראשון נועד להיכרות."},"1":{"0":"ה-Roadmap הוא פרט עסקי שמגיע אחר כך. הפגישה הראשונה בונה את השותפות, הבסיס לכל השאר.","2":"באגים ולוחות זמנים הם פרטים תפעוליים. הפגישה הראשונה עם ה-Tech Lead נועדה להכיר זה את זה.","3":"להנחית מתודולוגיה חדשה בפגישה הראשונה פותח את השותפות בפקודות. קודם מכירים את הצוות ואת הדינמיקה שלו."},"2":{"0":"מחקר שוק ומתחרים מקבל רק 5%. אסטרטגיה, עם 17%, היא הנתח הגדול ביותר במחקר של McKinsey.","2":"תמחור ואריזה הם הנתח הקטן ביותר, 2% בלבד, גם אם הם יכולים להיות הדבר המשפיע ביותר.","3":"מעקב אחרי מדדים לוקח 8%, פחות ממחצית ה-17% שהולכים להגדרת אסטרטגיה."},"3":{"0":"השלב מדגיש שזו לא היררכיה אלא שתי עדשות על אותה עבודה. ההבדל הוא במיקוד, לא בשכר או בדרגה.","2":"פרויקט יכול להסתיים בזמן ובתקציב ואף אחד לא צריך אותו. PM קיים בשביל הערך, PjM בשביל הביצוע.","3":"PM עובד עם כל בעלי העניין: הנהלה, שיווק, מכירות ו-Customer Success. החלוקה היא מה מול איך, לא עם מי."},"4":{"0":"Thinker מתאים לשלב החדירה, כשמחפשים PMF. בצמיחה צריך מישהו שמחליט מהר ומבצע.","2":"Improver מתאים לבגרות: שיפור ואופטימיזציה של תהליכים קיימים. בצמיחה העדיפות היא ביצוע מהיר והובלת צוותים.","3":"Producer מתאים לשלב השימור, עם מיקוד באיכות ותחזוקה. מוצר בצמיחה צריך את הקצב של Builder."},"5":{"0":"שיווק, מכירות ותמיכה הם בעלי עניין שה-PM משרת. שלושת המעגלים של Eriksson הם Business, Technology ו-UX.","2":"עיצוב, פיתוח ובדיקות הם שלבי הבנייה. המעגלים של Eriksson הם Business, Technology ו-UX.","3":"אלה מצבי עבודה, לא המעגלים של Eriksson. דיאגרמת ה-Venn שלו מציבה את ה-PM בין Business, Technology ו-UX."},"6":{"0":"ההפך: PM חייב להשפיע כל הזמן, כי אף אחד לא כפוף לו והחלטות צריכות שותפים.","2":"בלי סמכות, PM לא יכול פשוט להחליט לבד. הוא צריך לשכנע מפתחים, מעצבים ובעלי עניין.","3":"אי אפשר להוביל לבד. הובלה בלי סמכות פירושה לסחוף את הצוות ובעלי העניין בעזרת נתונים ואמון."},"7":{"0":"שליטה צמודה בפרויקט היא העבודה של PjM. PM שמשקיע 60% בלו״ז ותקציב מזניח את ה-מה וה-למה.","2":"עמידה בתאריכים לא אומרת כלום על ערך. פרויקט יכול להסתיים בזמן ובתקציב ועדיין לא לתת דבר שמישהו צריך.","3":"זמן ותקציב הן שאלות של ביצוע. החלטות מוצר מתחילות מהערך למשתמש ולעסק."},"8":{"0":"להאשים את הפיתוח מפספס את תפקיד ה-PM: לוודא שהצוות בונה את הדבר הנכון בעזרת חזון ועדיפויות ברורים.","2":"תפקיד ה-PM להבין את הצורך, לא לחכות שלקוחות יבקשו. פיצ׳ר שאף אחד לא ביקש מצביע על עדיפויות לא ברורות.","3":"לראות בבזבוז דבר בלתי נמנע מדלג על הלקח. חזון ברור וניהול Backlog הם בדיוק מה שמונע אותו."},"9":{"0":"הגדרת החזון והכיוון האסטרטגי היא ליבת התפקיד: ה-PM הוא הבעלים של ה-מה וה-למה.","2":"ניתוח נתוני שימוש הוא חלק מהעבודה: ה-PM מחליט על בסיס נתונים ומזהה דפוסי התנהגות.","3":"תקשורת עם בעלי עניין היא מרכזית: ה-PM הוא הצומת העמוס ביותר במפת הארגון ומיישר קו בין המחלקות."},"10":{"0":"השעות הן לא הבעיה. הצוות שחרר הרבה, אבל מדד כמה בנה ולא מה השתנה אצל המשתמשים.","2":"עוד Output לא יעזור: 15 פיצ׳רים כבר לא הזיזו דבר. הפתרון הוא למדוד Outcome, לא לשחרר יותר.","3":"התקציב לא היה החסר. הפיצ׳רים יצאו אבל לא פתרו בעיה אמיתית, הדפוס הקלאסי של Feature Team."},"11":{"0":"ביצוע עיוור הוא הדפוס של Feature Team. גם בקשה דחופה מה-CEO מצדיקה לבדוק איזו בעיה היא פותרת.","2":"PM בצוות מועצם גם לא מסרב על הסף. הוא מבין את הבעיה שמאחורי הבקשה ומתקף את ההנחות.","3":"להעביר הלאה מדלג על העבודה של ה-PM עצמו: להחזיק ב-מה וב-למה ולבדוק את הבעיה לפני שבונים."},"12":{"0":"זה בדיוק הרצף ש-Cagan דוחה. השלישייה עובדת יחד מהרגע הראשון, לא בתורות.","2":"להחליט לבד ולעדכן את האחרים שובר את השלישייה. כל אחד אחראי לסיכון אחר: ערך, שימושיות וישימות.","3":"אף אחד לא מוביל לבד. ה-PM אחראי לערך ולכדאיות, ה-Designer לשימושיות וה-Tech Lead לישימות, יחד."},"13":{"0":"השלב אומר שטבעי ש-PM בארגון קטן ינהל גם פרויקטים. הבעיה מתחילה רק כשזה משתלט על הזמן.","2":"השלב לא קובע סף של גודל חברה. הסימן הוא זמן: כשתיאום דוחק החוצה אסטרטגיה ו-Discovery.","3":"שילוב התפקידים לא תמיד עדיף. כשלו״ז אוכל את רוב הזמן, האסטרטגיה וה-Discovery נפגעים."},"14":{"0":"הנקודה של Yang לא קשורה לקוד. PM לא צריך לכתוב קוד; הוא צריך להחזיק בבעיה ובתוצאה.","2":"זה לא עניין של מאמץ או מסמכים. הבעיה היא התפיסה: לחכות להוראות במקום להחזיק בבעיה.","3":"בעלות על המוצר לא אומרת להתעלם מהנהלה ומלקוחות. היא אומרת להוביל מתוך הבנה, לא מתוך ציות."}},"4":{"0":{"0":"משתמשים מתארים פתרונות, לא בעיות. להכניס כפתור CSV בלי לשאול למה עלול לבנות את הפתרון הלא נכון.","2":"לסגור את הבקשה עוצר את הלמידה. הראיון הוא הזדמנות למצוא את הבעיה שמאחורי הבקשה.","3":"הבטחה לבנות לפני שמבינים את הצורך מתחייבת לפתרון שאולי לא פותר את הבעיה האמיתית."},"1":{"0":"שרה מייצגת עסקאות גדולות, אבל אלכס הוא ה-Decision Maker: אם הוא מאמץ את הכלי, כל הצוות שלו בא אחריו.","1":"מייק עובד בכלי כל יום אבל לא מחליט בשביל הצוות. אלכס כן, והוא גם מחבר בין הצרכים של שרה ושל מייק.","3":"משאבים שווים לכל פרסונה פירושם פוקוס על אף אחת. פרסונות נועדו לבחירות חדות, לא לשרת את כולם בבת אחת."},"2":{"0":"1-2 ראיונות לא מראים דפוס: דפוס הוא משהו שחוזר. החזרה מתחילה בדרך כלל רק סביב 5 ראיונות.","2":"ראיונות עומק לא נועדו למובהקות סטטיסטית; זה התפקיד של מחקר כמותני עם מדגם גדול.","3":"אחרי 5-8 ראיונות מגיעים לרוויה: ראיונות נוספים כמעט לא מגלים דבר חדש, ומעבר לזה זה בזבוז זמן בשלב הזה."},"3":{"0":"סקר מאמת דפוסים, אבל כמעט לא חושף בעיות שמשתמשים לא מודעים להן. בשלב הגילוי, תצפיות קודמות.","1":"תצפיות מצוינות לגילוי, אבל מדגם קטן לא מראה כמה הבעיה גדולה. בשביל זה מגיעים הסקרים.","3":"הן עונות על שאלות שונות: תצפיות חושפות למה ואיך, סקרים מודדים כמה. התוצאות לא מחליפות זו את זו."},"4":{"0":"Awareness עוסק בהבאת אנשים. המשתמשים האלה כבר נרשמו, ו-55% מהם נושרים אחרי ההרשמה, לפני שהגיעו לערך.","2":"ה-Retention עומד על 94%, כך שמי שמגיע לערך נשאר. הדליפה קורית מוקדם יותר, ב-Onboarding.","3":"Advocacy מגיע אחרי שמשתמשים מרוצים. השבר מוקדם יותר: 55% מהנרשמים לא מגיעים לרגע הערך."},"5":{"0":"שאלה על עתיד היפותטי מזמינה כן מנומס. The Mom Test שואל במקום זה על התנהגות ספציפית בעבר.","2":"מצגת הופכת את הראיון למכירה. אנשים מחמיאים למה שמראים להם; התנהגות העבר היא שחושפת ביקוש.","3":"שאלות סגורות על רעיון עדיין אוספות דעות. The Mom Test מחפש עובדות: מה אנשים עשו בפועל."},"6":{"0":"רשימת משימות לספרינט היא Backlog. JTBD עוסק במשתמשים: העבודה שבשבילה הם שוכרים מוצר.","2":"זה תיאור של ניהול פרויקטים. JTBD היא תיאוריה על הסיבה שאנשים משתמשים במוצרים, לא על חלוקת עבודה בצוות.","3":"ל-JTBD אין קשר לביצועי עובדים. הוא מסביר את המוטיבציה שמאחורי השימוש של לקוחות במוצר."},"7":{"0":"מספרים קודם פירושם למדוד לפני שיודעים מה למדוד. מחקר איכותני קודם חושף את הבעיה עצמה.","2":"הסדר חשוב: הגילוי עונה מה הבעיה, ורק אז האימות יכול למדוד כמה היא גדולה.","3":"כל אחד עונה על שאלה אחרת, למה מול כמה. בלי אחד מהם נשארת לא ידועה הבעיה עצמה או הגודל שלה."},"8":{"0":"מספר הבקשות לא הופך את הפתרון לנכון. לקוחות מתארים פתרונות, ולצורך שמאחוריהם אולי יש פתרון טוב יותר.","2":"לעולם לא להקשיב זה מוגזם. לקוחות הם מקור הצרכים; העבודה היא לחפור לבעיה שמאחורי הבקשה.","3":"קלות הפיתוח לא מוכיחה ערך. גם פיצ׳ר של שבוע הוא בזבוז אם הוא לא עונה על הצורך האמיתי."},"9":{"0":"גם תצפית דורשת תכנון. היתרון שלה הוא במה שהיא חושפת: התנהגות שמשתמשים לא שמים לב אליה אצל עצמם.","2":"ראיון לוכד את מה שאנשים אומרים, ואנשים לא תמיד מדווחים על עצמם בדיוק. תצפית סוגרת את הפער הזה.","3":"המהירות היא לא היתרון. תצפית מראה את הפער בין מה שאנשים אומרים למה שהם עושים בפועל."},"10":{"0":"זה לא שקר אלא הטיה קוגניטיבית: אנשים מדווחים לא מדויק על עצמם. ראיונות נשארים שימושיים בשילוב תצפית.","2":"שום דבר לא מרמז שההנחיות השתנו. הפער בין אמירה לעשייה הוא דפוס נפוץ וטבעי.","3":"לבטל את התצפית כמקרה חריג מפספס את הלקח: מה שאנשים אומרים שהם עושים שונה לעתים קרובות ממה שהם עושים."},"11":{"0":"הנתונים הם לא המגבלה. הכלל קיים בשביל פוקוס: עם יותר מדי פרסונות לא משרתים אף אחד היטב.","2":"העלות היא לא הסיבה. עשר פרסונות מדללות את הפוקוס, וההחלטות על המוצר מפסיקות להיות חדות.","3":"המגבלה לא קשורה למקום על הלוח. היא נועדה לשמור על פוקוס בסגמנטים החשובים ביותר."},"12":{"0":"גרפים יפים הם עדיין פתרון. 5 Whys חופר מתחת לדשבורד אל הצורך: לדעת מה קורה.","2":"זו הכללה, לא צורך. 5 Whys שואל למה המשתמש הזה רוצה את הנתונים, והתשובה היא visibility.","3":"לקבל את הבקשה כפשוטה מדלג על 5 Whys. דשבורד הוא פתרון; התראות חכמות או עדכון יומי אולי ישרתו את הצורך טוב יותר."},"13":{"0":"המהירות היא לא הסיכון המרכזי. המחיר הגדול הוא לבנות מהר וטוב משהו שאף אחד לא צריך.","2":"You are not the user: גם ל-PM מנוסה יש הטיות קוגניטיביות. אינטואיציה לבדה יכולה לפספס את הבעיה האמיתית.","3":"הסיכון הוא לא המראה. פונקציונליות נכונה לא שווה דבר אם הפיצ׳ר פותר בעיה שלא קיימת."},"14":{"0":"היא לא זולה יותר; היא דורשת ללכת למקום שבו העבודה קורית. הערך שלה הוא לראות אילוצים וכלים אמיתיים.","2":"Contextual Inquiry מתאימה לכל מוצר, גם תוכנה. Go to the Gemba פירושו המקום שבו העבודה קורית.","3":"מספר המשתתפים הוא לא העניין. היא חושפת את הסביבה, הכלים וההרגלים שראיון רגיל מפספס."}},"5":{"0":{"0":"נתוני ה-Win/Loss מצביעים למקום אחר: ההפסדים באים מצוותי פיתוח שאומרים שהם מעדיפים את ה-UI של Linear, לא את המחיר.","2":"Velox מפסידה לא בגלל פיצ׳ר חסר אלא בגלל חוויה: מהירות, קיצורי מקלדת והתחושה של הממשק.","3":"ראיונות ה-Win/Loss מצביעים על המוצר עצמו: מפתחים מעדיפים את ה-UI של Linear. מודעות לא מסבירה הפסד בעסקאות ראש בראש."},"1":{"0":"SOM הוא מה שריאלי לתפוס ב-2-3 שנים בהינתן תחרות ומשאבים. שום תקציב שיווק לא הופך אותו לזמין מחר.","2":"כל השוק העולמי הוא TAM, כ-$20B אצל Velox. SOM הוא הפלח הצר: סטארטאפים בשלבי Series A-C בארה״ב.","3":"SOM הוא המספר שנכנס לתחזיות העסקיות. משקיעים חושדים דווקא ב-TAM ענק בלי SAM ו-SOM ריאליים."},"2":{"0":"לרצות הכל זה לא פוזישנינג. פוזישנינג בוחר את מי משרתים ובאיזה ציר מנצחים; לכסות הכל מטשטש את זה.","2":"להתחרות על הכי זול זה מרוץ לתחתית. הפוזישנינג צריך לשבת על ערך: פשוט, מהיר ו-Remote-first.","3":"שונה מכולם לא אומר שום דבר ספציפי. פוזישנינג מגדיר את הקהל, את הצורך ואת המתחרה שמולו מנצחים."},"3":{"0":"חדירת שוק פירושה למכור יותר לאותו שוק, סטארטאפים. Enterprise הוא שוק חדש עבור Velox.","2":"Velox לא בונה מוצר חדש. היא מוסיפה SSO, הרשאות ו-Audit Logs למוצר הקיים כדי להגיע ל-Enterprise.","3":"גיוון הוא מוצר חדש בשוק חדש, כמו עוזר AI. Enterprise Readiness נשען על המוצר הקיים."},"4":{"0":"לרדוף אחרי הכל פירושו להילחם בענקים במגרש שלהם. ClickUp מנסה לעשות הכל וסובלת מבעיות ביצועים.","2":"שחקנים גדולים לא הופכים נישה לחסרת סיכוי. פוקוס מאפשר לנצח בנישה, כמו ש-Linear מנצחת בצוותי פיתוח.","3":"אין צורך לברוח מהקטגוריה. ל-Velox יש נישה, צוותים מבוזרים, שבה היא יכולה להיות הטובה ביותר."},"5":{"0":"אלה מדדים פיננסיים של חברה אחת. Porter מסתכל על הענף: מתחרים, נכנסים חדשים, תחליפים, ספקים וקונים.","2":"אלה שלבי פיתוח מוצר. חמשת הכוחות מנתחים את הלחץ התחרותי על הרווחיות של ענף שלם.","3":"אלה קבוצות האימוץ של Rogers. חמשת הכוחות של Porter מתארים תחרות בענף, לא סוגי לקוחות."},"6":{"0":"Bottom-up סופר לקוחות פוטנציאליים, לא נוכחיים. הכפלת הלקוחות המשלמים היום נותנת הכנסה, לא גודל שוק.","2":"אף שיטה לא יוצאת מיעדי החברה או מאנשי המכירות. TAM מודד את השוק, לא את התחזית הפנימית.","3":"ראיונות וסקרים הם שיטות מחקר. Top-down יוצא מדוחות שוק; Bottom-up סופר לקוחות פוטנציאליים כפול מחיר."},"7":{"0":"Strengths הוא ה-S ב-SWOT: החוזקות הפנימיות שנמצאות בשליטת הארגון.","1":"Weaknesses הוא ה-W ב-SWOT: חולשות פנימיות, כמו ה-DX של Velox שחלש מזה של Linear.","3":"Threats הוא ה-T ב-SWOT: איומים חיצוניים מהסביבה העסקית, שאינם בשליטת הארגון."},"8":{"0":"$50B גבוה בהרבה מה-$1B+ שמשקיעים מחפשים. הבעיה הפוכה: הגודל לא אומר כלום על מה שאפשר לזכות בו.","2":"משקיעים מנוסים רואים ב-TAM ענק בלי SAM ו-SOM ריאליים דגל אדום, לא סיבה להשקיע.","3":"TAM עדיין רלוונטי: הוא מודד את גודל ההזדמנות. צריך רק לצמצם אותו ל-SAM ול-SOM."},"9":{"0":"העתקה עיוורת היא טעות נפוצה. קודם בודקים אם זה צורך אמיתי של הלקוחות שלכם ואם זה מתאים לחזון.","2":"התעלמות מפספסת אות: הלקוחות מבקשים את זה. המהלך הוא להבין למה, לא להסתכל הצידה.","3":"הורדת מחיר לא עונה על הצורך, ותחרות על מחיר היא מרוץ לתחתית. קודם מבינים מה הלקוחות רוצים."},"10":{"0":"Cost Leadership פירושו להיות הזולים ביותר, כמו Walmart או Ryanair. בחירה בנישה אחת היא אסטרטגיה אחרת.","1":"Differentiation בולטת בשוק הרחב, כמו Apple. הצטמצמות לנישה אחת היא Focus.","3":"Stuck in the Middle הוא היעדר בחירה. להתמקד רק בצוותי פיתוח היא בחירה אסטרטגית ברורה."},"11":{"0":"עלות ליחידה שיורדת עם הגודל היא Economies of Scale, כמו AWS. Network Effects עוסק בערך שעולה עם המשתמשים.","2":"מותג הוא חפיר נפרד, כמו הזהות של Apple. Network Effects גדל עם מספר המשתמשים, כמו WhatsApp.","3":"עלויות מעבר הן חפיר נפרד, כמו Salesforce. Network Effects פירושו שיותר משתמשים הופכים את המוצר לשווה יותר."},"12":{"0":"Cirque du Soleil לא ניצחה כי הייתה זולה. היא הוציאה את החיות, הוסיפה סיפור ומוזיקה ופנתה לקהל חדש.","1":"Red Ocean הוא מאבק על שוק קיים. Cirque du Soleil יצאה מהמאבק הזה ויצרה קטגוריה חדשה.","3":"היא לא רק בלטה בין הקרקסים; היא יצרה קטגוריה שלמה בלי מתחרים ישירים."},"13":{"0":"נישה קטנה היא אסטרטגיית Focus, בחירה לגיטימית. Stuck in the Middle הוא כישלון לבחור אסטרטגיה בכלל.","2":"המלכודת של Porter לא עוסקת במעבר מ-B2C ל-B2B. היא היעדר יתרון ברור: לא הזולה, לא המיוחדת, לא הממוקדת.","3":"חיקוי מובילים הוא טעות אחרת. Stuck in the Middle פירושו לא לבחור באף אחת משלוש האסטרטגיות."},"14":{"0":"התקציב לא מגדיר בידול. המבחן הוא אם לקוחות ישלמו עליו יותר ואם למתחרים קשה להעתיק אותו.","2":"בידול יכול להיות חוויה: Linear מנצחת על מהירות ו-UX. מה שקובע הוא שהלקוח מוכן לשלם עליו.","3":"רמת המחיר היא לא המבחן. בידול הוא מה שהלקוח מעריך מספיק כדי לשלם עליו, ושקשה למתחרים להעתיק."}},"6":{"0":{"0":"מובייל יכול לחכות רבעון. ויתור על Activation משאיר הפסד של $500K בשנה שפוגע בכל משתמש חדש.","1":"התראות הן שיפור, לא משנות משחק. Enterprise מביא $250K+ מיד ופותח שוק חדש.","3":"אף אחד מהשניים לא מזיז הכי הרבה: מובייל יכול לחכות רבעון והתראות הן ליטוש. הכסף נמצא ב-Enterprise וב-Activation."},"1":{"0":"עוד פיצ׳רים לא מזהה את החסם האמיתי. Retention של 94% מוכיח שהמוצר עובד; רוב הנרשמים פשוט לא מגיעים אליו.","2":"להאשים מתחרים חזקים זו התחמקות מהאתגר. האבחנה צריכה לומר מה חוסם את הצמיחה: Activation של 45%.","3":"עוד נרשמים יזרמו לאותה דליפה: 55% לא מגיעים לערך. החסם הוא Activation, לא תנועה."},"2":{"0":"לעשות הכל לאט יותר זה עדיין לא לבחור. פוקוס פירושו לוותר על דברים, כמו מובייל ברבעון הזה.","2":"להעתיק מתחרים זו תגובה, לא בחירה. פוקוס פירושו לבחור במה מצטיינים ולוותר על השאר.","3":"להקשיב רק ללקוחות גדולים זו הטיה, לא בחירה אסטרטגית. פוקוס הוא ויתור על טוב לטובת מצוין."},"3":{"0":"מקדם מעל 1 פירושו שכל משתמש מביא יותר ממשתמש חדש אחד: צמיחה שמזינה את עצמה, לא צמיחה איטית.","2":"מעל 1, הצמיחה האורגנית מזינה את עצמה בלי להיות תלויה בשיווק בתשלום.","3":"1.2 מעל הרף של 1, שמסמן צמיחה שמזינה את עצמה. השלב מונה את זה כסימן חזק ל-PMF."},"4":{"0":"Sean Ellis Test לא מודד תשלום. הוא שואל כמה המשתמשים יתאכזבו אם המוצר ייסגר.","2":"מספר נרשמים לא אומר כלום על צורך. המבחן סופר כמה יהיו מאוד מאוכזבים בלי המוצר.","3":"רווחיות היא לא המבחן. Sean Ellis מודד היקשרות: 40%+ שיהיו מאוד מאוכזבים אם המוצר ייסגר."},"5":{"0":"Rumelt מפריד ביניהם: להגיע ל-60% Activation זה יעד, ולהתמקד ב-Onboarding זו אסטרטגיה, ה-איך.","2":"ההבדל הוא לא משך הזמן. יעד הוא תוצאה רצויה; אסטרטגיה היא הדרך: אבחנה, מדיניות ופעולות.","3":"ההבחנה של Rumelt לא עוסקת בקהל. יעד אומר מה, אסטרטגיה אומרת איך, וזה נוגע לכל הארגון."},"6":{"0":"Desirable, Feasible ו-Viable הם שלושת עמודי המוצר, לא ה-DHM של Biddle.","1":"זה לא הפירוש של DHM. אצל Biddle האותיות הן Delight, Hard to Copy ו-Margin-enhancing.","3":"Design, Handoff, Monitoring מתאר תהליך עבודה. ה-DHM של Biddle בוחן יוזמות: Delight, Hard to Copy, Margin-enhancing."},"7":{"0":"ההבחנה של Cagan לא עוסקת בגודל או בבכירות. היא עוסקת במה שהצוות מקבל: רשימת פיצ׳רים או בעיה לפתור.","2":"ב-Empowered Teams יש PM; ה-Product Trio מוביל את הגילוי יחד. ההבדל הוא בעיה מול רשימת פיצ׳רים.","3":"המתודולוגיה היא לא העניין. Feature Team יכול לעבוד בספרינטים של שבועיים ועדיין רק לבצע רשימת פיצ׳רים."},"8":{"0":"עוד פיצ׳רים רק יחמירו. ה-KR סופר Output, והשאלה היא מה השתנה אצל המשתמשים.","2":"זה נראה מדיד, אבל סופר פיצ׳רים ולא תוצאות. ו-לשפר את המוצר מעורפל מכדי לכוון מישהו.","3":"עוד KRs לא יתקנו. הבעיה היא בסוג: מדדי Output במקום Outcome, תחת Objective מעורפל."},"9":{"0":"חזון ותקציב הם לא אסטרטגיה. ה-Kernel של Rumelt דורש אבחנה, מדיניות מנחה ופעולות קוהרנטיות.","2":"רשימת יעדים ו-KPIs היא יעדים שמתחפשים לאסטרטגיה. היא אומרת מה רוצים, לא איך מגיעים.","3":"להיות הכי טובים בהכל זו הימנעות מבחירה. כשהכל בעדיפות עליונה, שום דבר לא בעדיפות."},"10":{"0":"מפתחים לא בוחרים ב-Linear בגלל מחיר אלא בגלל DX. הורדת מחיר לא פותרת את זה.","2":"לרדוף אחרי מחיר ובידול יחד זו מלכודת Stuck in the Middle: נכשלים בשניהם.","3":"להעתיק את Linear פירושו להילחם במגרש החזק שלה, DX. היתרון של Velox הוא בנישה שלה: צוותים מבוזרים."},"11":{"0":"אותו קהל ואותם פיצ׳רים במחיר נמוך זה Red Ocean: מאבק על שוק קיים.","2":"לחכות שמתחרים ייכשלו זו לא אסטרטגיה. Blue Ocean פירושו ליצור שוק חדש בעצמכם.","3":"להוסיף הכל זה ההפך מ-Blue Ocean, ששואל גם מה לבטל ומה לצמצם, לא רק מה להוסיף."},"12":{"0":"Economies of Scale מורידים עלות ליחידה. כאן מה שגדל הוא הערך לכל משתמש כשחברי צוות מצטרפים.","1":"מותג יוצר אמון והעדפה, אבל משתמשים שמביאים עמיתים כי הערך גדל זה Network Effects.","3":"עלויות מעבר מונעות עזיבה. הסימן כאן שונה: ערך שגדל עם כל חבר צוות חדש."},"13":{"0":"משקיעים מנוסים לא מתלהבים מ-TAM לבדו; בלי SAM ו-SOM הוא מעיד על חוסר הבנת השוק.","2":"משקיעים כן מתעניינים בגודל השוק, כל עוד הוא ריאלי: SOM מראה כמה אפשר באמת לתפוס.","3":"SAM ו-SOM חשובים גם לסטארטאפים: SOM מראה כמה ריאלי לתפוס עם המשאבים הקיימים."},"14":{"0":"למהר להעתיק זו תגובה רגשית. קודם בודקים אם הלקוחות שלכם צריכים את זה ואם זה מתאים לאסטרטגיה.","2":"לא כל מהלך של מתחרה הוא איום ישיר. תגובה אסטרטגית שואלת מה הלקוחות שלכם צריכים.","3":"להסתכל על מתחרים זה חלק מהעבודה; הטעות היא להעתיק בעיוורון. מסתכלים, ואז מחליטים לפי האסטרטגיה."},"15":{"0":"רשימת פיצ׳רים היא Backlog, לא חזון. חזון מתאר את הבעיה ואת המצב העתידי שהמוצר שואף אליו.","1":"יעד הכנסות כמו $10M הוא תוצאה שמגיעה אם החזון מתממש, לא החזון עצמו.","3":"ארכיטקטורה היא איך בונים, ומשתמשים לא קונים ארכיטקטורה. חזון מתחיל מהבעיה האנושית."},"16":{"0":"לחכות להנחיות זו ההתנהגות של Feature Team. צוות מועצם מחזיק בבעיה ומציע את הכיוון הבא.","1":"השקעה שכבר נעשתה לא הופכת רעיון כושל לעובד. להמשיך רק מבזבז עוד על משהו שהוכח כלא עובד.","3":"הסתרת כישלון הורגת את הלמידה. המבחן של Cagan הפוך: לומר בגלוי בדקנו וזה לא עובד."},"17":{"0":"Discovery לא מסתיים קודם; זה Waterfall בתחפושת. המסלולים רצים באותו זמן, בפער של 1-2 ספרינטים.","2":"לבנות קודם ולבדוק אחר כך זה בדיוק מה ש-Discovery מונע: הוא מתקף רעיונות לפני ש-Delivery בונה.","3":"המסלולים לא מתחלפים; הם רצים באותו שבוע, כש-Discovery עובד 1-2 ספרינטים קדימה."},"18":{"0":"לספור פיצ׳רים ששוחררו זה Output. צוות ששחרר 10 פיצ׳רים שאף אחד לא משתמש בהם נכשל.","2":"שלמות לפני שחרור היא לא העיקרון. Outcome over Output עוסק במדידת השפעה, לא בליטוש.","3":"איכות קוד מול מהירות היא Trade-off אחר. העיקרון עוסק במדידה האם הבעיה נפתרה."},"19":{"0":"רווח מוקדם לבדו לא מוכיח התאמה. Rachitsky מחפש סימנים כמו המלצות מפה לאוזן שאיש לא ביקש.","1":"מספר נרשמים לא מראה צורך. המלצות בלי בקשה מראות שהמוצר באמת פותר בעיה.","3":"ציון NPS לבדו לא מוכיח התאמה. המלצות שאיש לא ביקש הן סימן חזק יותר, לפי Rachitsky."}},"7":{"0":{"1":"240 מכפיל רק Reach ב-Impact ובדרך גם טועה בחשבון, ומדלג על Confidence ועל החלוקה ב-Effort.","2":"Confidence מכפילים, לא מחלקים: הוא מקטין את הציון לפי מידת הוודאות, ולכן 200 לא מתקבל.","3":"800 שוכח לחלק ב-Effort. בלי החלוקה, פיצ׳ר יקר ופיצ׳ר זול נראים אותו דבר."},"1":{"0":"לחכות לסוף הרבעון פירושו לשלם את ההאטה של 30% כל הרבעון: כ-3.6 שבועות אבודים, יותר מ-2 שבועות התיקון.","2":"המוצר עובד, אבל כל פיצ׳ר לוקח 30% יותר זמן. חוב שמאט את הצוות הוא עלות עסקית, לא משימה לזמן פנוי.","3":"חוב שמאט כל פיצ׳ר מעכב את כל ה-Roadmap. השלב מציג אותו כבעיה עסקית שה-PM צריך לתעדף."},"2":{"0":"Must-have הוא דבר שבלעדיו משתמשים עוזבים. אף אחד לא עוזב מוצר כי אין בו Dark Mode.","1":"Performance עולה ככל שמשקיעים יותר, כמו מהירות. Dark Mode הוא כן או לא, ולא משפר ליניארית.","3":"Kano בנוי בדיוק לזה: מסווגים לפי מה שרוב המשתמשים מרגישים, גם כשיש הבדלים אישיים."},"3":{"0":"לבנות מיד מדלג על ה-Trade-off: $100K עכשיו באים על חשבון SSO, שמכניס $150K+ בכל שבוע.","2":"התעלמות מה-CEO סוגרת את השיחה. RICE הוא נקודת פתיחה לדיון, לא פסק דין להסתתר מאחוריו.","3":"דחייה לרבעון הבא בלי דיון היא עדיין התחייבות עיוורת, בלי Trade-off שה-CEO יכול לשקול."},"4":{"0":"זה הפוך: RICE מחשב ציון מספרי לפי נוסחה, ו-MoSCoW ממיין דרישות לארבע קטגוריות.","2":"הן עונות על צרכים שונים: RICE להשוואה מדויקת, MoSCoW ליישור קו עם Stakeholders בשפה שכולם מבינים.","3":"השלב בוחר מודל לפי המצב, לא לפי גודל החברה: RICE לתעדוף רבעוני, MoSCoW ליישור קו עם Stakeholders."},"5":{"0":"פירוט ברמת User Story שייך ל-Now. Later רחוק חצי שנה ויותר, ושם אי הוודאות גבוהה מדי לתאריכים מדויקים.","2":"הפירוט יורד ככל שהאופק מתרחק: Now מפורט, Next בינוני, Later כללי. אותו פירוט היה מעמיד פנים של ודאות.","3":"Later הוא חלק מהמבנה: הוא מחזיק נושאים ברמה גבוהה לחצי שנה ויותר, יותר כוונה מהבטחה."},"6":{"0":"ב-ICE מכפילים את שלושת המרכיבים, לא מחברים: 8+6+4 נותן 18, אבל 8×6×4 נותן 192.","1":"Ease הוא אחד משלושת הגורמים ב-ICE. בלעדיו נשאר 8×6=48, והציון מתעלם מכמה קל לבנות את הפיצ׳ר.","3":"אין ב-ICE שלב של חלוקה ב-2. Ease נמוך כבר מוריד את הציון דרך ההכפלה עצמה."},"7":{"0":"זו עלות הפיתוח. Cost of Delay מודד כמה העסק מפסיד על כל חודש שהפיצ׳ר מתעכב.","2":"זה מדד של מהירות הצוות. Cost of Delay עוסק בהפסד העסקי מההמתנה, לא בקצב העבודה.","3":"עלות תחזוקה שייכת לפיצ׳ר שכבר קיים. Cost of Delay מתמחר את ההפסד מכך שהפיצ׳ר עוד לא קיים."},"8":{"0":"ויתור בגלל בכירות מחליף את התעדוף בקול החזק ביותר, בדיוק התחרות שמודלי התעדוף נועדו למנוע.","2":"התעלמות מבעל עניין בכיר שוברת אמון. השלב דורש שקיפות: להראות את הציונים ולהסביר את הסדר.","3":"להכניס לספרינט בלי להזיז דבר מעמיס עליו. כל כן הוא לא שקט למשהו אחר, גם כשלא אומרים את זה."},"9":{"0":"הם שונים באופק ובפירוט: ה-Roadmap מראה לאן ולמה, וה-Backlog מחזיק את המשימות של היום.","2":"ה-Roadmap הוא כלי תקשורת לקהלים רבים: הנהלה, צוות ולקוחות, וכל אחד מקבל תצוגה משלו.","3":"הכיוון הפוך: ה-Roadmap מתרגם אסטרטגיה לתוכנית, והמשימות המפורטות ב-Backlog נגזרות ממנו."},"10":{"0":"Reach גבוה לבדו לא מכריע. Confidence של 50% חוצה את הציון, סימן שהראיות עדיין דלות.","2":"Confidence הוא מכפיל ב-RICE: 50% חוצה את הציון, כך שהוא משנה את התוצאה ישירות.","3":"Confidence נמוך מוריד את הציון, הוא לא מוחק את הפיצ׳ר. הצעד הנכון הוא לאסוף נתונים ולהעלות אותו."},"11":{"0":"השם הזה לא קשור לתעדוף. CD3 הוא נוסחה: Cost of Delay חלקי Duration, לא שיטה לגילוי לקוחות.","1":"גילוי מתמשך הוא רעיון אחר. CD3 הוא ציון: עלות הדחייה חלקי זמן הפיתוח.","3":"CD3 הוא לא לוח מדדים. הוא מחלק את עלות הדחייה החודשית בזמן שלוקח לבנות, כדי לקבוע סדר."},"12":{"0":"המודל כן שוקל עלות: בדוגמה של השלב Effort הוא קריטריון במשקל 15%, הפוך, כך שפחות מאמץ מקבל יותר נקודות.","2":"השלב ממליץ על Weighted Scoring בדיוק כשיש כמה Stakeholders עם דרישות סותרות, לא רק בסטארטאפים.","3":"השלב לא טוען שהשיטה ישנה. המגבלה היא ה-Inputs: משקלות וציונים שנקבעים בהערכה אנושית."},"13":{"0":"להציג מסגרת ונתונים זה בדיוק המהלך המומלץ: הוא הופך ויכוח דעות לשיחה על הנחות.","1":"לתת ל-Stakeholder להרגיש שותף הוא חלק מהגישה הנכונה: זה מפחית התנגדות במקום ליצור אותה.","3":"לתעד מה הוחלט ולמה זה נוהל טוב: ההחלטה נשארת שקופה גם אחרי הפגישה."},"14":{"0":"Quick Win הוא הפינה ההפוכה: ערך גבוה ומאמץ נמוך, העבודה שעושים ראשונה.","1":"ל-Big Bet יש ערך גבוה לצד המאמץ הגבוה, ולכן שווה לתכנן אותו בקפידה.","2":"Fill-in הוא ערך נמוך אבל גם מאמץ נמוך, ולכן אפשר לעשות אותו בזמן פנוי. מאמץ גבוה הופך אותו ל-Time Sink."}},"8":{"0":{"0":"שעות נוספות מסתירות את הבעיה: SSO לבדו ממלא את כל ה-Velocity ולא משאיר מקום לבאגים. מתכננים לפי הקיבולת האמיתית.","2":"לוותר על SSO פירושו לוותר על פריט אסטרטגי. פירוק לשלבים שומר עליו בתנועה בתוך ה-Velocity.","3":"Velocity הוא הקצב הממוצע של הצוות, ועליו מתכננים. פירוק ה-SSO לשלבים מכניס אותו לתוכנית בלי חיזוק זמני."},"1":{"0":"לעצור הכל בשביל Dark Mode באמצע ספרינט פוגע ב-SSO האסטרטגי. ל-CEO מגיע Trade-off, לא ביצוע עיוור.","2":"התעלמות מה-CEO סוגרת את השיחה. המהלך הנכון מסביר את המחיר ומציע את הספרינט הבא.","3":"עבודת לילה מעמיסה על ספרינט מלא ומסתירה את ה-Trade-off האמיתי: Dark Mode עכשיו פירושו לדחות את SSO."},"2":{"0":"לחפש מי אחראי לכל משימה שלא הושלמה הופך את ה-Retro להאשמה. המטרה היא שיפור מתמיד.","2":"לחפש אשמים הורג את הכנות. Retro שואל מה נשנה, לא מי אשם.","3":"להתמקד ב-CEO מפנה את המבט החוצה. Retro בוחן מה הצוות עצמו יכול לשנות בספרינט הבא."},"3":{"0":"זו הצדקה בלי משתמש ובלי ערך. User Story אומר מי רוצה, מה ולמה.","2":"עדיפות ודדליין הם נתוני תכנון, לא סיפור. אין כאן מי המשתמש ואיזה ערך הוא מקבל.","3":"זה מפרט של משימה טכנית. User Story מתאר את המשתמש ואת הערך, לא SAML ו-Story Points."},"4":{"0":"ספרינטים לא מתאימים לתמיכה, שמתאימה לזרימה הרציפה של Kanban. הבעיה היא יותר מדי עבודה פתוחה בבת אחת.","2":"עוד אנשים רק יפתחו עוד טיקטים במקביל. הפתרון הוא לסיים את מה שהתחיל לפני שלוקחים עבודה חדשה.","3":"פחות שעות לא מצמצמות את 14 הטיקטים הפתוחים. ריבוי המשימות הוא מה ששוחק, ו-WIP Limit מטפל בזה."},"5":{"0":"Acceptance Criteria מגדירים מה Story אחד עושה. המחלוקת כאן היא על רף האיכות המשותף: טסטים ו-Code Review.","2":"Sprint Goal אומר לאן הספרינט מכוון. הוא לא מכריע אם קוד בלי טסטים נחשב גמור.","3":"Velocity עוסק בכמה להתחייב. כאן השאלה היא מה פירוש גמור, ואת זה DoD מגדיר לכל פריט."},"6":{"0":"זה נכון: Velocity הוא כלי תכנון שעוזר להעריך כמה עבודה הצוות יכול לקחת.","1":"זה נכון: Velocity הוא ממוצע ה-Story Points שהצוות מסיים בכל ספרינט לאורך זמן.","3":"זה נכון: Velocity יציב לאורך כמה ספרינטים הוא סימן לצוות בוגר."},"7":{"0":"OKR קובע יעד ומדדים, אבל לא ממפה בעיות משתמשים לפתרונות ולניסויים. זה בדיוק מה שמיכל צריכה.","2":"Roadmap עובר מהחזון ועד ה-Backlog. הוא לא מקשר בין הבעיות שהמחקר העלה לפתרונות ולניסויים.","3":"Story Map פורש את הזרימה של פתרון שכבר נבחר. מיכל רוצה לחזור אחורה מה-Wizard אל הבעיות עצמן."},"8":{"0":"אורך הספרינט הוא לא הבעיה: הצוות בחר יותר מדי בשבילו. מתכננים לפי Velocity, לא לפי תקווה.","1":"כישורים הם לא הסיבה הסבירה. התחייבות־יתר בתכנון היא הבעיה הנפוצה ביותר.","3":"הפתעות קורות, ולכן מוסיפים Buffer. החמצה של 40% מצביעה על התחייבות־יתר, לא על מזל רע."},"9":{"0":"Dual-Track לא עוסק בפחות שעות. הערך שלו הוא לגלות מה לבנות תוך כדי בנייה של מה שכבר אומת.","2":"Dual-Track לא מחליף את Scrum. ה-Delivery יכול לרוץ בספרינטים, וה-Discovery רץ לצידו.","3":"ה-PM מרכזי: ה-PM והמעצב מובילים את ה-Discovery. המסלולים רצים במקביל, לא בלי PM."},"10":{"0":"טקסים לבדם הם לא Agile. סירוב לשנות כיוון שובר ערך מרכזי: תגובה לשינוי על פני מעקב אחרי תוכנית.","1":"Agile מוגדר לפי ערכים, לא טקסים. Stand-ups וספרינטים בלי נכונות לשינוי הם Waterfall בתחפושת.","3":"Scrum Master מוסמך הוא לא העניין. טקסים בלי תגובה לשינוי אינם Agile בכל מקרה."},"11":{"0":"Waterfall in Disguise פירושו שכל הדרישות נכתבות מראש בלי גילוי. הסימפטום כאן הוא שאף אחד לא מודד.","2":"עוד פיצ׳רים הם המחלה, לא התרופה. הבעיה היא שאף אחד לא מודד אם הפיצ׳רים עובדים.","3":"DoD עוסק באיכות לפני השחרור. הפער כאן הוא אחרי ההשקה: אף אחד לא בודק אם הפיצ׳ר עמד ביעד."},"12":{"0":"100% Discovery פירושו לא לשחרר כלום. המחקר צריך לרוץ לצד הבנייה, לא במקומה.","1":"כלל האצבע הוא בערך 70% Delivery ו-30% Discovery, לא חלוקה שווה בין המסלולים.","3":"Discovery פעם ברבעון נדיר מדי. הנקודה המרכזית היא שהוא קורה כל שבוע."},"13":{"0":"להתחייב ל-Velocity הכי גבוה כדי להרשים מוביל להתחייבות־יתר. התכנון צריך לשבת על הממוצע האמיתי.","1":"להכתיב משימות והערכות מוחק את החלק של הצוות: ה-איך וה-כמה. זה פוגע בריאליות ובמחויבות.","3":"לדחוס את כל הבקלוג מתעלם מהקיבולת. התכנון בוחר את מה שנכנס ב-Velocity."},"14":{"0":"Retro ו-Sprint Planning הם טקסים של Scrum. Continuous Discovery עוסק במגע שבועי עם לקוחות.","2":"שחרור פיצ׳רים הוא Delivery. Continuous Discovery הוא מחקר: ראיונות, בדיקות Prototype וניסויים.","3":"כתיבת סיפורים היא עבודת Backlog. Continuous Discovery פירושו לגעת בלקוחות כל שבוע דרך מחקר קטן."}},"9":{"0":{"0":"המראה הוא לא העניין. Out of Scope קובע מראש מה לא ייבנה, כך שאף אחד לא ידרוש את זה באמצע.","2":"זו לא דרישה פורמלית של ה-CEO. Out of Scope הוא הסעיף שחוסך הכי הרבה ויכוחים על היקף.","3":"גם עם משאבים בשפע הוא חשוב: הוא עוצר את הנטייה הטבעית להוסיף עוד ועוד, ומכריע מחלוקות מראש."},"1":{"1":"לעבוד טוב ולהיטען מהר אי אפשר לבדוק. AC טובים הם ספציפיים ומדידים, כמו 3 Templates ו-3 שניות.","2":"שביעות רצון ו-NPS הם תוצאות, לא תנאי קבלה. AC בודקים התנהגות קונקרטית שהצוות יכול לאמת.","3":"זו תוכנית בנייה עם מילים עמומות כמו מודרני וחלק. AC מנסחים תנאי שאפשר לבדוק: Given, When, Then."},"2":{"0":"חיסכון בכסף הוא תוצר לוואי. העיקר הוא ה-MVP: לבדוק את הליבה מהר, ללמוד ואז להרחיב.","2":"נוחות המפתחים היא לא המטרה. הגרסה הפשוטה מאפשרת ללמוד מהר ולהפחית סיכון לפני שמשקיעים יותר.","3":"לגלות תוך כדי בנייה זה יקר. לשאול מראש עשוי להראות ש-Templates לבדם מספיקים כ-MVP."},"3":{"0":"כמות ה-Templates שנבחרו היא Leading Indicator שמסביר למה. Activation הוא ה-Outcome שמזיז את העסק.","2":"לחיצות על דלג עוזרות לאבחן את הזרימה, אבל הן אות משני. המטרה ש-Onboarding v2 משרת היא Activation.","3":"זמן שהייה יכול לעלות מסיבות רעות, כמו בלבול. ה-Outcome שחשוב הוא Activation, מ-45% ל-60%."},"4":{"0":"ההבדל הוא לא בשפה או במיקום הקהל. MRD עוסק ב-למה ולמי; PRD עוסק במה לבנות.","2":"ה-MRD נכתב קודם והוא לא נספח טכני. הוא מגדיר את ההזדמנות בשוק שה-PRD נבנה עליה.","3":"זה מחליף ביניהם: MRD הוא הזדמנות השוק, למה ולמי, ו-PRD הוא הפתרון, מה לבנות."},"5":{"0":"זו שאלה טובה: המחיר של לא לפתור בודק אם הבעיה אמיתית ומשמעותית.","2":"זו שאלה טובה: היא בודקת שהפתרון נבחר מול חלופות, ולא כברירת מחדל.","3":"זו שאלה טובה: מה קורה אם נחכה 6 חודשים בודקת דחיפות אסטרטגית, את ה-למה עכשיו."},"6":{"0":"זה מתאר פתרון עם פרטי עיצוב, בלי משתמש ובלי ערך. User Story מתחיל ממי ולמה.","2":"עדיפות ותזמון הם נתוני תכנון. חסר מי המשתמש ואיזה ערך הדילוג נותן לו.","3":"קרוב, אבל חסרים חלקי הפורמט: משתמש מסוים וה-כדי ש, הערך שבדילוג."},"7":{"0":"PRD לא יכול לבוא לפני MRD: מגדירים פתרון רק אחרי שמבינים למה ולמי.","1":"להתחיל ב-Tech Spec פירושו להחליט איך בונים לפני שיודעים למה ומה. ה-MRD בא ראשון.","3":"זה הפוך לגמרי: סיפורי הספרינט באים אחרונים, אחרי שה-למה, ה-מה, המראה וה-איך הוגדרו."},"8":{"0":"Story Points לא נכנסים למשפט ה-Story. הבעיה היא בתוכן: פתרון מוכתב ובלי ערך.","2":"הוא שובר את הפורמט: אין כדי ש, והוא מכתיב עיצוב, כפתור כחול, במקום צורך.","3":"לא צריך שם אישי; תפקיד מספיק. מה שחסר הוא הצורך והערך שמאחוריו."},"9":{"0":"הם שונים בהיקף: AC שייכים ל-Story אחד, ו-DoD הוא סטנדרט שכל משימה צריכה לעמוד בו.","2":"שניהם משרתים את כל הצוות. ההבדל הוא בהיקף: AC לכל Story, DoD לכל עבודה.","3":"אין ביניהם סדר קבוע. AC מתארים מה Story עושה; DoD אומר מתי עבודה כלשהי באמת גמורה."},"10":{"0":"פירוט לא מבטיח הבנה כשאף אחד לא קורא. 2-3 עמודים רזים עונים על השאלות המרכזיות.","2":"ארוך יותר זה גרוע יותר: השלב מגדיר PRD טוב כ-2-3 עמודים מדויקים, וכבר 20 לא נקראים.","3":"התרגום הוא לא הבעיה. האורך הוא הבעיה: 20 עמודים פירושם שהמסמך לא נקרא."},"11":{"0":"הפעולה של המשתמש היא ה-When. Given מתאר את מצב הפתיחה לפני כל פעולה.","1":"התוצאה הצפויה היא ה-Then. Given הוא המצב ההתחלתי שממנו התרחיש יוצא.","3":"Given הוא לא שם או תפקיד. הוא מצב המערכת או המשתמש לפני שהפעולה מתחילה."},"12":{"0":"תזמון בא אחר כך. קודם שואלים אם הבעיה אמיתית; אחרת גם בנייה מהירה היא בזבוז.","2":"טכנולוגיה היא שאלת איך למועד מאוחר יותר. קודם בודקים שהבעיה אמיתית ושווה פתרון.","3":"הקצאת מפתחים היא שאלת ביצוע. אם הבעיה לא אמיתית, שום מספר מפתחים לא יצדיק את הבנייה."},"13":{"0":"עלות לבדה מראה רק את ההוצאה. ההנהלה צריכה גם הכנסות צפויות, ROI ותרחישי סיכון.","2":"פיצ׳רים עם AC שייכים ל-PRD. Business Case מדבר כסף: עלות, הכנסות, ROI ותרחישים.","3":"השוואת מתחרים מראה שהשוק קיים, לא שההשקעה הזו משתלמת. לזה צריך עלות, הכנסות ו-ROI."},"14":{"0":"הערכת מאמץ נשענת על ה-PRD ועל הצוות, לא על ה-MRD. ה-MRD קיים כדי להבין את ההזדמנות.","2":"ב-MRD אין דרישות טכניות; הן ב-Tech Spec. ה-MRD עוסק ב-למה ולמי.","3":"השלב קושר את ה-MRD לשוק, לא לרגולציה. התפקיד שלו לוודא שהבעיה שווה פתרון."}},"10":{"0":{"0":"החטאה של 2pp ביעד לא מוחקת שיפור של 13pp+ עם 99% מובהקות. מושלם הוא אויב הטוב.","2":"לחכות חודש ליעד המדויק מעכב ניצחון מוכח. משחררים עכשיו וממשיכים לשפר.","3":"להתחיל מחדש זורק גרסה שכבר עובדת: 13pp+ עם 99% ביטחון."},"1":{"0":"הסרת השלב מאבדת את הערך שלו: מי שמזמין מראה Retention גבוה ב-40%. מתקנים את השלב, לא חותכים אותו.","1":"חיוב להזמין הופך נקודת נטישה לחומה. עדיף להראות את הערך ולהקל על ההזמנה.","3":"הנתונים כבר מראים את ערך השלב, 40%+ Retention, ואת המחיר שלו, 25% נטישה. זה מספיק כדי לפעול."},"2":{"0":"זה עוסק בתכנון הניסוי. העיקרון עוסק בהחלטה: לבדוק סגמנטים לפני שפוסלים פיצ׳ר.","2":"זה הפוך: מפלחים כדי למצוא הצלחות נסתרות, כמו 11pp+ בצוותים קטנים מתחת לתוצאה כוללת של 2.6pp+.","3":"להגדיר סגמנט יעד זה נוהל טוב, אבל העיקרון עוסק בניתוח התוצאות לפני שזורקים פיצ׳ר."},"3":{"0":"זה ניסוי מוצר, לא ניהול מתקן. הדלת היא כפתור או לינק לפיצ׳ר שעוד לא קיים.","2":"זו לא בדיקת אבטחה. היא מודדת ביקוש: כמה לוחצים על פיצ׳ר שעוד לא נבנה.","3":"A/B על כפתורים קיימים משפץ את הממשק. Fake Door בודק ביקוש לפיצ׳ר שעוד לא נבנה."},"4":{"0":"אין כאן מדד ולא מסגרת זמן, כך שאי אפשר לדעת אם ההשערה אומתה. מחקר ומתחרים הם לא מבחן.","2":"המבנה מתחיל טוב, אבל כי קיבלנו בקשות הוא לא מדד. חסר מדד, מ-X ל-Y, ועד מתי.","3":"להעתיק מתחרים זו לא השערה, ולקוחות מרוצים זה לא מדיד. חסרים מדד ותאריך יעד."},"5":{"0":"יש הבדל: ב-Concierge הלקוח יודע שזה ידני; רק ב-Wizard of Oz זה מוסתר ממנו.","2":"Wizard of Oz לא אוטומטי; אדם עובד מאחורי הקלעים. ההבדל הוא אם המשתמש יודע.","3":"Wizard of Oz לא צריך Back-end אוטומטי; הוא רק נראה אוטומטי. כך הוא בודק ביקוש בזול."},"6":{"0":"Lean Startup מתחיל קטן: MVP מינימלי, לא מוצר שלם. לחכות לרווחים מאט את הלמידה.","2":"תוכנית עסקית למשקיעים היא לא הלולאה. הלולאה בונה MVP, מודדת שימוש אמיתי ומחליטה Pivot או Persevere.","3":"הלולאה עוסקת בלמידה על המוצר, לא בבניית צוות. בונים MVP, מודדים מדדים אמיתיים ואז מחליטים."},"7":{"0":"הסף הפוך: מובהקות פירושה p-value מתחת ל-0.05. ב-0.03 התוצאה מובהקת.","2":"p-value הוא לא גודל השיפור. הוא אומר כמה סביר שהבדל כזה יופיע במקרה.","3":"p-value לא מתאר חלק מהמשתמשים. הוא הסיכוי לתוצאה קיצונית כזו אם אין הבדל אמיתי."},"8":{"0":"ההרשמות מראות עניין, אבל רק 15 מ-200 חזרו, 7.5%. המדד שחשוב הוא מי קיבל ערך וחזר.","2":"עוד נרשמים ימלאו את אותו דלי דולף. הבעיה היא שהמשתמשים לא חוזרים.","3":"7.5% שחוזרים ביום השני זה דגל אדום. הצעד הבא הוא לראיין את 185 שלא חזרו."},"9":{"1":"המונחים שונים: Pivot משנה כיוון, כמו מ-B2C ל-B2B; Iteration משפר באותו כיוון.","2":"זה הפוך: Iteration הוא צעד קטן, Pivot הוא שינוי כיוון יסודי.","3":"שניהם נשענים על למידה, אבל שונים בהיקף: פנייה אסטרטגית מול שיפור הדרגתי."},"10":{"0":"ניסוי A/B שבועי על כל פיצ׳ר הוא לא המינימום של Torres. הבסיס שלה הוא ראיון אחד של 30 דקות.","2":"סקר של 100 משתמשים הוא לא ההרגל שהיא מתארת. המינימום הוא ראיון אחד של 30 דקות בשבוע.","3":"PRD הוא מסמך של Delivery, לא של Discovery. המינימום של Torres הוא לדבר עם לקוח אחד בכל שבוע."},"11":{"0":"להסתיר שאדם עושה את העבודה זה Wizard of Oz. ב-Concierge הלקוח יודע שהשירות ידני.","2":"Concierge נועד ללמוד את התהליך מקרוב לפני אוטומציה. בדיקת מחיר בלבד לא דורשת את זה.","3":"Concierge בא לפני האוטומציה. אם המוצר כבר בנוי ואוטומטי, עברנו את השלב הזה."},"12":{"0":"האם המשתמש רוצה ומוכן לשלם זה Value. Feasibility שואל אם אפשר לבנות בזמן ובתקציב.","2":"שימוש בממשק בלי עזרה הוא Usability. Feasibility עוסק בשאלה אם אפשר לבנות את זה טכנית.","3":"הכנסות שמצדיקות את ההשקעה הן Viability. Feasibility שואל אם אפשר בכלל לבנות את זה."},"13":{"0":"סקרנות של המפתחים היא לא למידה על לקוחות. Pivot בא בעקבות נתונים שמפריכים את ההשערה.","2":"מתחרה חדש לבדו לא מפריך את ההשערה שלכם. עושים Pivot כשהנתונים שלכם מראים שהכיוון נכשל.","3":"Pivot בלי נתונים הוא ניחוש. הוא צריך לבוא בעקבות ראיות שההשערה הופרכה."},"14":{"0":"העלות היא לא הבעיה בניסוי קצר. הסיכון הוא לפספס דפוסי שימוש שבועיים, כולל סוף השבוע.","2":"דווקא הסיכון ההפוך קיים: Novelty Effect, משתמשים מגיבים כי זה חדש. ניסוי קצר לא מבחין בזה.","3":"מדיניות פנימית היא לא העניין. ניסוי קצר מפספס מחזור שבועי מלא ויכול להיות מוטה מהחידוש."}},"11":{"0":{"0":"ה-KRs האלה הם פעולות, לא תוצאות. להריץ ניסוי או לעצב מסך לא אומר אם משהו השתפר.","2":"100% ואפס נטישה לא ריאליים. OKR טוב שאפתני אבל בר השגה; סביב 70% נחשב הצלחה.","3":"לשחרר פיצ׳רים וטיפים זה Output. KR צריך למדוד Outcome, כמו Activation."},"1":{"0":"הגודל הוא לא הבעיה. גם מיליון נרשמים היו Vanity אם לא ברור כמה פעילים או משלמים.","2":"המספר יכול להיות מדויק לגמרי. הוא Vanity כי הוא לא משקף ערך: פעילות או תשלום.","3":"גם גודל הוא לא הבעיה. הוא Vanity כי ספירה כוללת מסתירה כמה פעילים ומשלמים."},"2":{"0":"שחיקה היא לא מה ש-Goodhart מזהיר ממנו. הסיכון הוא משחק במספר: לסגור באגים קלים כדי להגיע ל-10.","2":"חוק Goodhart הוא בדיוק הסיכון: ברגע שמספר הופך ליעד, אנשים מייצרים את המספר ולא את הערך.","3":"התמריץ פועל הפוך: כדי להגיע מהר ל-10, הצוות יבחר באגים קלים, לא קריטיים."},"3":{"0":"מדד שנבחר כדי להרשים הוא לרוב Vanity. North Star משקף את הערך שהמשתמשים באמת מקבלים.","2":"סך ההורדות הוא מספר Vanity שלא אומר כלום על ערך שוטף. North Star משקף ערך יומיומי.","3":"North Star יציב ומיישר את כל הצוותים. מדד שמשתנה כל רבעון לא יכול לכוון את כולם לאותו כיוון."},"4":{"0":"Referral בא אחרי Retention: משתמשים ממליצים כשהם ממשיכים לחזור ומקבלים ערך.","1":"Activation לא יכול לבוא לפני Acquisition: משתמשים צריכים קודם להגיע כדי לחוות ערך.","3":"Awareness לא חלק מ-AARRR, ו-Referral חסר. החמישה הם Acquisition, Activation, Retention, Referral ו-Revenue."},"5":{"0":"זו אסטרטגיית חיקוי, לא ההטיה. Survivorship Bias הוא להסיק מסקנות רק ממי שנשאר.","2":"להעדיף משתמשים ותיקים זו בחירה, לא ההטיה הזו. ההטיה היא להתעלם ממי שעזב כשמנתחים.","3":"להתמקד במשלמים זו בחירה עסקית. Survivorship Bias פירושו לפספס למה אחרים עזבו."},"6":{"0":"הם משרתים מטרות שונות: KPI שואל איך אנחנו מתפקדים, OKR שואל לאן אנחנו מכוונים.","2":"אף אחד מהם לא קשור לגודל הצוות. KPI הוא מדד שוטף; OKR הוא יעד תחום בזמן, בדרך כלל רבעוני.","3":"KPI הוא מדד שוטף, לא דווקא חודשי, ו-OKR בדרך כלל רבעוני, לא שנתי."},"7":{"0":"גם קורלציה חזקה לא מוכיחה סיבה. ייתכן שמשתמשים מוטיבציוניים גם צופים בהדרכה וגם משתמשים יותר.","2":"הם שונים: קורלציה היא תנועה משותפת, סיבתיות היא השפעה. רק ניסוי מבוקר מוכיח אותה.","3":"זה מעשי מאוד: פיצ׳ר שנבנה על קשר שגוי מבזבז פיתוח. בשביל זה קיימים מבחני A/B."},"8":{"0":"המדדים לא תמיד זזים יחד. אם Activation מוגדר ברפיון, הוא יכול לעלות בלי ערך אמיתי ובלי הכנסות.","2":"הם קשורים: כל מדד צריך להתחבר בסוף ל-Revenue. הפער הוא סימן שכדאי לחקור.","3":"Activation חשוב, אבל רק אם הוא מוגדר כערך אמיתי. כאן ההגדרה אולי סופרת גם מי שרק מתנסה."},"9":{"0":"ב-3 ימים אולי אין מספיק מדגם ומובהקות, ו-Novelty Effect יכול לנפח תוצאות מוקדמות.","2":"אין כלל קבוע של חודש. מה שקובע הוא גודל מדגם, p-value מתחת ל-0.05 ומחזור שבועי מלא.","3":"פיצול קבוע של 50/50 הוא לא החלטה. קודם מוודאים שהתוצאה מובהקת, ואז משחררים או מוותרים."},"10":{"1":"שניהם חשובים: Leading מאפשר לפעול מוקדם, Lagging מאשר מה קרה. PM חכם עוקב אחרי שניהם.","2":"הם מודדים דברים שונים: הרשמות ו-Activation מנבאים, הכנסות ו-Churn מדווחים על מה שכבר קרה.","3":"אף אחד מהם לא קשור ל-B2C או ל-B2B. ההבדל הוא בתזמון: ניבוי העתיד מול שיקוף העבר."},"11":{"0":"שורות קוד הן עוד מדד תפוקה, וגם אותו אפשר לנפח. Counter-metric צריך לשמור על האיכות.","2":"מספר ישיבות לא בודק מה מהירות עלולה לשבור. המשקל הנגדי למהירות הוא איכות: באגים ותקלות.","3":"הודעות ב-Slack לא מאזנות מהירות. הסיכון במרדף אחרי Velocity הוא קוד מלא באגים, ולכן מודדים איכות."},"12":{"0":"Activation Rate הוא ה-Output שאליו מכוונים, לא Input. Input הוא מה שהצוות שולט בו ישירות.","2":"הכנסות הן Output, וגם Lagging. Inputs הם פעולות שהצוות שולט בהן, כמו ניסויים.","3":"Day-30 Retention הוא מדד Output. הצוות לא מזיז אותו ישירות; הוא מזיז Inputs כמו ניסויים."},"13":{"0":"מספרים מראים מה קורה, לא למה. בלי הקשר ובלי משתמשים קל להסיק מהם מסקנה שגויה.","2":"לשלב נתונים עם אינטואיציה ומשתמשים זו בדיוק גישת Data-Informed ש-Yang ממליץ עליה, לא הסיכון.","3":"גודל הצוות הוא לא העניין של Yang. הסיכון הוא להחליט לפי מספרים בלבד בלי להבין למה."},"14":{"0":"שקר הוא לא החשש. הגעה קבועה ל-100% פשוט מראה שהיעדים לא מתחו את הצוות.","2":"אין כלל של ערכים עגולים. הנקודה היא ש-70% נחשב טוב, ולכן 100% מעיד על חוסר שאפתנות.","3":"שחיקה היא לא הסיבה. OKR נועד למתוח את הצוות; 100% קבוע אומר שזה לא קרה."}},"12":{"0":{"0":"Error Prevention עוצר טעויות לפני שהן קורות, כמו אישור לפני מחיקה. צבעי עדיפות מיידעים, לא מונעים.","2":"Flexibility פירושו קיצורי דרך למשתמשים מנוסים. רמות עדיפות קבועות מציגות מצב במבט אחד.","3":"Help הוא עזרה בהקשר, כמו טיפ ליד שדה. שלוש רמות בצבעים לא צריכות הסבר: הן הופכות את המצב לגלוי."},"1":{"0":"זה מכתיב פרט ויזואלי, צבע, במקום צורך. פידבק מוצרי אומר מה המשתמש צריך ולמה.","2":"לא יפה זה עמום ואי אפשר לפעול לפיו. פידבק טוב מציין צורך ואת ההקשר שלו.","3":"אנימציות מגניבות הן פתרון מבוסס טעם בלי צורך של משתמש מאחוריו. פידבק מתחיל מהצורך."},"2":{"0":"יותר התראות שנשלחו זו לא הצלחה; זה יכול להיות יותר רעש. מודדים מה המשתמשים עושים איתן.","1":"שביעות הרצון של המעצב היא לא מדד מוצרי. הצלחה נראית בהתנהגות המשתמשים: תלונות, לחיצות ו-NPS.","3":"התאמה ויזואלית היא שאלה עיצובית. הצלחה נמדדת בתלונות, ב-Click Rate וב-NPS יחד."},"3":{"0":"זה הפוך: ה-Prototype הוא השלב המפורט והיקר ביותר, ולכן הוא אחרון, לא ראשון.","2":"להתחיל מ-Mockup מדלג על השלבים הזולים. רמת הפירוט עולה שלב אחר שלב: Sketch ראשון, Prototype אחרון.","3":"Sketch הוא השלב הגס והזול ביותר ובא ראשון. כאן הוא שלישי, אחרי ה-Prototype."},"4":{"0":"זה ההפך מהעיקרון: לחייב משתמשים לזכור פקודות בעל פה זה בדיוק מה שהוא בא למנוע.","2":"מילוי טפסים אוטומטי הוא נוחות אחרת. Recognition over Recall עוסק בהצגת אפשרויות במקום לחייב לזכור.","3":"אין מבחן זיכרון ברשימה של Nielsen. העיקרון מפחית עומס על הזיכרון על ידי הצגת האפשרויות."},"5":{"0":"זה פידבק טוב: הוא מצביע על בעיה, ה-CTA מתחרה על תשומת לב, ומשאיר את הפתרון למעצב.","1":"זה פידבק טוב: הוא מגדיר צורך מדיד, הבנה תוך 3 שניות, בלי להכתיב עיצוב.","3":"זה פידבק טוב: הוא מציין צורך, גישה בלחיצה אחת, ולא איך הכפתור צריך להיראות."},"6":{"0":"Empathize בא ראשון, לא אחרון. אי אפשר להגדיר את הבעיה לפני שמבינים את המשתמשים.","2":"להתחיל ברעיונות מדלג על ההבנה. התהליך נפתח ב-Empathize וב-Define, ורק אחר כך Ideate.","3":"לבנות אב טיפוס קודם פירושו לבנות לפני שיודעים מה הבעיה. Empathize פותח את התהליך."},"7":{"0":"מדריך סגנון של מותג עוסק בזהות שיווקית. Design System הוא ספריית רכיבים של המוצר: כפתורים, טפסים, טיפוגרפיה.","2":"Figma או Sketch הם כלים. Design System הוא אוסף הרכיבים המשותף שהצוות משתמש בו שוב ושוב במוצר.","3":"עקרונות שמישות הם רשימת בדיקה לשיפוט מסכים. Design System הוא ספריית רכיבים לשימוש חוזר."},"8":{"0":"Jakob's Law מזהיר שמשתמשים מצפים לדפוסים מוכרים. חדשנות צריכה להישען על ראיות, לא להיות מאושרת לפי מראה.","1":"לא לשנות כלום חוסם שיפור. בדיקת שמישות תראה אם הניווט החדש עובד.","3":"אישור של המנכ״ל לא אומר אם משתמשים יצליחו לנווט. בדיקה עם 5 משתמשים כן."},"9":{"0":"הם שונים: UX הוא המסע כולו ואיך הוא מרגיש, UI הוא השכבה הוויזואלית של כפתורים, צבעים וטיפוגרפיה.","2":"זה הפוך: UX הוא החוויה הרחבה, ו-UI הוא שכבה אחת בתוכה.","3":"UX רלוונטי לכל מוצר דיגיטלי, לא רק לאפליקציות מובייל: זו החוויה של שימוש בכל מוצר."},"10":{"0":"הודעות שגיאה ברורות עוזרות בדיעבד. Error Prevention מעדיף לעצור את הטעות לפני שהיא קורית.","2":"הסתרת שגיאות משאירה את המשתמש מבולבל. העיקרון עוסק במניעת טעויות, לא בהסתרתן.","3":"בלי שום הגבלה מזמינים טעויות. Error Prevention מוסיף הגנות, כמו כפתור מושבת עד שהטופס תקין."},"11":{"0":"אף אחד מהם הוא לא השלב האינטראקטיבי; זה ה-Prototype. Wireframe מציג מבנה, Mockup את המראה הסופי.","2":"אלה שלבים שונים: Wireframe בודק מבנה וזרימה, Mockup בודק מראה ותחושה.","3":"הנייר מגיע עוד קודם, ב-Sketch. ה-Wireframe בא לפני ה-Mockup, לא אחריו."},"12":{"0":"לייצר רעיונות לפני שמבינים למה משתמשים מתקשים עלול לפתור את הבעיה הלא נכונה. Empathize בא קודם.","1":"אב טיפוס שמזיז את הפיצ׳ר מניח שהמיקום הוא הבעיה. אולי השם לא ברור; קודם מבינים.","3":"מבחן בודק פתרונות שעוד אין לכם. קודם לומדים מהמשתמשים למה הם מתקשים."},"13":{"0":"טעם, טרנדים ואנימציות נשארים אצל המעצבת. ה-PM בודק מטרות עסקיות, מגבלות טכניות וצרכי משתמש.","2":"ספירת מסכים או גודל קובץ לא אומרים כלום על ערך. המסננים הם עסקי, טכני ומשתמש.","3":"העדפות וותק הם לא קריטריונים. ה-PM שואל אם העיצוב משרת את העסק, ניתן לבנייה ופותר את בעיית המשתמש."},"14":{"0":"השלב מציין שב-B2B לקוחות Enterprise מבקשים לעתים קרובות דוח נגישות, ובלעדיו עסקה יכולה להיתקע.","2":"נגישות היא לא נישה: היא אחריות מוצרית שמרחיבה את בסיס המשתמשים.","3":"השלב מכניס נגישות ל-Acceptance Criteria של כל פיצ׳ר, לא כמשימה נפרדת למועד מאוחר יותר."}},"13":{"0":{"0":"לחכות עד שכל באג יתוקן פירושו לאבד 3 עסקאות עם דדליין. השקה מבוקרת עם ETA שומרת עליהן.","1":"השקה שקטה לכולם בלי מילה על באגים ידועים מסכנת אמון אצל כולם. שקיפות עם ETA בונה אמון במקום.","3":"להסתיר באגים ידועים שורף אמון ברגע שהלקוחות נתקלים בהם. שקיפות ו-ETA עדיפים על שתיקה."},"1":{"0":"המחיר הוא לפי משתמש, $15 למשתמש, לא לפי משימות שנוצרו. Usage-based היה גובה לפי פעילות בפועל.","2":"Flat rate מתעלם ממספר המשתמשים, אבל כאן המחיר הוא לפי משתמש, ועוד בתוך מבנה של שלוש חבילות.","3":"ל-Velox יש חבילות בתשלום, Pro ו-Enterprise. Freemium בלי שדרוג סותר חבילת Enterprise של $15 למשתמש."},"2":{"0":"QA עם באגים קריטיים סגורים הוא סעיף מרכזי ברשימה: לא משיקים על תקלה קריטית ידועה.","1":"Analytics נמצא ברשימה: בלעדיו אי אפשר לדעת אחרי ההשקה אם הפיצ׳ר עבד.","3":"Rollback plan נמצא ברשימה: אם משהו נשבר, צריך דרך חזרה מוכנה."},"3":{"0":"הם שונים בקהל ובסיכון: Soft Launch בודק יציבות על 5-10% מהמשתמשים, Big Bang יוצא לכולם עם PR.","2":"השלב לא מדרג אותם לפי עלות. הבחירה תלויה ברמת הסיכון ובמוכנות המוצר.","3":"Soft Launch שקט מטבעו ולא דורש יותר פרסום. הוא פונה לקבוצה קטנה כדי לבדוק יציבות."},"4":{"0":"תמחור לפי עלות הפיתוח הוא ההפך מ-Value-based. ללקוח חשוב הערך, לא העלויות שלכם.","1":"ממוצע מחירי המתחרים הוא תמחור לפי תחרות. Value-based מתחיל ממה שהפתרון שווה ללקוח.","3":"שעות עבודה הן נתון עלות. Value-based שואל כמה הלקוח ישלם על הבעיה שנפתרה לו."},"5":{"0":"גרסה חינמית היא Freemium, דרך למשוך משתמשים. Decoy הוא אפשרות שנבנתה כדי להידחות.","2":"הנחה מוגבלת בזמן יוצרת דחיפות, טקטיקה אחרת. Decoy עובד דרך השוואה, כמו Medium שגורם ל-Large להיראות זול.","3":"שינוי שם משפיע דרך מילים. Decoy מוסיף אפשרות נוספת שמכוונת את הבחירה דרך השוואה."},"6":{"0":"Anchoring ו-Decoy Effect הן טקטיקות להצגת מחירים, לא מחקר על כמה לקוחות מוכנים לשלם.","1":"NPS ו-CSAT מודדים נאמנות ושביעות רצון, לא מחיר. הם לא חושפים נכונות לשלם.","3":"Cost-plus ו-Break-even יוצאים מהעלויות שלכם. מחקר Willingness to Pay שואל את הלקוחות כמה הערך שווה להם."},"7":{"0":"זה מחליף ביניהם: Freemium הוא גרסה מוגבלת חינם לתמיד; Free Trial הוא גישה מלאה לזמן מוגבל.","2":"הגרסה הבסיסית ב-Freemium חינמית, לא מוזלת, ו-Free Trial פותח את כל הפיצ׳רים, לא חלק מהם.","3":"Freemium נשען על שדרוג לפרימיום, לא בהכרח על פרסומות. Free Trial לא דורש תשלום מראש."},"8":{"0":"Product-Led פירושו התנסות חינם ו-Self-serve, כמו Slack. רשימת המתנה עושה ההפך: מגבילה גישה כדי לבנות ביקוש.","1":"Sales-Led נשען על דמו, פיילוט וחוזה שנתי. רשימת ההמתנה וההזמנות של Superhuman מייצרות ביקוש בדרך אחרת.","3":"Usage-based הוא מודל תמחור, לא תנועת GTM. הוא לא מתאר איך Superhuman בנתה ביקוש."},"9":{"0":"GTM רחב יותר מפרסום: הוא כולל גם קהל, ערוצים, מסר, תמחור ותזמון.","2":"זה לא סתם שם לפרסום. GTM מחבר את המוצר ללקוח: למי, באילו ערוצים, באיזה מסר ובאיזה מחיר.","3":"כל מוצר צריך דרך להגיע ללקוחות, בכל תקציב. מוצר מצוין עם GTM חלש לא מגיע לשום מקום."},"10":{"0":"הכלל לא עוסק בשיווק מול מוצר. הוא אומר שרוב עבודת ההשקה, QA, תמיכה ו-Analytics, קורית לפני היום עצמו.","2":"זו לא חלוקת תקציב. זה עניין של תזמון: 90% מהעבודה היא הכנה, כדי שיום ההשקה יעבור חלק.","3":"זה לא עוסק במי שמע מראש. זה עוסק בהכנה: QA, תמיכה מוכנה, Analytics ו-Rollback plan."},"11":{"1":"הם שונים בגודל ובמטרה: Soft Launch בודק יציבות בקבוצה קטנה, Beta אוסף פידבק מקבוצה גדולה יותר.","2":"אף אחד מהם לא קשור לפלטפורמה. ההבדל הוא בגודל הקבוצה ובמטרה: יציבות מול פידבק.","3":"זה מחליף ביניהם: הקבוצה הקטנה שבודקת יציבות היא Soft Launch; Beta גדולה יותר ואוספת פידבק."},"12":{"0":"להתחיל נמוך ולהעלות אחר כך זו טקטיקת חדירה, לא Anchoring. Anchoring מציג קודם את המחיר הגבוה.","2":"עיגון לעלות הפיתוח הוא Cost-plus. העוגן כאן הוא המחיר הראשון שהלקוח רואה.","3":"מחיר אחד לא משאיר עוגן להשוואה. Anchoring נשען על הצגה של נקודת ייחוס גבוהה קודם."},"13":{"0":"יותר חבילות לא מוסיפות הכנסות כשהלקוח לא מצליח לבחור. Choice Paralysis יכול להיגמר בלי רכישה בכלל.","2":"כלל האצבע הוא 3-4 חבילות לכל היותר. שבע יוצרות Choice Paralysis, לא אידיאל.","3":"הבעיה המרכזית היא הבחירה של הלקוח, לא התחזוקה. יותר מדי אפשרויות מקשות להחליט."},"14":{"0":"Van Westendorp שואל לקוחות על תפיסת מחיר; הוא לא מנתח את מחירי המתחרים.","2":"השיטה לא מחשבת עלות. היא שואלת ארבע שאלות על מתי מחיר מרגיש זול או יקר.","3":"משתמשים בה לפני קביעת תמחור, לא כדי לנתח המרה בדפים קיימים."}},"14":{"0":{"0":"10x הוא לא הרף. מעל 3x נחשב בריא ל-SaaS, ו-3.8x אפילו משאיר מקום להשקיע יותר בגיוס.","2":"1x פירושו שלקוח מחזיר רק את מה שעלה לגייס אותו: איזון במקרה הטוב. SaaS בריא מכוון ל-3x ומעלה.","3":"היחס הוא לב ה-Unit Economics: הוא מראה כמה מחזיר כל דולר שהושקע בגיוס. כאן $3.8 על כל $1."},"1":{"0":"פרסום ממומן מביא משתמשים, אבל לא משנה כמה כל משתמש מזמין. המקדם עולה דרך ה-Invite Flow.","2":"הנחות לא גורמות למשתמשים להזמין את הצוות. המקדם הוויראלי עולה כשההזמנה קלה וברורה יותר.","3":"עוד פיצ׳רים לא מעלים את מספר ההזמנות למשתמש. לולאת הצמיחה המרכזית כאן היא הזמנת הצוות."},"2":{"0":"ההשפעה לא ליניארית. Bain & Company מצאו ששיפור של 5% בשימור מעלה רווח ב-25-95%, כי לקוח קיים זול יותר.","1":"זה הרבה יותר מפי שניים: המחקר מראה 25-95%, כי לקוח קיים זול פי 5 מלקוח חדש.","3":"ההשפעה של שימור רחוקה משולית: שיפור של 5% יכול להעלות רווח ב-25-95%."},"3":{"0":"מתחת ל-1, כל משתמש מביא פחות ממשתמש חדש אחד, וההתפשטות דועכת. צמיחה אורגנית מהירה דורשת K מעל 1.","2":"0.8 פירושו שההמלצות לא מחליפות משתמש אחד באחד. התפשטות קבועה שמזינה את עצמה דורשת K מעל 1.","3":"K-factor סופר כמה משתמשים חדשים כל משתמש מביא, לא המרת מבקרים. 0.8 פירושו צמיחה שלא מזינה את עצמה."},"4":{"1":"זה לא AARRR. מדדי הפיראטים של McClure עוקבים אחרי המשתמש: Acquisition, Activation, Retention, Referral, Revenue.","2":"המונחים האלה מתארים תהליך התאוששות, לא שלבי צמיחה. AARRR עוקב אחרי משתמשים מ-Acquisition ועד Revenue.","3":"אלה מונחים של תשומת לב, לא השלבים של McClure. AARRR כולל Acquisition, Activation, Retention, Referral ו-Revenue."},"5":{"0":"North Star משקף ערך למשתמשים, לא פיננסים לטווח קצר. הכנסה חודשית היא מדד Lagging שלא לוכד את הערך.","2":"סך הנרשמים מתעלם מפעילות, מספר Vanity. North Star משקף את הערך שהמשתמשים מקבלים, כמו Nights Booked.","3":"ציון סקר הוא תקופתי ועקיף. North Star הוא מדד התנהגות של ערך, כמו Time Spent Listening."},"6":{"0":"ממוצע כללי מערבב ותיקים עם חדשים ומסתיר את השינוי. משווים מחזורים לפי חודש הצטרפות.","2":"סקר למשתמשים פעילים שומע רק את מי שנשאר. שימור לפי מחזור מראה את ההתנהגות של כל מי שהצטרף.","3":"הרשמות לא אומרות אם המשתמשים החדשים נשארים. ההשפעה של ה-Onboarding נראית בשימור של מחזור מרץ."},"7":{"0":"0.15 זה נמוך: רק 15% מהמשתמשים החודשיים מגיעים ביום נתון, מתחת ליעד הטיפוסי של 20-25%+.","2":"DAU/MAU מודד דביקות, לא צמיחה. גם מוצר שצומח מהר יכול להחזיק משתמשים שכמעט לא חוזרים.","3":"היחס לא משווה הרשמות לנטישה. הוא מודד כמה מהמשתמשים החודשיים חוזרים ביום נתון."},"8":{"0":"עם 80% Churn, עוד גיוס ממלא דלי מחורר. קודם מתקנים את הסיבה שאנשים עוזבים.","2":"השקעה שווה עדיין שופכת כסף לדלי שמאבד 80%. כאן השימור קודם.","3":"זה לא רק עניין של תקציב. עם 80% Churn, כסף הגיוס דולף החוצה, ולכן תיקון השימור קודם."},"9":{"1":"3 הוא מספר ההזמנות למשתמש, לא המקדם. מכפילים ב-30% שמצטרפים: 3×30% = 0.9.","2":"K הוא הזמנות כפול המרה: 3×30% = 0.9, לא 1.3. לא מוסיפים את המשתמש עצמו.","3":"0.3 הוא רק שיעור ההמרה. K מכפיל אותו ב-3 ההזמנות, כך ששני המנופים חשובים."},"10":{"0":"NRR סופר הכנסות, לא מספר לקוחות. Upsell מלקוחות קיימים יכול לדחוף אותו מעל 100%.","2":"Churn נמוך לבדו לא מעביר NRR מעל 100%. הלקוחות הקיימים צריכים גם להוציא יותר, דרך Upsell או Cross-sell.","3":"NRR לא כולל לקוחות חדשים. מעל 100% פירושו שהלקוחות הקיימים לבדם מגדילים את ההכנסות."},"11":{"0":"יום 1 חזק לא אומר הרבה כשיום 90 מגיע לאפס. השימור לא יתקן את עצמו; אף אחד לא מוצא ערך מתמשך.","2":"עקומות יורדות, אבל עקומה בריאה מתיישרת. עקומה שיורדת לאפס מראה שאף קבוצה לא נשארת, והתקציב ידלוף.","3":"משתמשים שמגיעים ועוזבים הם דלי מחורר, גם באפליקציה חינמית. העקומה מראה שאין ערך מתמשך."},"12":{"0":"אלה מדדים שונים: Activation הוא רגע הערך הראשון, Retention הוא חזרה לאורך זמן.","2":"הסדר לבדו הוא לא הסיבה. Activation מנבא Retention כי משתמש שחווה ערך נוטה לחזור.","3":"הכיוון הפוך: שיפור ב-Activation מנבא שיפור ב-Retention, לא להפך."},"13":{"1":"זה מחליף ביניהן: תבניות שמתפרסמות ונמצאות בחיפוש הן תוכן; הזמנה ישירה לחברי צוות היא ויראלית.","2":"אף אחת לא דורשת תקציב פרסום: שתיהן עוברות דרך משתמשים. תבניות מביאות מחיפוש, הזמנות מביאות ישירות.","3":"שתיהן אורגניות, אבל המנגנון שונה, ולכן גם המדדים והחוליה החלשה שצריך לתקן שונים."},"14":{"0":"צמיחה מצטברת משימור פירושה פחות הוצאה על כל דולר הכנסה, לא יותר. לקוח שנשאר ממשיך לשלם בלי עלות גיוס חדשה.","2":"מספר קבוע של נרשמים בכל חודש הוא צמיחה ליניארית. הצבירה מגיעה מלקוחות שנשארים ומתרחבים.","3":"השלב לא קושר צמיחה מצטברת לגודל צוות המכירות. היא מגיעה מלקוחות שנשארים, ממליצים ועושים Upsell."}},"15":{"0":{"0":"מנכ״ל קורא את שתי השורות הראשונות. מסמך של 5 עמודים בלי שורה תחתונה לא אומר לו מה מבקשים שיחליט.","2":"ציר זמן הוא כל המסע, והמנכ״ל צריך רק את ההחלטה, העלות והסיכון. השורה התחתונה נקברת בסוף.","3":"מגיעים עם בעיה ופתרון מומלץ, לא רק עם בעיה. שאלה פתוחה מעבירה למנכ״ל את כל העבודה בלי תוכנית ו-Trade-off."},"1":{"0":"״המנכ״ל ביקש״ היא סמכות מושאלת: היא מנצחת ויכוח אחד ומאבדת את הצוות לאורך זמן. חסרים נתונים ו-Trade-off.","2":"טובה אישית ולחץ רגשי לא נותנים ל-VP Eng הקשר להחליט. השפעה בנויה על נתונים ועל Business Impact.","3":"יום עבודה מגיע ממקום כלשהו. הסתרת ה-Trade-off יוצרת הפתעה בהמשך ופוגעת באמון, במקום לתת ל-VP Eng להחליט."},"2":{"0":"בלי תחקיר לא מבינים למה באג ידוע לא תוקן לפני ההשקה, ואותו משבר עלול לחזור.","2":"חיפוש אשם הוא ההפך מ-Blameless Post-mortem. המטרה היא לשפר את התהליך, לא למצוא מפתח שייקח אחריות.","3":"הנהלה צריכה BLUF, לא 10 עמודים. והמטרה היא שיפור תהליך עם הצוות, למשל DoD קפדני יותר, לא דוח."},"3":{"0":"ניהול צמוד מתאים לבעלי כוח ועניין גבוהים, כמו המנכ״ל. בעל עניין נמוך לא צריך עדכון כל בוקר.","1":"יש לו כוח רב על המוצר, ולכן אסור שיופתע. עדכון תמציתי ברגעים הנכונים, כמו תקציב וסיכון, שומר עליו מרוצה.","3":"דוחות שבועיים ומצגות חודשיות הם הצפה. לבעל כוח עם עניין נמוך מספיק עדכון תמציתי מדי פעם."},"4":{"0":"ב-RACI ה-C הוא Consulted: מי ששואלים לפני ההחלטה. מי שעוזר בעבודה עצמה הוא בעצם R.","2":"Reach, Impact ו-Confidence שייכים לתעדוף בנוסח RICE. RACI לא מתעדף, הוא מגדיר מי עושה מה בכל משימה.","3":"RACI לא עוקב אחרי סיכונים. הוא מגדיר ארבעה תפקידים לכל משימה או החלטה כדי למנוע בלבול בבעלות."},"5":{"0":"אתגור ישיר בלי אכפתיות נקרא Obnoxious Aggression. Radical Candor דורש את שני הצדדים יחד.","2":"אכפתיות בלי אתגור נקראת Ruinous Empathy. ריכוך או דילוג על ביקורת מונע מהאדם את מה שהוא צריך לשמוע.","3":"Radical Candor מחבר אכפתיות אישית עם אתגור ישיר. ביקורת מול כל הצוות לא משדרת אכפתיות כלפי האדם."},"6":{"0":"Competing מתאים למצבי חירום או להחלטה מוסרית ברורה, אבל הורס יחסים. PM לא מנהל אף אחד וצריך אותם גם מחר.","1":"Avoiding מתאים לנושאים לא חשובים או לזמן התקררות. כסגנון קבוע, בעיות לא נפתרות ורק מחמירות.","3":"Accommodating מתאים כשהנושא חשוב רק לצד השני. PM שתמיד מוותר מאבד כבוד במקום לבנות אמון."},"7":{"0":"״אתה לא מכבד אנשים״ הוא שיפוט, לא תיאור. משוב כזה מוביל לוויכוח מתגונן במקום לשיחה עניינית.","1":"זה SBI רק בשם: ״לאחרונה, בכמה ישיבות״ אינו מצב ספציפי, ו-״מזלזל״ הוא פרשנות ולא התנהגות שנצפתה.","3":"העלאת ההתנהגות של אדם אחד מול כל הצוות הופכת משוב להבכה. SBI הוא שיחה עניינית על מצב מסוים וקרוב."},"8":{"0":"כשהמנכ״ל שואל למה לסמוך על הנתונים, תחושת בטן לא עונה. אמון בנוי על שקיפות לגבי איך הנתונים נאספו.","2":"דוגמאות של מתחרים לא עונות על השאלה. המנכ״ל שאל על הנתונים שלכם, ולכן מציגים מתודולוגיה, מדגם ורמת ביטחון.","3":"בחירה רק בנתונים התומכים היא ההפך משקיפות. כשמישהו מגלה את מה שהושמט, האמון נשחק."},"9":{"0":"PM הוא מנהיג בלי סמכות, וזה כולל אחריות לדינמיקה של הצוות. התעלמות משאירה את חבר הצוות מחוץ לשיחה.","2":"העברה למנהל מדלגת על השיחה האישית. שיחה פרטית ואמפתית היא מה שיוצר Psychological Safety.","3":"לחץ לדבר מול כולם עלול להגביר את הסגירות. מוגנות פסיכולוגית נבנית בשיחה פרטית שבה מקשיבים מה חוסם."},"10":{"0":"טווח ההסכמה האפשרי בין הצדדים הוא ZOPA, לא BATNA. BATNA היא החלופה שלכם אם המשא ומתן נכשל.","2":"חלוקה באמצע בלי לבדוק אינטרסים היא טעות נפוצה: שני הצדדים נשארים עם חצי תפוז שאף אחד לא צריך.","3":"חשיפת האינטרס שמאחורי העמדה היא כלי אחר מ-Getting to Yes. BATNA עוסקת בחלופה שלכם, לא בצרכים של הצד השני."},"11":{"1":"שאלות טכניות הן לא הטעות, הן דרך להבין. קבלה מיידית וויתור על הפיצ׳ר הם בדיוק הטעות של ״לוותר״.","2":"הסלמה למנהל היא סמכות מושאלת והופכת שיחה לוויכוח. שואלים את המפתח מה כן אפשר ומחפשים חלופות יחד.","3":"חצי פיצ׳ר מיידי הוא חלוקה באמצע בלי לבדוק אינטרסים. קודם שואלים מה מדאיג ומה כן אפשר לבנות."},"12":{"0":"הבעיה היא לא הטון אלא האורך והפורמט: Slack מיועד לעד 3 משפטים, ומסמך מפורט שייך ל-Doc.","2":"פיצול ל-5 הודעות עדיין שם מסמך שלם ב-Slack. מה שמתאים לערוץ הזה הוא עד 3 משפטים, והפירוט עובר ל-Doc.","3":"BLUF עוזר, אבל 5 עמודים ב-Slack עדיין לא ייקראו. כלל הערוצים הוא: לא שולחים Doc ב-Slack."},"13":{"0":"זה הפוך: רכים בצורה, בשפה של ״אנחנו״, ותקיפים בתוכן. ויתור על העמדה המקצועית מפרק את ההחלטה עצמה.","2":"פגישה באמצע כשיש התנגדות מוותרת על התוכן. העיקרון הוא לשמור על העמדה כשהנתונים תומכים בה.","3":"העיקרון לא מעביר את ההחלטה למי שיש לו סמכות. PM מוביל בלי סמכות, ונשאר תקיף בעמדה המבוססת שלו."},"14":{"0":"Managing Up הוא עדכון שבועי קצר, לא דיווח יומי מפורט. המטרה היא למנוע הפתעות, לא להציג מאמץ.","2":"מגיעים עם בעיה ופתרון מומלץ, וזה מראה בעלות. מי שמעביר כל צעד להחלטת המנהל מקבל פחות אוטונומיה, לא יותר.","3":"Managing Up הוא תקשורת יעילה, לא חנפנות ולא מרוץ על קרדיט. העדכון היזום נועד לבנות אמון ולמנוע הפתעות."}},"16":{"0":{"0":"ספרינט הוא פרק זמן שבו הצוות בונה, לא ישיבה. התכנון הוא רק טקס הפתיחה שלו, ה-Sprint Planning.","2":"ספרינט הוא Time-box קבוע: הוא מסתיים בתאריך, גם אם לא כל הפריטים נכנסו. לא מאריכים אותו עד שהכול מוכן.","3":"ספרינט נמשך חודש או פחות, לרוב שבועיים, ומניב Increment שעובד. מסמך רבעוני הוא תכנון, לא ספרינט."},"1":{"0":"כמה פריטים נכנסים לספרינט מחליט הצוות, לא ה-PO. יעד Story Points שנכפה מבחוץ מוביל להתחייבות יתר.","2":"פירוק הפריטים למשימות והערכת המורכבות הם חלק ה-״איך״, וזה שייך לצוות הפיתוח, לא ל-PM.","3":"ה-PO לא מכתיב פתרונות טכניים. PM שמכתיב לצוות איך לפתח פוגע בביצועים ובתחושת הבעלות."},"2":{"0":"רשימת באגים היא ״רשימת קניות״ של טיקטים. Sprint Goal טוב מתאר תוצאה אחת למשתמש, לא רשימת פריטים.","2":"Sprint Goal נותן כיוון לצוות אחד בספרינט אחד. השוואה בין צוותים היא בדיוק השימוש הלא נכון במדדים.","3":"תאריך הסיום כבר קבוע ב-Time-box. ה-Goal מגדיר מה רוצים להשיג, וכך מאפשר לוותר על פריטים בלי לפספס אותו."},"3":{"0":"15 דקות הן המקסימום ל-Daily, לא בעיה. פגישה קצרה היא בדיוק מה שהטקס הזה אמור להיות.","1":"זו המטרה של ה-Daily: פגישת תיאום של הצוות עצמו. ה-PM מקשיב ומסיר חסמים, ולא מנהל אותה.","3":"Stand-up פירושו פגישה בעמידה, כדי שתישאר קצרה. זה חלק מהפורמט, לא Anti-pattern."},"4":{"0":"Review מציג את המוצר לסטייקהולדרים בדמו חי, לא בודק קוד. ו-Retro דן בתהליך, לא מתכנן Stories.","2":"זה הפוך: ב-Review מציגים את ה-Increment לסטייקהולדרים, וב-Retro הצוות דן בתהליך העבודה שלו.","3":"Retro לא מעריך כל מפתח, והוא על התהליך. Velocity הוא כלי תכנון, ומדידת מפתחים בודדים היא שימוש שגוי בו."},"5":{"0":"Velocity פשוט לחישוב: ממוצע ה-Story Points שהצוות משלים בספרינט. הבעיה היא מה קורה כשהופכים אותו ליעד.","2":"השלב לא קושר את Velocity לגודל הצוות. הוא כלי תכנון לכל צוות, והבעיה היא השימוש בו כמדד ביצועים.","3":"Velocity הוא כלי התכנון המרכזי של ספרינטים בסקראם, כלומר כלי אג׳ילי. הבעיה היא שימוש בו כמדד ביצועים."},"6":{"0":"ה-Buffer של 20% נועד לבאגים דחופים ולעזרה הדדית, לא לבקשות חדשות. ״דבר קטן״ באמצע הספרינט פוגע ביציבות.","2":"רק ה-PO מבטל ספרינט, ורק כשה-Sprint Goal כבר לא רלוונטי. בקשה קטנה של סטייקהולדר לא מצדיקה את זה.","3":"ספרינט הוא Time-box קבוע ולא מאריכים אותו. גם בצוות של מיכל ועידו לא הוארך הספרינט, אלא דחו פריט."},"7":{"0":"ה-DoD כולל בדיקות שעברו, ולכן מיזוג קוד לבד לא מספיק. דחיית הבדיקות לספרינט הבא יוצרת חוב טכני.","2":"ה-DoD הוא הסכמה של כל הצוות שחלה על כל פריט. ה-PO לא מוותר על סעיפים כדי לסגור ספרינט בזמן.","3":"אין ״גמור חלקית״: פריט עומד ב-DoD או שאינו גמור. חצי נקודות מנפחות את התמונה ומסתירות את העבודה שחסרה."},"8":{"0":"ספרינט שנכשל הוא הזדמנות ללמידה. ענישה וקיצוץ Velocity מעבירים מסר של אשמה במקום לברר למה זה קרה.","2":"השלב מדגיש שכישלון ספרינט זה בסדר, והחשוב הוא להבין למה. חיפוש אשמים לא עונה על השאלה הזו.","3":"דווקא אחרי כישלון הרטרו הכי חשוב: שם מבינים מה השתבש. דילוג על רטרו הוא Anti-pattern מפורש בשלב."},"9":{"0":"קגן מדגיש העצמה של הצוות: ה-PM מגדיר מה ולמה, והצוות מחליט איך. PM שאומר לכולם מה לעשות פוגע בבעלות.","2":"ה-PM לא כותב את הקוד. ה-״איך״ שייך למפתחים, ותפקיד ה-PM הוא להגדיר את הבעיה ואת הערך.","3":"ה-PO מציג פריטים ב-Planning, זמין לשאלות ומאשר את ה-Increment ב-Review. ויתור על הטקסים מנתק אותו מהצוות."},"10":{"0":"לפי ה-Scrum Guide ה-Scrum Master לא מבטל ספרינט. גם צוות שלא עומד ביעדים לא מבטל, אלא לומד ברטרו.","2":"ההנהלה לא מוסמכת לבטל ספרינט לבד. אם שינוי אסטרטגי הופך את ה-Sprint Goal ללא רלוונטי, ההחלטה של ה-PO.","3":"ב-Scrum Guide אין הצבעה על ביטול. רק ה-PO מבטל, ורק כשה-Sprint Goal איבד רלוונטיות."},"11":{"0":"שיפור אמיתי בא בדרך כלל בהדרגה. קפיצה של 50% מיד אחרי שהתחילו לדרג לפי Velocity מצביעה על ניפוח.","2":"כלי חדש לא מסביר קפיצה של 50% בדיוק כשהתחיל הדירוג. התזמון מצביע על Goodhart: המדד הפך ליעד.","3":"הסרת חסמים משפרת בהדרגה. קפיצה חדה מיד עם תחילת הדירוג, באותו צוות, היא הסימן הקלאסי ל-Story Point Inflation."},"12":{"0":"ב-Scope Creep הקו עולה במקום לרדת, כי נוספים פריטים. כאן הקו שטוח ואז צונח, וזה דפוס אחר.","2":"Early Finish הוא קו שמגיע לאפס מוקדם מדי. כאן הקו מגיע לאפס רק ביום האחרון, אחרי ימים בלי התקדמות.","3":"הדפוס האידיאלי הוא ירידה אלכסונית חלקה. אינטגרציה שנדחית ליום האחרון היא הבעיה, לא התוכנית."},"13":{"0":"Scrum of Scrums לבדו לא מספיק ל-6 צוותים בלי פריימוורק תומך, ובשלב הוא מומלץ 2-3 פעמים בשבוע, לא פעם אחת.","1":"SAFe בנוי לעשרות ומאות צוותים ומוסיף שכבות של תהליכים ותפקידים. ל-6 צוותים זה Overhead מיותר.","3":"Kanban מתאים לעבודה לא צפויה כמו תמיכה, לא למספר הצוותים. LeSS מראה ש-6 צוותים כן מתכננים ספרינט משותף."},"14":{"0":"גם ספרינט של שבוע דורש Sprint Goal יציב ותכנון מראש, וזה לא אפשרי עם 15-20 באגים דחופים שמגיעים בכל שבוע.","2":"SAFe הוא פריימוורק לתיאום עשרות צוותים, לא פתרון לעבודה לא צפויה של צוות תמיכה אחד.","3":"Scrumban נשמע מפתה, אבל בפועל מסבך את שני הפריימוורקים ומתאים יותר לצוותים במעבר."}},"17":{"0":{"0":"הבעלות הפוכה כאן: ה-Product Backlog שייך ל-PO, וה-Sprint Backlog שייך לצוות הפיתוח.","2":"ההבדל הוא בהיקף, לא בסוג הפריט. שני הבקלוגים יכולים לכלול פיצ׳רים, באגים וחוב טכני.","3":"זה הפוך: ה-Product Backlog הוא מסמך חי שמשתנה תמיד, וה-Sprint Backlog קבוע במהלך הספרינט."},"1":{"0":"Given-When-Then הוא פורמט של Acceptance Criteria. הוא בודק התנהגות, אבל לא אומר מי המשתמש ולמה הוא צריך את זה.","2":"״המערכת תאפשר״ הוא ניסוח של דרישה טכנית. אין בו משתמש מסוים ואין בו את הערך שהוא מקבל.","3":"פירוק לרכיבים ולשעות הוא Task של המפתחים, ה-״איך״. בדיוק מזה עידו ביקש לצאת כדי להבין את הצורך."},"2":{"0":"INVEST של Bill Wake מתאר תכונות של Story טובה. Input, Scope ו-Track הם לא חלק ממנו, ו-T הוא Testable.","2":"Story לא חייבת להיות חדשנית או ויזואלית. ב-INVEST ה-V הוא Valuable וה-S הוא Small, קטנה מספיק לספרינט.","3":"ב-INVEST ה-T הוא Testable, לא Technical. Story טכנית בלי ערך למשתמש היא דווקא בעיה לפי ה-V."},"3":{"0":"החלקים התחלפו: הלחיצה היא הפעולה ושייכת ל-When. ו-״מהירה ויציבה״ היא תוצאה שאי אפשר לבדוק.","2":"״הוא מרוצה״ היא לא תוצאה שאפשר לבדוק. Then צריך לתאר משהו שקורה במערכת ושעידו יכול לאמת.","3":"Then שמתאר מימוש הוא Over-specification: הוא לוקח מהמפתח את ה-״איך״ ולא מתאר תוצאה שאפשר לבדוק."},"4":{"0":"״מהירה, פשוטה ומאובטחת״ אי אפשר למדוד. AC טוב נותן ערכים שאפשר לבדוק, כמו זמן הגעה ותוקף.","2":"קריאה לשירות דרך Endpoint היא פרט מימוש, ה-״איך״. AC מתאר את ההתנהגות שהמשתמש רואה.","3":"Code Review ו-CI שייכים ל-Definition of Done, שחל על כל Story. AC צריך להיות ספציפי לסטורי הזה."},"5":{"0":"מטריצת ערך-מאמץ מתעדפת פריטים בודדים. היא לא מראה את זרימת המשתמש, ולכן לא מגלה מה חסר לגרסה מקצה לקצה.","2":"WSJF ממיין פריטים בודדים לפי ציון. הוא נשאר רשימה שטוחה, ולא מראה אילו Stories יוצרות יחד זרימה שלמה.","3":"Burndown עוקב אחרי התקדמות בתוך ספרינט. הוא לא עוזר להחליט אילו Stories נכנסות ל-MVP."},"6":{"0":"את ה-Tasks מפרק צוות הפיתוח, לא ה-Scrum Master. וה-PM כותב גם User Stories, לא רק Epics.","2":"פתרון טכני ב-AC הוא Over-specification. ה-AC מתאר התנהגות, וה-״איך״ נשאר למפתחים.","3":"זה הפוך: ה-PM כותב את ה-User Stories, מה ולמה. ה-Tasks והסדר שלהם הם עבודת הצוות."},"7":{"0":"פירוט של פריטים רחוקים הוא בזבוז: הם ישתנו או לא ייבנו בכלל. לפי Pichler מפרטים רק את מה שבא בקרוב.","2":"בלי פריטים מוכנים בראש הבקלוג ה-Planning נתקע. ה-20% העליונים צריכים AC כבר לפני שהספרינט מתחיל.","3":"Epics גדולים יושבים בתחתית הקרחון ככותרות. מפרטים לפי קרבה לראש הבקלוג, לא לפי גודל הפריט."},"8":{"0":"טיקט טכני בלי הקשר עסקי הוא Anti-pattern אחר. ״Epic בתחפושת״ עוסק בגודל: פרויקט שלם בכסות של Story.","2":"AC עמומים כמו ״המערכת תהיה מהירה״ הם Anti-pattern נפרד. ״Epic בתחפושת״ הוא טיקט ענק שצריך לפרק.","3":"Story שמכתיבה קוד היא Over-specification, Anti-pattern אחר. ״Epic בתחפושת״ הוא טיקט גדול מדי לספרינט."},"9":{"0":"לפי Patton, Story היא הזמנה לשיחה, לא מסמך מושלם. אם ה-PM והצוות לא דיברו עליה, הם לא באמת מבינים אותה.","2":"ב-INVEST ה-N הוא Negotiable: Story פתוחה לשיחה ואינה חוזה. PM שלא מוכן לשנות פרטים יוצר בעיה.","3":"Story מזמינה שיחה עתידית בין ה-PM לצוות. היא לא תיעוד של שיחה שכבר הייתה עם משתמש."},"10":{"0":"WSJF לא מסתכל רק על Cost of Delay אלא מחלק אותו במשך: 30/13 הוא בערך 2.3, פחות מ-24/8 שהוא 3.0.","2":"WSJF הוא חישוב פשוט, לא מבחן סטטיסטי. החלוקה במשך נותנת 3.0 מול 2.3, ולכן הם לא שווים.","3":"הנוסחה צריכה רק Cost of Delay ו-Duration, ושניהם נתונים. Velocity ומספר מפתחים לא נכנסים לחישוב."},"11":{"0":"Edge Cases מגדירים מה קורה במצבי קצה של הפיצ׳ר עצמו. הם לא אומרים מה לא לבנות, כמו ייצוא ל-Excel.","2":"Context מסביר את ה-״למה״ ומי ביקש. הוא לא מסמן איפה העבודה נגמרת, ולכן לא עוצר תוספת של Excel.","3":"מוקאפ מראה איך המסך ייראה. הוא לא אומר במפורש מה לא כלול בטיקט, ולכן לא מונע הרחבה של ההיקף."},"12":{"0":"200 פריטים מפורטים מראש הם בזבוז על פריטים שכנראה לא ייבנו, ובקלוג לפי סדר הגעה הוא בקלוג בלי תעדוף.","2":"פירוט של כל הפריטים סותר את עקרון הקרחון, ופריטים ישנים שנשמרים ״למקרה״ הופכים לרעש. מיון לפי תאריך אינו תעדוף.","3":"ה-Product Backlog הוא מסמך חי שמשתנה תמיד. סדר קבוע לרבעון ופריטים שלא יוצאים לעולם הופכים אותו לנטל."},"13":{"0":"Dual-Track מבוסס על Evidence. בנייה בניגוד לנתונים מבזבזת Delivery על פיצ׳ר שמשתמשים כבר הראו שלא ירצו.","2":"הרצה חוזרת רק כי התוצאה לא נוחה מתעלמת מה-Evidence. הנתונים נועדו לפתוח שיחה עם המנכ״ל, לא להיעלם.","3":"ל-Delivery Backlog עוברים רק פריטים שעברו אימות חיובי ב-Discovery. פשרה ארגונית עוקפת את העיקרון הזה."},"14":{"0":"״הלקוח תמיד קודם״ הוא כלל גס. גם לחוב הטכני ולשיפור ה-UX יש Cost of Delay, וההחלטה תלויה בחישוב.","2":"חוב טכני לא תמיד קודם. ה-deadline של לקוח ה-Enterprise וה-8% המוכחים הם Cost of Delay שצריך לשקלל.","3":"A/B Test מוכיח ערך, אבל לא את ה-Time Criticality של ה-deadline או את ההאטה של 20%. צריך להשוות את שלושתם."}},"18":{"0":{"0":"Git Tag משמש עוגן פנימי לחזרה לקוד. המשמעות העמוקה של המספר היא כלפי מי שצורך את התוכנה: מה השתנה והאם בטוח לשדרג.","2":"השלב מזהיר מ-״גרסה 2.0״ שיווקית: קפיצה כי זה נשמע טוב שוברת את משמעות המספר.","3":"תאריך שחרור הוא רק מה ש-CalVer מספר. המספר משמש קודם כול חוזה: מה השתנה, וכמה בטוח לשדרג."},"1":{"0":"ב-SemVer הגודל של הפיצ׳ר לא קובע. MAJOR עולה רק על שינוי שובר תאימות, ופיצ׳ר גדול ותואם הוא MINOR.","2":"הכול זז דרגה: פיצ׳ר חדש ותואם הוא MINOR, תיקון באג הוא PATCH, ו-MAJOR שמור לשינוי שובר.","3":"שנה וחודש במספר הם CalVer, לא SemVer. ב-SemVer כל רכיב מתאר את סוג השינוי ואת התאימות לאחור."},"2":{"0":"השלב מזהיר מקפיצה שיווקית ל-2.0 בלי Breaking Change אמיתי: היא שוברת את המשמעות של המספר.","2":"השאלה היא אם משתמש קיים יצטרך לשנות משהו, לא כמה ספרינטים זה לקח. פיצ׳ר גדול ותואם הוא MINOR.","3":"תיקוני באגים תואמים, גם הרבה מהם, נשארים ב-PATCH. רק שינוי שעלול לשבור קוד קיים מעלה MAJOR."},"3":{"0":"MAJOR עולה רק כשמשהו קיים נשבר. שדה אופציונלי חדש לא מחייב משתמש קיים לשנות כלום.","1":"PATCH שמור לתיקון באג. שדה חדש הוא יכולת חדשה ותואמת, ולכן הוא MINOR.","3":"MINOR נכון, אבל כשמעלים MINOR ה-PATCH מתאפס. 1.5.2 מדלג על הכלל הזה."},"4":{"0":"0.y.z לא אומר מי משתמש במוצר. הוא מסמן פיתוח ראשוני שבו אין הבטחת יציבות. לבדיקות פנימיות יש תווית alpha.","2":"בגרסת 0 ה-API עוד לא נחשב יציב, ואפילו MINOR יכול לשבור. ההתחייבות ליציבות מתחילה רק ב-1.0.0.","3":"בגרסת 0 אין הבטחת תאימות בכלל, ולכן גם MINOR יכול לשבור. ה-0 לא מעיד שעוד לא היה Breaking Change."},"5":{"0":"זה הפוך: גרסת Pre-release תמיד ״קטנה״ מהגרסה הסופית, ולכן 1.0.0 הסופית היא הגבוהה מכולן.","2":"1.0.0 הסופית גבוהה מכל Pre-release, ו-alpha היא הנמוכה ביותר. הסדר כאן מבולבל.","3":"הסיומת כן משפיעה על הסדר: alpha קטנה מ-beta, שקטנה מ-rc. רק Build Metadata אחרי + לא משפיע."},"6":{"0":"22.04 הוא שנה וחודש. מספר CalVer לא אומר דבר על תאימות לאחור, ולכן אי אפשר לזהות ממנו Breaking Change.","2":"מספר רץ הוא 1, 2, 3. כאן המספר מורכב משנה וחודש, אפריל 2022, וזה בדיוק CalVer.","3":"Hash הוא מזהה commit ארוך שלא קריא לבני אדם. 22.04 הוא מספר קצר וקריא שמבוסס על תאריך."},"7":{"0":"זה הפוך: לספרייה ש-API אחרים תלויים בו התאימות קריטית, ולכן SemVer. אפליקציית SaaS יכולה להסתפק ב-CalVer.","2":"הבחירה תלויה במי שצורך את התוכנה, לא בלוח זמני השחרור. השלב מזהיר מבחירת מודל בלי לחשוב על הצרכן.","3":"קוד פתוח מול מסחרי זה לא הקריטריון. השאלה היא אם יש צרכנים שתלויים בתאימות, כמו ספרייה או API."},"8":{"0":"שינוי שם של שדה הוא Breaking Change, ולכן לעולם לא MINOR. Changelog מפורט לא מונע מהאינטגרציה להישבר.","2":"שבוע בלי הודעה נוספת זה לא תקופת Deprecation. בדרך כלל נותנים 6-12 חודשים, הודעה מראש ומסלול מעבר.","3":"Canary תופס באגים מוקדם, אבל השינוי עדיין שובר את ה-5% בלי אזהרה. לשינוי שובר צריך גרסה חדשה והודעה מראש."},"9":{"0":"זה הפוך: Changelog נכתב למפתחים, מדויק ותמציתי. Release Notes נכתבים ללקוחות ומתמקדים בערך.","2":"ההבדל הוא בקהל, לא בסוג הגרסה. Changelog כולל גם Added ו-Removed, לא רק תיקוני באגים.","3":"שני המסמכים מתעדים מה שכבר שוחרר. Changelog הוא לא תוכנית לגרסאות הבאות."},"10":{"0":"Deprecation לא חוסם מיד, וגם לא נמשך בלי סוף: היכולת עוד עובדת, ומודיעים מראש שתוסר בגרסה עתידית.","2":"תיעוד בדיעבד הוא בדיוק ״שדרגנו והפיצ׳ר פשוט נעלם״. Deprecation בא לפני ההסרה, עם זמן להסתגל.","3":"Feature Flag היא שיטת שחרור שמסתירה קוד. כיבוי הדרגתי בלי הודעה מראש לא נותן למשתמשים זמן להסתגל."},"11":{"0":"לא כל commit מעלה PATCH: fix מעלה PATCH, feat מעלה MINOR, ו-docs לא משנה את הגרסה בכלל.","2":"Conventional Commits מבוססים על קידומות שמתארות את סוג השינוי, לא על חותמות זמן. החישוב הוא לפי SemVer.","3":"מספר טיקט לא אומר אם השינוי הוא תיקון, פיצ׳ר או שינוי שובר. הקידומת היא שמאפשרת לחשב את הגרסה."},"12":{"0":"המספר הוא חוזה, לא סלוגן. קפיצה מזויפת ל-5.0 פוגעת באמון המפתחים בכל שיטת הגרסאות, גם אם יש Release Notes.","2":"Breaking Change ב-PATCH הוא ההפתעה שהורסת אמון. מי שישדרג בביטחון לגרסה ״קטנה״ יגלה שהקוד שלו נשבר.","3":"מספר הגרסה נקבע לפי כללי SemVer, לא בהצבעה. יש Breaking Changes, ולכן הגרסה היא MAJOR."}},"19":{"0":{"0":"ההבחנה של Karpathy לא עוסקת באיפה התוכנה רצה, אלא במי שכותב את הכללים: מתכנת, או רשת שלומדת מנתונים.","2":"חיבור לרשת ול-API חיצוניים הוא לא ההבדל. ב-Software 2.0 המתכנת נותן נתונים ומבנה רשת, והרשת לומדת את הכללים.","3":"רישוי ותשלום לא קשורים להגדרה. ההבדל הוא בין כללים מפורשים שנכתבים ביד לבין כללים שנלמדים מנתונים."},"1":{"0":"המודל לא מחפש באינטרנט בזמן אמת. הוא מנבא את ה-Token הבא לפי מה שלמד באימון, ולכן משלבים RAG כשצריך מידע עדכני.","2":"אין למודל מאגר תשובות מוכנות. כל תשובה נבנית Token אחרי Token, כניבוי סטטיסטי של מה שסביר שיבוא.","3":"כללים לוגיים שמתכנת הגדיר מראש הם Software 1.0. מודל שפה למד דפוסים מנתונים ומנבא, הוא לא מריץ כללים."},"2":{"0":"כיוון הכתיבה לא משנה למודל. הבעיה היא שה-Tokenizer אומן בעיקר על אנגלית, ולכן מפרק עברית ליותר Tokens.","2":"מודלים כן מייצרים טקסט עברי קוהרנטי. הבעיה היא העלות: אותו טקסט בעברית מתפרק ליותר Tokens.","3":"המודלים מעבדים עברית ישירות, בלי תרגום. ההבדל הוא שאותו טקסט צורך יותר Tokens, ולכן עולה יותר וממלא את ה-Context מהר יותר."},"3":{"0":"זה הפוך: Training נמשך שבועות עד חודשים על אלפי GPU, ו-Inference לוקח בדרך כלל שניות לכל בקשה.","1":"Training עולה מיליוני דולרים ולכן רוב הסטארטאפים לא מאמנים מאפס. Inference עולה סנטים עד דולרים לקריאה.","3":"אלה שני שלבים שונים: Training לומד את המשקלים פעם אחת, ו-Inference משתמש במודל המאומן בכל בקשה של משתמש."},"4":{"0":"בנייה מאפס מתאימה רק לחברות AI גדולות: יקרה מאוד ודורשת צוות מחקר. Karpathy ממליץ להתחיל מ-API ולהוכיח ערך.","2":"Fine-tuning הוא השלב היקר מבין השלושה, ומגיעים אליו רק אם גם RAG לא מספיק. מהיום הראשון זה מדלג על הזול והמהיר.","3":"הכלל הוא להתחיל עכשיו עם API קיים ולהוכיח ערך. המתנה לדור הבא של מודלים לא מופיעה בגישה המדורגת."},"5":{"0":"הזיה היא לא קריסה או באג בקוד. המודל עונה כרגיל, אבל המידע שהוא מציג בביטחון פשוט שגוי.","2":"שגיאות כתיב קל לזהות. הזיה מסוכנת דווקא כי היא נשמעת אמינה: ציטוטים ומקורות מומצאים שנאמרים בביטחון.","3":"הודעת שגיאה מהשרת היא בעיה טכנית שגלויה למשתמש. הזיה היא תשובה רגילה למראה שמכילה מידע שגוי."},"6":{"0":"גם מודל גדול יותר מנחש: הסטטוס העדכני לא נמצא במה שלמד באימון. השיפור הגיע מהזנת הסטטוס מה-DB כעובדה.","2":"יותר Tokens בלי המידע הנכון רק מייקרים כל קריאה. מה שחסר למודל הוא הסטטוס האמיתי ממקור אמין.","3":"תיקון ידני של כל תשובה הוא עבודה אנושית אחרי הטעות. RAG מונע אותה מראש, כי המודל מקבל את הסטטוס כעובדה."},"7":{"0":"בחירת מודל חשובה, אבל קודם צריך לדעת אם המוצר משתלם: כל קריאה עולה כסף, וב-100K משתמשים זה מצטבר מהר.","2":"שפת תכנות ו-Framework הם החלטות של הצוות. השיקול הייחודי למוצר AI הוא עלות ה-Inference לכל אינטראקציה.","3":"רוב הסטארטאפים משתמשים במודל קיים דרך API ולא מאמנים בעצמם. השאלה הראשונה היא אם ה-Revenue מכסה את עלות השימוש."},"8":{"0":"זו שאלת ״איזה AI״ לפני ״למה AI״. AI הוא כלי, וקודם צריך לזהות בעיה ש-AI פותר טוב יותר מפתרון קלאסי.","2":"תקציב הוא שאלה של המשך. בלי בעיה מוגדרת אין לפי מה להעריך אם העלות שווה משהו למשתמשים.","3":"לוח זמנים לשילוב מניח שכבר ברור מה בונים. השאלה הראשונה היא איזו בעיה של המשתמשים ה-AI יפתור."},"9":{"0":"ההבדל מהותי: Fine-Tuning מאמן את המודל עצמו על נתונים חדשים, ו-Prompt Engineering רק משנה את ההוראות למודל קיים.","2":"Prompt Engineering הוא הדרך הזולה והמהירה. היקר מבין השניים הוא Fine-Tuning, שדורש נתונים ועלות אימון.","3":"Fine-Tuning הוא אימון נוסף על הנתונים שלכם, ולכן הוא דווקא דורש נתונים. בלי נתונים אין על מה לאמן."},"10":{"0":"בלי מסמכי המדיניות האמיתיים המודל מנחש מהידע הכללי שלו, וזה בדיוק המצב שבו הוא ממציא מדיניות.","2":"Fine-tuning מתאים לסגנון או התנהגות מסוימים, והוא יקר. למידע ארגוני ועדכני, RAG נותן את המסמך עצמו כעובדה.","3":"בניית מודל מאפס מתאימה רק לחברות AI גדולות. כאן מספיק לתת למודל קיים את המסמכים הנכונים."},"11":{"1":"המודל למד גם חשיבה וקוד, לא רק טקסט. הבעיה היא שהמילה מגיעה אליו כ-Tokens, והוא לא רואה כל r בנפרד.","2":"המילה קצרה מכדי שהזיכרון יהיה הבעיה. המודל פשוט לא רואה אותיות בודדות, רק Tokens שהם חלקי מילים.","3":"אף מילה לא מוסרת מנתוני האימון כדי לחסוך מקום. הקושי נובע מה-Tokenization, שמחלק מילים לחלקים ולא לאותיות."},"12":{"0":"תשובה ארוכה לא מבטיחה Engagement. מה שבטוח הוא שכל Token שהמודל מייצר עולה כסף, ב-50K משתמשים.","2":"אורך התשובות לא משפיע על האימון, שקורה פעם אחת. הוא משפיע על ה-Inference, שמשלמים עליו בכל קריאה.","3":"תשובות ארוכות אכן ממלאות את ה-Context, אבל ההשלכה העיקרית היא כספית: כל Token שמיוצר עולה כסף."},"13":{"0":"הסיבה היא לא אימוץ טכנולוגיה. בתחום משפטי הזיה, כמו ציטוט חוק שגוי, עלולה לגרום נזק ממשי ללקוח.","2":"הבעיה היא לא שפה. גם בקריאה מושלמת המודל עלול להמציא פסיקה בביטחון, ולכן אדם צריך לאמת.","3":"השלב לא מסתמך על רגולציה כזו. הסיבה היא מהות התחום: הזיה במידע שאנשים מסתמכים עליו מסוכנת."},"14":{"0":"חוסר דטרמיניזם הוא תכונה מובנית של מודלי AI, לא באג. הספק לא יתקן אותו, ולכן מתכננים חוויה שמתמודדת איתו.","2":"Fine-tuning יקר ומתאים לסגנון או התנהגות. הוא לא הופך תכונה מובנית של המודל לדטרמיניסטית.","3":"הקפאת התשובה הראשונה מסתירה את התכונה במקום לתכנן לה, ותשובה ראשונה חלשה תישאר לתמיד בלי אפשרות לנסות שוב."},"15":{"0":"Clustering מוצא קבוצות בלי תווית מראש. כאן יש תווית ידועה, ביטל או לא ביטל, ולכן זה Classification.","2":"Regression מנבא מספר רציף כמו מחיר. השאלה כאן היא כן או לא, וגם המחיר שהלקוח ישלם לא נשאל בכלל.","3":"Object Detection הוא משימת ראייה שמאתרת אובייקטים בתמונה. אין כאן תמונות, יש ניבוי של עזיבה."},"16":{"0":"Baseline הוא מושג אחר: התוצאה הפשוטה שהמודל צריך לנצח. Ground Truth הוא התווית הנכונה שמולה בודקים כל ניבוי.","2":"אחוז הניבויים הנכונים הוא Accuracy, מדד שמחושב מול ה-GT. וגם לא הוא ה-KPI הראשי: PM מגדיר KPI עסקי.","3":"Ground Truth הוא התווית עצמה, לא הנתונים הגולמיים לפני התיוג. איכות התיוג, לא כמות הנתונים, קובעת את התקרה."},"17":{"0":"STT רגיל מחזיר טקסט בלבד. זיהוי מי דיבר מתי הוא יכולת נפרדת, Speaker Diarization, שצריך לדרוש במפורש.","2":"TTS הופך טקסט לקול, הכיוון ההפוך. בפגישה יש הקלטת קול שצריך להפוך לטקסט ולפצל לפי דובר.","3":"Object Detection מאתר אובייקטים בתמונה. זיהוי דוברים בהקלטה הוא משימת אודיו, לא משימת ראייה."},"18":{"0":"מדעני הנתונים מחליטים מה רלוונטי, לא ה-PM. טבלה ״לא רלוונטית״ יכולה להסתיר קורלציה מפתיעה או פיצ׳ר חזק.","2":"אי אפשר לבקש טבלה שלא יודעים שקיימת. בלי התמונה המלאה גם קשה לזהות Data Leakage ולבנות פיצ׳רים.","3":"ב-CRISP-DM הבנת הנתונים באה לפני ה-Modeling. דווקא בשלבים המוקדמים, כמו EDA, צריך את כל הטבלאות."},"19":{"0":"CRISP-DM הוא מחזורי, לא לינארי: חוזרים אחורה לפי הצורך, למשל מ-Evaluation חזרה להבנה העסקית.","2":"חמש השאלות לחקירת נתונים לפני מודל הן EDA. CRISP-DM הוא כל התהליך, שישה שלבים מהבנת הבעיה ועד Deployment.","3":"מדדים כמו Accuracy ו-AUC-ROC שייכים לשלב ה-Evaluation בלבד. CRISP-DM הוא מתודולוגיה של כל הפרויקט."},"20":{"0":"עוד צילומים עם אותן תוויות משמרים את אותו קיצור דרך. רק רופא, עם ידע בתחום, זיהה מה המודל באמת למד.","2":"הקיצור עובד מבחינה טכנית ונותן דיוק גבוה, ולכן רשת עמוקה יותר לא בהכרח תוותר עליו. רופא חשף אותו.","3":"הקיצור עובד גם על נתוני הבדיקה, ולכן גם מדד אחר היה נראה טוב. הבעיה נחשפה בבדיקה של רופא, לא בטבלת מדדים."}},"20":{"0":{"0":"יש משתמשים אמיתיים: הלוחם בשטח, בים, באוויר או בגבול. הקושי הוא להגיע אליהם, לא שהם לא קיימים.","2":"העקרונות דומים, אבל היישום שונה מאוד: רגולציה, סיווג, רכש ארוך ודרגים רבים מחייבים להתאים כמעט כל כלי מוכר.","3":"החייל רוצה מערכת פשוטה, מהירה ואמינה, ובונים למקרה הגרוע: בחושך, בגשם, עם כפפות. UX קריטי, לא מיותר."},"1":{"0":"הרבה מערכות צבאיות לא מחוברות לאינטרנט, ולכן אין בהן כלי Analytics. נתוני שימוש מהשטח בדרך כלל לא זמינים.","1":"קשה לתאם ראיון של 45 דקות עם לוחם בתפקיד. ולפי השלב, שעה בתחקיר מבצעי שווה עשרה ראיונות.","3":"NPS הוא כלי משוב אזרחי. בשטח המשוב מגיע מתחקירים ודיווחים, ולפעמים רק בעל פה, ושם שומעים מה באמת נכשל."},"2":{"0":"ICD מתאר איך המערכת מדברת עם מערכות אחרות. הוא לא מתאר איך המערכת נכנסת למשמרת ולנהלים בשטח.","2":"STR מפרט עוד דרישות טכניות. מנהל התפעול לא שאל מה המערכת עושה, אלא איך משתמשים בה בפועל.","3":"Traceability Matrix מקשרת כל דרישה לצורך, לבדיקה ולרכיב. היא לא מתארת את תמונת השימוש במשמרת סוערת."},"3":{"0":"התקציב הוא לא הסיבה. גם עם תקציב אי אפשר להריץ שתי גרסאות במקביל בקרב ולסכן את המשימה בשביל ניסוי.","1":"החוזה לא הסיבה. A/B Test דורש להריץ גרסאות שונות במקביל, ובסביבה מבצעית המערכת חייבת לעבוד באופן אחיד.","3":"תרגילים וסימולציות הם בדיוק הכלים שבהם מתקפים מערכת צבאית. הבעיה היא ניסוי מבוקר בקרב, לא איסוף נתונים בתרגיל."},"4":{"0":"זה הפוך: FAT נעשה במפעל, בסביבה מבוקרת, ו-SAT נעשה באתר האמיתי, בתנאי שטח.","2":"סקירות תכנון על הנייר ולפני ייצור הן PDR ו-CDR. FAT ו-SAT הם מבחני קבלה של מערכת שכבר נבנתה.","3":"Red Team הוא צוות שמנסה לשבור את המערכת, כלי נפרד. FAT ו-SAT נבדלים במיקום: מפעל מול אתר."},"5":{"0":"תוספת על עלות הפיתוח לא מכסה את השאר. פיתוח הוא רק 20-30% מה-TCO, והשאר הוא אינטגרציה, הדרכה ותחזוקה לאורך שנים.","2":"מחיר רישיון לא ממפה את עלויות מחזור החיים: אינטגרציה, הדרכה, אישורי אבטחה ופירוק בסוף. זה בדיוק ה-״שאר״.","3":"מי שמתמקד רק בעלות הפיתוח מפספס כ-70% מהתמונה. מנהל הפרויקט שאל בדיוק על החלק החסר."},"6":{"0":"התקציב קבוע ואין שקל נוסף. הסבר על ערך לא משנה תקרה מאושרת, ולכן צריך לתכנן בתוכה.","2":"הורדת מחיר בלי לצמצם היקף רק מעבירה את החריגה לדמי התחזוקה. התקציב עדיין לא מכסה את כל הרשימה.","3":"TCO מראה עלות לאורך זמן, אבל לא משנה תקציב קבוע של 2.5 מיליון. ההצעה עדיין חורגת מהתקרה."},"7":{"0":"מפקד בכיר הוא רק דרג אחד. בפרויקט צבאי יש לפחות 6 קבוצות, ולדרג התקציב, למשל, יש כוח לעצור פרויקט.","1":"צוות הפיתוח והספק הם רק חלק מהתמונה. בלי המשתמש, הלוגיסטיקה והתקציב, מוצר מבריק יכול להיכשל.","3":"המשתמש בשטח חשוב, אבל המפקד מחליט, המדינה רוכשת והאוצר מממן. מי שמדבר רק איתו מפספס את מקבלי ההחלטות."},"8":{"0":"מפקד בכיר מתעניין בכשירות, ביכולות ובלוח זמנים. ז׳רגון טכני מציף אותו במקום לתרגם לשפה מבצעית.","2":"לדרג הבכיר השפה היא מבצעית ותמציתית. מייל ארוך עם כל הפרטים לא נותן את השורה התחתונה.","3":"מתודולוגיה היא שפה של צוות המוצר. למפקד מדברים על ״יכולות מבצעיות״, לא על Sprints או User Stories."},"9":{"0":"השלב מבחין בין מערכות קריטיות למערכות מידע. Velox מנהלת משימות טכנאים ולא מפעילה את הרשת, ולכן v1 לגיטימית.","2":"במערכת שליטה ברשת כשל יכול להפיל את הרשת, ונדרש אפס כשלים. שם אין מקום ל-״נתקן בגרסה הבאה״, גם אחרי FAT ו-SAT.","3":"הקריטריון הוא סוג המערכת, קריטית או מערכת מידע, לא התקציב לתחזוקה. כסף לא הופך מערכת קריטית לגמישה."},"10":{"0":"גיוס מפתחים הוא אתגר אחר. רוטציה פירושה שאנשים בתוך הפרויקט מחליפים תפקיד כל 2-3 שנים, והידע הולך איתם.","2":"שינויי דרישות ותוכניות רב-שנתיות הם אתגר של תהליך הרכש. רוטציה עוסקת באנשים שעוזבים ובידע שהולך איתם.","3":"תלות בספק היא חיסרון של COTS, לא של רוטציה. הבעיה כאן היא ה-Champion, ה-SME והמשתמשים שמתחלפים."},"11":{"0":"פיתוח מאפס הוא ההפך מ-COTS. הוא שמור לצרכים שבאמת אין להם מענה בשוק.","2":"שכבת התאמה היא תוספת שמחברת COTS לצרכים, והשילוב נקרא Hybrid. COTS עצמו הוא המוצר המסחרי המוכן.","3":"מכרז הוא שלב בחירת ספק בתהליך הרכש. COTS מתאר את סוג הפתרון: מוצר מסחרי מהמדף."},"12":{"0":"פריסה רחבה לפני שהוכח ערך מגדילה את הסיכון. הגישה המומלצת היא להתחיל קטן וללמוד לפני הרחבה.","2":"שינוי דוקטרינה דורש גיבוי מדרג בכיר, ולכן קודם מוכיחים ערך ב-POC קטן ורק אז משנים דוקטרינה.","3":"שדרוג הדרגתי הוא הגישה הבטוחה, אבל לא מכניס טכנולוגיה חדשה. ההמלצה היא חדשנות מבוקרת דרך POC."},"13":{"0":"יש מספיק עבודת מוצר. ריבוי דרגים, סיווג ותהליכי אישור ארוכים פשוט דורשים את רוב הזמן לתיאום.","2":"זה לא חוסר בידע טכני. גם PM טכני מאוד יבלה את רוב הזמן בתיאום, כי כך בנויה סביבה של 6 דרגים ויותר.","3":"הסיבה היא המבנה הארגוני, לא חוסר בכלים. ריבוי בעלי עניין, היררכיה וסיווג דורשים תיאום מתמיד."},"14":{"0":"המפקד, המדינה והאוצר הם לא רק שלבי אישור. לכל אחד צרכים משלו: יכולות, Value for Money ועמידה בתקציב.","1":"משרד הביטחון הוא הקונה ורוצה Value for Money. הוא לא מייצג את החייל שרוצה פשטות, או את המפקד שרוצה יכולות.","3":"הצרכים שונים ואף מתנגשים: פשטות לחייל, יכולות למפקד, Value for Money למדינה ותקציב לאוצר."}},"21":{"0":{"0":"השלב לא עוסק בשכר. ההבדל המהותי הוא שהחלטות ננעלות: תבניות, רכיבים שכבר נקנו והסמכות.","2":"בחומרה דור מוצר נמשך חודשים עד שנים, ושינוי אחרי נעילה עולה פי כמה. קצב האיטרציה שונה לגמרי.","3":"מיכל יצאה עם גלעד לשטח וראתה איך טכנאים מטעינים ברכב, וכך הוזז השקע. הבנת משתמשים קריטית גם בחומרה."},"1":{"0":"הבעיה בתהליך ההרכבה, לא בתכנון. שינוי אטם הוא תיקון תבנית ו-6-8 שבועות: תרופה חזקה מדי לבעיית תהליך.","2":"מעבר בלי תנאים משחרר יחידות דולפות ללקוח. דליפה היא בעיה פיזית, לא באג שמתקנים בשטח.","3":"הורדת היעד כדי שהשער יעבור היא דילוג על השער. קריטריונים נקבעים מראש, לא כשהתוצאות כבר על השולחן."},"2":{"0":"גם בלי הובלה ואחריות, 119 מתוך 299 הם כ-40%, לא 55%. והובלה ואחריות הן עלות אמיתית של כל מכשיר.","2":"חישוב מה-BOM בלבד נותן כ-40%, אבל מפספס הובלה, מכס ואחריות, שהן עלות אמיתית של כל יחידה.","3":"195 מתוך 299 הם כ-65%, אבל זה חלק העלות מהמחיר. הרווח הגולמי הוא מה שנשאר: 104 מתוך 299, כ-35%."},"3":{"0":"דווקא להפך: הלקח הוא לתכנן לוח שמקבל רכיבים חלופיים כבר בבחירת הרכיבים ב-EVT, כלומר סביב השבבים.","2":"השלב לא מציע לייצר שבבים בעצמכם. הלקח הוא ספק שני או לוח שמקבל חלופות, והחלטה על כך כבר ב-EVT.","3":"מוצר חומרה צריך רכיבים פיזיים. הלקח הוא לא לוותר על חומרה אלא לא לתלות רכיב קריטי בספק יחיד."},"4":{"0":"1,800 מכסה רק את הייצור. בלי מלאי לתיקון המכשירים שכבר בשטח, המודמים ייגמרו לפני שהדור הבא מוכן.","2":"מעבר מיידי לדור הבא דורש תכנון מחדש, בדיקות והסמכה מההתחלה. בינתיים לא יהיו מודמים לייצור ולתיקונים.","3":"Last-time buy הוא בדרך כלל NCNR: אי אפשר לבטל או להחזיר. קנייה מקסימלית משאירה מזומנים תקועים במחסן."},"5":{"0":"IP הוא דירוג אחד לפי IEC 60529, לא תקן אזורי. הספרה הראשונה מתארת הגנה מאבק והשנייה הגנה ממים.","2":"נפילות ורעידות נבדקות בתקני עמידות אחרים, כמו MIL-STD-810. דירוג IP עוסק באבק ובמים בלבד.","3":"דירוג IP לא מתאר טווח טמפרטורות. שתי הספרות מתארות הגנה מאבק ומים, ו-IP68 אטום לאבק ועמיד בטבילה ממושכת."},"6":{"0":"דילוג על שלב כי מתחרה הכריז על מוצר הוא טעות נפוצה. הדילוג חוזר כעלות גבוהה יותר בשלב הבא.","2":"סיום מוקדם הוא לא סיבה לעצור. עוברים שער כשהקריטריונים שנקבעו מראש התקיימו, לא לפי לוח הזמנים.","3":"לחץ זמן שמוביל לדילוג על שלבים חוזר כעלות גבוהה יותר בשלב הבא. תנאי מעבר נקבעים מראש ולא נמחקים בגלל דדליין."},"7":{"0":"השלב בפריסה מדורגת נועד בדיוק לזה. המשך ל-100% יפיל את הבעיה על כל המכשירים עם הסוללה החלופית.","2":"החלפת סוללות היא תגובה פיזית ויקרה לבעיה שנוצרה בתוכנה. חזרה לגרסה הקודמת דרך מחיצות A/B פותרת אותה.","3":"הפצה לכולם מעבירה את הבעיה ללקוח ומתעלמת ממדד העצירה שנקבע מראש. צוותי השטח ייתקעו עם סוללה שנגמרת מהר."},"8":{"0":"חומרה כן מתעדכנת אחרי ייצור: OTA מתקן לוגיקה, ממשק וניהול סוללה. אבל רק אם המנגנון תוכנן מראש.","2":"ביקור טכנאי בכל מכשיר הוא בדיוק מה שתכנון מראש חוסך. בלי מנגנון עדכון, כל תקלה הופכת לנסיעה לשטח.","3":"החלפת מכשיר שלם בגלל קושחה היא התגובה היקרה ביותר. מנגנון עדכון שתוכנן ב-EVT מונע אותה."},"9":{"0":"השינוי עצמו זהה בשני השלבים. מה שגדל הוא כל מה שכבר ננעל סביבו: תבניות, מלאי רכיבים ויחידות גמורות.","2":"העלות לא נובעת מתיעוד. ב-MP צריך לתקן תבניות יקרות, לעדכן BOM, לחזור על בדיקות ולגרוט מלאי.","3":"אישור מנכ״ל לא עולה כסף. העלות היא תבניות, מלאי שנזרק ובדיקות והסמכות חוזרות."},"10":{"0":"התיקון זהה, אבל ב-MP כבר יש תבניות, מלאי ויחידות גמורות. לכן אותה בעיה עולה הרבה יותר מאוחר.","1":"כלל האצבע הוא פי 100 ולפעמים יותר, לא פי 10. ב-MP לא רק חוזרים על בדיקות, אלא מחליפים תבניות וגורטים מלאי.","3":"ב-MP עוד לא בהכרח נמכרו מכשירים שצריך להחזיר. כלל האצבע לבעיה שנמצאת אחרי ייצור המוני הוא פי 100."},"11":{"0":"הורדת מחיר מקטינה את הרווח ולא משנה את עלות היחידה. היעד הוא להוריד את ה-BOM עצמו מ-180 ל-120 דולר.","2":"מעבר ספק בלי בדיקת איכות מסוכן: מה שלא רואים במפעל מגלים אצל הלקוח. וכל שינוי כזה דורש בדיקות.","3":"המתנה לא מורידה עלות. עלות היחידה נקבעת בעיקר בתכנון, ו-cost-down היא עבודה פעילה על רכיבים, הרכבה וחלקים."},"12":{"0":"הסמכה נעשית במעבדה מוסמכת, לא אצל היצרן תוך ימים. סריקה מקדימה, בדיקות רשמיות ואישורים לוקחים שבועות עד חודשים.","2":"CE ו-FCC בודקים בטיחות, EMC ורדיו. עמידות למים ואבק היא דירוג IP, נושא נפרד.","3":"הבעיה היא זמן, לא חשבונאות. בלי הסמכה אי אפשר למכור, וכל ממצא במעבדה דורש סבב תיקונים נוסף."},"13":{"0":"Recall מגיע כשיש סיכון בטיחותי. כאן אין סימן כזה, והתקלה מוגבלת לאצווה אחת של 600 יחידות.","2":"עדכון קושחה לא מתקן מחבר שנשחק, והעלאת זרם הטעינה עלולה ליצור סיכון חדש.","3":"המתנה להחזרות משאירה צוותים בלי מכשיר. כשהתקלה ידועה ומוגבלת לאצווה, מחליפים מראש לפי טווח מספרים סידוריים."},"14":{"0":"כל החלפת רכיב בחומרה היא Trade-off. בלי לבדוק עלות, זמן אספקה והשפעה על לוח הזמנים, אי אפשר לדעת אם זה משתלם.","2":"קריאות באור שמש היא דרישת ליבה לצוותי שטח. מדבקה לא פותרת את הבעיה, והיא תגיע ללקוחות כבר בדור הזה.","3":"החלפת רכיב מחייבת לחזור על בדיקות. דילוג ל-MP בלי DVT חוזר כעלות גבוהה יותר בשלב מאוחר."}},"22":{"0":{"0":"גיימיפיקציה לא בונה משחקים. היא לוקחת מכניקות משחק להקשרים שאינם משחק, כמו מוצרים, תהליכים ולמידה.","2":"אנימציות הן קוסמטיקה. גיימיפיקציה אמיתית מבינה את הפסיכולוגיה של המוטיבציה ומשתמשת בה כדי להניע התנהגות.","3":"ספרינטים הם מתודולוגיית פיתוח. גיימיפיקציה היא שימוש במכניקות משחק כדי להניע התנהגות של משתמשים."},"1":{"0":"כסף, קידום והכרה הם תגמולים חיצוניים. SDT עוסקת במוטיבציה פנימית, שנשארת גם כשהפרס נעלם.","2":"תחרות וניצחון מניעים בעיקר שחקן מסוג Killer. SDT מגדירה צרכים בסיסיים של כולם: בחירה, התקדמות ושייכות.","3":"נקודות, תגים ולוח מובילים הם מכניקות (PBL), לא צרכים. מכניקה טובה רק עונה על הצרכים האלה."},"2":{"1":"האפקט לא עוסק בכמות הפעולות. הוא מתאר פגיעה במוטיבציה הפנימית כשמוסיפים פרס לפעילות שאנשים עושים ברצון.","2":"זה ההפך: האפקט מראה שתגמול חיצוני יכול לפגוע במוטיבציה הפנימית, ולא תמיד לחזק אותה.","3":"זה לא עניין של דרישה לפרסים גדולים יותר. ילדים שקיבלו פרס על ציור ציירו פחות אחרי שהפרס הוסר."},"3":{"0":"Explorer מונע מסקרנות ורוצה לגלות תוכן חדש, כמו Easter eggs ותוכן נסתר. דירוג לא מעניין אותו.","1":"Socializer רוצה לשתף, לעזור ולתקשר. מכניקות שמתאימות לו הן צ׳אט, שיתוף וצוותים, לא דירוג.","2":"Achiever רוצה להשלים ולאסוף, ומעדיף תגים, רמות ואתגרים. הוא לא צריך לנצח אחרים כדי להרגיש הישג."},"4":{"0":"ההבחנה לא בין חיצוני לפנימי. White Hat יוצר מוטיבציה חיובית שבה המשתמש מרגיש טוב, ו-Black Hat מניע דרך FOMO ופחד.","2":"Social Influence ו-Ownership לא נכללים באף אחת מהקבוצות כאן. White Hat הוא משמעות, הישג והעצמה, ו-Black Hat הוא מחסור, אי-ודאות והימנעות.","3":"החלוקה היא לפי תחושה, לא לפי טווח זמן: White Hat משאיר את המשתמש מרוצה, ו-Black Hat יוצר התמכרות בלי סיפוק."},"5":{"0":"ההשקעה במודל היא לא תשלום אלא נתונים, תוכן וזמן שהמשתמש מכניס. היא מעלה את ערך המוצר ומקשה לעזוב.","2":"תגמול לא צפוי הוא שלב ה-Variable Reward, השלב השלישי. Investment בא אחריו ומחזק את הסבב הבא.","3":"תזכורת שמחזירה את המשתמש היא Trigger חיצוני, השלב הראשון במודל. Investment הוא מה שהמשתמש משקיע."},"6":{"0":"DAU עולה ו-NPS יורד באותו זמן הוא סימן מוכר: משתמשים נכנסים מפחד לאבד את הרצף, לא מהנאה. זה לא יתוקן לבד.","2":"לרצפים יש הסבר ישיר לירידה: הם מפעילים Avoidance, פחד מהפסד. משתמשים מחויבים להיכנס, אבל פחות מרוצים.","3":"הבעיה היא לא שעמום אלא תחושת חובה. עוד מכניקות לא יתקנו את הפחד לאבד רצף, ועלולות להחמיר אותו."},"7":{"0":"עלות פיתוח היא סיכון בכל פרויקט. הסיכון הייחודי לגיימיפיקציה ב-B2B הוא תחושה ילדותית והתנגדות ארגונית.","2":"השלב לא מזהיר מזה. ב-B2B המניע הוא יעילות והתקדמות מקצועית, והסיכון הוא שהמשחק ייראה ילדותי ויידחה.","3":"העתקה על ידי מתחרים היא לא הסיכון שהשלב מציין. הסיכון הוא אנשי מכירות בכירים שידחו נקודות ותגים כילדותיים."},"8":{"0":"המכניקות שונות: רצפים ו-XP ב-Duolingo, מקטעים ו-KOM ב-Strava, גרף תרומות ב-GitHub. המשותף הוא הקשר לפעילות בעלת משמעות.","2":"השלב לא מסביר את ההצלחה במחיר. הגרף של GitHub מייצג עבודה אמיתית, והרצף של Duolingo מייצג התמדה בלמידה.","3":"GitHub משמש מפתחים בעבודה מקצועית. הגיל לא הסוד, אלא החיבור למשהו שכבר חשוב למשתמש."},"9":{"0":"צפייה בסרטונים היא לא Flow. Flow הוא ריכוז מלא שנוצר כשרמת האתגר מותאמת לרמת המיומנות.","2":"צבירת נקודות מהירה לא יוצרת Flow. אם האתגר קל מדי ביחס למיומנות, התוצאה היא שעמום.","3":"שימוש כפייתי שמשכיח אוכל ושינה הוא Compulsion Loop, Dark Pattern. Flow הוא איזון בריא בין אתגר למיומנות."},"10":{"0":"לוח מובילים מראה ל-95% מהמשתמשים שהם לא בראש. במקום מוטיבציה הם מרגישים חוסר מסוגלות.","2":"הסיכון העיקרי הוא לא העלות אלא ההשפעה על המוטיבציה: רוב המשתמשים יראו שהם רחוקים מהפסגה.","3":"השלב לא מזהיר משחיקה. הסיכון שלו הוא ההפך: רוב המשתמשים מתייאשים ומשתתפים פחות."},"11":{"1":"השלב לא מגביל גיימיפיקציה לפי מספר משתמשים. Duolingo ו-Strava עובדות בקנה מידה ענק.","2":"גיימיפיקציה נפוצה מאוד ב-B2C, כמו Duolingo ו-Strava. ב-B2B משתמשים במכניקות עדינות יותר.","3":"Duolingo היא אפליקציה למובייל עם רצפים, XP וליגות. גודל המסך לא מונע גיימיפיקציה."},"12":{"0":"אלה שלבי תהליך פיתוח מוצר. מודל ה-Hook מתאר לולאת הרגל: מה מפעיל, פעולה, תגמול והשקעה.","2":"זה מתאר מסלול להחלטת רכישה. מודל ה-Hook לא נגמר בפעולה: אחריה באים תגמול לא צפוי והשקעה שסוגרת לולאה.","3":"אלה שלבים של תהליך עיצוב פתרון. מודל ה-Hook של Nir Eyal מסביר איך מוצרים יוצרים הרגל שחוזר שוב ושוב."},"13":{"0":"לוח מובילים מייאש את רוב המשתמשים שלא בראש, ומתגמל מהירות ולא השלמה. כצעד ראשון הוא מסוכן.","2":"תגים עובדים רק כשהם מייצגים הישג אמיתי. כצעד ראשון עדיף משהו פשוט שמראה התקדמות ומתאים לכל סוגי השחקנים.","3":"הנחה היא תגמול חיצוני שעלול להחליש מוטיבציה פנימית, והיא מורכבת יותר. מתחילים פשוט ומודדים."},"14":{"0":"תשלום נוסף לא בודק אתיקה, ו-Pay to Win הוא בעצמו Dark Pattern. המבחן הוא איך המשתמש מרגיש כשהוא מבין את המנגנון.","2":"DAU יכול לעלות גם ממניפולציה, כמו ברצפים שמפעילים פחד. מספר גבוה לא אומר שהמנגנון הוגן.","3":"העובדה שמתחרים משתמשים במנגנון לא הופכת אותו לאתי. Dark Pattern נשאר Dark Pattern גם כשהוא נפוץ."}},"23":{"0":{"1":"אלה שכבות שונות: UI הוא העיצוב הוויזואלי, ו-IA הוא המבנה של המידע. אחריות ה-IA היא בעיקר של ה-PM.","2":"ההבדל לא בפלטפורמה. לכל מוצר, באתר או באפליקציה, יש גם ארכיטקטורת מידע וגם עיצוב ויזואלי.","3":"IA הוא כל המבנה של המידע: היררכיה, ניווט וסידור התוכן בכל המוצר, לא רק התפריט הראשי."},"1":{"0":"צבעים וגופנים הם Visual Design, תחום המקצוע של המעצב. ה-PM אחראי על ה-למה, ה-מה וה-IA.","2":"אייקונים ואנימציות שייכים לעיצוב הוויזואלי, באחריות המעצב. ה-PM מגדיר את מסגרת המוצר.","3":"Mockups ב-Figma הם עבודת המעצב. ה-PM מגדיר מטרות משתמש ומבנה מידע, והמעצב הופך אותם לחוויה ויזואלית."},"2":{"0":"אלה גדלי מסך שונים. מצבי מסך מתארים את מצב הנתונים: ריק, טוען, חלקי, מלא או שגיאה.","2":"זה מבנה של סיפור, לא של מסך. ב-Spec מגדירים מה רואים כשאין נתונים, בזמן טעינה, בנתונים חלקיים, במלאים ובשגיאה.","3":"אלה גרסאות תצוגה של אותו מסך. חמשת המצבים עוסקים במה שקורה לנתונים, למשל מה מוצג כשאין עדיין כלום."},"3":{"0":"מבנה ארגוני הוא בדיוק מה ש-IA לא צריך לשקף. ב-Card Sorting התגלה שמשתמשים שמים את הדוחות ליד הגדרות, לא ליד Dashboard.","2":"IA הוא החלטת מוצר של ה-PM, לא החלטת עיצוב. והוא צריך לשקף את המודל המנטלי של המשתמשים, לא דעה של מישהו בצוות.","3":"תחושת בטן של צוות התמיכה היא עדיין ניחוש. Card Sorting נותן ל-15 משתמשים לסדר בעצמם ומגלה את המודל המנטלי שלהם."},"4":{"0":"Hierarchical מתאים לתוכן עם רמות, מהכללי לפרטי. כאן אלה צעדים בתהליך עם התחלה וסוף, לא תתי-רמות.","2":"Matrix מתאים לסינון ומיון לפי כמה צירים, כמו באמזון. התהליך כאן הוא רצף צעדים, לא חיפוש לפי מאפיינים.","3":"Tag-Based מתאים לתוכן עם הרבה קשרים, כמו האשטגים. תהליך יצירת פרויקט צריך להוביל את המשתמש צעד אחרי צעד."},"5":{"0":"אלה עמודות של לוח משימות: הן מתארות סטטוס של משימה, לא את התנאים שבהם פיצ׳ר נחשב גמור.","2":"זה מחזור לשיפור תהליכים. הוא לא מגדיר מצב התחלתי, פעולה ותוצאה צפויה שאפשר לבדוק.","3":"זה מיון של הרגלי צוות לשינוי. הוא לא אומר מה המסך צריך לעשות או איך בודקים שהוא עובד."},"6":{"0":"סבבים קטנים הם לא הבעיה: עדיף 2 סבבים של 5 משתמשים מסבב אחד של 10. הטעות היא במי שבודקים.","2":"השלב לא מונה בדיקה מרחוק כטעות. הטעות הנפוצה היא חברים ומשפחה, שנחמדים מדי ומכירים את המוצר דרככם.","3":"העיקר הוא לתעד הכול: מה אמרו, מה עשו ואיפה נתקעו. אמצעי התיעוד פחות חשוב ממי שנבדק."},"7":{"0":"משתמש אחד או שניים לא מספיקים כדי לזהות דפוס. בעיה אמיתית היא מקום שבו 3 משתמשים ויותר נתקעו.","2":"בדיקת שמישות היא מחקר איכותני שמגלה דפוסים, לא מדגם סטטיסטי. כבר 5 משתמשים מוצאים כ-85% מהבעיות.","3":"כל משתמש נוסף מוסיף פחות ופחות. 100 משתמשים בסבב אחד מבזבזים זמן שעדיף להשקיע בתיקון ובסבב נוסף."},"8":{"0":"יש הבדל: Sitemap עונה ״אילו מסכים יש?״, ו-User Flow עונה ״איך משתמש מגיע מ-A ל-B?״.","2":"ההבדל לא בפלטפורמה. שניהם משמשים גם באתרים וגם באפליקציות, ומתארים תמונה רחבה מול מסלול ממוקד.","3":"ההבדל לא בקהל. ה-PM בונה Sitemap כדי לוודא שכל הצרכים מכוסים, ו-User Flow מתאר מסלול אחד למטרה."},"9":{"0":"הוראה כמו ״תשנה לירוק״ מכתיבה פתרון. ה-PM מסביר מה הבעיה, והמעצב יודע איך לפתור אותה.","2":"״לא יפה״ לא אומר למעצב מה לא עובד. משוב טוב מסביר את ה-למה, למשל שהמסך לא עקבי עם שאר המוצר.","3":"ה-PM שותף לחוויה ומביא את ה-למה: מטרת המשתמש ומה שעלה בראיונות. ויתור על משוב משאיר את המעצב בלי הקשר."},"10":{"1":"NPS מודד נכונות להמליץ, לא שמישות. שרון ביקשה מספר שמשווה את השמישות עצמה, לפני ואחרי.","2":"6 משתתפים חושפים דפוסים, אבל הם לא סטטיסטיקה שאפשר להשוות לתעשייה. מחקר איכותני לא נותן Benchmark.","3":"5-Second Test בודק רושם ראשוני: האם ברור מה המסך עושה. הוא לא נותן ציון שמישות שמשווים לממוצע."},"11":{"0":"Empty State הוא מצב שבו עדיין אין נתונים, למשל הצוות הראשון. כאן המשתמש כבר לחץ והבקשה בדרך.","2":"Partial State מציג רק חלק מהמידע. כאן אין עניין של כמות נתונים, אלא של בקשה שעוד לא חזרה מהשרת.","3":"Error State מגיע רק אם הבקשה נכשלה. ברגע שאחרי הלחיצה עוד לא ידוע אם היא תצליח."},"12":{"0":"מטרות משתמש ומודל מנטלי של הפרסונה הם חלק מה-למה וה-מה, ולכן באחריות ה-PM.","2":"IA ועומק הניווט הם החלטת מוצר, באחריות ה-PM בעיקר, עם המעצב כשותף.","3":"Acceptance Criteria נכתבים על ידי ה-PM ומשמשים בסיס לבדיקות QA. הם לא תחום המעצב."},"13":{"0":"SUS ממולא אחרי עבודה עם המסך ומודד שמישות. מיכל רוצה לבדוק רושם ראשוני, עוד לפני השקעה ב-hi-fi.","2":"Card Sorting בודק איך משתמשים מארגנים מידע, כלומר IA. הוא לא בודק אם מסך מסוים מעביר מה המוצר עושה.","3":"בדיקת ביצועים מודדת מהירות טעינה, לא תקשורת. מסך שנטען מהר יכול עדיין להיות לא ברור."},"14":{"0":"Overview הוא הסעיף הראשון ב-Spec ומסגרת לכל השאר, ולכן קשה לשכוח אותו. מקרי הקצה הם מה שנשמט.","1":"רכיבי הממשק הם הבסיס לעיצוב ומופיעים כמעט תמיד. מה שנשכח הוא מה קורה כשהשרת נופל או כשאין נתונים.","3":"Acceptance Criteria הם בסיס לבדיקות QA וסעיף מוכר. השלב מסמן את Edge Cases כסעיף שרוב ה-PMs שוכחים."}},"24":{"0":{"0":"ההבדל לא בפלטפורמה. גם באתר וגם באפליקציה יש UI לאנשים ו-API שמערכות מדברות דרכו.","2":"UI ו-API לא מוגדרים לפי מחלקה. UI הוא ממשק לבני אדם, ו-API הוא ממשק בין מערכות.","3":"שניהם ממשקים, אבל למשתמשים שונים לגמרי: מסכים וכפתורים לבני אדם, מול חוזה שמערכות אחרות קוראות לו."},"1":{"0":"SOAP מבוסס XML פורמלי ומתאים למערכות פיננסיות וממשלתיות ותיקות. הוא לא נבחר בגלל ביצועים.","1":"REST עם JSON פשוט ונפוץ ומתאים ל-Public API. בין שירותים פנימיים gRPC מהיר ממנו פי 5-10.","3":"WebSocket הוא חיבור דו-כיווני קבוע לזמן אמת, כמו צ׳אטים ומשחקים. ביצועים בין מיקרו-שירותים הם התחום של gRPC."},"2":{"0":"Rate Limit מגביל כמות בקשות, אבל לא מבחין בין ניסיון חוזר לבקשה חדשה. הכפילות תמשיך, ובקשות לגיטימיות ייחסמו.","2":"GET מיועד לקריאה בלבד, לא ליצירת משאבים. אי אפשר ליצור משימה ב-GET, ולכן זה לא פותר את הבעיה.","3":"ניסיון חוזר אחרי נפילת רשת הוא התנהגות סבירה של לקוח. סקריפט לילי משאיר כפילויות כל היום ומגלגל את הבעיה ללקוחות."},"3":{"0":"הוספת שדה אופציונלי לתשובה לא שוברת לקוחות קיימים, שפשוט מתעלמים ממנו. זה שינוי Non-Breaking.","1":"Endpoint חדש לא משנה שום דבר שלקוחות כבר משתמשים בו. זה שינוי Non-Breaking.","3":"Header אופציונלי חדש לא מחייב אף לקוח לשנות קוד. מי שלא שולח אותו ממשיך לעבוד כרגיל."},"4":{"0":"דווקא כאן GraphQL חלש: הוא פחות ידידותי ל-Cache. REST נחשב Cacheable.","2":"GraphQL מורכב יותר לתחזוקה. ל-API פשוט ולהשקה מהירה REST מתאים יותר.","3":"למהירות מקסימלית בין מיקרו-שירותים פנימיים משתמשים ב-gRPC. GraphQL פותר Over-fetching, לא ביצועים."},"5":{"0":"Polling מהיר יותר רק מוסיף עומס ובקשות מבוזבזות, ועדיין יש עיכוב. Webhook שולח את האירוע ברגע שהוא קורה.","1":"GraphQL משפר את צורת השאילתה, לא את התזמון. השרת שלהם עדיין צריך לשאול שוב ושוב אם משהו השתנה.","3":"קובץ לילי מגיע אחרי יום שלם. החברה ביקשה לדעת ברגע שמשימה נסגרת, לא למחרת בבוקר."},"6":{"0":"מסמך שמתעדכן ביד מתיישן מהר ולא מייצר SDKs, שרת Mock או בדיקות התאמה. הוא לא נשאר מסונכרן לקוד.","2":"לבקש מכולם לחכות סותר את המטרה. Mock Server שנוצר מ-OpenAPI מאפשר להתחיל לבנות לפני שה-Backend מוכן.","3":"JSON Schema מתאר רק את מבנה האובייקט. בלי Endpoints אין חוזה שאפשר לייצר ממנו תיעוד, SDKs או Mock."},"7":{"0":"שינוי שם השירות בכל גרסה מבלבל ושובר אינטגרציות. URL Versioning משאיר את השם ומוסיף v1 או v2 בנתיב.","2":"החלפת שרת מבטלת את הגרסה הישנה. בכל אסטרטגיה חובה לתמוך בגרסה הישנה במקביל לחדשה.","3":"עדכון הגרסה הקיימת בשינוי שובר יפיל לקוחות. לכן מנהלים גרסאות ותומכים בישנה במקביל."},"8":{"0":"200 OK אומר שהבקשה הצליחה. הוא ההפך מבקשה לא תקינה.","1":"404 אומר שהמשאב לא נמצא. הבקשה עצמה יכולה להיות תקינה לגמרי.","3":"500 הוא שגיאה בצד השרת. בקשה לא תקינה היא בעיה בצד הלקוח, כמו פרמטר חסר."},"9":{"0":"הגבלת גישה לנתונים לפי Scopes היא Authorization. Rate Limiting מגביל כמות בקשות, לא מה מותר לראות.","2":"מניעת כפילויות אחרי ניסיון חוזר היא תפקיד של Idempotency Key. Rate Limiting מגן על המערכת מעומס.","3":"מדידת Latency ו-Error Rate היא ניטור. Rate Limiting לא מודד, הוא חוסם לקוח שצורך יותר מדי."},"10":{"0":"Basic Auth שולח שם משתמש וסיסמה, ומומלץ רק לשימוש פנימי על HTTPS. אפליקציית צד שלישי לא צריכה לקבל סיסמה.","1":"API Key קבוע מתאים לשירותים פנימיים ואבות טיפוס. הוא לא מבחין בין משתמשים ואין בו Scopes.","3":"Public API פתוח לצדדים שלישיים, לא פתוח לכולם בלי זיהוי. בלי אימות אין דרך לדעת מי ניגש ומה מותר לו."},"11":{"0":"הזמן מבקשה לתשובה הוא Latency. Time to First Hello World מתחיל ברישום ונגמר בבקשה המוצלחת הראשונה.","2":"תשלום הוא מדד עסקי. Time to First Hello World הוא מדד DX: כמה מהר מפתח חדש מצליח לעבוד עם ה-API.","3":"זה מדד של צוות הפיתוח הפנימי. Time to First Hello World מודד את החוויה של מפתח חיצוני שנרשם."},"12":{"0":"JSON קריא לבני אדם ונוח לדיבוג, אבל לא הקומפקטי. רשומה של 100KB ב-JSON היא כ-35KB ב-Protobuf.","1":"XML הוא דווקא הכבד מכולם: אותה רשומה תופסת 130KB, לעומת 35KB ב-Protobuf.","3":"HTML נועד להצגת דפים לבני אדם, לא להעברת נתונים בין שרתים. הוא לא פורמט נתונים קומפקטי."},"13":{"0":"שינוי שם שדה הוא Breaking, גם אם זו אות אחת. כל לקוח שמשתמש ב-userName ייכשל, ולכן PATCH לא מתאים.","2":"גם 5% מהלקוחות הם לקוחות אמיתיים שיישברו. שינוי שובר דורש גרסה חדשה, לא משנה כמה משתמשים בשדה.","3":"הזיהוי נכון, אבל מעבר כפוי בגרסה הבאה ישבור את מי שלא יספיק לעדכן. צריך v2 במקביל ל-v1 עם תקופת תמיכה."},"14":{"0":"חיבור שמחכה דקות נשבר בקלות ופוגע בחוויה, גם עם Timeout ארוך. פעולה של יותר מ-2-3 שניות צריכה להיות אסינכרונית.","2":"שדרוג שרתים לא מבטיח שעבודה של 2 דקות תרד ל-3 שניות. תכנון אסינכרוני פותר את הבעיה בלי להמר על חומרה.","3":"שתי קריאות של דקה הן עדיין המתנה ארוכה, הרבה מעל 2-3 שניות. וגם פיצול דוח לשניים מסבך את הלקוח."}},"25":{"0":{"0":"קפיצה ישר לפתרון היא הסיבה מספר 1 לכישלון בראיונות PM. פתרון מהיר בלי להבין מי המשתמש ומה כואב לו הוא ניחוש.","2":"ניסיון קודם שייך לשאלות Behavioral. בשאלת Product Sense מתחילים מהבנת השאלה ומהמשתמש.","3":"Wireframe הוא כבר פתרון. לפני שמשרטטים צריך לברר מה בדיוק שואלים ולמי בונים."},"1":{"0":"רעיון יחיד בלי משתמש ובלי Pain Points הוא קפיצה לפתרון, הטעות מספר 1. מבנה ברור הוא מה שמביא ציון גבוה.","2":"רקע על החברה לא עונה על השאלה. המבנה הנכון מתחיל במשתמש ובכאבים שלו, וממשיך לפתרונות ולמדדים.","3":"זה הסדר ההפוך: רעיונות לפני משתמש הם קפיצה לפתרון. בודקים קודם למי בונים ומה כואב לו, ורק אז מציעים."},"2":{"0":"תשובה בלי מדדים היא סימן למועמד לא בשל. המראיין רוצה לראות מדד ראשי, משניים ומדד Guardrail.","2":"NPS לבדו הוא מדד כללי. חסרים מדד ראשי שקשור למטרת הפיצ׳ר ומדד Guardrail שבודק שלא נגרם נזק.","3":"ספירת קליקים לא אומרת אם המשתמשים קיבלו ערך, ואין כאן מדד Guardrail שבודק שלא פגענו במשהו אחר."},"3":{"0":"חוסר ידע על החברה פוגע, אבל הטעות מספר 1 היא קפיצה לפתרון בלי להבין למי ולמה.","2":"קיצור הוא לא העיקר. גם תשובה ארוכה נכשלת אם היא מתחילה בפתרון במקום במשתמש ובבעיה.","3":"מועמדים לא נכשלים מחוסר ידע אלא מחוסר מבנה. והטעות הנפוצה ביותר היא לקפוץ לפתרון."},"4":{"0":"אלה מושגים של תכנון אסטרטגי. ב-STAR מספרים סיפור: מה היה המצב, המשימה, מה עשיתם בפועל ומה יצא.","2":"חוזקות ואיומים לקוחים מ-SWOT, כלי לניתוח אסטרטגי. STAR הוא מבנה לסיפור התנהגותי.","3":"אין כאן Action, החלק הכי חשוב ב-STAR: מה אתם עשיתם באופן ספציפי. ובלי Result אין תוצאה מדידה."},"5":{"0":"הקל ביותר לפיתוח מתעלם מה-Impact. המראיין רוצה לראות קריטריונים, השוואה מנומקת ומה ויתרתם עליו.","2":"שאלת Execution בודקת יכולת לתעדף לבד. העברת ההחלטה למנכ״ל לא מראה חשיבה שיטתית.","3":"״אעשה את כל השלושה״ הוא חוסר תעדוף, אחת הטעויות הנפוצות. השאלה מבקשת לבחור ולהסביר את ה-Trade-off."},"6":{"0":"1-2 ראיונות לא מספיקים לבנות מבנה וביטחון. הכלל המעשי הוא 50 שאלות בכתב ו-20 ראיונות Mock.","1":"קריאת תיאוריה לבד לא מספיקה. צריך לתרגל בקול רם, כמו בספורט, עד שהתנועות הופכות לאינסטינקט.","3":"השלב לא דורש 100. לפי הכלל המעשי, 50 שאלות בכתב ו-20 ראיונות Mock מספיקים כדי להיות מוכנים."},"7":{"0":"השיטה ממליצה על 3-5 רעיונות, לא 10. מה שחסר הוא ההסבר למה ויתרו על השניים האחרים.","2":"Wireframe הוא לא חלק מהמבנה. אחרי רשימת הפתרונות בא שלב Evaluate: השוואת Trade-offs.","3":"ניתוח מתחרים לא נדרש בשלב הזה. המראיינים מצפים לשמוע למה בחרו פתרון אחד ומה המחיר של הוויתור."},"8":{"0":"״אני אוהב כי זה טוב״ היא בדיוק התשובה החלשה. בודקים אם אתם מפרקים מוצר: משתמש, כאב, פתרון ולמה זה עובד.","2":"השאלה לא מבקשת לשווק את המוצר אלא לנתח אותו: למי הוא מיועד, למה הוא מצליח ומה הייתם משפרים.","3":"היכרות עם מגמות שוק לא נבדקת כאן. בודקים Product Sense: הבנה למה מוצר מסוים עובד ואיפה יש הזדמנות."},"9":{"0":"בחירה בקל לפיתוח מתעלמת מ-Impact ומסיכון. המראיינים רוצים לראות קריטריונים מוגדרים, לא קיצור דרך.","2":"אימוץ דעת המנהל לא מציג שום מסגרת חשיבה. המראיינים בודקים איך אתם מקבלים החלטה בעצמכם.","3":"השאלה מניחה שאין מספיק נתונים. PM טוב מחליט גם באי-ודאות, עם רמת ביטחון מוצהרת ודרך לבדוק בדיעבד."},"10":{"0":"חמישה רעיונות לפני שבחרתם משתמש הם קפיצה לפתרון. אחרי שאלות ההבהרה בא זיהוי הלקוח.","2":"ניתוח מתחרים הוא לא השלב הבא ב-CIRCLES. אחרי Comprehend בא Identify: בחירת פרסונה עם נימוק.","3":"Wireframe הוא כבר פתרון. בלי פרסונה נבחרת, ״אעצב לכל הסטודנטים״ פירושו שעיצבתם לאף אחד."},"11":{"0":"עומק טכני לא הופך תשובה לטובה. חסרים מה הייתה הסיטואציה, מה אתם עשיתם בפועל ומה התוצאה המדידה.","2":"שם החברה ותואר התפקיד לא מספרים מה עשיתם. החלק החשוב ב-STAR הוא ה-Action, ואחריו תוצאה במספרים.","3":"ממליצים מגיעים בסוף תהליך הגיוס, לא בתוך התשובה. התשובה עצמה צריכה מבנה STAR עם תוצאה מדידה."},"12":{"0":"המאמץ הנמוך ביותר בלי Impact גבוה נותן מעט ערך. מתעדפים קודם את מה שגם משפיע הרבה וגם דורש מעט.","2":"Impact הכי גבוה בלי להתחשב ב-Effort מתעלם מחצי מהמטריצה. מתחילים במה שנותן הכי הרבה ערך על הכי מעט עבודה.","3":"העברת הבחירה למראיין מוותרת על מה שהוא בא לבדוק: תהליך מנומק ו-Trade-offs שאתם מסבירים."},"13":{"0":"מקוריות לא נבדקת כאן. Waze בסדר גמור, הבעיה היא שהתשובה לא מנתחת למי המוצר, למה הוא מצליח ומה לשפר.","2":"השאלה היא על מוצר שאתם אוהבים, מכל תחום. מה שנבדק הוא עומק הניתוח, לא תחום המוצר.","3":"השאלה מבקשת מוצר שאתם אוהבים, גם של אחרים. החולשה היא ניתוח שטחי, לא הבחירה במוצר שלא בניתם."},"14":{"0":"חישוב ההפסד הכספי לא מראה איפה הבעיה. כדי להציע פתרון צריך לדעת איפה בדיוק משתמשים נתקעים.","2":"השוואה לתעשייה אומרת אם 45% טוב, אבל לא איפה 55% הנותרים נעצרים. זה מה שמצביע על הפתרון הנכון.","3":"הערכת זמן פיתוח מניחה שכבר יש פתרון. קודם מבינים איפה במשפך משתמשים נושרים ולמה."}},"26":{"0":{"0":"עמידה במסגרת הזמן היא חלק מהמבחן ומראה שיקול דעת. אב טיפוס של 35 שעות שלא עונה על השאלה הפסיד בתרחיש להגשה ממוקדת.","2":"מהירות לא נבדקת כאן. ניתוח חלקי מפספס את מה שהבודקים מחפשים: מסגור, Trade-offs והמלצה אחת ברורה.","3":"לכסות כל אפשרות לעומק היא טעות נפוצה, ״לפתור הכול״. הבריף הגדיר מסגרת, והתעלמות ממגבלה שנקבעה בו היא טעות."},"1":{"0":"היסטוריה ומתחרים דוחים את השורה התחתונה. כשההמלצה לא מגיעה בדקה הראשונה, הבודקים מנחשים לאן אתם הולכים.","1":"סיפור אישי לא אומר מה אתם ממליצים. BLUF פותח בהמלצה, במדד שהיא מזיזה ובסיבה.","3":"מעבר כרונולוגי על כל האפשרויות קובר את ההמלצה בסוף. פותחים בשורה התחתונה, והשאר נבחן מולה."},"2":{"1":"קמפיין מייל הוא קפיצה לפתרון. עוד לא ידוע אם הירידה אמיתית, למי היא קרתה ולמה.","2":"Rollback לפני שבודקים את הנתונים הוא ניחוש. ייתכן שהמדידה השתנתה, או שהסיבה חיצונית ולא הגרסה.","3":"סיבות חיצוניות כמו מתחרים נבדקות בהמשך. קודם מוודאים מה בדיוק נמדד ושהירידה אמיתית, ואז מפלחים."},"3":{"0":"כל מקור יחיד מוטה. Levels.fyi, למשל, חזק בחברות גדולות וחלש בסטארטאפים, ולכן לא מספיק לבנות עליו טווח.","1":"הקצה העליון שהמגייס נותן הוא תקציב של משרה אחת, לא נתון שוק. טווח מבוסס נבנה ממקורות בלתי תלויים.","2":"נתון ישן עם אחוז קבוע הוא ניחוש. השלב ממליץ על מקורות מ-12 החודשים האחרונים, בהשוואה של תפקיד דומה לתפקיד דומה."},"4":{"0":"שנות ה-CS הן ההוכחה הכי חזקה שלה. מגייסים שואלים אילו החלטות מוצר כבר קיבלתם, וקורסים לבד לא עונים על זה.","2":"רשימת לקוחות מראה היקף, לא עבודת מוצר. חסרים הכאבים שזיהתה, ההמלצה שנתנה ומה השתנה בעקבותיה.","3":"תואר שלא היה הוא סיכון: בדיקת ממליצים תחשוף את הפער. כותבים את התואר האמיתי ומראים את עבודת המוצר בבולטים."},"5":{"0":"״הייתי אחראי על״ מתאר תחום, לא הישג. חסרה תוצאה מדידה שמראה מה השתנה בזכותכם.","1":"תכונות כלליות כמו תשוקה ותקשורת כל מועמד יכול לכתוב. אין כאן פועל, מעשה או תוצאה.","3":"כמות פיצ׳רים וישיבות היא נפח עבודה, לא תוצאה. בולט חזק מראה מה עשיתם ומה השתפר במספרים."},"6":{"0":"השלב מציע להוסיף שקף ״איך עבדתי״: מקורות, מה נבדק ואיפה כלי AI עזר. הסתרה פוגעת באמינות אם זה יתגלה.","1":"הבודקים שואלים על כל שקף, וכל מספר נבדק. מועמד ב׳ בתרחיש איבד אמינות בגלל נתון של 73% מכלי AI שלא נבדק.","2":"חברות שונות קובעות כללים שונים: חלקן מעודדות AI וחלקן מגבילות. לכן קוראים את ההוראות, לא נמנעים אוטומטית."},"7":{"1":"בחירת מודל היא פרט, לא אסטרטגיה. גם המודל הגדול ביותר טועה, והשאלה היא איך מודדים איכות ומה עושים כשהוא לא בטוח.","2":"הבטחה לענות על הכול מתעלמת ממחיר הטעות בחיוב. תשובה חזקה מתכננת מה קורה כשהמודל לא בטוח, כולל העברה לנציג.","3":"ב-AI Product Sense הגדרת איכות ו-evals היא חלק מעבודת ה-PM, לא רק של ההנדסה. ממשק יפה לא מציל תשובה שגויה."},"8":{"0":"מהירות כתיבה ושמות כלים לא נבדקים. הכלי הוא רק כלי, ומה שנמדד הוא שיקול הדעת שלכם.","1":"בדיקה ביקורתית של הפלט היא בדיוק מה שנבדק. מי שסומך על הכלי בלי לבדוק מפספס את עיקר התרגיל.","3":"לא זה הקריטריון. בודקים איך אתם ממסגרים, מכוונים, בודקים ומחליטים, ומצפים שתחשבו בקול."},"9":{"0":"תיאור כללי של איך אתם ״בדרך כלל״ פועלים הוא נורה אדומה. שאלה התנהגותית מבקשת מקרה אמיתי אחד.","2":"האשמת הצד השני היא נורה אדומה. המיקוד צריך להיות במה שאתם עשיתם ובתוצאה.","3":"לקחים ועצות כלליות לא מחליפים מקרה אמיתי. חסרים המצב, המשימה, הפעולות שלכם והתוצאה."},"10":{"0":"במסלולי APM יש מעט משרות והרבה מועמדים, ונדרש תיק עבודות בולט. להגביל את עצמכם רק אליהם מוריד סיכויים.","1":"עזיבה סוגרת את הדלת הכי ריאלית, מעבר פנימי. מגייסים שואלים אילו החלטות מוצר קיבלתם, וקורס לא עונה על זה.","2":"המתנה פסיבית לא בונה הוכחות. משימות מוצר אמיתיות עכשיו הן החומר לקורות החיים ולראיונות."},"11":{"1":"השלב מתאר את מטלת הבית כשלב מקובל בחברות רבות. קורות חיים חזקים מכניסים לתהליך, לא מחליפים אותו.","2":"תהליך בחברה אחת נמשך בדרך כלל 3-6 שבועות וכולל כמה סבבים. הצעה מיד אחרי שיחת המגייס איננה הנורמה.","3":"בסוף התהליך יש בדרך כלל 2-3 שיחות ממליצים. בוחרים מראש אנשים שראו אתכם עובדים ומתדרכים אותם."},"12":{"0":"בסיס בלבד מתעלם מקרן השתלמות, בונוס ומניות. בדוגמה בשלב, הצעה עם בסיס נמוך יותר הסתכמה בשנה ביותר.","1":"אופציות על הנייר הן לא כסף עד אקזיט, ושוויין יכול להיות מאפס ועד לא ידוע. צריך לשקלל סיכון ו-Vesting.","3":"השוואת בסיס מול בסיס מפספסת את שאר הרכיבים, ואווירה היא לא שיטת השוואה. משווים תגמול כולל."},"13":{"0":"השלב לא מייחס את הדירוג לעיצוב השקפים. מועמד א׳ ענה על השאלה שנשאלה, עם משתמש ברור ומדד ראשי.","2":"הדירוג נשען על ההגשה עצמה, לא על ותק. אב הטיפוס של ג׳ פתר בעיה אחרת ולקח פי ארבעה זמן.","3":"הדירוג לא נבע מהסכמה עם תוכנית מוקדמת. מועמד א׳ מסגר את הבעיה, הציג Trade-offs ועמד ב-8 השעות."},"14":{"0":"ניחוש בביטחון שוחק אמון כשמתברר שהוא שגוי. ״עוד אין לי תשובה, וכך אבדוק״ משדר בגרות.","1":"התנצלות על האנגלית מקטינה אתכם עוד לפני שהתחלתם, ולא עונה על השאלה. עדיף לומר שתבדקו ותחזרו.","2":"מעבר לשקף אחר הוא התחמקות, והפאנל מזהה אותה. כנות עם דרך לבדוק בונה אמון."},"15":{"0":"הנתונים לא ישנים: Levels.fyi מנובמבר 2026. הפער נובע ממה שנספר: תגמול כולל מול שכר בסיס בלבד.","1":"רוב משיבי PM Live עובדים בחברות מוצר, לא בחברות קטנות דווקא. ההבדל העיקרי הוא שהוא מדווח בסיס בלבד.","3":"שני המקורות מדווחים ברוטו. הפער נובע מכך ש-Levels.fyi כולל בונוס ומניות, ו-PM Live רק שכר בסיס."},"16":{"1":"נתון אמריקאי הוא תגמול כולל עם מניות, במטבע אחר. מול חברה ישראלית מעגנים במקורות ישראליים, בסיס מול בסיס.","2":"הדולר עלה כ-15% בחצי שנה, והנתון כולל RSUs, מס ויוקר מחיה אחרים. המרה בשער של היום לא הופכת אותו להשוואה הוגנת.","3":"הנתון לא חסר ערך: הוא רלוונטי כשבוחנים רילוקיישן או עבודה מרחוק לחברה זרה. הוא פשוט לא עוגן למשא ומתן מקומי."},"17":{"0":"קרן השתלמות לא מחויבת בחוק, ולכן חשוב לוודא שהיא בחוזה. בסקר של PM Live רק 71% דיווחו שיש להם.","2":"משכורת 13 לא מחויבת בחוק. היא מגיעה רק לפי חוזה, הסכם קיבוצי, צו הרחבה או נוהג קבוע במקום העבודה.","3":"פנסיה מחויבת בחוק, והמעסיק לא יכול לוותר עליה. מה שכדאי לבדוק הוא על איזה שכר מחושבות ההפרשות."}},"27":{"0":{"0":"50 שאלות שנבחרו לדמו לא מייצגות שימוש אמיתי. 94% בדמו לא אומרים כלום על המקרים הקשים, כמו עברית והרשאות.","2":"מודל גדול יותר לא מבטיח שהטעויות ייעלמו, וגם לא מגלה איפה המוצר נכשל. רק בדיקה על שאלות אמיתיות, לפי פלחים, תגלה זאת.","3":"הערה שתשובות עלולות להיות שגויות לא מודדת איפה ובאיזו חומרה. הטעויות בפלחים הקשים עדיין יגיעו לכל הלקוחות."},"1":{"0":"אישור החזרים אוטומטי משלב טעות יקרה בכסף עם טעות שקשה לזהות. זה לא הימור ראשון טוב.","1":"העברת משימות בין עובדים משלבת טעות יקרה בהוגנות עם טעות שקשה לזהות. אין כאן אדם שבודק לפני הביצוע.","2":"התחזית מפתה כי הערך גבוה, אבל יש מעט היסטוריה והיא נשלחת ישר להנהלת הלקוח. טעות בה תתגלה רק כשיהיה מאוחר."},"2":{"0":"מדדים גנריים נשמעים מקצועיים, אבל מפספסים את הכשלים הספציפיים של המוצר שלכם. הקטגוריות צריכות לצמוח מקריאת שיחות.","1":"שופט LLM בלי הגדרות מייצר מספרים חסרי משמעות. קודם צריך לדעת אילו טעויות קורות, ורק אז להגדיר לו מה לבדוק.","3":"מעט משתמשים לוחצים לייק או דיסלייק, ובעיקר המרוצים מאוד או הכועסים מאוד. זה לא בסיס להכרעה."},"3":{"1":"גם המודל החזק ביותר טועה, ולשופטים יש נטיות ידועות כמו העדפת תשובות ארוכות. כיול מול תוויות אנושיות הוא חובה.","2":"סולם של 1 עד 10 פחות עקבי מעבר או נכשל. יותר פירוט לא אומר יותר אמינות.","3":"שופט נוטה להעדיף את הסגנון של עצמו. לתת לו לדרג את התשובות שלו מגביר את ההטיה במקום לבדוק אותה."},"4":{"0":"ממוצע שעלה יכול להסתיר פלח שקרס, ובמוצר ישראלי עברית אינה פלח שולי. בודקים ספים לכל פלח.","1":"עד שהתלונות מגיעות, הלקוחות כבר נפגעו. הירידה ידועה עכשיו, ולכן עוצרים לפני השחרור.","3":"מחיקת הדוגמאות בעברית רק מסתירה את הבעיה. המשתמשים בעברית עדיין יקבלו תשובות גרועות יותר."},"5":{"1":"כשהצעדים ידועים מראש, סוכן אוטונומי מוסיף מורכבות וסיכון בלי שום תועלת. תהליך קבוע צפוי יותר, זול יותר וקל לבדיקה.","2":"כמה סוכנים מוסיפים עוד מורכבות לתהליך שהצעדים שלו קבועים. AI נדרש רק בשלב הסיכום, לא בכל שלב.","3":"שלב הסיכום הוא בדיוק המקום שבו AI מוסיף ערך. כתיבה ידנית מוותרת עליו, כשבדיקה אנושית לפני שליחה כבר מכסה את הסיכון."},"6":{"0":"95% לכל צעד לא אומר 95% למשימה. הסיכוי שכל עשרת הצעדים יצליחו הוא 0.95 בחזקת 10, כ-60%.","2":"שום דבר בשרטוט לא גורם לצעדים לבדוק זה את זה. בלי נקודות בקרה, הטעויות מצטברות ולא מתקזזות.","3":"כל צעד נכשל ב-5% מהמקרים, לא 10%, והסיכויים מוכפלים: 0.95 בחזקת 10 הוא כ-60%, לא 10%."},"7":{"0":"99% אישורים לא מוכיחים שהעוזר צודק, רק שאף אחד לא קורא. ביטול האישור יסיר את קו ההגנה האחרון.","1":"תזכורת חודשית לא משנה את הדפוס. משפרים את הצגת השינויים ומודדים זמן בדיקה ושיעור דחייה.","2":"זמן האישור הוא דווקא הסימן החשוב: שתי שניות כמעט תמיד אומרות שאין בדיקה אמיתית, כלומר Automation Bias."},"8":{"1":"תשובה על בסיס פרויקטים דומים נראית מועילה, אבל בפועל זו הזיה מנומסת. המשתמש יסמוך על מידע שלא קיים.","2":"הודעת שגיאה מגלגלת את הבעיה למשתמש. הבעיה היא שאין מידע, לא ניסוח השאלה או השפה שלה.","3":"אחוז ביטחון שלא כויל נותן תחושת דיוק כוזבת. עדיף לומר בפשטות שלא נמצא מידע ולהציע צעד הבא."},"9":{"0":"הוראה בפרומפט היא תזכורת, לא אמצעי הגנה: אפשר לעקוף אותה או לאבד אותה בעריכה. הרשאות אוכפים בקוד.","2":"שופט עלול לפספס, והמידע כבר הגיע למודל. מה שהמודל לא קיבל, הוא לא יכול לחשוף.","3":"אימון על מידע פרטי רק מגדיל את הסיכון שהוא ידלוף. ההגנה היא סינון לפי הרשאות לפני שהמידע מגיע למודל."},"10":{"0":"הזיה היא המצאת מידע, וכאן מדובר בהוראה זדונית שמוסתרת בתוכן. הורדת Temperature מפחיתה אקראיות, לא מניפולציה.","1":"אימון מחדש על נתונים עדכניים לא עוצר הוראה זדונית שמוסתרת בתוכן שהמודל קורא. זה סיכון של Prompt Injection.","2":"איזון נתוני האימון לא רלוונטי כאן. הסכנה היא טקסט עוין בתוך משימה, ולכן מגבילים הרשאות כלים ומאשרים פעולות רגישות."},"11":{"0":"הפרומפט הוא חלק מהמוצר: הוא קובע טון, גבולות והתנהגות. שינוי בו עובר גרסאות, סקירה ובדיקת רגרסיה כמו קוד.","1":"מותר לשנות פרומפט אחרי השקה, רק לא בלי לבדוק. הבעיה כאן היא השינוי בלי evals וסקירה.","3":"פרומפט קצר יותר לא בהכרח מדויק יותר. בתרחיש, הקיצור השמיט שורה שהסתירה באג הרשאות."},"12":{"0":"הסרת הפיצ׳ר מכולם מענישה את 95% המשתמשים שלא יוצרים את רוב העלות. צריך לטפל במעטים, לא לבטל לכולם.","1":"העלאה אחידה נראית הוגנת, אבל מענישה את רוב המשתמשים בגלל מיעוט. מכסה עם תשלום על חריגה מכוונת למי שיוצר את העלות.","3":"מודל זול בלי בדיקת איכות פוגע באמון של כל המשתמשים. הבעיה מרוכזת ב-5%, ולכן הפתרון צריך להיות ממוקד."},"13":{"1":"יותר שיחות יכולות לנבוע מתסכול: משתמשים שואלים שוב כי לא קיבלו תשובה. ספירה לבד לא מבחינה בין ערך לתסכול.","2":"גם כישלון אי אפשר להסיק מהמספר הזה לבד. צריך לבדוק משימות שהצליחו, שימוש חוזר ומשוב שלילי.","3":"ה-North Star של הפיצ׳ר הוא משימות מוצלחות למשתמש פעיל, לא מספר שיחות. יעד לשיחות עלול לתגמל תסכול."},"14":{"0":"גם שופט יקר לא בודק הרשאות שאף אחד לא ביקש ממנו לבדוק. הוא מודד רק את הקריטריון שקיבל.","2":"אין שום סימן לבעיית שפה. השופט התבקש לבדוק אם התשובה נשענת על המקורות, והיא אכן נשענה.","3":"השופט דירג שלוש תשובות שחשפו משימות פרטיות, כך שהיו שאלות כאלה. הבעיה היא שהקריטריון לא כלל הרשאות."}},"28":{"0":{"0":"מחכים ללחץ: כשהבקשה הראשונה מגיעה, לומדים את הצוות תחת לחץ במקום לדעת מראש איפה היא עלולה להיתקע.","1":"מסמך Roadmap מדבר עליכם ועל העדיפויות שלכם, ולא מלמד דבר על מה שכל צוות נמדד עליו ומה מדאיג אותו.","3":"רשימת ״מתנגדים״ הופכת עמיתים ליריבים. רוב ה״לא״ בא מהגנה על מדד, לא מהתנגדות למוצר."},"1":{"1":"היועצת המשפטית מנסחת חוזים, לא בקרות אבטחה. שאלת אבטחה של לקוח צריכה את מי שמחזיק את האבטחה בפועל.","2":"תשובה ״סבירה״ שאינה מדויקת הופכת להתחייבות כלפי הלקוח. גם בלי CISO, מישהו מחזיק את התחום.","3":"פתיחת משרה לא עונה ללקוח עכשיו. בחברה קטנה מחפשים מי מחזיק את התחום, לא את התואר."},"2":{"0":"DORA עצמם מזהירים שיעדים על המדדים שלהם מזמינים ״משחקים״. מדד שהופך ליעד מפסיק להיות מדד טוב.","2":"שום דבר לא מבטיח ירידה ״בהכרח״: פיצול מלאכותי משנה את המספר, לא את האיכות. בוחנים מהירות ויציבות יחד.","3":"הסיכון הפוך: אנשים כן מגיבים ליעדים, ולכן המספר יעלה. השאלה היא אם יעלה גם השיפור האמיתי."},"3":{"0":"ה-SRE לא מעכב בזדון, הוא מגן על הזמינות שעליה הוא נמדד. הסלמה ל-CEO לא משנה את המדד של אף אחד.","1":"גיא פועל לפי המדד שלו, עסקאות שנסגרות ברבעון. ביטול ההבטחה פוגע במספר שלו ולא פותר את הקונפליקט.","2":"זה לא עימות אישי אלא שני מדדים שמושכים לכיוונים שונים. גישור לא משנה את המדד של אף אחד."},"4":{"0":"מנהלי פיתוח נמדדים על מסירה צפויה ובריאות הצוות. לייחס את ההתנגדות להעדפה אישית מפספס את המדד שמאחוריה.","2":"תקציב ענן לא קשור לשינוי באמצע ספרינט. מה שנפגע הוא ההתחייבות של הספרינט והפוקוס של הצוות.","3":"היחס בין מפתחים ל-QA לא משתנה בגלל פיצ׳ר אחד. מה שמשתנה הוא שההתחייבות לספרינט נשברת."},"5":{"0":"Commits הם מדד פעילות יחיד: הוא מזמין ״משחקים״ ומעניש עבודה חשובה שלא נספרת, כמו Code review וחניכה.","1":"טיקטים שנסגרו הם עוד מדד פעילות יחיד. SPACE ממליצה לשלב כמה ממדים ולא לדרג לפי מדד פעילות אחד.","3":"שעות רשומות מודדות נוכחות, לא השפעה. גם הן מדד פעילות יחיד, והיעד יזיז את המספר ולא את התרומה."},"6":{"1":"בגישה של Google תקציב השגיאות הוא כלל מוסכם מראש: כשהוא נגמר, מאטים שחרורים. אין צורך בקנס כדי שזה יחול.","2":"החמרה ל-99.99% מקטינה את התקציב פי עשרה. זה לא כלי ענישה, וה-PM קובע את ה-SLO יחד עם SRE.","3":"תקציב השגיאות לא מעביר בעלות על פיתוח. הצוות ממשיך לבנות, ומשקיע באמינות עד שהתקציב מתחדש."},"7":{"0":"כ-4.3 דקות מתאים ל-99.99%, תשיעייה נוספת. 0.1% מ-43,200 דקות הם כ-43 דקות.","2":"כ-7 שעות מתאים ל-99%, תקציב גדול פי עשרה. ב-99.9% נשארים כ-43 דקות בלבד.","3":"3 ימים הם כ-10% מהחודש, כלומר זמינות של כ-90%. זה רחוק מאוד מ-99.9%."},"8":{"0":"ה-PM לא מחזיק כוננות. מי שבנה את השירות מכיר אותו הכי טוב, ולכן הוא מחזיק אותה בהתחלה.","1":"שירות בייצור בלי כוננות שם את הלקוחות בסיכון: תקלה בשתיים בלילה תחכה לבוקר.","2":"SRE לא חייבים לקבל כל שירות. ב-Google סקירת מוכנות היא השלב הראשון לפני ש-SRE לוקחים שירות."},"9":{"0":"בדיקה ידנית כל בוקר היא בדיוק ה״גבורה״ ש-DataOps Manifesto אומר לצמצם, והיא תופסת את הטעות רק אחרי שקרתה.","1":"איסור על שינוי אירועים משתק את המוצר. חוזה נתונים מאפשר שינוי ועוצר רק שינוי שובר לפני שהוא מגיע לצרכנים.","3":"ריענון מהיר יותר רק מציג מספר שגוי מוקדם יותר. הוא לא מונע את השבירה עצמה."},"10":{"0":"מתחרים לא מגדירים את הצורך. אם המשתמשים מסתכלים פעם בשבוע, ריענון מהיר רק עולה יותר במחשוב ובתקלות.","2":"בחירת טכנולוגיה לפני שיודעים את הצורך מתחילה מהיכולת הטכנית. טריות נתונים עולה כסף, מורכבות ותקלות.","3":"השאלה הראשונה היא אם 5 דקות בכלל נחוצות. בלי לדעת מה המשתמשים מחליטים, אין סיבה לדרוש את זה מאף צוות."},"11":{"1":"הבעיה היא לא אורך המחקר אלא שההחלטה כבר נסגרה, ולכן המחקר לא יכול לשנות כלום.","2":"התסכול לא נובע מתקציב. חוקרים נמדדים בהשפעה, ומחקר שבא לאשר החלטה סגורה לא יכול להשפיע.","3":"חוקרים כן משתתפים בהחלטות, וזו בדיוק ההשפעה שעליה הם נמדדים: המלצות שאומצו והגיעו למשתמשים."},"12":{"0":"FP&A נמדדים על סטייה מהתקציב ודיוק תחזית. הוצאה בלי אישור היא בדיוק ההפתעה שהם מנסים למנוע, והיא שורפת אמון.","1":"״לשאול״ מתקציב של צוות אחר בלי לערב אותו שורף אמון, גם מול הצוות וגם מול הכספים.","2":"FP&A צריכים לשפוט אם ההוצאה מוצדקת. בלי עלות ליחידה ושער לפני הרחבה, אין להם דרך להעריך את הסטייה."},"13":{"0":"אישור כללי לא פוטר מהודעה: לפי סעיף 28 ב-GDPR, המעבד חייב להודיע ללקוח על מעבד-משנה חדש ולאפשר התנגדות.","1":"התנאים הסטנדרטיים של ספק עשויים לאפשר לו להשתמש בנתונים לצרכיו, ולכן המחלקה המשפטית בודקת אותם. וחובת ההודעה ללקוח נשארת.","3":"אישור כללי נועד בדיוק כדי שלא יצטרכו חוזה חדש. הוא דורש הודעה והזדמנות להתנגד, לא החתמה מחדש."},"14":{"1":"הורדת הרף פוגעת בצוות לאורך זמן. מה שבאמת מעכב את זמן האיוש הוא קצב הראיונות והמשוב.","2":"גיוס עוקף בלי לעדכן את צוות הגיוס שובר את התהליך שעליו הם אחראים, ולא מקצר את הראיונות והמשוב.","3":"המתנה למועמד ״מושלם״ שעונה על כל דרישה מותחת את החיפוש, וכל יום כזה נספר במדד של צוות הגיוס."}},"29":{"0":{"1":"התחייבות מיידית בגלל סכום יוצרת הבטחה שאולי לא תקוים, עוד לפני שמבינים את הבעיה ואם הפער באמת חוסם.","2":"סירוב אוטומטי פוגע ביחסים עם המכירות ומפספס מודיעין חשוב מהשטח. בקשה עם סימן דולר היא נתון, לא החלטה.","3":"תאריך משוער שניתן ללקוח הופך להבטחה, ואם לא תקוים היא תתגלה רק לקראת החידוש."},"1":{"1":"אין כאן שום קשר לגודל הלקוח. הלחץ נובע מכך שעסקה אחת חוצה את קו המכסה ומשנה את ההכנסה של ה-AE.","2":"העמלה לא מוגבלת לרבעון הראשון. הלחץ בסוף השנה נובע מהמכסה השנתית ומהמאיצים שמעליה.","3":"AEs מתוגמלים על Bookings, לא על NRR. והנחה בכלל מקטינה הכנסה, היא לא מגדילה אותה."},"2":{"0":"אצל CSM כלל האצבע הוא 70:30 עד 80:20 בין בסיס למשתנה, כך שרוב התגמול הוא בסיס.","1":"אצל SE כלל האצבע הוא 70:30 עד 80:20, ואין תגמול שנקבע ברובו לפי מספר דמואים.","2":"תגמול בתמיכה הוא ברובו בסיס. CSAT הוא מדד שהתמיכה נמדדת עליו, לא רוב השכר."},"3":{"0":"הערכים הפוכים: GRR לא כולל הרחבות ולכן לעולם לא עולה על 100%. כאן הוא 90%.","2":"92% ו-107% מתקבלים כששוכחים את ההקטנות של $20K. גם הקטנה היא הכנסה שאבדה.","3":"115% מוסיף את ההרחבות בלי לנכות נטישה והקטנות. NRR מחשבים: 1,000 פחות 100 ועוד 150."},"4":{"0":"SDRs לא סוגרים עסקאות, הם מייצרים פגישות ו-Pipeline. וגם הנחות סגירה אינן משהו שה-PM נותן.","1":"SDRs לא נמדדים על שביעות רצון. מה שעוזר להם להשיג תשובות הוא כאבים בשפה של הלקוחות.","2":"אימוץ המוצר הוא עניין של לקוחות קיימים. SDRs פונים ללקוחות חדשים ונמדדים על פגישות ו-Pipeline."},"5":{"1":"דמו של משהו שלא קיים שנראה כמו מוצר חי יוצר הבטחה סמויה, והלקוח יצפה לקבל אותו.","2":"שקפים בלבד מחלישים את הדמו ומפספסים הזדמנות Discovery עם לקוח אמיתי. אפשר להציג את מה שקיים על הנתונים שלו.","3":"עבודה בערבים לא משנה את הבעיה: תצוגה שנראית חיה ולא קיימת היא עדיין הבטחה סמויה ללקוח."},"6":{"0":"סקריפטים בלי בדיקות, תיעוד ובעלים הם ״מוצר צללים״. להשאיר אותם מגדיל את הסיכון גם אם עוד לא התלוננו.","1":"להעביר הכל לפיתוח מנפח את המוצר בקוד חד-פעמי. צריך להחליט על כל סקריפט בנפרד.","3":"זה משאיר את מוצר הצללים בלי החלטה: ה-SEs לא בעלים של קוד שלקוחות תלויים בו לאורך זמן."},"7":{"0":"לקפוץ לפיצ׳ר מניח שזה פער במוצר. אבל כאן מי שהוביל את המוצר עזב, וזה עשוי להיות בעיית אימוץ.","2":"הנחה היא החלטה מסחרית, לא של ה-PM. וקודם צריך לברר את הסיבה, לא להניח שהיא המחיר.","3":"סיכון נטישה יכול לנבוע מפער במוצר, ואז הוא בדיוק עניין של המוצר. צריך לברר לפני שמחליטים מי מטפל."},"8":{"0":"בחלוקה המקובלת ה-CSM מחזיק אימוץ, בריאות לקוח וערך. ההיכרות עם הלקוח לא הופכת אותו לבעלים המסחרי.","2":"התמיכה פותרת תקלות ונמדדת על זמני תגובה ו-CSAT. משא ומתן על חידוש והרחבה הוא לא התפקיד שלה.","3":"ה-PM משפיע על המוצר, אבל המשא ומתן המסחרי על החידוש וההרחבות שייך לבעלים המסחרי של הלקוח."},"9":{"1":"זמן תגובה הוא מדד תפעולי של התמיכה. הוא לא מראה מה במוצר גורם לפניות.","2":"מספר נציגים ושעות הם נתוני כוח אדם של התמיכה, ולא מגלים איפה המוצר מבלבל או נשבר.","3":"רשימת הלקוחות הרועשים היא נקודת התחלה, לא תמונה מלאה. היא לא מראה סיבות שורש ומגמה."},"10":{"0":"הבעיה איננה המקצועיות של הצוות: אותה עבודה חוזרת בכל לקוח, וזה סימן ליכולת שחסרה במוצר.","1":"מה שחוזר בכל הטמעה הוא Backlog מוצר בתחפושת, לא גזירת גורל. כלי ייבוא במוצר יקצר את הזמן לערך ראשון.","3":"העלאת מחיר משאירה את מוצר הצללים של סקריפטים. המטרה המשותפת היא יותר ARR, לא יותר שעות."},"11":{"0":"הזיכרון של אנשים מוטה, ושחזור לא נותן נתון שאפשר לסכם בדולרים ולעקוב אחריו לאורך זמן.","2":"סקר שוק כללי לא יגיד למה הפסדתם עסקאות ספציפיות. הנתון שחסר נמצא ב-CRM.","3":"דוח הכנסות לפי רבעון ואזור לא מכיל סיבות הפסד, ולכן לא יראה כמה עסקאות אבדו בגלל האינטגרציה."},"12":{"0":"מעורבות של שותף לא הופכת עסקה ל-Sourced. בשנייה ההזדמנות כבר הייתה קיימת, והשותף רק עזר לקדם אותה.","1":"הסיווג הפוך: בראשונה השותף הביא את ההזדמנות, ובשנייה רק עזר לקדם הזדמנות שה-AE כבר פתח.","2":"שותפים נספרים גם כשהם מביאים או מקדמים הזדמנות, לא רק כשהם חותמים. וגם התגמול נקבע לפי הסיווג."},"13":{"0":"יום ראשון הוא סוף שבוע בניו יורק. החפיפה האמיתית היא שני עד חמישי.","1":"השעה מתאימה לניו יורק, אבל יום שישי הוא סוף שבוע בישראל.","3":"23:00 שוחקת את הצוות הישראלי, וממילא רוב ההחלטות יכולות לעבור בכתב עד הבוקר."},"14":{"0":"הקדמת הבטא פתרה את המקרה הנוכחי, אבל לא מונעת את ההבטחה הבאה שתעבור בלי בעלים.","1":"השיחה עם ה-CIO טיפלה בלקוח אחד. שורש הבעיה היה הבטחות שעוברות מיד ליד בלי תיעוד ובלי בעלים.","2":"הדמו מנע הבטחה סמויה בעסקה אחת, אבל לא יצר מנגנון שמתעד כל התחייבות ומעביר אותה ל-CSM."}},"30":{"0":{"0":"סדר העדיפויות בבאקלוג הוא ניהול שוטף של צוותי המוצר, בתוך המדיניות שהדירקטוריון קבע.","1":"משא ומתן על מחיר עם לקוח הוא ניהול שוטף שבידי המנכ״ל וההנהלה, לא סמכות שסעיף 92 שומר לדירקטוריון.","2":"בחירת ספקי ענן וכלים היא החלטה תפעולית יומיומית של ההנהלה, לא מתפקידי הדירקטוריון בחוק."},"1":{"0":"דירקטור חובש שני כובעים, אבל כדירקטור חובות הזהירות והאמונים שלו הן כלפי החברה וכל בעלי המניות, לא כלפי הקרן.","1":"למייסדים אין עדיפות בחובות האמון. הדירקטור חב לחברה ולכלל בעלי המניות, והמייסדים הם חלק מהם.","2":"העובדים חשובים, אבל חובות האמון של דירקטור הן כלפי החברה וכלל בעלי המניות, לא כלפי קבוצה אחת."},"2":{"0":"תקציב שנתי ותוכנית גיוסים כמעט תמיד דורשים אישור דירקטוריון, כי הם התוכנית שהוא מאשר.","1":"הענקת הון, כולל הגדלת ה-Option Pool ואופציות לעובדים, כמעט תמיד עוברת אישור דירקטוריון.","3":"גיוס כסף, בהון או באשראי, הוא מההחלטות שכמעט תמיד דורשות אישור של הדירקטוריון."},"3":{"1":"רשימת פיצ׳רים עם תאריכים מדויקים יוצרת התחייבויות, והדירקטוריון לא מנהל את ה-Roadmap.","2":"צילומי מסך לא אומרים דבר על התוכנית. הדירקטוריון צריך לדעת אם המוצר מקדם את היעדים שאושרו.","3":"Story Points הם מדד פנימי של הצוות. הם לא מראים מדד מול יעד ולא קושרים את העבודה ליעדי החברה."},"4":{"0":"$260K הם ה-Bookings: כל ערך החוזה כולל החד-פעמי. ARR סופר רק הכנסה חוזרת בקצב שנתי.","1":"$240K הם המנוי לשנתיים. ARR הוא קצב שנתי, ולכן מחלקים בשתיים.","3":"$10K בחודש הם ה-MRR, ההכנסה החודשית. ARR הוא אותה הכנסה חוזרת בקצב שנתי."},"5":{"0":"עלות Inference שנוצרת בכל שימוש היא עלות מכר, לא פיתוח. היא מעלה את ה-COGS ל-$6.","2":"90% סופר רק את ה-$2 של ה-AI ושוכח את ה-$4 של ענן, תמיכה ושירותים.","3":"שכר המפתחים שבונים את הפיצ׳ר הוא הוצאת פיתוח, לא עלות מכר, ולכן לא נכנס לרווח הגולמי."},"6":{"1":"חלוקה בסך ההוצאות היא Gross Burn: תרחיש שבו ההכנסות נעלמות. שווה לדעת, אבל זה לא ה-Runway.","2":"חלוקה בהכנסות לא אומרת כלום על קצב השריפה. ה-Runway נקבע לפי Net Burn, כלומר הוצאות פחות גבייה.","3":"Runway מחשבים כמזומנים חלקי Net Burn. הזמן שגיוס לוקח משפיע על מתי מתחילים לגייס, לא על החישוב."},"7":{"0":"בחודש של 30 יום, 99.9% מתיר כ-43 דקות השבתה ו-99.95% רק כ-22. זה חצי, ולרוב תשתית כפולה.","2":"זיכויי שירות משולמים רק כשמחטיאים את היעד, לא כקנס חודשי קבוע.","3":"זו החלטה מוצרית וכלכלית לא פחות ממשפטית: היא דורשת תשתית ותורנות שנכנסות ל-COGS, ולכן צריך לתמחר אותה."},"8":{"0":"קיצוץ רוחבי פוגע גם במה שיוצר ערך. אם השימוש עלה ב-60%, עלייה של 30% בחשבון היא בכלל שיפור.","1":"ריכוז ההחלטות בכספים מוציא את המהנדסים מהתמונה, ו-FinOps בנוי על עבודה משותפת של הנדסה וכספים.","2":"התחייבות ארוכה משתלמת רק על שימוש יציב שכבר מבינים. כאן עוד לא ברור מה גרם לעלייה."},"9":{"0":"העדפות הצוות הן שיקול, לא בסיס להחלטה. בונים כשהיכולת מבדלת את המוצר, ואחרי ספירת העלות המלאה.","1":"השוואה של רישיון מול שבועיים פיתוח שוכחת את התחזוקה, האבטחה והעדכונים לאורך שנים.","3":"מה שהמתחרים עשו הוא שיקול, לא בסיס להחלטה. חיוב הוא לרוב תשתית שכולם צריכים, ולכן ברירת המחדל נוטה לקנייה."},"10":{"1":"הדירקטוריון לא מראיין מועמדים. הוא מאשר את התקציב ואת תוכנית הגיוסים, וגיוס נוסף נוגע בהם.","2":"אין חובה כזו בחוק. גיוס נוגע בתקציב כי כל עובד הוא התחייבות חודשית חוזרת, לא בגלל בעלי המניות.","3":"מהנדסים חדשים אכן צריכים זמן חפיפה, אבל זו לא הסיבה שההחלטה נוגעת בתקציב. הסיבה היא ההוצאה החוזרת."},"11":{"0":"Commit צריך להכיל רק עסקאות שסגירתן די בטוחה. עסקה שתלויה ביכולת שלא אושרה עוד לא שם, גם אם איש המכירות מכיר את הלקוח.","1":"העסקה לא אבודה, רק לא ודאית. מוציאים אותה מ-Commit ל-Best Case, לא מוחקים אותה מהתחזית.","2":"להכניס יכולת ל-Roadmap כדי ״לתקן״ תחזית הוא בדיוק Roadmap שנכתב לפי עסקאות."},"12":{"1":"״זה כבר ב-Roadmap״ הוא לא תאריך. סעיף כזה הופך הבטחת מוצר לסיכון הכנסה.","2":"אין בסיס להניח שהלקוח לא יהיה נאמן. כשהתחייבות באמת נדרשת, יש דרך: בדיקת היתכנות, תמחור ואישור ב-Deal Desk.","3":"הגדלת הצוות לכל תאריך שיידרש מוסיפה הוצאה חוזרת ל-Burn, ועדיין משאירה את ההבטחה כסיכון הכנסה."},"13":{"0":"גודל העסקה לבדו לא מכריע. בקשה של לקוח אחד היא נקודת נתון, ו-Theme נולד כשבקשה חוזרת ותואמת אסטרטגיה.","2":"לבנות את שלושתם זה בדיוק Roadmap שנכתב לפי עסקאות. לבקשות חד-פעמיות מציעים חלופות: שותף, מעקף או מחיר שמכסה את העלות.","3":"סירוב גורף מתעלם מאות חשוב מהשטח. כשהרבה עסקאות מבקשות אותה יכולת בכיוון האסטרטגיה, זה Theme."},"14":{"0":"החלטות שוטפות על פרויקטים שייכות להנהלה, לא לדירקטוריון. העצירה נדחתה כי לא הייתה נחוצה כדי לעמוד ביעד.","2":"השהיית ההימור דווקא חוסכת כ-$45K בחודש. היא נדחתה כי המחיר שלה הוא צמיחה עתידית, ולא היה בה צורך.","3":"לא התנגדות של הקרנות עצרה אותה: שלושת המנופים האחרים הביאו לרווח גולמי של כ-76%, יותר ממה שהדירקטוריון ביקש."}},"31":{"0":{"1":"OKR אישיים עוסקים בכיוון, אבל הבעיה היא מתי ואיפה בודקים ומחליטים. הם לא מפרידים בין דיווח להחלטה.","2":"פיצול לשני פורומים מכפיל את הפגישות ולא מוציא את הדיווח לכתב. ההחלטות עדיין יידחו.","3":"1:1 עם כל מנהל מבטל את המקום המשותף שבו מחליטים על סוגיות. הבעיה היא קצב, לא קשר אישי."},"1":{"0":"יעד חברה חדש לא מצייר את התלויות ולא מתאם אותן. הבעיה היא מבנה: מי עובד עם מי ועל מה.","1":"החלטה מהירה יותר לא עוזרת כשהצוותים לא יודעים שהם תלויים זה בזה. צריך קודם לצייר את התלויות.","3":"ועדת היגוי שבועית מוסיפה תיאום במקום לצמצם אותו, ועדיין לא ממפה את התלויות מראש."},"2":{"0":"OKR לא אומר מי מחזיק את המילה האחרונה על המחיר. הבעיה היא שאף אחד לא יודע אם הוחלט ומי החליט.","2":"פגישה ארוכה יותר לא קובעת מי מכריע, ואם אין יומן החלטות, גם ההסכמה תישכח בחודש הבא.","3":"צוות חדש הוא שינוי מבנה גדול, והוא עדיין לא אומר מי מאשר שינוי מחיר ואיפה זה נרשם."},"3":{"0":"ארגון מחדש לא בוחר יעדים. עשרה יעדים ״בעדיפות עליונה״ הם רשימת משאלות: זו בעיית כיוון.","1":"OKR אישי שקשור לבונוס דוחף אנשים ליעדים בטוחים (סטיבן קר, 1975), ולא מצמצם את רשימת המשאלות.","2":"פגישת סטטוס יומית לא בוחרת עבור אף אחד, רק מוסיפה דיווח. מה שחסר הוא כמה יעדי חברה ברורים."},"4":{"0":"סקירת מסמכים חודשית לא מחליפה את השיחה. ההפתעה בהערכה נוצרה בכל שיחה שבה אף אחד לא אמר כלום.","2":"DACI מגדירה מי מחליט, לא מי נותן משוב. הבעיה כאן היא משוב שלא ניתן בזמן.","3":"העברה לצוות אחר רק מזיזה את הבעיה. מה שחסר הוא שיחה קבועה ומשוב ספציפי בזמן."},"5":{"1":"הסיכון שכרטיס השיטה מזהיר ממנו הוא לא זמן הכתיבה, אלא שכאשר הציון קובע כסף, אנשים מציבים יעדים קלים.","2":"ההפך הוא הצפוי: כשהציון קובע כסף, אנשים מציבים יעדים שקל לעמוד בהם, לא יעדים שאפתניים.","3":"Google ו-John Doerr ממליצים במפורש להפריד בין OKR לתגמול. חיבור לבונוס מתגמל דבר אחד ומקווה לאחר."},"6":{"0":"אין הארכה אוטומטית: זה ה-Circuit breaker שמונע מפרויקטים להימתח לנצח. גם ה-Cool-down לא נועד לכך.","1":"הוספת אנשים מזכירה את חוק ברוקס: תוספת לפרויקט מאחר רק מעכבת אותו, בגלל תיאום וחפיפה.","3":"להמשיך ״כי כבר השקענו״ הוא Sunk cost. ב-Shape Up הזמן קבוע, והבעיה חוזרת לעיצוב לפני כל המשך."},"7":{"0":"לפי ג׳רמיה לי, שעבד ב-Spotify כ-PM, המודל לא יושם שם במלואו. לכן אין מה להעתיק ״כמו שהוא״.","1":"הבעיות לא היו בשמות: ל-Chapter leads לא הייתה אחריות על מסירה, ולא היה תהליך משותף לעבודה בין צוותים.","2":"השלב לא קושר את המודל לחברות מדיה. הלקח הוא השאלה איך לשמור גם על עצמאות וגם על יישור קו."},"8":{"0":"ב-RACI, Informed רק מעודכנת, בעוד היועצת חייבת לאשר. ו-RACI פחות חדה בשאלה מי מחזיק את המילה האחרונה.","2":"כאן יש מי שחייבת לאשר עמידה בדין ומי שמכריעה. Consent מעבירה הצעה כשאין התנגדות מנומקת, ומתאימה לניסויים.","3":"ב-DACI סמנכ״לית המוצר הייתה ה-Approver, לא Contributor. ו-Driver מקדם את ההחלטה, הוא לא מאשר עמידה בדין."},"9":{"1":"שינוי ניסוח עם אפשרות לחזור הוא דלת דו-כיוונית: אפשר להחליט עליו מהר, אדם אחד או קבוצה קטנה.","2":"ניסוי A/B מוגבל בזמן הוא הפיך מעצם הגדרתו, ולכן דלת דו-כיוונית שמחליטים עליה מהר.","3":"Feature Flag נועד בדיוק לאפשר כיבוי, ולכן ההחלטה הפיכה. זו דלת דו-כיוונית."},"10":{"0":"שתיקה בחדר והתנגדות בצ׳אט הן בדיוק הסימן לזכויות החלטה לא ברורות. בזוס מצפה שיאמרו את זה בגלוי.","1":"הסכמה מלאה אינה התנאי. מי שלא השתכנע אומר זאת, ואז מתחייב לביצוע ההחלטה של ה-Approver.","2":"העלאה בכל פגישה היא פתיחה מחדש של החלטה שכבר התקבלה. אחרי שאומרים את ההתנגדות, מתחייבים."},"11":{"0":"ב-Consult ההחלטה עדיין של המנהלת: היא שומעת ומחליטה. כאן יערה מחליטה לבד.","1":"ב-Sell המנהלת מחליטה ומשכנעת. כאן ההחלטה כולה של יערה, ומיכל רק רוצה לדעת אחר כך.","2":"ב-Agree מחליטים יחד. כאן מיכל לא שותפה להחלטה, רק מתעדכנת בתוצאה."},"12":{"1":"הבשלות שייכת למשימה, לא לאדם: ותק בהנדסה אינו ניסיון בראיונות. יעד ובדיקה בסוף הרבעון מתאימים למי שבשל במשימה.","2":"מניעת המשימה לא מפתחת אף אחד. מתחילים בליווי צמוד ומרפים ככל שהביצוע במשימה הזו משתפר.","3":"קורס לבדו לא מחליף ליווי תוך כדי עבודה. הבשלות למשימה נבנית בביצוע, עם הכוונה צמודה בהתחלה."},"13":{"0":"לפי Meyer, שתיהן שוויוניות בהובלה, אבל במשוב שלילי ישראל בקצה הישיר וארה״ב עקיפה יותר. שם המשפט נשמע כהתקפה.","1":"להימנע מהתנגדות בשיחה מוותר על הכנות. שומרים על התוכן והישירות, ומשנים רק את העטיפה.","3":"העברה למנכ״ל לא פותרת את פער הסגנון ומוציאה את ה-PM מהשיחה. מה שצריך לשנות הוא העטיפה, לא את מי שאומר."},"14":{"0":"גלגול הפער להערכת הביצועים הוא בדיוק מה שהשלב מזהיר ממנו. מתכננים מחדש את היעדים בגלוי.","2":"דחיית כל ההחלטות משתקת את הצוות לחמישה שבועות. ממלא מקום ומסמך העברה מונעים שידע יחיה בראש אחד.","3":"אישורים מרחוק בזמן שירות משאירים את הידע בראש אחד ואינם מכבדים את השירות. לשם כך יש ממלא מקום."}},"32":{"0":{"0":"שיתוף מסמכים הוא התלהבות, לא כוח. Champion נבחנת במעשים, ומי שלא מביאה למקבל ההחלטות מתנהגת כמו Coach.","1":"להפסיק לבקש גישה משאיר את ה-EB לא ידוע עד הסוף. הצעד הנכון הוא לבקש שוב, עם חומר שעוזר לה להציג.","3":"פנייה עוקפת בלי לספר לה פוגעת באמון של מי שעוזרת לכם מבפנים. עדיף לבקש שוב ולצייד אותה בחומר."},"1":{"0":"סיפור החברה מדבר עליכם, לא עליו. ל-EB מגיעים עם תוצאה עסקית: הבעיה במספרים שלו והמחיר של לא לשנות.","1":"סיור במסכים מתאים למשתמשים, לא למי שמחליט אם להעביר תקציב.","3":"לוגואים בונים אמון, אבל הם לכל היותר הוכחה משנית. בלעדי הבעיה ומחירה, אין לו סיבה להקשיב."},"2":{"0":"מסך ההגדרות מרחיק אותה מהבעיה שלה. היא רוצה לראות את התוצאה, לא את הארכיטקטורה.","1":"שיא בסוף נשמע הגיוני, אבל בדקה ה-18 חצי מהחדר כבר בטלפונים. מתחילים מהתוצאה שהלקוחה רוצה.","2":"עכבר חופשי מהדקה הראשונה מרחיק אותה מהבעיה שלה. קודם מראים את התוצאה, ואז את הדרך הקצרה אליה."},"3":{"0":"השמצת המתחרה פוגעת באמינות שלכם ולא מבררת מה עומד מאחורי ההתנגדות.","1":"הבטחה לרבעון הבא סוגרת את הנושא מהר, אבל היא התחייבות בלי גילוי ובלי אישור.","3":"טבלת חולשות של המתחרה לא עונה על השאלה איזו בעיה זה פותר ללקוח, ושוב מדברת על המתחרה במקום על הצורך."},"4":{"1":"רשימה מלאה ארוכה מדי למבט חטוף באמצע שיחה. Battlecard שמיש קצר מספיק לרפרוף ונותן ניסוחים מוכנים.","2":"הסתרת החוזקות של המתחרה מתפוצצת מול הלקוח, והמוכרים מפסיקים לסמוך על הכרטיס.","3":"Battlecard צריך להישאר מעודכן. כרטיס שלא משתנה מתיישן, ולכן יש בו תאריך אימות."},"5":{"0":"שדה ״סיבת ההפסד״ נוטה לומר ״מחיר״: קונים מרככים ביקורת ומוכרים לא מציינים את עצמם. צריך לאבחן קודם.","2":"נתוני ה-CRM הם נקודת התחלה, לא זבל. לא מתעלמים מהם, אלא בודקים אותם מול ראיונות עם הקונים.","3":"הנחה ממוקדת נשמעת זהירה, אבל היא מתקנת בעיה שעוד לא אובחנה."},"6":{"1":"Decision criteria עוסק במה שלפיו בוחרים ספק. שאלון אבטחה ונספח עיבוד נתונים מגיעים אחרי ההחלטה, בדרך לחתימה.","2":"Metrics מגדיר את התוצאה העסקית שהלקוח רוצה. הוא לא ממפה רכש, משפטית ואבטחה.","3":"Decision process גם עוסק בתהליך, אבל הוא נגמר בהחלטה. כאן העיכוב קרה אחרי ה״כן״, בדרך לחתימה."},"7":{"0":"דמו והצעת שדרוג הופכים את הפורום למכירה. CAB קיים כדי ללמוד מהלקוחות, כשהם מדברים רוב הזמן.","1":"איסוף משאלות נשמע כמו הקשבה, אבל הבטחת תאריכים בחדר הופכת את הפורום לשוק.","2":"מצגת גיוסים הופכת את המפגש למכירה של הספק, ולא מאפשרת ללקוחות לאתגר את התוכנית."},"8":{"0":"תחושה לא מחליפה ראיה. EB שאף אחד לא פגש הוא הנחה, ולכן העסקה לא נשארת ב-Commit.","2":"תיקון מספרי של התחזית לא מחליף ראיות. הסקירה בודקת כל עסקה לפי הראיה שמאחורי הצבע.","3":"דווקא Champion ״שתציג להנהלה״ בלי גישה ל-EB הוא בדיוק מה ש-MEDDPICC נועד לחשוף."},"9":{"0":"מחיר והנחות הם תפקידים מסחריים. ה-PM תורם באותיות שבהן ידע מוצרי משנה: כאב, מדדים, קריטריונים ותחרות.","1":"התחזית וההחלטה מה נכנס ל-Commit שייכות לצד המסחרי, לא ל-PM.","2":"מסלול הנייר נראה כמו עבודה מסודרת שאפשר לקחת, אבל הוא שייך ל-AE ולתפקידים המסחריים."},"10":{"0":"סביבה גדולה יותר לא פותרת את הבעיה: POC בלי קריטריונים הוא ארגז חול שלא נגמר בהחלטה.","2":"הנחה לא מגדירה מה נחשב הצלחה. בלי קריטריונים, בעלים ותאריך, ה-POC לא יוביל להחלטה.","3":"לוח זמנים ארוך נשמע נדיב, אבל הוא רק מותח הערכה שאין לה יעד."},"11":{"0":"הצגה כאילו זה קיים עוזרת לסגור, אבל הלקוח יגלה, והאמינות של כל הדמו תיפגע.","1":"קוד ייעודי לדמו אחד הוא תחזוקה בלי ערך, והשלב פוסל קוד מיוחד בתוך המוצר עבור דמו.","3":"אין צורך להסתיר כל כיוון: מותר להציג מסך עתידי כשהוא מסומן ככיוון, באישור ה-PM ובלי תאריך."},"12":{"0":"צבע לוגו של לקוח אחד הוא בקשה בודדת. לבקשה כזו נותנים מעקף או ״לא״ מנומק, לא גילוי.","2":"יכולת שכבר קיימת דורשת הצגה טובה יותר ואולי שיפור UX, לא גילוי של משהו חדש.","3":"אינטגרציה ללקוח יחיד שמתכנן להחליף מערכת היא בקשה בודדת, לא דפוס. מקבלת מעקף או ״לא״ מנומק."},"13":{"0":"אישור ה-AE ותאריך שהלקוח בחר לא בודקים עלות, קיבולת והתאמה למוצר. אלה בדיוק מה שחסר כאן.","1":"אישור VP Sales נשמע בכיר, אבל לא מחליף בדיקת עלות, קיבולת והתאמה למוצר. ותאריך של מתחרה אינו הערכה.","2":"הערכה בעל-פה ומילה של Champion הן לא גילוי, לא עסקה מוסמכת ולא אישור הנהלת המוצר."},"14":{"1":"הסיבה לא הייתה מדיניות גורפת: ההשקעה של שישה שבועות מפתח בעסקה עם פערים ב-EB ובמדד הייתה הימור.","2":"לורה נשארה ה-Champion והוכיחה זאת במעשים. הפגישה נועדה לברר אם הסנכרון חשוב ל-EB.","3":"ה-EB לא מאשר כל החלטה טכנית. הפגישה נועדה לסגור פער במפה: לא ידעו אם הסנכרון בכלל חשוב לו."}},"33":{"0":{"0":"מקור הליד חשוב רק אחרי שיודעים שהלידים טובים. MQL הוא מי שהביע עניין, לא קונה.","2":"עלות לליד חשובה רק אחרי שיודעים שהלידים איכותיים. ליד זול מהפלח הלא נכון לא שווה כלום לעסק.","3":"פתיחות והקלקות מראות עניין בתוכן, לא אם הלידים הפכו להזדמנויות ואם הם מהקהל הנכון."},"1":{"0":"ההפך: נתח קול מעל נתח השוק נוטה ללוות צמיחה לאורך זמן, ולכן אינו בהכרח בזבוז.","1":"Binet ו-Field מצאו קשר: בממוצע כ-0.5% צמיחה בשנה בנתח השוק על כל 10 נקודות של עודף קול.","3":"המחקר מראה את הכיוון ההפוך: מותג שבולט יותר מנתח השוק שלו נוטה לצמוח, לא להתכווץ."},"2":{"0":"צפיות מראות חשיפה, לא הבנה. הן לא אומרות אם הקונים הבינו את המסר.","1":"שביעות הרצון של המוכרים חשובה, אבל היא לא מה שהלקוח הבין.","2":"פרסום באתרי חדשות הוא חשיפה, לא הבנה. האות החזק הוא קונים שחוזרים על המסר בעצמם."},"3":{"0":"טרנד אינו קטגוריה. יצירת קטגוריה יקרה ואיטית, ו-Redgate למשל התחברה לטרנד בלי להמציא קטגוריה.","1":"כשכולם אומרים AI, המילה עצמה לא מבדלת. מה שמבדל הוא מה שהיכולת עושה והחלופות לא, עם הוכחה.","3":"התעלמות מהטרנד מפספסת תשובה חשובה לשאלה ״למה עכשיו״."},"4":{"1":"Dunford מזהירה שחברות שיוצרות קטגוריה מפסידות לא פעם, בטווח הארוך, למי שנכנס אחריהן.","2":"הסיכון המרכזי אינו רישום סימן מסחר אלא חינוך השוק לבעיה ולמסגרת חדשה, וזה לוקח שנים ותקציב.","3":"חינוך שוק לקטגוריה חדשה לוקח שנים ותקציב, לא רק שנה של הכרה מאנליסטים."},"5":{"0":"״המתקדמת והחכמה ביותר״ היא טענה כללית בלי הוכחה, Puffery שלא ישכנע קונה ספקן.","1":"״התרעה מוקדמת״ היא עמוד, נושא שתומך בהבטחה. הוכחה היא משהו שאפשר לבדוק, כמו נתון עם מקור וגודל.","2":"״רואים מה נתקע״ הוא הגג, הצעת הערך. אין בו נתון, ציטוט או מקרה שאפשר לבדוק."},"6":{"0":"ה-PMM מוביל את המסרים, אבל ה-PM הוא הבעלים של אמת המוצר ויכול, וצריך, לעצור טענה לא נכונה.","1":"ה-PM לא כותב את השקף. התפקיד שלו הוא להביא את הנתונים והגבולות, והמסרים נשארים בידי ה-PMM.","2":"מה שמשכנע לא הופך טענה לנכונה. ״חוזה כל עיכוב״ היא טענה שהמוצר לא עומד בה."},"7":{"0":"הדרגה קובעת כמה משאבי שיווק ההשקה מקבלת, לא מי מקבל את הפיצ׳ר. השקת T1 יכולה, ולרוב צריכה, להתפזר בהדרגה.","2":"הפצה הדרגתית אינה שמורה ל-T3. הדרגה וההפצה הן שני צירים נפרדים.","3":"הדרגה נקבעת לפי ההשפעה על השוק והעסק, לא לפי מספר החשבונות שמקבלים את הפיצ׳ר."},"8":{"0":"Release Notes הם תיעוד עובדתי של מה שהשתנה, לא חומר שיווקי. הנרטיב הוא שמספר למה זה חשוב ללקוח.","1":"כל השקה צריכה Release Notes, ובעיקר השקות T1 ו-T2 צריכות גם נרטיב. זה הפוך מהמוצע.","2":"Release Notes מתעדים מה השתנה, והנרטיב מסביר מה השתנה בעולם של הלקוח. אף אחד מהם אינו מחירון או רשימת באגים."},"9":{"1":"כל שם חדש הוא עוד מילה שהלקוח צריך ללמוד. שמות מותג נשמרים למה שנמכר בנפרד או משנה את הסיפור.","2":"פיצ׳ר בתוך המוצר מקבל שם שמתאר מה הוא עושה. שם שנון לא אומר ללקוח מה הפיצ׳ר עושה.","3":"שם באנגלית בלבד מתעלם מהממשק ומהמילון בעברית."},"10":{"1":"שמות תיאוריים אינם אסורים בשיווק. הבעיה היא שהם חלשים כסימן מסחר ונרשמים רק בתנאים מסוימים.","2":"האורך אינו העניין. ההבדל בין פיצ׳ר למוצר הוא ההגנה: שם תיאורי ברור, אבל קשה להגן עליו.","3":"התרגום אינו הבעיה. שם תיאורי חלש מבחינת סימן מסחר, ולכן פחות מתאים למוצר שבונים לשנים."},"11":{"0":"תרגום מילולי עלול להישמע נוקשה או להיקרא אחרת, כמו שקרה ל-Velox בקייס. ומסר שנבדק באנגלית לא נבדק בעברית.","2":"עמוד בעברית צריך מסר שעובד בעברית. מסר שנבדק באנגלית לא נבדק מול קונים ישראלים.","3":"תרגום אוטומטי עם בדיקת כתיב נשאר מילולי: הוא לא בודק את התחושה והמטרה, ולא נבדק מול קונים."},"12":{"0":"בכ-60 המרות בחודש A/B לא יגיע למובהקות בזמן סביר, ותוצאה של שבוע היא בעיקר רעש.","1":"עמיתים כבר יודעים מה התכוונתם, ולכן לא יגלו אם קונה מבחוץ מבין את המסר.","3":"נפח חיפוש של מילת מפתח לא בודק אם הקונים מבינים את המסר ולמה."},"13":{"0":"חוק הגנת הצרכן אכן חל בעיקר על צרכנים, אבל ב-B2B יש כלים אחרים: חוק עוולות מסחריות ודיני חוזים.","2":"חוק עוולות מסחריות אוסר תיאור כוזב גם של המוצר שלכם, לא רק של מתחרה.","3":"גם טענה במצגת מכירה יכולה להספיק: חוק החוזים מאפשר ביטול חוזה שנכרת בגלל הטעיה."},"14":{"0":"כלל ״אם-אז״ קבוע אינו AI. תווית AI על יכולת בלי מודל היא AI-Washing, והיא מטעה לקוחות.","1":"הבעיה אינה עיצובית אלא הטעיה. לקוח שיגלה שה-AI הוא כלל קבוע יפסיק להאמין גם ביכולות האמיתיות.","3":"ה-FTC הבהירה שאין ״פטור AI״ מהחוק, גם כשהלקוחות הם עסקים, ולא רק גופים פיננסיים מפוקחים."},"15":{"0":"בלי לדעת למי מוכרים ומול מה משווים, כל כותרת היא ניחוש. עמוד הנחיתה נגזר מה-ICP ומהמיצוב.","2":"יערה גילתה שלקוחות משווים בפועל לסקריפטים של צוות ה-IT, כך שכרטיס מוקדם מול Zapier היה מכוון לחלופה הלא נכונה.","3":"סרטון שמושך תשומת לב עדיין צריך מסר. בלי ICP ומיצוב, התוכן שלו הוא ניחוש."},"16":{"1":"הבעיה אינה שם של לקוח. התיאור מדבר על אדם ולא על ארגון, ולכן זו פרסונה ולא ICP.","2":"ICP אינו מילה אחת: הוא מתאר ענף, גודל, מבנה, טריגר ומתי לא למכור.","3":"ICP ופרסונה הם שני מסמכים שונים: ארגון מול אדם בתוך העסקה. כשמערבבים, המכירות מגיעות לאנשים הנכונים בארגונים הלא נכונים."},"17":{"0":"השקת T1 דורשת עמודים, הכנת מכירות וסיפורי לקוח ש-PM לבד לא יכול להפיק בלי לוותר על Discovery.","1":"ביטול השקה של מוצר מוכן מוותר על הערך ללקוחות. אפשר לבקש משאבים או להוריד את הדרגה בגלוי.","3":"״T1 במצגת, T3 בפועל״ הוא הגרוע מכולם: ההנהלה מצפה לתוצאות שאף אחד לא תכנן לספק."},"18":{"0":"קונים מרככים ביקורת מול מי שמכר להם, ולכן כדאי שישאל מישהו שלא היה בעסקה.","1":"סקר שנתי מגיע מאוחר מדי ושומע בעיקר את המרוצים.","2":"זכיות מראות מה באמת הכריע את ההחלטה. בלעדיהן לא יודעים מה לשמר במסר ובמוצר."},"19":{"0":"עוד יכולות מאריכות רשימה שכבר לא נקראת. הקונה צריך לראות במבט אם החבילה בשבילו ובמה היא שונה.","2":"״Platinum״ עדיין לא אומר למי החבילה ומה מקבלים בה. זה אותה בעיה בשם אחר.","3":"הסתרת מחיר מתאימה לפעמים לעסקאות גדולות, אבל היא לא פותרת בעיית הבנה של החבילות."},"20":{"0":"תקציב פנוי אינו סיבה לגייס. הסימן האמיתי הוא עומס שדוחק את ה-Discovery.","1":"מה שהמתחרה עושה אינו סיבה. גיוס PMM נובע מעומס ומצורך אמיתי אצלכם.","3":"עיצוב אתר מחדש הוא עבודה למעצב או לסוכנות, לא בהכרח ל-PMM."},"21":{"0":"סקר עובדים על צבעים לא מגלה למה לקוחות עוזבים. הסיבה היא לרוב בחוויה, לא בלוגו.","2":"עלות ותזמון של לוגו קופצים לביצוע לפני שבדקו את הסיבה. מיתוג מחדש לא מתקן הבטחה שבורה.","3":"מה שמתחרים עשו לא מסביר את הנטישה שלכם. ומיתוג מחדש עלול לאפס נכסים מבדלים שכבר נבנו."},"22":{"0":"עלייה בהמרה לבדה לא מראה מה קורה אחר כך: ביטולים, תלונות ואמון.","1":"פסילה גורפת מוותרת על הלמידה. מדדי מעקה וגרסה בקול המותג בודקים אם אפשר לקבל את שניהם.","3":"המתח בין צמיחה למותג צפוי, וה-PM מכריע בו לפי נתונים וההבטחה. אין להעביר את ההחלטה הלאה."},"23":{"1":"הטמעה מיידית מוותרת על הון מותג ששילמתם עליו, כשהקהל וההבטחה שונים.","2":"עצמאות מלאה לתמיד יקרה ולא מעבירה שום אמון מ-Velox.","3":"שם חדש לגמרי מוחק את מה שהלקוחות כבר מכירים, ולא מעביר אמון מ-Velox."},"24":{"0":"עוקבים הם חשיפה לטווח קצר. הון מותג הוא ההבדל שהשם עושה להחלטה ולמחיר.","1":"הקלקות בשבוע אחרי כנס מראות חשיפה קצרה, לא מה שהשוק זוכר.","2":"מספר פיצ׳רים מודד תפוקה, לא את ההשפעה של השם על החלטת הקונים."},"25":{"1":"Binet הראה קשר בשלוש קטגוריות צרכניות ב-2020, לא בכל תחום. ב-B2B, עם מעט חיפושים, המספר רועש.","2":"Binet דווקא מצא קשר בין נתח חיפוש לנתח שוק. ב-B2B הוא רועש, ולכן משתמשים בו כמגמה ולא פוסלים.","3":"השוואה חד-פעמית לממוצע מפוסט מתעלמת מהשיטה. משווים לעצמכם לאורך זמן."}},"34":{"0":{"1":"מה שהמתחרים עושים הוא שיקול, לא המבחן. יחידה טובה מתיישרת עם הערך, צפויה, וגדלה עם הלקוח.","2":"נוחות החיוב היא שיקול, לא המבחן. ״פרויקט״ נכשל כאן כי לקוחות יאחדו פרויקטים כדי לחסוך.","3":"הכנסה מיידית היא שיקול, לא המבחן. יחידה שלא משקפת ערך תשחק לרעתכם כשהלקוחות יתאימו את עצמם אליה."},"1":{"0":"״ללא הגבלה״ חושף את שולי הרווח לזנב הכבד: העלות עולה עם כל פעולה, והמחיר לא.","1":"תשלום לפי שימוש בלבד יוצר חשבון לא צפוי, בדיוק מה שהקונים לא רוצים.","2":"תמחור לפי תוצאה דורש הגדרה מוסכמת של ״הושלם״. כשהסוכן מחליט על כך בעצמו, זה מזמין ויכוחים."},"2":{"1":"בתוך Pro היכולת תעלה את העלויות ותוריד את הערך של החבילה לרוב הלקוחות, שלא מעוניינים בה.","2":"ויתור מפספס את ה-15% שמוכנים לשלם הרבה. מוותרים רק כשגם העניין וגם הנכונות לשלם נמוכים.","3":"ב-Free היכולת היקרה רק מייקרת משתמשים שלא משלמים."},"3":{"0":"ה-PM מכיר את המוצר, אבל לא רואה לבד את כל התמונה: הכספים מביאים רצפות ושוליים, והמכירות את השטח. בשינוי גדול ההחלטה של המנכ״ל.","2":"הכספים מביאים רצפות ושולי רווח, אבל לא רואים את היחידה, האריזה והשימוש במוצר. אף אחד לבד לא רואה הכל.","3":"המכירות מביאות את השטח, אבל היחידה והאריזה הן מה שהמוצר אחראי עליו. לבנות מוצר סביב מחיר זה הפוך."},"4":{"0":"השקיפות אינה העניין: לצרכן מציגים מחיר כולל בלבד, במטבע ישראלי וכולל מע״מ, ודולרים אינם עומדים בזה.","2":"הערה בתחתית לא מספיקה: סעיף 17ד אוסר להציג לצרכן מחיר שאינו המחיר הכולל בלבד.","3":"החוק לא מחייב תקופת ניסיון. הבעיה היא אופן הצגת המחיר: כולל, בשקלים וכולל מע״מ."},"5":{"0":"ב-$20 יותר אנשים אומרים ״כן״, אבל המכפלה היא 12, נמוכה מ-12.5 שמתקבל ב-$25.","1":"המחיר הגבוה ביותר לא ממקסם הכנסה: $30 כפול 35% הם 10.5, הנמוך מבין השלושה.","2":"ארבע השאלות שייכות ל-Van Westendorp, שיטה אחרת שמודדת טווח מחיר. כאן מספיק לכפול מחיר בשיעור הקונים."},"6":{"0":"הורדת מחיר בלי אבחון מוותרת על הכנסה. בראיונות מתגלה לא פעם סיבה אחרת, כמו ערך שלא הוכח.","1":"סקר ללקוחות קיימים לא שואל את מי שלא קנה, ולכן לא מגלה למה הפסדתם.","3":"העברת אישורים למנכ״ל לא עונה על השאלה למה הפסדנו."},"7":{"0":"ב-Reverse Trial לא משלמים מראש. מתחילים עם היכולות בתשלום לזמן מוגבל, ובסוף יורדים לחבילה חינמית.","1":"הסדר הפוך: מתחילים ביכולות בתשלום, ורק בסוף התקופה יורדים לחבילה החינמית.","3":"יש הבדל של ממש: בניסיון רגיל מאבדים גישה בסוף, וב-Reverse Trial נשארים בחבילה חינמית."},"8":{"1":"כשמשתמש חינמי יקר, Freemium נדיב מממן משתמשים שאולי לעולם לא ישלמו.","2":"פרסומות לא פותרות את בעיית העלות, וחבילה בלי הגבלה רק מגדילה אותה.","3":"מחיר מלא בלי ניסיון מוסיף מחסום, דווקא כשהערך מורגש רק אחרי כמה ימי הגדרה."},"9":{"0":"85% מתעלם מהקרדיטים. עלות Inference שנוצרת בכל שימוש היא חלק מעלות המכר, עד $1.20 נוספים.","1":"עלות Inference שנוצרת בכל שימוש היא עלות מכר, לא הוצאת פיתוח, ולכן היא נכנסת לשולי הרווח.","3":"חבילות קרדיטים נמכרות בנפרד ומביאות הכנסה משלהן, ולכן הן לא מורידות את שולי הרווח של המושב."},"10":{"0":"הורדת מחיר כדי שלא ישימו לב מוותרת על הכנסה ולא עוזרת ללקוח להבין מה ״שורף״ קרדיטים.","1":"״ללא הגבלה״ שאינו כזה פוגע באמון. קרדיטים נכשלים בדרך כלל בהסבר, לא במספרים.","3":"שינוי שקט לחלק מהלקוחות פוגע באמון. ב-Cursor חיובים מפתיעים הובילו להתנצלות והחזרים."},"11":{"0":"אישור אוטומטי מלמד את השוק שהמחירון לא אמיתי.","1":"סירוב גורף מפספס עסקאות טובות. הנחה עמוקה עולה לדרג שרואה את כל התמונה, עם תמורה.","2":"הבטחת פיצ׳ר בתמורה להנחה היא בדיוק Roadmap שנכתב לפי עסקאות."},"12":{"0":"$12.75 רואה רק את החשבונית ומפספס את הדליפה: משלמים רק על 9 מתוך 12 חודשים.","2":"חודשים חינם הם הכנסה שלא נכנסת. במפל המחיר הם נערמים על ההנחה שבחשבונית.","3":"$11.25 סופר רק את החודשים החינמיים ושוכח את 15% ההנחה. שתיהן מצטברות."},"13":{"0":"בנטישה של 10% נשארים 90% מהמושבים, ו-90% כפול $50 הם $45, יותר מ-$40. ההכנסה עדיין עולה.","2":"בנטישה של 25% נשארים 75%, ו-75% כפול $50 הם $37.50, כבר פחות מ-$40. נקודת האיזון נמוכה יותר.","3":"ב-50% נשארת מחצית מהמושבים, $25 במקום $40. ההכנסה מתחילה לרדת הרבה לפני כן."},"14":{"1":"החוק לא אסר העלאה. ההפרדה נועדה להגן על השוליים מהר ולתת לוותיקים זמן להסתגל למחיר.","2":"המחקר לא קבע את $8 כתקרה. דחיית המחיר נועדה להקטין נטישה, לא לשמור עליו לעולם.","3":"גיא דווקא רצה להעלות מחיר לכולם בבת אחת. הסיבה הייתה הפרדה בין הגנה על השוליים להגנה על הוותיקים."}},"35":{"0":{"0":"מתחרים חשובים, אבל בלי מפת הקונים תבנו לפי הרגלים מהתחום הקודם. בבנק החותם, המשתמש ומי שעוצר הם אנשים שונים.","1":"שימור חודשי הוא הרגל מהעולם הצרכני. בבנק קודם צריך להבין מי חותם, מי משתמש ומי יכול לעצור.","3":"בבנק Compliance, רכש ו-Legal יכולים לעצור את העסקה. Onboarding בלי שיחה מתעלם ממי שבאמת מחליט."},"1":{"1":"חוק הפיקוח על יצוא ביטחוני חל גם על השיווק שקודם ליצוא, לא רק על המשלוח.","2":"מקור המימון לא פוטר מפיקוח. פטור מאמתים מול אפ״י, לא מניחים אותו.","3":"הסכם סודיות לא פוטר מרישום ומרישיון שיווק. שיווק בלי רישיון הוא סיכון משפטי אמיתי."},"2":{"0":"מצגת היא הבטחה. בביטחון ״הוכח בשטח״ מנצח כל מצגת.","2":"הורדות בגרסה אזרחית מודדות שוק אחר, עם משתמשים וצרכים אחרים. הלקוח הביטחוני רוצה לראות עבודה בתנאים אמיתיים.","3":"לקוח צרכני מרוצה שייך לשוק אחר. לקוח ביטחוני מחפש ניסוי שטח ורמת מוכנות שמתאימה לרכש."},"3":{"0":"MVP לא פוטר מרישיון. בפינטק ״מה מותר?״ היא שאלה מוצרית ששואלים לפני האפיון, לא אחרי.","2":"בטא סגורה לא פוטרת מרישיון. החזקת כסף של אחרים עלולה להפוך את החברה לגוף מפוקח כבר מהיום הראשון.","3":"אחרי ההשקה זה מאוחר מדי: אם נדרש רישיון, השירות כבר פועל בלעדיו. שואלים לפני האפיון."},"4":{"0":"הצפנה לבדה לא מוציאה מתחולת התקן: מי ששומר נתוני כרטיס עדיין כפוף ל-PCI DSS.","1":"מייל הוא בדיוק מה שהתקן בא למנוע. וגם כך נתוני הכרטיס מגיעים אליכם.","3":"ענן ציבורי לא מוריד מכם את האחריות. כל מי ששומר נתוני כרטיס כפוף לתקן."},"5":{"0":"MITRE לא מפרסמת דירוג. ההערכות מראות איך מוצרים מזהים שלבי מתקפה, ולכן ״מספר 1״ אינו טענה נכונה.","1":"למבחנים יש משקל: הם מראים איך מוצרים מזהים שלבי מתקפה. המגבלה היא שאינם דירוג וכיסוי יכול להסתיר רעש.","2":"כיסוי מלא יכול לבוא עם הרבה התרעות שווא. CISO ירצה לראות רמת רעש ו-POC בסביבה שלו."},"6":{"0":"לפי הסקר של Gartner, רוב הארגונים מצמצמים ספקים כדי לשפר את מצב הסיכון, ורק מיעוט כדי לחסוך. הנחה לא עונה על הצורך.","1":"עשרה מודולים חלשים לא הופכים מוצר לפלטפורמה. מוצר נקודתי שורד כשהוא סוגר פער כואב ומשתלב במה שכבר נקנה.","2":"המתנה משאירה את המוצר בחוץ בזמן שה-CISO כבר מצמצם. מה ששורד הוא מוצר שמשתלב בפלטפורמות הקיימות."},"7":{"0":"אלגוריתם שמנבא הידרדרות ומכוון החלטה קלינית הוא כמעט בוודאות תוכנה רפואית. ״Wellness״ כדי לעקוף רגולציה הוא מלכודת.","2":"ניסוי A/B על מטופלים הוא בדיוק אחת המלכודות. בתוכנה רפואית בונים ראיות בתיקוף קליני מסודר.","3":"שחרור לרופאים לפני בדיקת המסלול הרגולטורי מפעיל תוכנה רפואית בלי אישור ובלי תיקוף קליני."},"8":{"0":"אישור FDA לא תקף אוטומטית: עדיין צריך רישום ישראלי באמ״ר, עם הצהרות ומסמכים.","1":"ישראל דווקא נשענת על אישורים ממדינות מוכרות כמו ארה״ב, ולכן לא צריך מחקר קליני מאפס.","2":"אמ״ר נשען על אישורים ממדינות מוכרות, כולל ארה״ב, ולא רק על סימון CE."},"9":{"1":"פתיחה לכולם יוצרת חנות ריקה. שוק בלי נזילות מאכזב את שני הצדדים, ואפקט הרשת לא מתחיל.","2":"רוב השווקים ש-Lenny Rachitsky חקר טיפלו קודם בהיצע. קונים שמגיעים לחנות ריקה מתאכזבים.","3":"עמלה גבוהה מוקדם מדי מזמינה דליפה: הצדדים ייפגשו בחנות ויסגרו ביניהם מחוצה לה."},"10":{"0":"חסימת פרטי קשר מעצבנת את שני הצדדים ולא נותנת להם סיבה להישאר.","1":"העלאת עמלה רק מגבירה את הדליפה, כי היא מגדילה את התמריץ לעבוד מחוץ לחנות.","3":"התעלמות מפסידה עמלות ונתונים. דליפה היא סימן שהפלטפורמה לא נותנת מספיק ערך אחרי ההיכרות."},"11":{"0":"מי שמחכה למכרז מגלה את תנאי הסף מאוחר מדי, ומפספס את ההזדמנות לעזור לנסח דרישות מעשיות.","2":"ניסיון לעקוף את ועדת המכרזים מסכן את ההצעה.","3":"הדרישות עוד לא נקבעו. RFI הוא ההזדמנות לעזור לנסח אותן וללמוד את תנאי הסף, לא לנחש ולבנות מראש."},"12":{"0":"כשל בתשלום ביום העמוס ביותר עולה יותר מכל שיפור בהמרה. לכן נהוגה הקפאת שינויים לפני עונת שיא.","1":"ניסוי A/B בשיא העומס עדיין חושף חצי מהלקוחות לסיכון של כשל בתשלום.","2":"לבקש מהלקוח לבטל את העונה פשוט לא מציאותי. דוחים את השינוי, לא את העונה."},"13":{"1":"Roadmap בשבוע הראשון, לפני שמבינים את השפה ואת הכסף, הוא בדיוק מה ש-Watkins ממליץ להימנע ממנו.","2":"העתקה מהחברה הקודמת מתעלמת מהרגולציה, הסיכון והערך שמיוחדים לתחום התשלומים.","3":"שינויים לפני שמבינים למה עושים כך הם בדיוק מה ש-Watkins ממליץ להימנע ממנו."},"14":{"0":"הסכמה מיידית הייתה לוקחת עלות קבועה של קו מוצר שני בשביל לקוח אחד, כשהצורך האמיתי היה אחר.","1":"סירוב היה מפסיד עסקה שאפשר היה לענות עליה: כל הצרכים האמיתיים נפתרו בלי התקנה מקומית.","3":"הנחה לא עונה על מה שהבנק צריך באמת: נתונים בישראל, מפתחות בשליטתו ויומני ביקורת."}},"36":{"0":{"0":"לרכז את כל האירועים נשמע יסודי, אבל זה בדיוק מה שמייצר 40 גרפים בלי מטרה.","2":"כלי חדש לא אומר איזו החלטה הדשבורד משרת. בלי החלטה, יהיה מקום לעוד גרפים שאף אחד לא פותח.","3":"דשבורד ״מלא מכל הטבלאות״ הוא אותו קיר גרפים, רק מהר יותר. קודם שואלים איזו החלטה מחכה."},"1":{"0":"המוסכמה היא אובייקט ואחריו פעולה בזמן עבר. שם כפתור או מספר כפתור קושר את האירוע לממשק ולא לפעולה.","1":"אירוע לכל תבנית מפזר את אותה פעולה על עשרות שמות, ואי אפשר לבנות עליו משפך. הפרטים הולכים למאפיין.","2":"תאריך בשם הוא טעות דומה: הזמן כבר נרשם עם האירוע, ושם משתנה מפצל את אותה פעולה."},"2":{"0":"מייל מפתה כי הוא ״מזהה בוודאות״, אבל הוא משתנה והוא מידע אישי. ובלי workspace_id האירוע לא נכנס לחישוב.","1":"סשן מחבר ביקור אחד. מדד ברמת סביבת עבודה מחושב ממזהה הסביבה, לא מהביקור.","3":"המזהה האנונימי נועד לזמן שלפני ההרשמה. בלי מזהה הסביבה, אי אפשר לחשב שיעור הפעלה לכל סביבה."},"3":{"0":"מהדפדפן האירוע עלול ללכת לאיבוד בחוסמי פרסומות, ולהישלח גם כשההזמנה בכלל נכשלה.","2":"שליחה משני הצדדים תחת אותו שם סופרת כל הזמנה פעמיים.","3":"ניסיון חוזר לא פותר חסימה בדפדפן, והאירוע עדיין יישלח גם כשההזמנה נכשלה."},"4":{"0":"כלל איחוד בכלי האנליטיקה מתקן מקום אחד ומשאיר את המחסן שבור, כמו שקרה בקייס.","1":"שינוי שם מותר, הוא פשוט גרסה חדשה של חוזה: מעדכנים, ממפים, מודיעים ובודקים.","3":"לחכות שמשהו יישבר מעביר את הבעיה לצרכנים. ממפים את שני השמות ומודיעים מראש, לפני השחרור."},"5":{"0":"קוד שעובר קומפילציה ובדיקות יחידה לא אומר שהאירוע מגיע בשם הנכון, עם המאפיינים והמזהים.","1":"חודש אחרי ההשקה זה מאוחר: נתונים שגויים כבר נאספו. בודקים לפני, ומשווים למסד המוצר כבר יום אחרי.","2":"אישור שהחיבור תקין לא בודק שכל אירוע מגיע פעם אחת, בשם הנכון ורק כשהפעולה הצליחה."},"6":{"1":"לפי ה-GDPR, מידע שעבר פסאודונימיזציה ואפשר לקשר בחזרה לאדם עדיין נחשב מידע על אדם מזוהה.","2":"הבעיה איננה ביצועים. זה מידע אישי שאפשר לקשר בחזרה, והמדד ממילא לא צריך אותו.","3":"מיקום הספק לא הופך מייל מגובב לאנונימי. והמדד צריך רק כמה הזמנות נשלחו ואיך."},"7":{"1":"כלי האנליטיקה מהיר, אבל רואה רק מה שנשלח אליו: לא את פניות התמיכה ולא את החיוב.","2":"הדשבורד מציג שיעור הפעלה לפי חודש ולא מחבר פניות תמיכה וחיוב.","3":"דוח CRM מראה לקוחות משלמים, אבל לא אירועי מוצר ופניות תמיכה. השאלה חוצה שלושה מקורות."},"8":{"0":"COUNT(*) סופר שורות, כלומר אירועים, לא משתמשים. 12,400 הן משימות, ו-1,850 הם האנשים.","1":"השאילתה היא על Task Created, ולא על צפיות. 12,400 הן אירועי יצירה, ו-1,850 הם משתמשים שונים.","3":"הפער נראה כמו כפילויות, אבל משתמש פעיל פשוט מופיע בהרבה שורות, וזה תקין לגמרי."},"9":{"1":"אזור זמן מזיז כמה שעות בקצוות החודש, ולא משלש שום ספירה.","2":"בוטים לא מסבירים ספירה שגדלה בדיוק לפי מספר החברים. חיבור אחד-לרבים משכפל כל סביבה לפי חבריה.","3":"ההכפלה נוצרה בחיבור בשאילתה, לא בטעינה. סופרים COUNT(DISTINCT workspace_id) או מקבצים חברים לפני החיבור."},"10":{"0":"ישראל מקדימה את UTC בשעתיים בחורף ובשלוש בקיץ, לא ביום שלם.","2":"עיגול לא מסביר את הפער. ההבדל נובע מגבולות חודש שזזים בכמה שעות בין שני אזורי הזמן.","3":"זה נשמע הגיוני, אבל קצוות החודש זזים: סביבות מהשעות הראשונות של החודש נספרות ב-UTC בחודש הקודם."},"11":{"1":"רשימות בוטים מוכרים לא מכירות את אוטומציית ה-QA שלכם. בדיקות מסמנים בעצמכם.","2":"עובדים בודקים, מדגימים ומנסים, ולכן מטים את נתוני ה-Onboarding. מסמנים חשבון פנימי ומסננים במודל.","3":"מחיקה באיסוף נשמעת יסודית, אבל מה שנמחק לא חוזר, גם אם הכלל היה שגוי."},"12":{"0":"עוד גרפים מגדילים את הקיר שאף אחד לא פותח. דשבורד נפתח כשברור מה עושים איתו.","1":"מייל עם 40 גרפים מעביר את אותו קיר לתיבת הדואר. הבעיה היא מטרה, לא ערוץ.","2":"החלפת כלי מפתה כשנראה שהממשק אשם, אבל כלי חדש לא פותר בעיה של מטרה."},"13":{"0":"בעיית טריות הייתה פוגעת רק בחודשים האחרונים, לא יוצרת פער קבוע לאורך כל החודשים.","1":"אזור זמן משפיע רק על קצוות התקופה ולא מסביר קפיצה באמצע.","2":"אין כלל כזה. פער קבוע מרמז על הבדל בהגדרה או במסנן, וקפיצה מתאריך מרמזת על שינוי באותו יום."},"14":{"0":"לבקש מהעוזר לנמק נשמע אחראי, אבל ביטחון של מודל אינו ראיה. בודקים את ה-SQL ומספר מוכר.","2":"אותה תשובה פעמיים יכולה להיות אותה טעות פעמיים. הכפילות בקייס נתפסה רק בהשוואה לסך מוכר.","3":"טבלה מעוצבת ומלאה עדיין יכולה לספור שורות כפולות. בודקים יחידה, אוכלוסייה ושעון ב-SQL."}},"37":{"0":{"0":"דמו נראה כמו התקדמות, אבל הוא מציג את המקרים שמתאימים לספק. ובלי החלטה ומדד, אין לפי מה להשוות.","1":"אחוז כיסוי מהאתר נמדד על אוכלוסייה של הספק. בלי לדעת איזו החלטה משתנה, לא יודעים אילו שדות ואיזו איכות צריך.","2":"חוזה בלי צורך מוגדר לא יודע על מה להגן. קודם מגדירים החלטה, מדד וערך לנקודה."},"1":{"1":"80% אכן נמדד, אבל שיעור התאמה לא אומר אם התשובה נכונה. כיסוי אפקטיבי הוא התאמה כפול דיוק.","2":"ממוצע של שיעור ההתאמה והדיוק חסר משמעות. מכפילים אותם: 0.80 כפול 0.84.","3":"ה-95% נמדד על אוכלוסייה אחרת. מה שקובע הוא מה שנמדד על הרשומות של Velox."},"2":{"0":"פרופיל לחברה שנסגרה הוא טעות, לא יתרון. הספק ממציא ערכים או לא מעדכן.","2":"50 רשומות מלכודת מספיקות כדי לחשוף את הבעיה. 6 פרופילים מלאים לחברות שלא קיימות הם כבר ממצא.","3":"רשומות מלכודת לא בודקות מהירות. הן בודקות אם הספק מחזיר נתונים על חברות שכבר לא קיימות."},"3":{"0":"ממוצע יכול להסתיר פלח שקרס. לכן הסף לכל פלח נקבע מראש כשער, ומי שנכשל בו יוצא.","1":"שאלת חובה בטופס מחזירה בדיוק את החיכוך בהרשמה שרצו להימנע ממנו.","2":"הנחה מורידה מחיר, אבל לא מתקנת כיסוי. ישראל עדיין נכשלת בשער."},"4":{"0":"השוואה בין נמצאו ללא נמצאו מוטה: חברות גדולות ומוכרות נמצאות יותר, והן שונות ממילא.","1":"השוואה לשנה שעברה מערבבת עונתיות וכל מה שהשתנה מאז. רק חלוקה אקראית מנטרלת את זה.","3":"תחושה של אנשי המכירות אינה מדידה, והיא לא מבודדת את השפעת ההעשרה."},"5":{"0":"הנחת כמות מוזילה גם את הרשומות השגויות. רשומה שגויה עולה פעמיים: בקנייה ובהחלטה שמתבססת עליה.","1":"תשלום מראש רק מגדיל את התלות בספק עוד לפני שהוכח ערך.","3":"הגדלת המינימום רק מגדילה את התלות לפני שהוכח ערך, ולא קושרת את התשלום לנכונות הרשומות."},"6":{"1":"נקודת האיזון היא 54 חלקי 20, כלומר 2.7 נקודות, לא 9. גם הקצה התחתון של רווח הסמך, 3, מעליה.","2":"רווח סמך שלא כולל את האפס הוא סימן לתוצאה מובהקת, לא לספק. והקצה הזהיר שלו כבר מעל נקודת האיזון.","3":"החישוב לפי רווח גולמי הוא הזהיר יותר, וגם כך ההשקעה מוחזרת. אין צורך בהכנסות כדי להגיע ל-Go."},"7":{"0":"הרישיון קובע מה מותר, לא הפרשנות שלנו. מודל פנימי הוא עדיין אימון, והרישיון אוסר אימון.","1":"נתוני ניסיון מוגבלים בדרך כלל לבדיקה בלבד, ולכן אימון עליהם אינו פתרון.","2":"הסתרת המקור רק מחמירה את ההפרה. הדרך הנכונה היא נספח כתוב, כולל מה קורה למודל בסוף."},"8":{"0":"זו מלכודת העלות השקועה: ההשקעה הקודמת לא תחזור, בין אם ממשיכים ובין אם לא.","1":"״בינתיים״ נשמע זהיר, אבל בקלות הופך לשנה של תשלומים על ספק שכבר נכשל.","3":"הנחה לא מתקנת כיסוי חסר. הספק עדיין נכשל במדגם העיוור."},"9":{"0":"רשויות הפרטיות מדגישות שמידע אישי מוגן גם כשהוא פומבי. ״גלוי ברשת״ אינו היתר לכל מטרה.","1":"״לקנות ולמחוק״ אומר שכבר עיבדתם מידע אישי שלא הייתם צריכים.","2":"מיקום הספק לא פוטר מחובות הפרטיות שמגיעות עם מידע אישי."},"10":{"1":"מספר הלקוחות של הספק אינו הבדיקה. מה שחובה לברר הוא אם המאגר רשום, כנדרש ממאגר שנועד למסור מידע לאחרים.","2":"גיל המידע אינו השאלה המשפטית כאן. אחרי תיקון 13, מאגר שמוכר מידע על יותר מ-10,000 איש חייב רישום.","3":"שאלת האחסון נשמעת רצינית, אבל היא בדיקת אבטחה אחרת. החובה הראשונה היא לברר אם המאגר רשום."},"11":{"0":"המותג של ספק הענן מפתה לחשוב שמישהו כבר בדק, אבל לכל מוצר יש הסכם של הספק, והאיכות והמקור באחריותכם לבדוק.","2":"לכל מוצר במרקטפלייס יש הסכם של הספק, ב-AWS ה-Data Subscription Agreement, שקובע את זכויות השימוש.","3":"אף אחד לא בדק בשבילכם. בודקים איכות, מקור וזכויות שימוש בדיוק כמו ברכישה ישירה."},"12":{"0":"סקירת החידוש באמת בודקת הכל, אבל היא מגיעה חודשים מאוחר מדי.","1":"אנשי מכירות לא רואים שיעור כיסוי, ולכן ירידה כזו לא תיתפס מהר דרכם.","3":"בדיקת הוצאות לא מודדת איכות, ורבעונית היא גם איטית מדי."},"13":{"1":"חוזה ארוך מפתה בגלל ההנחה, אבל הוא מעמיק את התלות בספק במקום להקטין אותה.","2":"מזהה הספק כמפתח ראשי קושר אליו כל מערכת, ומחליף ספק הופך לעבודה כבדה בכל מקום.","3":"שמירת נתונים אחרי סיום ההתקשרות מפרה בדרך כלל את הרישיון. צריך תוכנית מחיקה, לא עותק."},"14":{"0":"״פתוח״ אינו ״בלי תנאים״: ODbL מחייב ייחוס ושיתוף זהה, וכדאי לבדוק עם המחלקה המשפטית.","2":"ODbL דווקא מתיר שימוש מסחרי, בתנאי ייחוס ושיתוף זהה.","3":"התנאים של ODbL הם ייחוס ושיתוף זהה, לא תמלוגים לפי משתמשים."}},"38":{"0":{"0":"AI לא ביטל את ההנדסה: קוד ייצור, ארכיטקטורה ואבטחה נשארים בבעלותה, גם בפיצ׳רים קטנים.","1":"תווית בטא לא הופכת קוד שלא נבדק לבטוח. אין לו הרשאות, בדיקות או בעלים.","3":"ויתור על אבות-טיפוס הוא ויתור על הדרך המהירה ביותר ללמוד. PM בונה כדי ללמוד, לא כדי לשחרר."},"1":{"0":"תווית בטא לא משנה את העובדה שהנתונים חשופים לקוד שאף אחד לא בדק, בלי הרשאות ובלי ניטור.","2":"הגבלת זמן לא עוזרת: גם לשבוע, נתוני הלקוח חשופים לקוד בלי הרשאות, ניטור, בדיקות או בעלים.","3":"כתב ויתור משפטי לא משנה את הסיכון: הנתונים עדיין חשופים לקוד שאף אחד לא בדק."},"2":{"0":"נתוני ייצור מוסיפים סיכון בלי ללמד יותר. שאלת שימושיות נבדקת היטב גם על נתוני דמה.","2":"מצגת עם הסברים לא בודקת הבנה עצמאית: מיכל מסבירה, והמנהל לא מבצע משימה בעצמו.","3":"ליטוש מושך את הדיון לצבעים במקום לשאלה אם מנהל מבין לבד איך לבנות תוכנית."},"3":{"1":"תשלומים הם בנייה כדי להרוויח: טעות שם היא אירוע כספי, ולכן שייכת להנדסה גם כשהשינוי נראה קטן.","2":"שינוי בנתוני הייצור הוא בנייה כדי להרוויח. טעות בו פוגעת בלקוחות אמיתיים, ולכן הוא שייך להנדסה.","3":"שינוי הרשאות הוא בנייה כדי להרוויח: טעות שם היא אירוע אבטחה, ולכן הוא שייך להנדסה."},"4":{"0":"״עובד בדמו״ לא אומר שיש לו הרשאות, בדיקות או בעלים. בדיקות השימוש הוכיחו את הרעיון, לא את הקוד.","2":"פיתוח לבד מעביר קוד ייצור לבעלות ה-PM. אם משתמשים מחדש בחלק מהקוד, זו החלטה של ה-Tech Lead.","3":"ההקלטות הן בדיוק מה ששומרים: הקוד נזרק, והלמידה והאב-טיפוס כמפרט חי נשארים."},"5":{"1":"במצגות קשה למצוא גם את ההחלטה וגם את הנימוק שלה. רשומת החלטה שומרת את ה״למה״.","2":"ערוץ צ׳אט מתעד ״מה״ בלי הקשר וממה ויתרו, וקשה למצוא בו את הנימוק אחרי חצי שנה.","3":"בתמלול מלא קשה למצוא את ההחלטה ואת הנימוק שלה. רשומה של עמוד או שניים שומרת את ה״למה״."},"6":{"0":"סיכומים מאבדים את הראיה בדרך, ולא מאפשרים לספור כמה ראיונות תומכים בכל ממצא.","1":"מצגת של עשר תובנות מאבדת את הראיות ואת שאר הממצאים, ואי אפשר לחפש בה או לחבר אותה למחקרים הבאים.","3":"הקלטות מלאות בלי תגיות כמעט בלתי אפשריות לחיפוש, ולא מאפשרות לספור תמיכה בממצא."},"7":{"1":"עוד מידע אינו תשובה טובה יותר: ההקשר מוגבל, ורעש מוריד איכות. והמודל עדיין לא יידע מה בוטל.","2":"עוד מסמכים בלי סטטוס ותאריך לא אומרים למודל איזו גרסה עדכנית ואיזו החלטה בוטלה.","3":"גישה לכל התיקיות מוסיפה רעש ועוקפת הרשאות, שצריך לאכוף לפני השליפה."},"8":{"0":"פרקים של PRD אחד תלויים זה בזה. סוכנים מקבילים שלא רואים זה את זה יקבלו החלטות סמויות שלא מתיישבות.","1":"כשכל מסך תלוי בקודם, סוכנים מקבילים מקבלים החלטות סמויות שלא מתאימות זו לזו.","2":"לשאלה קצרה צוות סוכנים רק מוסיף עלות: מערכת כזו יכולה לצרוך פי 15 טוקנים."},"9":{"0":"בדיקה רק בסוף מפספסת טעויות שהצטברו בדרך, כשכבר קשה למצוא מאיפה הגיעו.","2":"סוכנים לא מחליפים את נקודות הבדיקה של מי שמריץ אותם: התוכנית, דגימה מכל סוכן ומה שיוצא החוצה.","3":"בדיקה בכל צעד מבטלת את היתרון של סוכנים. מספיק לעצור בנקודות שבהן טעות עולה הכי הרבה."},"10":{"0":"בקשה כללית לא מגדירה מהי הצלחה: אין מטרה, אין הקשר של ההחלטה ואין הגדרת סיום.","1":"״תפקיד״ מרשים לא מגדיר מהי הצלחה. הסוכן צריך מטרה, הקשר, מגבלות, דוגמה והגדרת סיום.","3":"רשימה ארוכה של איסורים בלי מטרה מבלבלת את הסוכן במקום להנחות אותו."},"11":{"0":"מודל שמאשר את עצמו אינו הוכחה לדיוק. סינתזה של AI יכולה להמציא ציטוטים.","1":"דוח כתוב היטב יכול להכיל ציטוטים מומצאים. הבדיקה החשובה היא מול המקור, לא הניסוח.","2":"התאמה לציפיות לא מוכיחה דיוק. היא דווקא סיבה לבדוק פעמיים."},"12":{"0":"זה הגבול המשונן: משימות שנראות דומות יכולות ליפול משני צדי היכולת של המודל. הכללה מהצלחה אחת מסוכנת.","1":"ויתור מוחלט מפסיד את מה ש-AI עושה טוב, כמו סיכום שאפשר להאציל ולאמת.","3":"תעדוף הוא החלטה שה-PM מקבל וחותם עליה. בדיקה רק אחרי תלונה מעבירה את ההחלטה לסוכן."},"13":{"0":"מחיקת ההיסטוריה לא משנה את העובדה שבכלי לא מאושר אין שליטה על שמירה, אימון ומיקום המידע.","1":"הבעיה אינה איכות אלא מידע אישי ומסחרי של לקוחות שנכנס לכלי לא מאושר.","2":"בקשה בצ׳אט לא משנה את תנאי הכלי. אין שליטה על שמירה, אימון או מיקום המידע."},"14":{"0":"תחושה אינה מדידה: בניסוי של METR מפתחים מנוסים היו איטיים ב-19% עם AI, ועדיין העריכו שהיו מהירים ב-20%.","1":"מספר פרומפטים מודד פעילות, לא ערך. יעד עליו רק יגדיל את הפעילות.","2":"מחקר אחד על קבוצה מסוימת לא מוכיח שהכלים מאטים את כולם. משווים מדדי תוצאה לנקודת בסיס."}},"39":{"0":{"0":"פרופיל נראה כמו צעד ראשון, אבל בלי ראיות אין מה להגביר. מותג אישי הוא מוניטין שנשען על עבודה.","1":"עוקבים הם לכל היותר מגבר. בלי עבודה שאפשר להצביע עליה, אין על מה לדבר איתם.","2":"ויראליות היא לכל היותר מגבר, ומביאה קהל אקראי. מוניטין נבנה על ראיות, לא על פוסט אחד."},"1":{"0":"דעה על כל נושא נראית כמו מעורבות, אבל מדללת את מה שמזהים אתכם איתו.","2":"פוסטים בחוץ לא מחליפים עבודה שמנהלים רואים מקרוב: תחום מוביל, תשובות מהירות ולופים שנסגרים.","3":"אזכור שם בעדכון לא בונה חוזקה מזוהה. מותג פנימי נבנה מתחום אחד שמובילים ומאמינות יומיומית."},"2":{"0":"״אנחנו״ בלי שמות נשמע צנוע, אבל מוחק את התרומה של טל.","1":"לקחת את העבודה כשלה מאבד את הצוות. קרדיט טוב מדויק: מה היא עשתה ומה אחרים עשו, בשם.","3":"היעלמות מוחקת את החלק של מיכל: המסגור וההחלטות. קרדיט מדויק כולל את שתיהן."},"3":{"0":"המשפט מדויק ונשמע מקצועי, אבל הוא נושא ולא טענה. אין בו משהו שאפשר לחלוק עליו.","1":"״נושא חם״ הוא משפט שאף אחד לא יתווכח איתו, ולכן גם אף אחד לא יזכור. אין בו טענה, נימוק או מסקנה.","3":"״כדאי ללמוד״ הוא משפט שאיש לא יחלוק עליו. נקודת מבט היא טענה שנויה במחלוקת, עם נימוק ומסקנה מעשית."},"4":{"0":"לינקדאין לא מפרסמת נוסחה. היא מתארת קטגוריות של אותות, ולכן מי שמוכר ״נוסחה מדויקת״ מנחש.","1":"לינקדאין מתארת אותות של זהות, תוכן ופעילות, כולל זמן צפייה, לא דירוג לפי מספר עוקבים.","2":"לינקדאין עצמה ממליצה להימנע מפיתיונות מעורבות כמו ״כתבו כן״, ולכן ההנחה שזה תמיד עובד הפוכה להמלצות שלה."},"5":{"0":"פרץ של עשרה פוסטים ואז הפסקה לא בונה חזרתיות. מוניטין נבנה מאותו נושא, באותה רמה, לאורך זמן.","1":"קפיצה בין נושאים מוחקת את הזיהוי עם הנישה, גם אם היא נשמעת כמו ניסוי מוצרי.","2":"ויראליות מביאה קהל אקראי, ושתיקה ארוכה מוחקת את הקשר בין השם לנישה."},"6":{"0":"כותבים בשפת הקהל שרוצים להגיע אליו. מנהלי אבטחה אמריקאים לא יקראו פוסט בעברית.","2":"פוסט דו-לשוני נראה כמו ״גם וגם״, אבל הוא ארוך ומעייף את שני הקהלים.","3":"נוחות הכתיבה חשובה פחות ממי שיקרא. הקהל שהוא רוצה קורא באנגלית."},"7":{"0":"סקירה כללית לא בולטת ואין בה ניסיון ממקור ראשון. מארגנים מחפשים מה שהקהל יוכל ליישם.","1":"הצגת המוצר היא פיץ׳. הקול הקורא של Reversim Summit, למשל, אומר שהרצאות שיווק ומכירה לא רצויות.","2":"הרצאת מבוא כללית לא מביאה ניסיון ממקור ראשון, ולכן לא בולטת מול תקצירים עם מקרה אמיתי."},"8":{"1":"לייקים קלים להשוואה, אבל אצל מיכל הפוסט ה״פופולרי״ הביא אפס פניות, והפוסט הטכני עם מעט לייקים הביא ארבע.","2":"עוקבים הם לכל היותר מגבר. מותג אישי קיים כדי ליצור הזדמנויות ואמון, ולכן מודדים פניות.","3":"חשיפות של פוסט אחד לא אומרות אם נוצרו הזדמנויות. הפוסט ה״פופולרי״ של מיכל הביא אפס פניות."},"9":{"0":"כתיבה מאפס כל שבוע לא מנצלת את המסמך הטוב שכבר קיים. רעיון אחד יכול להגיע לכמה קהלים.","1":"החודש השקט כמעט לא מגיע, וקצב קטן וקבוע מנצח מאמץ חד-פעמי.","3":"עיצוב מושקע לפוסט אחד בחודש מוריד את הקצב. חזרתיות בונה מוניטין, לא גרפיקה."},"10":{"0":"השיטה היא הערך לקהל, והיא לא חושפת לקוח או נתונים שלו.","2":"הלקח הוא בדיוק הערך לקהל, והוא לא חושף לקוח או פרט מוגן.","3":"סיפור לקוח שהחברה כבר פרסמה הוא מקור בטוח לקשר אליו."},"11":{"0":"טענה שלילית על חברה אחרת בלי ביסוס היא סיכון לשון הרע, וחריפות מוציאה את הדיון מהמקצועיות.","1":"מחיקת ביקורת לגיטימית נראית כמו הסתרה. תשובה עניינית אחת משדרת ביטחון.","3":"מחיקת כל הפוסט נראית כמו הסתרה, ומוותרת על התוכן שבנה את המוניטין. תשובה אחת עניינית עדיפה."},"12":{"1":"הקול האישי הוא המותג. כשה-AI כותב הכל, הסיפור, הדעה והפרטים כבר לא שלה.","2":"העלאת המסמך הפנימי המלא מבטיחה דיוק, אבל היא דליפה של מידע פנימי.","3":"לינקדאין לא אוסרת שימוש ב-AI: היא מסמנת תוכן עם Content Credentials ומגבילה תגובות אוטומטיות."},"13":{"0":"חברים קרובים זמינים ונאמנים, אבל הם רואים את אותו עולם שאתם רואים.","2":"זרים גמורים רחוקים מדי. המחקר מצא את מירב המעברים דווקא בקשרים חלשים במידה בינונית.","3":"המחקר לא בדק מגייסים כקבוצה, אלא את חוזק הקשר. מירב המעברים הגיעו מקשרים חלשים במידה בינונית."},"14":{"1":"מנטור אינו בהכרח המנהל הישיר. מה שקובע הוא מה שעשתה: היא השתמשה בהשפעה שלה כדי לקדם את מיכל.","2":"ספונסר לא חייב לשבת מחוץ לחברה. שרון, מתוך החברה, הציעה את מיכל לתפקיד, וזו בדיוק ספונסרשיפ.","3":"ספונסרשיפ מוגדרת לפי מה שעושים, שימוש בהשפעה למען מישהו, ולא לפי דרגה. שרון עשתה בדיוק את זה."}},"40":{"0":{"0":"גודל המדגם לא הופך הערכה על העתיד לראיה. הסקר מודד ציפיות של מעסיקים לגבי 2030.","2":"הסקר באמת נערך ויש בו נתונים, ולכן זו לא דעה. אבל מה שהוא מודד הוא ציפיות לעתיד, כלומר תחזית.","3":"היוקרה של המפרסם לא הופכת הערכה על העתיד לראיה. בודקים אותה מול המציאות ב-2030."},"1":{"0":"בשלב הזה ״נכון ל״ פירושו מועד הנתונים, לא מועד הפרסום. ארבעה חודשים הם זמן ארוך בתחום שזז מהר.","2":"מתי מישהו בדק באתר לא אומר מתי הנתון נמדד. הקורא צריך לדעת מתי הנתונים נאספו.","3":"מועד הסקר הבא לא אומר מתי המספרים הנוכחיים נמדדו. ליד נתון כותבים את מועד איסופו."},"2":{"0":"אילו כלים הופעלו זו שאלה מאוחרת יותר. קודם צריך לדעת איזה חלק מכלל הפיטורים זה בכלל.","1":"ההתפלגות בין ענפים לא אומרת כמה גדול הנתון. שאלת שיעור הבסיס באה קודם: מתוך כמה פיטורים בסך הכל.","3":"עלות הכלים לא אומרת אם ״שיא״ הוא נתח גדול. לפי Challenger, ב-2025 רק כ-4.5% מהפיטורים יוחסו ל-AI."},"3":{"0":"חשיפה גבוהה פירושה שחלק מהמשימות אפשר להאיץ, לא שהתפקיד נעלם. תפקיד הוא צרור של משימות.","1":"החשיפה רלוונטית: חלק מהמשימות באמת יעברו לכלים. הצעד הבא הוא לפרק את התפקיד ולראות אילו.","2":"חשיפה לא אומרת שהתפקיד ייעלם, ולכן אין סיבה לברוח ממנו. מפרקים אותו למשימות ובונים את מה שגדל."},"4":{"0":"הממצא נוגע לצעירים בלבד: אצל עובדים מנוסים באותם מקצועות אין פער.","2":"אצל עובדים מנוסים באותם מקצועות אין פער, והירידה עוברת בעיקר דרך פחות גיוסים של צעירים.","3":"הירידה עוברת בעיקר דרך פחות גיוסים, והחוקרים מדגישים שזה תיאור ולא הוכחה לסיבה. ״מרצונם״ הוא הסבר שהנתון לא מראה."},"5":{"1":"אין בסיס לחלוקה כזו. ההסבר פשוט יותר: מודעה ממשיכה להתפרסם גם כשאף אחד לא מגויס אליה.","2":"מודעות וגיוסים הם שני מדדים שונים, והם לא חייבים לזוז יחד. מודעה יכולה להישאר פתוחה חודשים.","3":"מספר המודעות דווקא עלה, כך שחברות כן מפרסמות. הן פשוט מגייסות פחות ממה שהן מפרסמות."},"6":{"0":"Klarna לא ויתרה על הבוט, אלא הוסיפה אנשים. הלקח הוא למדוד איכות לצד עלות, לא לפסול סוכנים.","1":"המתנה למתחרים לא הייתה מלמדת דבר. הלקח הוא למדוד שביעות רצון, פניות חוזרות והסלמות כבר מהיום הראשון.","2":"המנכ״ל לא אמר שטעה בחישוב, אלא שהעלות הייתה שיקול דומיננטי מדי, והתוצאה הייתה איכות נמוכה יותר."},"7":{"1":"Hype Cycle מתאר ציפיות מטכנולוגיה, לא ייחוס של קיצוץ ל-AI כשיש לו סיבות אחרות.","2":"Base Rate היא שאלת הפרופורציה, מתוך כמה. היא לא מתארת הסבר שמסתיר ירידה בהכנסות.","3":"Augmentation מתאר AI שעוזר לעובדים, לא תירוץ לקיצוץ שנובע מירידה בהכנסות."},"8":{"1":"כתיבת מקרי בדיקה היא משימה שגרתית שעוברת לכלים, ולכן סביר שתקטן ולא תגדל.","2":"הרצת רגרסיה היא משימה שגרתית שעוברת לכלים, ולכן סביר שתקטן.","3":"תחזוקת סקריפטים היא משימה שגרתית שעוברת לכלים. מה שגדל הוא בדיקת מערכות שהתשובות שלהן משתנות."},"9":{"0":"מנהל ממשל AI כותב מדיניות ומעריך סיכונים. הבעיה כאן היא שחסר מי שיבנה ללקוח לפני החתימה.","1":"Agent Ops מפעיל סוכנים בייצור. הבעיה של Velox היא אינטגרציות מותאמות שצריך לבנות ללקוחות.","2":"ל-Velox לא חסרים אפיונים אלא מי שיבנה. עוד PM יכתוב עוד מסמכים, והאינטגרציה עדיין לא תיבנה."},"10":{"0":"ההבדל אינו יחס מנהלים לעובדים אלא רוחב השכבות: בשעון חול הבסיס רחב והאמצע דק.","1":"המודלים לא עוסקים בעבודה מרחוק אלא בצורת הארגון: כמה עובדים יש בתחילת הדרך, באמצע ובבכירים.","3":"בשני המודלים יש הנהלה ועובדים חדשים. ההבדל הוא רוחב: ביהלום הבסיס צר, כלומר פחות ג׳וניורים, לא אפס."},"11":{"0":"מספר מנהלי המוצר אצל המתחרה לא אומר איפה העבודה אצלכם מחכה.","2":"אין יחס שצריך להתיישר אליו: Andrew Ng כינה הצעה של שני PM למהנדס קיצונית מאוד. זו לא נורמה.","3":"עלות לא מגלה איפה הצוואר. אם העבודה מחכה לפיתוח או לסקירה, עוד מנהלי מוצר רק יאריכו את התור."},"12":{"0":"רוב החברות עדיין מציינות סיבות אחרות לפיטורים. כ-6.9% הם מיעוט קטן, לא הסיבה העיקרית.","1":"הכיוון ברור, ובגיוס הוא חזק עוד יותר: שיעור החברות שצמצמו גיוס בגלל AI עלה מכ-3% לכ-10%.","2":"מה שעלה הוא שיעור החברות שמציינות AI כסיבה, לא מספר הפיטורים. שיעור הפיטורים במחצית 2026 היה 2.8%."},"13":{"1":"הסיבה לא הייתה המחיר: הקפאת ג׳וניורים חוסכת מעט עכשיו, אבל משאירה את החברה בלי הבכירים של מחר.","2":"מיכל עצמה שינתה את תוכנית הגיוס והאטה את שאר הגיוס. היא השאירה ג׳וניורים כי זו דלת חד-כיוונית.","3":"הנימוק לא היה טכני. מיכל הפרידה בין החלטות הפיכות להחלטות שקשה להפוך, והקפאת ג׳וניורים היא מהסוג השני."},"14":{"0":"תחושה אינה הוכחה. המכ״ם עובד רק כשהוא מבוסס על תוצרים, כמו סט בדיקה שבניתם או אב-טיפוס שנבדק.","1":"קורסים שהסתיימו אינם הוכחה ליכולת, וכל שבוע תכוף מדי כדי לראות שינוי.","3":"המכ״ם נועד לתקן כיוון לאורך הדרך. עדכון רק בחיפוש עבודה מגיע מאוחר מדי כדי לבנות את מה שחסר."}},"100":{"0":{"0":"לפי LeMay, PM טוב לא נמדד בתואר במדעי המחשב. CORE הם פעלים יומיומיים: לתקשר, לארגן, לחקור ולבצע, לא קוד והנדסה.","2":"אלה נשמעים כמו תכונות של PM, אבל אלה לא האותיות של CORE. LeMay מדבר על ארבע פעולות יומיומיות, לא על הערכה וניהול סיכונים.","3":"אלה יעדים ומדדים של מוצר, לא כישורים. CORE מתאר מה ה-PM עושה כל יום, לא מה המוצר מודד."},"1":{"0":"בדיוק מזה LeMay מזהיר: לקחת פריימוורק ולכופף אליו את המציאות. פריימוורק משרת את ההבנה ולא מחליף אותה.","2":"העיקרון מתחיל מהבנה עמוקה של האתגר. לפי LeMay הבעיה הנפוצה היא בדיוק חוסר הבנה של הבעיה האמיתית.","3":"העיקרון עוסק בהבנת האתגר לפני בחירת כלי, לא בגודל המשימות ולא בדחיית הבעיות הגדולות."},"2":{"0":"ל-PM יש סמכות פורמלית כמעט אפסית, והוא מוביל דרך אמון והשפעה. רקמה מחברת מקשרת צוותים, לא מחליטה במקומם.","2":"לפי LeMay, אם כל החלטה עוברת דרככם, לא ארגנתם אלא בניתם צוואר בקבוק. זה ההפך מרקמה מחברת.","3":"המטאפורה עוסקת באנשים ובצוותים, לא במערכות טכניות. התרגום הוא בין שפת העסק, הטכנולוגיה והמשתמשים."},"3":{"0":"LeMay דוחף להפך: לכתוב קצר. תקשורת חשובה כי שאר הכישורים נשענים עליה, לא בגלל כמות המסמכים.","2":"השלב נותן סיבה אחרת: תקשורת היא היסוד ששלושת הכישורים האחרים בנויים עליו, לא כישור שקשה למדוד.","3":"מחקר וביצוע הם בעצמם כישורי CORE של ה-PM. לפי LeMay שום משימה שמקדמת את המוצר לא ״מתחת לכבוד״."},"4":{"0":"LeMay מעדיף הנחיה על פני הרצאה: לשאול ולהקשיב, לא להציג שקפים. מצגת לא הופכת ישיבה למוצדקת.","2":"לפי LeMay ״עדכון סטטוס״ הוא לא מטרה. אם אין החלטה לקבל, עדיף לשלוח הודעה במקום לכנס ישיבה.","3":"המבחן הוא מטרה והחלטה, לא נוכחות. גם כשכולם מגיעים, ישיבה בלי מטרה היא בזבוז זמן."},"5":{"0":"מי שמחכה לוודאות מלאה לא זז אף פעם. עד שכל הנתונים מגיעים, ההזדמנות כבר חלפה.","2":"העברת כל החלטה למעלה היא ויתור על התפקיד. לחיות באפור פירושו להחליט עם מה שיש, לא לברוח מהסיכון.","3":"לפי LeMay האפור הוא לא תקלה בתפקיד אלא התפקיד עצמו. הימנעות מאי-ודאות היא הימנעות מרוב עבודת המוצר."},"6":{"0":"LeMay ממליץ לא לנסות לשנות את הארגון בכוח, אלא ללמוד לעבוד בתוכו ולבנות בריתות עם אנשי מפתח.","2":"פוליטיקה היא הדרך שבה ארגונים מקבלים החלטות, ומי שמתעלם ממנה מוותר על השפעה. והנתונים מייעצים, לא מחליטים.","3":"״כן״ צייתני לכל דרישה מלמעלה הוא נטישת התפקיד. LeMay מציע לשאול איזו מטרה זה משרת ולהציע ניסוי זול."},"7":{"0":"HiPPO הוא ראשי תיבות של Highest Paid Person's Opinion. הוא עוסק בהחלטות לפי דרגה, לא ביעדים נסתרים.","2":"השם נכון אבל הבעיה הפוכה: הסיכון הוא החלטות לפי דרגה במקום ראיות, לא התעלמות מדעת הבכירים.","3":"HiPPO הוא Highest Paid Person's Opinion, לא שיטת תעדוף. הוא מתאר החלטות שמתקבלות לפי דרגה."},"8":{"0":"LeMay כתב את ההפך מקטלוג פריימוורקים. הוא מזהיר שפריימוורק משרת את ההבנה ולעולם לא מחליף אותה.","2":"לפי השלב, לאסטרטגיה ארוכת טווח כדאי לחפש במקום אחר, כמו Inspired. החוזקה של LeMay היא היומיום.","3":"השלב מציין מדדים וניתוח דאטה מתקדם כנושא שכדאי לחפש במקום אחר (Lean Analytics), לא כמוקד של LeMay."},"9":{"0":"לחכות ולקוות זה בדיוק מה שגורם לבעיית דדליין להתפוצץ כפליים. Clarity over Comfort פירושו לומר את זה מוקדם.","2":"הסתרת הסיכון מהמכירות חוסכת את השיחה הלא נעימה, אבל לא משאירה להם זמן להתאים את עצמם. ההפתעה רק גדלה.","3":"ריכוך הבשורה כדי לשמור על נוחות הוא בדיוק המלכודת. העיקרון דורש לומר את זה בבהירות, לא כ״סיכון קטן״."},"10":{"0":"Research עוסק במשתמשים, בנתונים ובשוק. קיצור מייל הוא שאלה של מה הקורא צריך לדעת, כלומר תקשורת.","1":"Execution עוסק בהובלת ה-Delivery ובהסרת חסמים. קיצור מייל לפסקה הוא החלטה על המסר ועל הקורא שלו.","3":"Organization עוסק בתעדוף ובתהליכי עבודה. כאן השינוי הוא באופן שבו המסר נכתב עבור הקורא."},"11":{"0":"LeMay מזהיר מהתחלה בפריימוורק. ״מוכח״ במקום אחר לא אומר שמתאים כאן: Best practice מיובא צריך בדיקה.","1":"Start with the work פירושו להתחיל מהבעיה, לא מהכלים. הטמעת פריימוורקים לפני הבנה היא ההפך מהעיקרון.","3":"הבעיה היא לא הקצב. גם כלי אחד ברבעון עדיין מתחיל מהפריימוורק במקום מהבעיה הקונקרטית."},"12":{"0":"לפי LeMay הטקסים הם אמצעי, וברגע שהם הופכים למטרה איבדתם את הדרך. ביצוע עיוור לפי הספר הוא המלכודת.","2":"העניין הוא לא שיעור ההשתתפות. טקס שלא משרת מטרה משנים או מבטלים, לא רק מסבירים אותו מחדש.","3":"LeMay מזהיר מ-Best practices מיובאים: מה שעבד במקום אחר עבד בהקשר מסוים, והעתקה עיוורת מובילה לאכזבה."},"13":{"0":"לחיות באפור פירושו לפעול בתוך אי-הוודאות, לא לחכות שתעבור. גם לא להחליט זו החלטה, בדרך כלל הגרועה ביותר.","2":"שיתוף הנתונים הוא לא העניין. ההמתנה ל-100% ודאות היא עצמה הטעות: המידע לעולם לא יהיה מושלם.","3":"LeMay לא קובע סף ודאות לפי גודל הסיכון. גם בהחלטות גדולות מגדירים מה ישנה את דעתכם, ומתקדמים."},"14":{"0":"לפי המטאפורה, הערך של PM הוא בחיבור ולא בידע מומחה. התיאום בין הצוותים הוא העבודה עצמה, לא בזבוז זמן.","1":"רקמה מחברת פועלת ביומיום, במרחב שבין הצוותים. PM שמנותק מהביצוע לא יכול לסנכרן או להסיר חסמים.","3":"כשכל החלטה עוברת דרך ה-PM נוצר צוואר בקבוק. לחבר פירושו שהצוות מתפקד גם כשאתם בחופשה."}},"101":{"0":{"0":"מכירה ללקוחות היא לא הסיבה. השלב קושר את הספר להשפעה על צוותים ו-Stakeholders בלי סמכות פיקודית.","2":"ל-PM אין סמכות פיקודית על מפתחים, מעצבים או Stakeholders. בדיוק בגלל זה הוא צריך כלים של השפעה.","3":"לפי קרנגי אנחנו לא עוסקים ביצורים של היגיון אלא של רגש. מי שמשכנע רק בהיגיון הפסיד עוד לפני הדיון."},"1":{"0":"חיוך, זכירת שמות ועניין אמיתי שייכים לשש הדרכים לגרום לאנשים לחבב אתכם, החלק השני של הספר.","2":"הימנעות מוויכוח, הודאה בטעות ו״הרעיון שלו״ הם כללי שכנוע מהחלק השלישי, לא הטכניקות הבסיסיות.","3":"פתיחה בשבח, טעויות בעקיפין ושמירה על כבוד הם מהחלק הרביעי, שינוי אנשים בלי לעורר טינה."},"2":{"0":"ההבדל הוא לא המקום. שבח כנה נשען על עובדה ספציפית, וקרנגי אף ממליץ לתת קרדיט בפומבי.","2":"הגודל הוא לא המבחן. קרנגי ממליץ לשבח כל שיפור, אפילו הקטן ביותר, כל עוד השבח ספציפי וכן.","3":"קרנגי לא מצמיד לשבח נקודה לשיפור. להפך, הוא מזהיר ש״אבל״ אחרי שבח מוחק אותו."},"3":{"0":"מי ששוכנע בניגוד לרצונו נשאר בדעתו. ניצחון לוגי גורם לצד השני להרגיש נחות, לא לשתף פעולה.","2":"לפי קרנגי הדרך היחידה לנצח בוויכוח היא להימנע ממנו. ויכוח סוער מקשיח עמדות, לא בונה כבוד.","3":"הצד שהפסיד מרגיש נחות ומחזיר בהזדמנות הבאה. מה שמרוויחים הוא טינה, לא סמכות."},"4":{"0":"בונוס הוא תגמול חיצוני. העיקרון הוא לחבר את המשימה למה שהמפתח כבר רוצה, למשל ללמוד טכנולוגיה חדשה.","2":"שכנוע בנתונים מגיע מהזווית שלכם, לא שלהם. קרנגי שם על הקרס את מה שהדג רוצה, לא את מה שהוא אוהב.","3":"ההתלהבות שלכם היא התותים עם השמנת: מה שאתם אוהבים. הדג נתפס על תולעת, על מה שהוא רוצה."},"5":{"0":"הכלל הוא להודות מהר ובנחישות, אפילו לפני שמישהו אחר אומר את זה. הסתרה כדי לשמור על מעמד מפספסת את הרעיון.","2":"המתנה לכל העובדות דוחה את ההודאה. ״טעיתי״ אחד בזמן אמת שווה יותר מעשרה נאומים על אמינות.","3":"הסבר הנסיבות הופך את ההודאה לתירוץ. הכוח הוא בהודאה מהירה ונחרצת, בלי להתחמק."},"6":{"0":"נתונים מלאים משכנעים בטיעון שלכם, והרעיון נשאר שלכם. העיקרון שותל את הכיוון בשאלות כדי שהם יגיעו אליו.","2":"גם כשהרעיון ״שלהם״, ה-PM מכוון בשאלות לעבר המטרה. לסגת בלי שום הכוונה זה לוותר על ההובלה.","3":"לבחור לבד ולהכריז הופך את זה להחלטה שלכם. העיקרון הוא שהצד השני ירגיש שהגיע לרעיון בעצמו."},"7":{"0":"פתיחה ישירה בבעיה מכניסה לעמדת הגנה. קרנגי פותח בשבח כנה, כמו קצף לפני התער.","2":"ה״אבל״ מוחק את השבח שלפניו. קרנגי מציע ״ו...״ במקומו, והצבעה על הטעות בעקיפין ובשאלות.","3":"ביקורת רק ב-1:1, אף פעם לא מול הצוות. וגם הצעת הפתרון בעצמכם לוקחת את הבעלות; עדיף לשאול."},"8":{"0":"הספר עוסק ביחסי אנוש בכלל, לא בסגירת עסקאות. העקרונות שלו חלים על כל מי שתלויים בו, גם צוותים ו-Stakeholders.","2":"קרנגי פוסל ניצחון בדיון: לנצח בוויכוח פירושו להפסיד ביחסים. הפרכות רק מקשיחות עמדות.","3":"ההשפעה אצל קרנגי בנויה על אמון, הקשבה והמניע של הצד השני, לא על היררכיה, הסלמות ואישורים."},"9":{"0":"הערכה חשובה מאוד לקרנגי, אבל הצליל הנעים ביותר שהוא מזכיר הוא השם של האדם עצמו.","2":"שבח הוא עיקרון נפרד. הצליל הנעים ביותר במשפט של קרנגי הוא שמו של האדם.","3":"שיקוף הוא חלק מהקשבה פעילה, עיקרון אחר. הצליל הנעים ביותר הוא השם של האדם עצמו."},"10":{"0":"הסלמה ותיעוד הם ביקורת בצורה אחרת. הם מכניסים את המפתח לעמדת הגנה ולא משנים את הגישה שלו.","1":"להפריך כל התנגדות זה לנצח בוויכוח ולהפסיד ביחסים. ההתנגדות רק מתקשחת.","3":"העלאה מול כל הצוות חושפת את המפתח בפומבי, והצבעת רוב לא נוגעת במה שבאמת מפריע לו."},"11":{"0":"הצגה כ״כבר אושר״ מחליפה שכנוע בהיררכיה. הצוות לכל היותר יציית, בלי תחושת בעלות.","2":"טיעון שלא משאיר מקום לוויכוח משכנע בניגוד לרצון, ולפי קרנגי מי ששוכנע כך נשאר בדעתו.","3":"המתנה פסיבית אולי לעולם לא תניב רעיון דומה. קרנגי שותל את הכיוון באופן פעיל, בעזרת שאלות."},"12":{"0":"לפי קרנגי העקרונות עובדים רק כשהם באים מהלב. עניין מזויף מזוהה מיד, ולכן הוא לא ״עדיין עובד״.","2":"הסכנה שקרנגי מעלה היא אמון, לא רכות. חוסר כנות נחשף ושוחק את האמון שהכל נשען עליו.","3":"העניין הוא לא שחיקה של שבחים. שבח לא כן הוא החנפה, ואנשים מזהים אותה מקילומטר."},"13":{"0":"מייל נתונים אחרי הישיבה הוא אותו ויכוח בכתב. כל ניצחון כזה בוויכוח כתוב מאבד עוד קצת רצון טוב.","1":"להימנע מוויכוח לא אומר לוותר על הכיוון. אצל קרנגי מכוונים בשאלות לעבר המטרה, לא נכנעים בשקט.","3":"הסלמה הופכת את המחלוקת לתחרות של היררכיה. ההשפעה אצל קרנגי עוברת דרך שאלות ונקודת המבט של הצד השני."},"14":{"0":"הכוונה היא השלב הרביעי. היא מגיעה רק אחרי הכנה, פתיחה בהכרה ודיאלוג אמיתי.","2":"גיבוי מההנהלה הוא לא אחד מחמשת השלבים. המודל נשען על נקודת המבט של ה-Stakeholder, לא על לחץ מלמעלה.","3":"PRD מוכן לא מופיע במודל. פתיחה בתוכנית שלכם מדלגת על הבנת הלחצים והמטרות של הצד השני."}},"102":{"0":{"0":"Sprint הוא חמישה ימים מלאים, יום לכל שלב. דחיסה לפחות ימים לא משאירה זמן לחשיבה אישית ולגיוס משתמשים.","2":"ב-Sprint לא כותבים קוד ולא משיקים: ביום חמישי בונים חזית בלי קוד, וביום שישי בודקים אותה מול חמישה משתמשים.","3":"עשרה ימים של עיצוב, פיתוח, QA והשקה הם מחזור Delivery מלא. Sprint הוא חמישה ימי Discovery שנגמרים בבדיקה, לא בהשקה."},"1":{"0":"זה תיאור ה-Facilitator, שמחזיק את השעון וחייב להישאר ניטרלי, ולכן הוא לא אמור להיות גם ה-Decider.","2":"Sprint מחליף קונצנזוס עמום ב-Decider אחד. ה-Supervote שלו קובע מה נבנה, גם אם ההצבעה הכללית אמרה אחרת.","3":"את הראיונות ביום שישי מנהל ה-Interviewer. ה-Decider מכריע על היעד ביום שני ועל ה-Supervote ביום רביעי."},"2":{"0":"המטרה היא לא לחסוך זמן. עבודה אישית קיימת כדי שהקול הרם לא ינצח וכל משתתף יביא פתרון שלם.","2":"ביום שלישי כולם מציירים, לא רק המעצבים. בספרינט של מיכל הסקיצה המנצחת הגיעה מנציג התמיכה.","3":"הסקיצות אנונימיות, כך שהן נשפטות לפי התוכן ולא לפי הכותב. בעלות על הרעיון היא לא המטרה."},"3":{"0":"מלוטש מדי פירושו שבזבזתם את היום. ה-Prototype צריך להיות אמין בעיני משתמשים, לא דמו להנהלה.","2":"רשלני מדי, והמשתמשים לא ייקחו אותו ברצינות. Goldilocks חייב להיראות אמיתי כדי לעורר תגובות כנות.","3":"ה-Prototype הוא חזית בלי קוד, ומיועד לזריקה. קוד Production הוא ההפך מהרעיון."},"4":{"0":"הטיעון הוא לא מובהקות סטטיסטית. לפי המחקר של Nielsen, 5 משתמשים כבר חושפים כ-85% מהבעיות.","2":"גם עם יותר זמן, עוד משתמשים מוסיפים מעט: אחרי החמישי הדפוסים חוזרים וה-ROI קורס.","3":"ממצא הוא מה ש-3 מתוך 5 עשו באותו אופן, דפוס התנהגות. זו לא הצבעה על מה שהם אמרו שאהבו."},"5":{"0":"Design Sprint הוא לא עבודת ממשק: הוא מוביל מבעיה לפתרון שנבדק מול משתמשים, כלומר Discovery.","2":"המשכים הפוכים: Design Sprint נמשך חמישה ימים, ו-Scrum Sprint נמשך שבועיים.","3":"התפקידים הפוכים: ב-Design Sprint בונים Prototype מזויף ולא MVP בקוד, ו-Scrum נועד ל-Delivery ולא למחקר."},"6":{"0":"ב-Art Museum אין הצגות: הסקיצות אנונימיות ונתלות בשקט. הדיון מגיע אחר כך, שלוש דקות לכל סקיצה.","2":"מוצרים מעוררי השראה מתעשיות אחרות הם Lightning Demos ביום שלישי, לא ה-Art Museum ביום רביעי.","3":"ה-Storyboard נבנה בסוף יום רביעי, אחרי ההחלטה. ב-Art Museum תולים את סקיצות הפתרון."},"7":{"0":"בדיוק אז Sprint משתלם: בעיה גדולה ועמומה, או צוות שתקוע עליה כבר חודשים.","2":"Knapp מונה את שני אלה כסיבות להריץ Sprint: צוות שמתווכח על הכיוון, ודדליין שלא משאיר מקום לתהליך ארוך.","3":"סיכון גבוה והחלטה שקשה לחזור ממנה הם מהסיבות המרכזיות להריץ Sprint, וכך גם לפני התחייבות לרבעון."},"8":{"0":"השראה ממוצרים אחרים היא Lightning Demos. Crazy 8s הוא 8 וריאציות של הרעיון שלכם ב-8 דקות.","2":"נקודות על הקיר הן ה-Heat Map ביום רביעי. Crazy 8s הוא תרגיל סקיצות של יום שלישי.","3":"מיפוי המסע והסיכונים הוא המפה של יום שני. Crazy 8s הוא 8 וריאציות של סקיצה, דקה לכל אחת."},"9":{"0":"Sprint לא משחרר גרסה: הוא בונה חזית בלי קוד כדי לבדוק. הוא מבטח את הפיתוח, לא מחליף אותו.","2":"Sprint מחליף קונצנזוס ב-Decider אחד. הערך שלו הוא ראיות ממשתמשים אמיתיים, לא הסכמה בצוות.","3":"ה-Prototype הוא חזית חד-פעמית באיכות Goldilocks, שנבנית כדי ללמוד ממשתמשים ולא כדי ללטש למשקיעים."},"10":{"0":"A/B אחרי השקה פירושו שכבר בניתם. ה-Sprint קיים כדי ללמוד לפני חודשים של פיתוח, לא אחריהם.","2":"Prototype מושלם מדי הוא בעצמו טעות נפוצה. בלי יום שישי, גם ה-Prototype המלוטש לא בודק כלום.","3":"השאלה היא לא מי מחליט. דילוג על הבדיקה הוא הטעות, לא משנה מי מאשר אותו."},"11":{"0":"זו הצלחה פגומה: הכיוון עובד וצריך ליטוש. כישלון יעיל פירושו שהכיוון עצמו שגוי.","2":"קריסת Prototype היא תקלה טכנית, לא תוצאת בדיקה. כישלון יעיל עוסק בכיוון שהתברר כשגוי.","3":"לפי Knapp דחיסה ליומיים היא טעות נפוצה: בלי זמן לחשיבה אישית ולגיוס משתמשים נשארים עם עוד סדנה."},"12":{"1":"ה-Storyboard הוא לא סיכום להנהלה. הוא התסריט פריים אחר פריים שממנו בונים את ה-Prototype ביום חמישי.","2":"מפת המסע של עד 15 צעדים נבנית ביום שני לבחירת היעד. ה-Storyboard מגיע ביום רביעי, אחרי ההחלטה.","3":"ב-Sprint לא כותבים אפיון. ה-Storyboard מנחה Prototype בלי קוד שנבנה למחרת, לא מפתחים בהמשך."},"13":{"0":"Knapp פוסל דחיסה: בלי זמן לחשיבה אישית ולגיוס משתמשים נשארים עם עוד סדנה נחמדה.","2":"המטרות מוחלפות: Lightning Demos הם להשראה, Crazy 8s לוריאציות מהירות, וראיונות משתמשים לוולידציה.","3":"השלב מונה כלים לקחת בנפרד, כמו Note-and-Vote, Crazy 8s ובדיקת חמשת המשתמשים. כל אחד עובד גם בלי Sprint מלא."},"14":{"0":"מקום על הקיר הוא לא הסיבה. Knapp מגביל כי מעל שבעה אנשים הקצב קורס והדיונים מתנפחים.","2":"הצוות שמומלץ כולל מומחה שיווק או מכירות ונציג תמיכה. הקול שלהם הוא חלק מהשיטה.","3":"תקציב הוא לא הסיבה. מעל שבעה משתתפים כל החלטה הופכת לוועדה והקצב קורס."}},"103":{"0":{"0":"Feasibility שייך, אבל Scalability ו-Time to Market הם לא סיכונים של Cagan. חסרים כאן Usability ו-Business Viability.","2":"אלה מדדים עסקיים, לא סיכונים. הסיכונים של Cagan הם שאלות שעונים עליהן לפני הבנייה, כמו האם מישהו ירצה את זה.","3":"Usability אחד מהארבעה, אבל גודל שוק, מתחרים ותמחור לא. Cagan אף רואה באובססיה למתחרים סימן לצוות חלש."},"1":{"0":"״איסוף דרישות״ ממכירות ומלקוחות הוא מה ש-Cagan מתאר כצוות חלש. לקוחות לא יכולים פשוט להגיד לנו מה לבנות.","2":"Discovery הוא לא שלב עיצוב. הטריו בודק יחד את כל ארבעת הסיכונים, כולל Feasibility ו-Viability, לא רק UX.","3":"לפי Cagan MVP הוא ניסוי להריץ, לא גרסה מצומצמת שמפתחים במשך חודשים. Discovery לא בונה מוצר."},"2":{"0":"הוותק הוא לא ההבדל. Empowered Team מקבל בעיה ומדד הצלחה במקום רשימת פיצ׳רים.","2":"ההנהלה עדיין מביאה את הבעיות והמדדים, והצוות מחזיר פתרונות מאומתים. היעדים לא נקבעים בלי ההנהלה.","3":"רשימת פיצ׳רים עם תאריכים היא בדיוק Feature Team. Empowered Team מקבל בעיה לפתור ומדד הצלחה."},"3":{"0":"ארבע השאלות לא בוחנות מתחרים. הן מתמקדות במטרה העסקית שלנו, במדד ההצלחה ובבעיה של הלקוח.","2":"השאלות הן לא חישוב פיננסי. הן מתחילות מהמטרה העסקית ומהבעיה של הלקוח, לפני כל פתרון.","3":"בחירת פיצ׳ר, לוח זמנים ומועד השקה קופצת ישר לפתרון. ה-Assessment מגיע לפני שנוגעים בפתרון."},"4":{"0":"Dual-Track לא עוסק בבאגים מול פיצ׳רים. מסלול אחד מגלה מה לבנות, והשני בונה את מה שכבר אומת.","2":"המסלולים רצים במקביל, כל הזמן. שבוע מחקר בתחילת רבעון הוא לא Continuous Discovery לפי Cagan.","3":"זה צוות אחד, לא שניים: הטריו (PM, מעצב ו-Tech Lead) בודק את ההזדמנות הבאה בזמן שהצוות בונה מה שאומת."},"5":{"0":"טווח הזמן הוא לא הבעיה של Cagan. הבעיה היא שהפיצ׳רים ננעלים כפתרונות לפני שאומתו.","2":"החלופה של Cagan היא Roadmap של תוצאות, עוד פחות מפורט בפיצ׳רים. וכשתאריך באמת נדרש, יש High-Integrity Commitment.","3":"להפך: Feature Roadmap לא נותן לצוות חופש, הוא מכתיב את הפתרון מלמעלה."},"6":{"0":"Scrum Master לא חלק מהטריו, ו-Usability שייך ל-Product Designer, לא ל-PM.","2":"בטריו אין Data Analyst, ו-Feasibility חסר כאן. ה-Tech Lead אחראי ל-Feasibility וה-Designer ל-Usability.","3":"הטריו הוא ה-PM, המעצב וה-Tech Lead של הצוות, שעובדים יחד על Discovery כל יום. CPO ו-VPs הם ההנהלה, לא הצוות."},"7":{"0":"שבוע מחקר בתחילת רבעון הוא בדיוק הטעות ש-Cagan מציין: Discovery כטקס חד-פעמי.","2":"לקוחות לא יכולים פשוט להגיד מה לבנות. איסוף בקשות הוא מה ש-Cagan מתאר כצוות חלש.","3":"ניטור אחרי השקה לומד ברגע היקר ביותר. Discovery בודק רעיונות לפני שבונים אותם."},"8":{"0":"את Feasibility קל ונוח לבדוק. Cagan קורא ל-Value הסיכון הקריטי והמוזנח: אם אף אחד לא צריך, שום דבר לא משנה.","2":"Viability חשוב, אבל מוצר שאף אחד לא רוצה ייכשל בכל מקרה. Value בא קודם.","3":"Usability רלוונטי רק כשמישהו רוצה את המוצר. בלי Value, קלות שימוש לא מצילה כלום."},"9":{"0":"Cagan הופך את זה: אפשר לשחרר הרבה ולא לשנות כלום. צוותים נמדדים על Outcome, לא על מה ששוחרר.","2":"Cagan לא נותן להם משקל שווה. Output בלי Outcome הוא עבודה קשה על הדבר הלא נכון.","3":"Velocity ו-Story Points מודדים כמות עבודה, כלומר Output. Outcome הוא שינוי במציאות, כמו Retention."},"10":{"0":"לפי Cagan רשימת פיצ׳רים עם תאריכים מקודדת כישלון: חצי ממנה לא יעבוד, וכולה כבר הפכה להתחייבות.","2":"בחירת הסדר עדיין בונה פיצ׳רים שאף אחד לא אימת. הצוות צריך לקבל בעיה ומדד, לא רשימה.","3":"ההיקף הוא לא העניין. גם 6 פיצ׳רים עם תאריכים קבועים הם פתרונות שננעלו לפני Discovery."},"11":{"0":"ב-Concierge עושים את העבודה ידנית, כך שהוא לא בודק אם אפשר לבנות. לזה יש Feasibility Prototype.","1":"בשירות ידני עוד אין ממשק ללמוד. Usability נבדק עם User Prototype.","3":"ה-Concierge בודק קודם אם הלקוחות רוצים את הערך בכלל, לפני השאלה אם זה משתלם לעסק."},"12":{"0":"החזון הוא התמונה של כמה שנים קדימה, והוא חייב להישאר יציב. Outcome Roadmap לא מחליף אותו, הוא מגדיר תוצאות לתקופה.","2":"Outcome Roadmap לא מוותר על כל מועד. כשתאריך נדרש, הצוות נותן High-Integrity Commitment אחרי בדיקה.","3":"זה לא אותו תוכן: אחד מכתיב פתרונות, והשני מגדיר תוצאה ונותן לצוות לגלות את הדרך."},"13":{"0":"Cagan קורא ל-PM שרק מעביר דרישות ״צינור״, לא מנהל מוצר. מגדירים ומעצבים יחד, לא במרוץ שליחים.","2":"אימות לבד עדיין מדלג על המעצב וה-Tech Lead. Usability ו-Feasibility צריכים להיבדק בתוך ה-Discovery, מההתחלה.","3":"Cagan לא קובע חריג לפי ניסיון. הטריו הוא עיקרון: יחד מהדקה הראשונה, וכל אחד אחראי לסיכון אחר."},"14":{"0":"הסדר הפוך: Empowered מתמקד בארגון, במנהיגות ובתרבות, ו-Inspired בכלים של ה-PM והטריו.","2":"השלב מציג את Empowered (2020) כספר נפרד שעוסק בארגון, לא כמהדורה מעודכנת של Inspired.","3":"החלוקה היא לא לפי גודל חברה. Inspired עוסק בצוות ובמוצר, ו-Empowered בארגון ובמנהלי המוצר."}},"104":{"0":{"0":"זו הלולאה עצמה: Cue, Craving, Response, Reward. החוקים הם מה שעושים לכל שלב, כמו להפוך את ה-Cue לגלוי.","2":"טריגר, פעולה, תגמול משתנה והשקעה הם המודל של Nir Eyal ב-Hooked, לא ארבעת החוקים של Clear.","3":"אלה לא החוקים של Clear. התחלה קטנה היא כלי בתוך חוק 3, והחוקים עצמם ממופים ל-Cue, Craving, Response ו-Reward."},"1":{"0":"המשפט הפוך. לפי Clear יעדים לא מספיקים, ודווקא המערכות קובעות את הרמה האמיתית.","2":"Clear לא נשען על מוטיבציה: היא מתנדנדת, וסביבה ומערכת לא.","3":"המסר של Clear הפוך: שאיפות לבדן לא מרימות, ונופלים לרמת המערכות."},"2":{"0":"להתחיל כמה הרגלים יחד היא טעות נפוצה לפי Clear: חמישה הרגלים ביום ראשון שווים אפס ביום חמישי.","2":"חיבור של חובה לדבר מהנה הוא Temptation Bundling, כלי של חוק 2, לא Habit Stacking.","3":"קביעת זמן ומקום מראש היא Implementation Intention. Habit Stacking נעגן בהרגל שכבר קיים."},"3":{"0":"הכלל של Clear לא עוסק במשימות קטנות. הוא מכווץ הרגל חדש, למשל עמוד אחד במקום ״לקרוא כל ערב״.","2":"שתי דקות הן תקרה לגרסת ההתחלה, לא מינימום יומי. קודם מגיעים, אחר כך משפרים.","3":"הכלל עוסק באופן שבו הרגל מתחיל, לא בסיכום. מעקב אחרי התקדמות שייך לחוק 4, כמו מהדקי הנייר."},"4":{"1":"זהות היא לא תדמית. זה מי שאתם מאמינים שאתם, וכל פעולה היא הצבעה עבורה, בלי קשר לאיך אחרים רואים.","2":"Clear לא מדבר על תכונות מולדות. זהות נבנית מפעולות, וכל אחת היא הצבעה למי שתהיו.","3":"תהליך הוא שכבה נפרדת. Clear מונה שלוש שכבות: תוצאות, תהליכים וזהות, והזהות היא העמוקה ביותר."},"5":{"0":"הרמה לא סופית: כמו קוביית הקרח, עוד מעלה אחת והיא נמסה. רוב האנשים מוותרים רגע לפני הפריצה.","2":"זה תיאור של הרגל אוטומטי. ה-Plateau הוא התקופה הארוכה שבה משקיעים ולא רואים תוצאות.","3":"ה-Plateau הוא ההפך מצמיחה מהירה: משקיעים ולא רואים כלום, עמק האכזבה."},"6":{"0":"עוד הגדרות ומסלולים מוסיפים חיכוך. חוק 3 הופך את הפעולה הנכונה לקלה ביותר, עם ברירות מחדל חכמות.","2":"התראות ותזכורות הופכות את ה-Cue לגלוי: זה חוק 1, לא חוק 3.","3":"חגיגות ופידבק מיידי הופכים את הפעולה למספקת: זה חוק 4."},"7":{"0":"Clear מדבר על חזרה מהירה, לא על השלמה כפולה. לא נדרשת שלמות, והסך השבועי הוא לא העניין.","2":"איפוס הספירה הופך פספוס אחד לכישלון. לפי Clear פספוס אחד הוא תאונה, ורק שניים מתחילים הרגל חדש.","3":"פספוס שני ברצף הוא בדיוק מה שהכלל מזהיר ממנו: זו תחילתו של הרגל חדש, של לא לעשות."},"8":{"0":"יעדים על הקיר עדיין נשענים על כוח רצון. Clear מעצב את הסביבה כך שהפעולה הנכונה תהיה הקלה ביותר.","2":"קביעת זמן ומקום ביומן היא Implementation Intention. עיצוב סביבה עובד על המרחב, כמו בקבוקי המים בקפטריה.","3":"נוחות היא לא העניין. הסביבה צריכה להפוך את הפעולה הרצויה לקלה ואת הפיתוי לבלתי נראה."},"9":{"0":"שני שלבים התחלפו: Gamification כמו Streak הופך למושך (Craving), ו-One-click הופך לקל (Response).","2":"אלה טקטיקות גיוס משתמשים. ארבעת החוקים בונים לולאת שימוש חוזרת, לא הרשמה חד-פעמית.","3":"השלב מיישם את החוקים בדיוק על מוצרים: התראות, Streak, פחות קליקים, חגיגות. ו-Clear דוחה הסתמכות על כוח רצון."},"10":{"1":"יותר פיצ׳רים מהמתחרים זה לא מה שהופך למושך. חוק 2 עוסק בציפייה לתגמול, כמו מד התקדמות.","2":"הדרכה ארוכה מוסיפה חיכוך במקום להוריד אותו. חוק 3 מקצר צעדים, כמו יצירת משימה ישר מהמייל.","3":"הנחה על כל חזרה היא לא התגמול ש-Clear מתכוון אליו. ולפני תגמול, המשתמש צריך בכלל לראות Cue."},"11":{"0":"יעד מחודד הוא עדיין יעד. לפי Clear למנצחים ולמפסידים יש אותם יעדים, וההבדל הוא המערכת.","2":"הכרזה היא בדיוק מה שנכשל אצל מיכל: היעד הוכרז בכל ישיבה ולא זז. רק מערכת מזיזה אותו.","3":"הגדלת היעד לא עוזרת. בלי מערכת, יעד גדול יותר הוא רק סיסמה גדולה יותר."},"12":{"0":"חיבור לפעולה יומית קיימת הוא Habit Stacking, כלי של חוק 1. Temptation Bundling מחבר ״צריך״ ל״רוצה״.","2":"הורדת שלבים מקטינה חיכוך, כלי של חוק 3. Temptation Bundling הופך את הפעולה למושכת, חוק 2.","3":"חבילת פיצ׳רים מוזלת היא תמחור, לא טכניקת הרגלים. Temptation Bundling מחבר פעולת חובה לפעולה רצויה."},"13":{"0":"Clear כן רואה הבדל: הרגלים מבוססי תוצאה חלשים, ומבוססי זהות חזקים, כי ההרגלים נובעים מהזהות.","2":"Clear אומר ההפך: התנהגות בלי זהות דורשת תזכורת מתמדת, וזהות גורמת לה לזרום באופן טבעי.","3":"אכיפה בהערכות ביצועים היא לא הסיבה. זהות עובדת כי ההרגלים נובעים ממנה מעצמם, לא מלחץ."},"14":{"0":"365% מניח חיבור פשוט. שיפורים יומיים מצטברים כריבית דריבית: 1.01 בחזקת 365 הוא כ-37.8 פעמים.","2":"37% מפספס פי מאה: 1.01 בחזקת 365 הוא כ-37.8 פעמים, לא 1.37.","3":"1% ביום מצטבר לכ-37.8 פעמים, הרבה מעל 10%. ו-Clear טוען ששינויים קטנים ועקביים מנצחים שינויים דרמטיים."}},"105":{"0":{"0":"ההבחנה היא לא סוג ההעסקה אלא הגישה: Mercenary שואל מה צריך לצאת מחר, ו-Missionary שואל אם זה פותר את בעיית הלקוח.","2":"Cagan לא מחפש את שניהם: צריך צוותים של Missionaries, לא צוותים של Mercenaries.","3":"לפי Cagan ההבדל הוא בסביבה, לא באופי: אותם אנשים הופכים ל-Missionaries כשנותנים להם בעלות אמיתית על בעיה."},"1":{"0":"גיוס הוא חלק מ-Staffing, אבל פיטורים ותקציב לא נמנים בשלוש. חסרים כאן Strategic Context ו-Coaching.","2":"תכנון, ביצוע ומדידה הם מחזור עבודה כללי. הנהגת מוצר אצל Cagan נותנת הקשר, מאיישת צוותים ומאמנת אנשים.","3":"חזון הוא חלק מ-Strategic Context, אבל Roadmap הוא לא אחריות של ההנהגה, וחסרים Staffing ו-Coaching."},"2":{"0":"להגיד ל-PM מה לעשות זו הכתבה, כלומר Micromanagement. Coaching שואל איך ה-PM הגיע להחלטה.","2":"לפי Cagan קורס או סדנה לא מחליפים ליווי מתמשך. Coaching הוא 1:1 קבוע.","3":"ה-1:1 אצל Cagan עוסק בחשיבה ובהחלטות, לא בדיווח סטטוס. סקירת משימות היא לא Coaching."},"3":{"0":"Roadmap של פיצ׳רים ותאריכים הוא מה ש-Feature Team מקבל. Strategic Context נותן את ה-למה, לא תוכנית ביצוע.","2":"בעלות, תלויות וצוותי פלטפורמה שייכים ל-Team Topology. Strategic Context הוא חזון, אסטרטגיה ויעדים.","3":"תוכנית כישורים אישית מגיעה מה-Gap Assessment, כלי של Coaching. Strategic Context הוא מה שכל הצוות מקבל."},"4":{"0":"Cagan מאתר את הסיבה בסביבה: אותם אנשים הופכים ל-Missionaries כשנותנים להם בעלות אמיתית.","2":"כותרת הספר אומרת ההפך: אנשים רגילים יוצרים מוצרים יוצאי דופן. לא צריך לגייס רק כוכבים.","3":"Cagan מצביע על הנהגה ותרבות, לא על טכנולוגיה. כלים ותשתית לא נמנים בין הסיבות שהוא מונה."},"5":{"1":"המונחים הפוכים: Output הוא מה ששחררנו, ו-Outcome הוא מה שהשתנה ללקוח ולעסק.","2":"גם מה שתכננו וגם מה ששחררנו הם Output. Outcome הוא ההשפעה, כמו שיפור ב-Retention.","3":"החלוקה היא לא טווח קצר מול ארוך. Output הוא מה שיצרנו, ו-Outcome הוא ההשפעה שהייתה לזה."},"6":{"0":"Cagan מזהיר לא לגזור את החלוקה מהמבנה הארגוני, ודורש שכל חלק יהיה שייך לצוות אחד בדיוק.","2":"צוותי חוויה נבנים סביב משתמשים ומסעות, לא סביב שכבות טכנולוגיות. שכבות מפזרות בעלות ומוסיפות תלויות.","3":"צוותים מתחלפים ו-Backlog משותף מטשטשים בעלות. Cagan רוצה שכל חלק יהיה בבעלות צוות אחד לאורך זמן."},"7":{"0":"איסוף ודירוג דרישות היא גישת Feature Team. ב-Empowered ה-Stakeholders נותנים אילוצים, לא פתרונות.","2":"Stakeholder שמופתע בהשקה הופך ליריב קבוע. משתפים בממצאי Discovery לפני שצריכים את התמיכה.","3":"לפי Cagan פיצ׳ר לכל צד הוא Roadmap של שקט תעשייתי, לא של אסטרטגיה."},"8":{"0":"הפוך: ב-Inspired נמצאות טכניקות ה-Discovery, ו-Empowered עוסק במנהיגות, תרבות ו-Coaching.","2":"החלוקה היא צוות מול ארגון, לא סטארטאפ מול ארגון גדול. Empowered עוסק בבניית הארגון.","3":"Empowered לא מחליף את ה-Discovery, הוא בונה את הארגון שמאפשר אותו."},"9":{"0":"תכנון מפורט מראש הוא ההפך מניסויים. צוותים שמפחדים להיכשל מפסיקים לנסות דברים חדשים.","2":"חיפוש אשמים הופך כישלון לעונש. Cagan רוצה שכישלון יהיה למידה.","3":"התעלמות מכישלונות מאבדת את מה שהם מלמדים. התרבות אצל Cagan לומדת מכישלון, לא מדלגת עליו."},"10":{"0":"כיוון מגיע מ-Strategic Context ומבעיה עם מדדים. רשימת פיצ׳רים שבועית מכתיבה פתרונות.","2":"האחריות היא של ההנהגה, לא של הצוות. לפי Cagan התיקון מתחיל בהנהגה, לא בצוות.","3":"Roadmap רבעוני של פיצ׳רים עדיין מכתיב פתרונות. צוות Empowered מקבל בעיות ומדדים, לא פיצ׳רים."},"11":{"0":"ה-Transformation מתחיל במחויבות מלמעלה, וה-Pilot בא אחריה ולא במקומה.","2":"בסדר של Cagan, Coaching בא לפני אוטונומיה. בלי Coaching, ״תהיו אוטונומיים״ היא נטישה.","3":"לפי Cagan את ה-Missionaries יוצרת הסביבה, לא מוצאים אותם. Pilot מוכיח תוצאות, הוא לא ממיין אנשים."},"12":{"0":"Backlog Manager לא מריץ Discovery, זה מה ש-Product Person עושה. כאן התפקידים מוחלפים.","2":"ההבדל הוא לא בכירות אלא דרך העבודה: לגלות מול משתמשים, או להעביר דרישות.","3":"גם כתיבת מפרט מלא מראש היא לא Discovery. Product Person בודק רעיונות מול משתמשים, לא מתעד אותם."},"13":{"0":"הקשר לא פוטר מתוצאות: Team Objectives הם תוצאה מדידה שכל צוות לוקח על עצמו.","2":"הקשר לא מחליף Coaching. שניהם אחריויות נפרדות של Product Leadership.","3":"ב-Empowered ה-Stakeholders מספקים אילוצים והקשר, והצוות הוא שמוצא את הפתרון."},"14":{"0":"בדיקת כל שלב היא גם Micromanagement. המאמן לא בודק כל צעד אלא מפתח שיקול דעת.","2":"להגיד בדיוק מה לשנות זו עדיין הוראה. Coaching שואל שאלות כדי שה-PM ימצא את התשובה.","3":"כלי ה-Coaching של Cagan הוא 1:1 פרטי וקבוע, לא סקירה פתוחה שחושפת את הטעויות של ה-PM."}},"106":{"0":{"0":"אלה לא השלבים של Ries. הלולאה שלו בונה, מודדת ולומדת, ומתכננים אותה הפוך, מתוך מה שרוצים ללמוד.","2":"עיצוב, פיתוח והשקה מתארים Delivery שנגמר בהשקה. הלולאה של Ries נגמרת בלמידה: האם ההשערה אומתה?","3":"הלולאה של Ries כוללת שלב מדידה מפורש של התנהגות משתמשים אמיתיים, עם מדדים שמובילים להחלטה."},"1":{"0":"לפי Ries, MVP הוא לא גרסה 1 מכווצת. גרסה עם כל פיצ׳רי הבסיס היא מוצר, לא ניסוי.","2":"MVP לא נבנה להשקה מלאה. ההצלחה שלו נמדדת בכמה הוא לימד, לא בכמה הוא מוכן.","3":"כל העניין ב-MVP הוא התנהגות של משתמשים אמיתיים. אב-טיפוס פנימי לא מייצר Validated Learning."},"2":{"0":"ההבדל הוא לא הקהל. Vanity Metric מטעה גם את הצוות, והמבחן הוא אם המדד מוביל להחלטה.","2":"דיוק הוא לא העניין: סך ההורדות יכול להיות מדויק ועדיין Vanity. הוא תמיד עולה ולא משנה אף החלטה.","3":"גם מדדי שימוש יכולים להיות Actionable, כמו משתמשים פעילים בשבוע או Cohort Retention. המבחן הוא אם הם מובילים להחלטה."},"3":{"0":"סקר שבו אנשים אומרים שיקנו מופיע בשלב כאשליה של למידה. Validated Learning מבוסס על התנהגות בפועל.","2":"״מומחה אמר שזה רעיון מעולה״ הוא אשליה של למידה לפי השלב. רק משתמשים אמיתיים בניסוי אמיתי מאמתים.","3":"״המתחרים כבר עושים את זה״ הוא אשליה של למידה. זה לא אומר כלום על איך המשתמשים שלנו מתנהגים."},"4":{"0":"ה-Baseline הוא רק נקודת הפתיחה, וגם מספרים עגומים הם נכס. קודם מכווננים את המנוע בניסויים.","2":"מהלך של מתחרה הוא לא הטריגר. Pivot נשען על הנתונים שלנו, שמראים שהכיוון תקוע למרות ניסויים.","3":"קובעים את הפגישה מראש כדי שההחלטה לא תידחה, לא כדי להחליף כיוון לפי לוח שנה. אם המחוגים זזים, ממשיכים."},"5":{"0":"Ries מזהיר שבלי הנחיה טובה חמשת ה״למה״ הופכים לחמש האשמות. המטרה היא לתקן את המערכת, לא למצוא אשם.","2":"5 Whys מנתח בעיה שכבר קרתה. זו לא דרך להצדיק רעיון לפיצ׳ר.","3":"תיקון סימפטומים הוא בדיוק מה שהשיטה מונעת. היא חופרת עד השורש, שלרוב הוא תהליך."},"6":{"0":"גודל שוק ותמחור הם לא שתי הנחות קפיצת האמונה. Ries מדבר על השערת הערך ועל השערת הצמיחה.","2":"אלה לא השתיים של Ries. בעיה ופתרון משאירים בחוץ את שאלת הצמיחה: איך לקוחות חדשים ימצאו את המוצר.","3":"טכנולוגיה ומימון הן לא ההשערות של Ries. שתיהן אצלו עוסקות בלקוח: ערך וצמיחה."},"7":{"0":"Ries לא ממיין Pivot לפי גודל. הקטלוג שלו מגדיר מה משתנה: הפיצ׳ר, הקהל, מודל ההכנסות או הטכנולוגיה.","2":"Landing Page, Video, Concierge ושאר הרשימה הם סוגי MVP, לא סוגי Pivot.","3":"Sticky, Viral ו-Paid הם שלושת מנועי הצמיחה, לא סוגי Pivot."},"8":{"0":"Innovation Accounting הוא לא תקציב. הוא מודד התקדמות מ-Baseline דרך ניסויים, כש-ROI עוד לא רלוונטי.","2":"הורדות והרשמות מצטברות הן בדיוק ה-Vanity Metrics ש-Ries מזהיר מהם: ״תיאטרון הצלחה״.","3":"מספר הניסויים הוא לא המדד. מה שקובע הוא אם המדדים זזים מה-Baseline לעבר היעד."},"9":{"0":"לפי הניתוח שהשלב מביא, הכסף לא נגמר ראשון: הסיבה הנפוצה, כ-42%, הייתה היעדר צורך אמיתי בשוק.","2":"Ries עונה לחשש מהמוניטין: אם עוד לא יודעים מי הלקוח, איך נדע מה הוא מחשיב כאיכות?","3":"ברוב הכישלונות הטכנולוגיה לא קרסה. הסיבה הנפוצה הייתה לבנות משהו שאף אחד לא צריך."},"10":{"0":"בלי השערה אחת ברורה אין MVP. חמישה עשר פיצ׳רים ושלושה חודשים הם מוצר, לא ניסוי.","2":"קיצוץ לפיצ׳רי ליבה עדיין בונה מוצר. המדד הוא הניסוי הקטן ביותר להשערה אחת, לא מספר הפיצ׳רים.","3":"״קודם ללטש, אחר כך לשחרר״ הוא בדיוק הבזבוז שהספר נלחם בו. הבעיה היא יותר מדי בנייה, לא פחות מדי."},"11":{"0":"אחוז גידול בהורדות הוא עדיין Vanity: ״200% צמיחה!״ מופיע בשלב כמדד מטעה.","2":"אותן הורדות כגרף שמטפס הן אותו Vanity Metric. הצורה לא הופכת מדד ל-Actionable.","3":"הדיוק הוא לא העניין: גם סך מאומת תמיד עולה ולא אומר כלום על שימוש אמיתי."},"12":{"0":"Slack לא מכר את המשחק לקהל חדש. כלי פנימי אחד הפך למוצר בפני עצמו.","1":"המוצר עצמו השתנה, לא רק הטכנולוגיה. Technology Pivot שומר על אותו פתרון בדיוק על טכנולוגיה חדשה.","3":"Zoom-out הופך מוצר לפיצ׳ר. Slack הלך בכיוון ההפוך: פיצ׳ר אחד הפך למוצר כולו."},"13":{"0":"הסיבה של Ries היא מהירות למידה, לא עלות או כוח אדם. לולאה קצרה מגלה בעיות אחרי שבוע, לא אחרי חודש.","2":"תדירות שחרור לא מעלה Retention מעצמה. Small Batches מקצרים את לולאת הלמידה ומקטינים את הסיכון.","3":"מספר פיצ׳רים ו-Velocity הם Output. Ries מודד התקדמות בלמידה מאומתת, לא בפיצ׳רים שנמסרו."},"14":{"0":"Pivot לפי Ries מבוסס נתונים מעצם הגדרתו, על Validated Learning. הביקורת היא ההפך: Pivot בלי למידה.","2":"לפי ההגדרה של Ries, Pivot שומר על מה שכבר נלמד. התחלה מאפס היא לא מה שהופך אותו לאמיתי.","3":"Ries ממליץ לקבוע את פגישת ה-Pivot-or-Persevere מראש, כדי שההחלטה לא תידחה לנצח."}},"107":{"0":{"0":"הסדר שבור: כל שימוש מתחיל בטריגר, וה-Investment מגיע רק אחרי התגמול.","2":"אלה לא שלבי ה-Hook. בלולאה של Eyal התגמול משתנה, והיא נגמרת ב-Investment ולא ב״יצירת הרגל״.","3":"התגמול ב-Hook משתנה, לא קבוע: תגמול קבוע נשחק. והלולאה נגמרת ב-Investment."},"1":{"0":"Internal Trigger הוא לא תזכורת שהמשתמש קבע. זה רגש, כמו שעמום או FOMO, שמולחם למוצר.","2":"לא משנה אם זה בתוך האפליקציה או מחוצה לה: באנר In-App הוא עדיין רמז חיצוני. Internal פירושו רגש.","3":"טריגרים מתניעים שימוש, ותגמולים מגיעים אחרי הפעולה. Internal Trigger הוא רגש כמו שעמום או חרדה."},"2":{"0":"Paid, Earned ו-Owned הם סוגים של External Triggers, לא תגמולים.","2":"Identify, Codify ו-Modify הם שלבי Habit Testing, לא סוגי תגמול.","3":"שעמום, FOMO ובדידות הם Internal Triggers: רגשות שמתניעים שימוש, לא תגמולים שמגיעים אחריו."},"3":{"0":"בנוסחה אין תגמול. במודל Fogg הרכיב השלישי הוא הטריגר: מוטיבציה, יכולת וטריגר.","2":"תדירות ותועלת נתפסת הם הצירים של ה-Habit Zone, לא הנוסחה של Fogg.","3":"האותיות נכונות אבל המשמעות לא: A היא Ability ו-T היא Trigger, לא קשב וזמן פנוי."},"4":{"0":"Motivation הוא המנוף היקר והפחות יעיל. הורדת חיכוך כמעט תמיד זולה ויעילה יותר.","2":"בקשת נתונים לפני הפעולה מוסיפה חיכוך. ו-Investment מבקשים רק אחרי שניתן תגמול.","3":"תגמול אחרי הפעולה לא עוזר כשמשתמשים לא משלימים אותה. המרה נמוכה מצביעה על חיכוך, ולכן בודקים Ability."},"5":{"0":"תדירות ותועלת נתפסת מגדירות את ה-Habit Zone. ה-Manipulation Matrix הוא מצפן אתי.","2":"זה Entertainer: משתמש בעצמו, אבל המוצר לא משפר חיים. Facilitator דורש את שניהם.","3":"זה Peddler: מאמין שהמוצר עוזר אבל לא משתמש בו. Facilitator דורש את שניהם."},"6":{"0":"Stored Value הוא ערך עבור המשתמש, לא ההכנסות של החברה. CLTV הוא מדד אחר.","2":"Eyal מבחין בין קנס יציאה ל-Stored Value: היסטוריה שמשפרת את השירות היא ערך אמיתי, קנס הוא לא.","3":"תגמולים משתנים הם שלב 3. Stored Value הוא מה שהמשתמש משקיע בשלב 4, ה-Investment."},"7":{"0":"הגודל הוא לא מה שעובד. לפי Skinner, הציפייה הלא ודאית, לא הפרס עצמו, היא שמציתה את הדחף.","2":"ערך שגדל עם ההשקעה מתאר את Stored Value, שלב 4. התגמול המשתנה עובד דרך אי-ודאות.","3":"העלות היא לא הסיבה. חוסר הצפיות הוא שמחזק את ההתנהגות בצורה החזקה ביותר."},"8":{"0":"הישג ושליטה, כמו Inbox ריק, הם תגמולי Self, לא Hunt. Hunt עוסק במשאבים ובמידע.","2":"השניים מוחלפים: Tribe הוא הכרה חברתית, ו-Hunt הוא חיפוש מידע ומשאבים.","3":"Tribe הוא לא נאמנות למותג ו-Hunt הוא לא תחרות. Tribe הוא הכרה חברתית, Hunt הוא מידע ומשאבים."},"9":{"0":"משך הביקור הוא לא המבחן של Eyal. הוא שואל תוך כמה זמן המשתמש ירגיש שהמוצר נעלם: שעות פירושן Hook.","2":"כניסה אחרי התראה מראה תגובה ל-External Trigger. הרגל פירושו לחזור גם בלי התראה.","3":"הזמן לרגע ה-Aha מודד את ה-Onboarding. מבחן ההרגל של Eyal הוא כמה מהר ירגישו שהמוצר נעלם."},"10":{"0":"8% פירושו שרוב המשתמשים לא חוזרים מדי יום. ה-Habit Zone דורש תדירות גבוהה, ו-8% זה נמוך.","2":"הנתון אומר ההפך: ב-DAU/MAU של 8% רוב המשתמשים לא חוזרים מדי יום. התדירות היא הבעיה.","3":"משתמשים חדשים לא יוצרים הרגל. היחס מראה שהקיימים לא חוזרים, ועוד גיוס רק ממלא דלי דולף."},"11":{"0":"הצפה בהתראות היא טעות נפוצה: המשתמשים מכבים הכל. עוד מאותו דבר לא יולחם לרגש.","2":"התראות Push הן Owned Trigger, לא Paid. וכל טריגר חיצוני עוזר רק כשהוא מולחם לרגש.","3":"לפי Eyal לא מתחילים ממוטיבציה. החוליה החסרה היא Internal Trigger, רגש, לא קמפיין."},"12":{"0":"משפר חיים בלי להשתמש בעצמו הוא Peddler, לא Entertainer. ה-Entertainer משתמש, אבל המוצר לא משפר חיים.","2":"Dealer לא משתמש וגם לא משפר חיים. ״משפר חיים בלי להשתמש״ הוא תיאור של Peddler.","3":"משתמש ומשפר חיים הוא ה-Facilitator, לא ה-Entertainer. וה-Dealer בכלל לא משתמש במוצר."},"13":{"0":"מוטיבציה וטריגר הם רכיבים נפרדים ב-B=MAT, ותדירות ותועלת שייכות ל-Habit Zone. הם לא גורמי Ability.","2":"אלה עקרונות איכות של ממשק. ששת הגורמים של Eyal מודדים כמה הפעולה עולה למשתמש: זמן, כסף, מאמץ ועוד.","3":"אלה רגשות ורצונות, לא המחיר של פעולה. גורמי הפשטות מודדים זמן, כסף, מאמץ, קבילות חברתית ושגרה."},"14":{"1":"חיכוך רלוונטי רק כשיש כבר טריגר. Eyal מתחיל מלוודא שיש טריגר ברור.","2":"Motivation הוא המנוף היקר והפחות יעיל, ולכן הוא מגיע בסוף, לא בהתחלה.","3":"תגמול והשקעה מגיעים אחרי הפעולה, בתוך הלולאה. בלי טריגר שום דבר לא מתחיל."}},"108":{"0":{"0":"אמא היא לא הלקוחה הקשוחה אלא הכי עדינה: היא אוהבת אתכם ולכן מעודדת. זו בדיוק הבעיה.","2":"משפחה וחברים נותנים את המשוב הפחות כן: הם אוהבים ורוצים לתמוך. זו נקודת המוצא של הספר.","3":"השם לא עוסק בפשטות. הוא עוסק בשאלות עובדתיות כל כך, שגם מי שאוהב אתכם לא יוכל לשקר לכם בנעימות."},"1":{"0":"הצגת הרעיון שוברת את כלל 1, שאלה על העתיד שוברת את כלל 2, ומחמאות ובקשות פיצ׳רים הם Bad Data.","2":"הכלל הראשון נכון, אבל ״מה הייתם רוצים בעתיד״ הוא Fluff, ובקשות פיצ׳רים הן רמז לכאב ולא מפרט.","3":"Fitzpatrick רוצה עומק: לחפור מתחת לכל תשובה כללית. ולתעד ציטוטים מדויקים, לא סיכום במילים שלכם."},"2":{"0":"זו אחת השאלות הטובות בספר: היא מעגנת את השיחה באירוע אמיתי מהעבר. היא ממקדת, לא מפזרת.","2":"שאלה על מה משלמים היום מומלצת בספר: היא חושפת Willingness to Pay דרך ההווה, לא דרך הבטחות.","3":"״איך פותרים את זה היום?״ היא שאלה טובה: היא על החיים שלהם, וזה שהרעיון שלכם לא מוזכר הוא בדיוק העניין."},"3":{"0":"סיפורים ספציפיים וציטוטים מדויקים מהעבר הם Good Data. סקרים ודירוגים לוכדים דעות, לא התנהגות.","2":"מחמאות הן ה-Bad Data הקלאסי, והנתון הלא נעים הוא לרוב החשוב ביותר. המבחן הוא עובדות, לא טון.","3":"הבטחות רכישה וכוונות לעתיד הן Fluff, כלומר Bad Data. Good Data הוא התנהגות מהעבר וכסף אמיתי."},"4":{"0":"״בטוח אשתמש״ נלהב הוא עדיין מילים: Fluff על העתיד. Commitment עולה זמן, מוניטין או כסף.","2":"משוב על פיצ׳רים חסרים הוא בקשת פיצ׳ר, עוד סוג של Bad Data. Commitment פירושו לוותר על משהו.","3":"מחמאות לא מצטברות ל-Commitment. זה מטבע אחר לגמרי: זמן, מוניטין או כסף, לא עוד שבחים."},"5":{"0":"הצגת המוצר הופכת את השיחה ל-Pitch, והלמידה נעצרת. Advancement הוא צעד שהלקוח עושה.","2":"Advancement עוסק בשיחה עם הלקוח, לא ב-Onboarding בתוך המוצר. זה הצעד הקונקרטי הבא.","3":"סיום נעים עם מחמאה ובלי צעד הבא הוא כישלון נעים: לידים זומבים, ידידותיים ולעולם לא קונים."},"6":{"0":"Saturation נמדד בין ראיונות, לא בתוך ראיון אחד: עוצרים כשהתשובות חוזרות אצל אנשים שונים, בדרך כלל 5 עד 15.","2":"הסכמה עם ההשערה היא לא המבחן. Saturation פירושו שאותם כאבים חוזרים, לא משנה מה קיוויתם לשמוע.","3":"Saturation כאן עוסק בראיונות, לא במתחרים. הוא מסמן שנעשו מספיק שיחות."},"7":{"0":"קזואלי לא אומר בלי הכנה: הספר דורש שלוש שאלות גדולות מראש וציטוטים מדויקים במהלך השיחה.","2":"הצגת הרעיון שוברת את הכלל הראשון. שיחה קזואלית מורידה הגנות, היא לא במה לרעיון.","3":"המטרה היא ללמוד, לא למכור. ברגע שמתחילים למכור הלמידה נעצרת, גם אם הפגישה ״הלכה טוב״."},"8":{"0":"״כמה תשלמו?״ היא שאלה היפותטית, Fluff. בקשה היא רמז לכאב, וחופרים למניע שלה.","2":"זה לא התפקיד של הלקוח לדעת מה לבנות. בקשת פיצ׳ר היא רמז לכאב, לא מפרט.","3":"הצגת ה-Roadmap הופכת את הראיון ל-Pitch ומקבלת את הבקשה כמו שהיא. קודם חופרים לכאב שמאחוריה."},"9":{"0":"בעיות לא צפויות הן סימן טוב: אם שום דבר לא הפתיע, לא למדתם כלום.","2":"לפי כלל ה-20%, הלקוח צריך לדבר רוב הזמן. מי שמדבר יותר מחמישית מהזמן מוכר, לא לומד.","3":"אי נוחות צפויה: ראיון טוב מרגיש לעיתים קצת לא נעים, כי שומעים דברים שלא רצו לשמוע."},"10":{"0":"78% שאומרים שהם רוצים זה מדד לאופטימיות. בנייה על זה מדלגת על הבדיקה אם הכאב אמיתי.","2":"״כמה תשלמו?״ היא בדיוק השאלה הגרועה שהספר מסמן. שואלים כמה הבעיה עולה להם היום.","3":"תגובה למוקאפ היא עדיין דעה ומזמינה מחמאות. אימות מגיע מהתנהגות בעבר."},"11":{"0":"כוונה מוצהרת לעתיד היא Fluff, הסוג השני של Bad Data. אנשים מדמיינים גרסה אידיאלית של עצמם.","2":"התלהבות בלי Commitment היא רעש, לא Signal. Signal הוא כאב שחוזר או נכונות להתקדם.","3":"זה לא ניטרלי, זה Bad Data. סקר ימדוד את אותה אופטימיות; רק התנהגות מהעבר או Commitment מאמתים."},"12":{"0":"״היית משתמש?״ ו״כמה היית משלם?״ הן שאלות היפותטיות על העתיד שמזמינות אופטימיות.","2":"שאלה על דעתם על הרעיון מניחה את הרעיון שלכם על השולחן, ומשם כולם נהיים מנומסים.","3":"״איזה פיצ׳ר חסר?״ מזמין בקשה, לא כאב. ושאלות עתידיות על רצון ותשלום הן Fluff."},"13":{"0":"כיסוי כל הכאבים מתעלם מהאות: כאבים שונים אצל כל אחד מעידים על סגמנט רחב מדי, לא על ביקוש רחב.","2":"עוד ראיונות מאותו קהל רחב ימשיכו להתפזר. הפתרון בספר הוא לפרוס את הסגמנט, לא לדגום עוד.","3":"עוצמה רגשית היא לא המבחן. Signal הוא כאב שחוזר אצל אנשים שונים בסגמנט ממוקד."},"14":{"0":"מחמאה היא Bad Data, ״זהב של שוטים״. היא לא וולידציה, חזקה ככל שתישמע.","2":"דירוג הופך מחמאה למספר, אבל היא נשארת דעה. זה רק מזמין עוד שבחים.","3":"הצגת תמחור ופיצ׳רים הופכת את הראיון למכירה ומזמינה עוד מחמאות. הלמידה נעצרת."}},"109":{"0":{"0":"זה הכיוון של רוב הארגונים, מבחוץ פנימה, ובדרך ה-Why הולך לאיבוד.","2":"How הוא המעגל האמצעי, ולכן הוא בא לפני What. ארגונים מעוררי השראה הולכים Why, אחר כך How ואז What.","3":"Sinek קובע כיוון קבוע לארגונים מעוררי השראה: תמיד מהליבה החוצה, ה-Why קודם."},"1":{"0":"אזורי המוח מוחלפים: הנאוקורטקס אחראי על שפה וניתוח ומקביל ל-What, והמוח הלימבי מקביל ל-Why.","2":"למוח הלימבי אין יכולת שפה בכלל. ה-Why פונה לחלק שמחליט, לא לחלק שמסביר.","3":"היגיון וניתוח הם הנאוקורטקס, מעגל ה-What. ה-Why פונה לרגש ולאמון שבמוח הלימבי."},"2":{"0":"מניפולציה אצל Sinek היא לא שקר: הנחות ומבצעים עובדים והם כנים. הם קונים עסקה, לא נאמנות.","2":"פחד ושאיפות נמצאים ברשימת המניפולציות של Sinek, אבל Inspiration הוא לא מפרט ומחיר. זו אמונה שאנשים מצטרפים אליה.","3":"המחלקה היא לא ההבחנה. הנחה היא מניפולציה מי שלא יפעיל אותה, ו-Inspiration היא אמונה, לא תקציב."},"3":{"0":"לקחת את העצה של כולם זו בדיוק מלכודת המסיבה: קונים הכל, מבזבזים, ושום דבר לא מתחבר.","2":"התאמה למתחרים היא ההפך מסינון לפי אמונה. המבחן הוא עקביות עם ה-Why שלנו, לא עם השוק.","3":"Celery Test מסנן לפי ה-Why, לא לפי החזר השקעה. Velox דחתה חוזה משתלם שסתר את ה-Why שלה."},"4":{"0":"Sinek אומר ההפך: Early Adopters קונים את ה-Why וסולחים על פינות לא מלוטשות. הרוב הוא שצריך הוכחות.","2":"ה-Early Majority צריך הוכחות והמלצות. מי שקונים את ה-Why ומפיצים אותו הם ה-Early Adopters.","3":"Early Adopters קונים חזון ותחושת בטן, לא פיצ׳רים. TiVo שיווקה What והתקשתה למרות עליונות טכנולוגית."},"5":{"0":"Sinek לא רואה יריבות: מאחורי כמעט כל ארגון מעורר השראה עומד צמד, ואף אחד לא מספיק לבד.","2":"אף אחד לא מחליף את השני: בעל החזון רואה מה שעוד לא קיים, והמבצע בונה את המבנה, ביחד.","3":"Sinek מתאר שני אנשים, כמו Walt ו-Roy Disney או Jobs ו-Wozniak, לא מנהיג אחד שעושה את שניהם."},"6":{"0":"לכל היצרנים הייתה גישה לאותם מהנדסים. לפי Sinek, Apple מוכרת אמונה, ומפרט לבדו לא מסביר את הנאמנות.","2":"עיצוב יפה ופשוט הוא ה-How של Apple. לפי Sinek הנאמנות נובעת מה-Why: אתגור הסטטוס קוו.","3":"לחץ חברתי הוא אחת משש המניפולציות ש-Sinek מונה. הוא קונה עסקאות, לא את הנאמנות שהוא מייחס ל-Apple."},"7":{"0":"הפוך: מה שאובד הוא הכיוון, ה-Why. ה-How Person נשאר וממשיך לבצע, אבל בלי מצפן.","2":"האזהרה של Sinek עוסקת במצפן, לא בקשרי לקוחות. ההחלטות גולשות מ-Why ל-What.","3":"הסיכון אצל Sinek הוא לא זהירות אלא אובדן כיוון: ההחלטות נהיות What-driven ולא נאמנות ל-Why."},"8":{"0":"פתיחה במפרט היא What-first: הדיון גולש מיד לצבעים, עלויות ולוחות זמנים במקום לערך.","2":"נתונים ו-ROI פונים לנאוקורטקס, שמבין אבל לא מחליט. אנשים מתווכחים עם What ומצטרפים ל-Why.","3":"הסתרת ה-Why מה-Stakeholders מוותרת על הכוח העיקרי שלו: עם What מתווכחים, ל-Why מצטרפים."},"9":{"0":"Why שהמעשים לא מגבים שובר אמון. ה-Phaeton של VW הוא הדוגמה בספר ל-What שסותר את ה-Why.","2":"סלוגן לבדו הוא Why כקמפיין: אם החלטות המוצר והתמחור שונות, הלקוחות ירגישו את הפער.","3":"Why שמשתנה לפי פלח הוא לא אמונה. עקביות ה-What עם Why אחד היא אחד משלושת התנאים של Sinek."},"10":{"0":"את ה-Why מוצאים במבט לאחור, לא בתחזיות. תחזיות עוזרות להחליט על ה-What, לא לגלות במה מאמינים.","2":"המיצוב של המתחרים מספר עליהם, לא על מה שאתם מאמינים. Sinek אומר להסתכל לאחור, אל הסיפור שלכם.","3":"נתוני שימוש עוזרים להחליט על ה-What. הם לא חושפים את האמונה, שנמצאת בעבר, בסיפור ההקמה."},"11":{"0":"האיטיות היא לא הסיבה. ההחלטה מתקבלת במוח הלימבי, שאין לו יכולת שפה בכלל.","2":"Sinek לא מדבר על לחץ. המוח הלימבי מחליט בכל מצב, והוא פשוט לא יודע לדבר.","3":"הפוך: אנשים מחליטים קודם לפי תחושה, ורק אחר כך מגייסים נתונים כדי להצדיק אותה."},"12":{"0":"ציון שביעות רצון מודד חיבה, לא חדות. המבחן הוא אם הצוות מצליח לצטט את השורה מהזיכרון.","2":"ניסוח ייחודי לא הופך Why לחד. המבחן הוא אם מישהו במסדרון יודע לצטט אותו.","3":"רשימת פיצ׳רים היא ה-What. שורת Why היא אמונה, כמו ״צוותים צריכים לעבוד, לא לנהל את העבודה״."},"13":{"0":"Why כללי כמו ״לעשות את העולם טוב יותר״ לא מסנן אף החלטה. Why טוב חד מספיק כדי לומר בעזרתו ״לא״.","2":"מדד ותאריך הופכים אותו ליעד, וזו בדיוק הבעיה. רווח והובלת שוק הם תוצאה, לא Why.","3":"Why שמוסתר מהלקוחות מאבד את כוחו: אנשים קונים את הסיבה שבגללה עושים, לא את מה שעושים."},"14":{"0":"הגיל הוא לא הביקורת, והספר כולל גם את כניסת Apple לטלפונים ב-2007. החולשה היא אילו מקרים נבחרו.","2":"הפוך: הספר נשען על מנצחים נבחרים, והחברות שקרסו בכלל לא נכנסות לתמונה.","3":"הביקורת היא לא עודף מספרים, הספר בנוי על סיפורים. החולשה היא שמסופרים רק סיפורי המנצחים."}},"110":{"0":{"0":"Karp טוען ההפך: ניטרליות היא אשליה, וסירוב לבחור הוא בעצמו בחירה.","2":"Karp לא קורא לממשלות לפתח לבד. הוא קורא לברית בין המהנדסים הטובים ביותר לבין המשימות הלאומיות.","3":"Karp אומר ההפך: עידן ה-AI דומה לעידן האטום, ומי שמוביל כותב את הכללים. הוא לא קורא להשהיה."},"1":{"0":"מכירה לכל קונה חוקי היא בדיוק הניטרליות ש-Karp דוחה. הבחירה למי למכור היא בחירה ערכית.","2":"Palantir בנתה את העסק שלה על עבודה עם ממשלות מערביות וארגוני ביטחון, לא על הימנעות מהם.","3":"Palantir עובדת גם עם בעלות ברית של ארה״ב, כמו בריטניה וישראל. הקו הוא דמוקרטיות מול יריבים, לא מדינה אחת."},"2":{"0":"אלה עקרונות Privacy by Design מפרק היישום ב-Velox. מתוכם רק Data Minimization נמצא בערימת האחריות.","2":"אלה מתארים את תרבות ההנדסה של Palantir, הכלי השני, לא את ערימת האחריות.","3":"אלה ארבע השאלות האתיות לכל מוצר, הכלי השלישי, לא ערימת האחריות."},"3":{"0":"Karp מכנה את הגישה הזו ״אגנוסטיות טכנולוגית״: לבנות כלים עוצמתיים ולסרב לשאול למה הם משמשים.","2":"לפי Karp הערכים מוטמעים במערכת עצמה: מי חשוד, מה מוצג, מי מקבל הלוואה. נתונים נקיים לא מוחקים את זה.","3":"השארת הערכים ללקוח היא הניטרליות ש-Karp דוחה. הבחירה את מי לשרת היא בחירה ערכית של הספק."},"4":{"0":"Human-in-the-Loop חל על החלטות קריטיות של חיים, חירות וזכויות, לא על תזמון ודוחות שגרתיים.","2":"זה הפוך: בהחלטות קריטיות ה-AI רק מציע. בדיקת לוגים בדיעבד לא משאירה אדם בתוך ההחלטה.","3":"האדם בלולאה הוא מקבל ההחלטה שמאשר את ההמלצה, לא האדם המושפע שנותן הסכמה."},"5":{"0":"השלב מדבר על אחריות אתית, לא אחריות משפטית לתקלות. היא נובעת מההחלטה מה לבנות ולמי.","2":"לספק כל מה שהלקוח מבקש זה להסתתר מאחורי ״אני רק בונה כלים״. שומר הסף מגדיר מראש אילו עסקאות ושימושים לדחות.","3":"הכוח של ה-PM נובע מהגדרת מה נבנה, לא מבעלות על מדיניות האתיקה של החברה או מאישור ערכי הצוות."},"6":{"0":"הוספת פרטיות אחרי ההשקה היא בדיוק הטעות: אתיקה ופרטיות שמודבקות בדיעבד במקום להיות מתוכננות מראש.","2":"איסוף מלא סותר את Data Minimization: אוספים רק מה שהמשימה דורשת, לא ״הכל, ליתר ביטחון״.","3":"Privacy by Design הוא חובה של הספק בתכנון עצמו: איסוף מינימלי, מטרה מוגדרת ובקרת גישה."},"7":{"0":"המבחן לא עוסק בבאזז שיווקי. הוא שואל אם היינו גאים, בדיקה אתית ולא יחסי ציבור.","2":"בהירות התיעוד היא לא השאלה. המבחן שואל אם הסיפור של המערכת היה גורם לנו גאווה.","3":"המבחן לא עוסק בדליפות. הוא מדמיין את סיפור המערכת מתפרסם ושואל אם היינו גאים בו."},"8":{"0":"השארת הגבולות לרגולטורים היא הסתתרות מאחורי ״אני רק בונה״. ה-PM הוא שומר הסף האתי של מה שנבנה.","2":"השלב אומר שגם סטארטאפי סייבר מתמודדים עם אותה דילמה: למי למכור ולמי לסרב, גם במחיר פי שלושה.","3":"לפי השלב הדילמות חיות בישראל יותר מכמעט בכל מקום, והיחידות הטכנולוגיות מצמיחות מנהלי מוצר גם היום."},"9":{"0":"אישור רגע לפני ההשקה הוא עדיין מאוחר. By Design פירושו שאלות אתיות ב-PRD, ב-Design Review וב-Sprint Planning.","2":"ההבדל הוא בתזמון, לא בשכבה: מתחילת הפיתוח לעומת רק אחרי בעיה, בממשק ובקוד כאחד.","3":"קוד אתי שמתפרסם הוא לא תכנון. By Design פירושו שאלות אתיות בתוך תהליך הפיתוח עצמו."},"10":{"0":"FDE לא סוקר שווקים ולא מדגים למכירות. הוא יושב אצל הלקוח, רואה את הבעיה מקרוב ומתקן אותה במקום.","2":"FDE הוא לא צוות טיפול בתקלות. הוא עובד אצל הלקוח כדי להתאים את המוצר לצרכים אמיתיים.","3":"FDE עובד אצל הלקוח בשטח, לא במטה. הערך שלו הוא לראות את הבעיה מקרוב."},"11":{"0":"מהירות והיקף הם שאלות How. השאלה הראשונה בשיעור קודמת להן: מי משתמש הקצה ותחת איזה פיקוח.","2":"מחיר ומספר קונים מגיעים אחר כך. השאלה האתית הראשונה היא את מי המערכת משרתת ומה השפעתה על אזרחים.","3":"מה שהמתחרים עושים לא מכריע שום דבר אתי. השאלה הראשונה היא את מי המערכת משרתת, לא איך היא בולטת."},"12":{"0":"Data Minimization עוסק באיסוף פחות, לא בדחיסת מה שנשמר. המטרה היא פרטיות, לא עלויות אחסון.","2":"איסוף רחב הוא בדיוק הבעיה. העיקרון מגביל מה נאסף, לא רק מה מוצג.","3":"שימוש רק למטרה שלשמה נאסף הוא Purpose Limitation, עיקרון נפרד. Minimization מגביל מה נאסף מלכתחילה."},"13":{"0":"הדאגה של Karp היא לא הכנסות. היא שדמוקרטיות יישארו עם טכנולוגיה נחותה בזמן שהיריבים מתקדמים.","2":"Karp טוען ההפך: אם המהנדסים הטובים במערב מסרבים, סין ורוסיה ממלאות את הוואקום.","3":"הטיעון של Karp עוסק במאזן הכוחות, לא בדעת הקהל או ברגולציה."},"14":{"0":"הספר אומר ההפך: כישרון שמופנה לפרסום ולקניות הוא הבעיה, לא הוכחה ליתרון.","2":"הכשל עוסק בעליונות של המערב, לא ביתרון של מי שמשיק ראשון. ו-Karp קושר כוח לאחריות.","3":"ביטול מחאת עובדים כפינוק הוא ביקורת שהמבקרים מפנים ל-Karp עצמו, לא כשל המנצח."}},"111":{"0":{"0":"המעגל של Sinek הוא לא נוהל של HR. הוא נבנה מההתנהגות של המנהיג, יום אחרי יום.","2":"איומים חיצוניים קבועים ולא בשליטתכם. המעגל מגן מסכנות פנימיות, כדי שהאנרגיה תופנה החוצה.","3":"מעגל שמכסה רק קומץ נבחר יוצר חצר, לא צוות. Sinek מותח אותו סביב כולם."},"1":{"0":"שני זוגות מוחלפים: Endorphins מסכים כאב ו-Dopamine מתגמל הישג; Serotonin הוא גאווה ו-Oxytocin אמון.","2":"כל התפקידים במקום הלא נכון: Endorphins מסכים כאב, Dopamine מתגמל הישג, Serotonin גאווה, Oxytocin אמון.","3":"Endorphins מסכים כאב ולא אזעקת לחץ, שהיא Cortisol. ו-Oxytocin בונה אמון, לא מסכה כאב."},"2":{"0":"החלוקה שגויה: Endorphins ו-Dopamine הם הזוג האנוכי, ו-Serotonin ו-Oxytocin הם הזוג החברתי.","2":"לפי Sinek הכימיקלים האנוכיים חיוניים. הבעיה היא תרבות שמתגמלת רק אותם, לא הכימיקלים עצמם.","3":"החלוקה היא לא גוף מול מצב רוח. האנוכיים מניעים ביצוע אישי, והחברתיים מחברים אנשים לצוות."},"3":{"0":"בניית אמון איטית היא Oxytocin, לא Dopamine. הסכנה ב-Dopamine היא התמכרות ליעדים אישיים.","2":"הכרה וסטטוס הם Serotonin. הסיכון ב-Dopamine הוא מרוץ אחרי מספרים אישיים שדורס עמיתים.","3":"Sinek לא קושר Dopamine לפחד מכישלון; פחד ולחץ הם Cortisol. הסיכון ב-Dopamine הוא ״כל אחד לעצמו״."},"4":{"0":"Destructive Abundance לא עוסק ב-Backlog. זה הרגע שבו המדדים נעשים אמיתיים יותר מהאנשים, והערכים נשחקים עם ההצלחה.","2":"נדיבות היא לא הבעיה: ב-Barry-Wehmiller הקרבה משותפת דווקא יצרה נדיבות. הסכנה היא שחיקת הערכים.","3":"לפי Sinek הערכים נשחקים דווקא כשהולך טוב. Destructive Abundance מתחיל בהצלחה, לא במחסור."},"5":{"0":"העברת דרישות כמו שהן הופכת את ה-PM לצינור שמעביר בהלה. מנהיג סופג את הלחץ ומתרגם אותו.","2":"לקחת את ה-Credit לעצמו הופך את הכלל: את הקרדיט מעבירים לצוות, ואת האחריות לוקחים על עצמכם.","3":"Circle of Safety בלי סטנדרטים גבוהים הוא מועדון חברתי. והסתרת אי-ודאות היא Cortisol; משתפים את ההקשר."},"6":{"0":"Project Aristotle מצא את ההפך: ביטחון פסיכולוגי היה המנבא החזק ביותר להצלחת צוות.","2":"Google מצאה שהביטחון חזק יותר מהכישרון האישי של חברי הצוות, לא חלש ממנו.","3":"המונח של Edmondson הוא אמונה משותפת בצוות שבטוח לקחת סיכון, לא תכונה אישית. המעגל של Sinek הוא אותו רעיון."},"7":{"0":"הכרה פומבית בונה גאווה וסטטוס, כלומר Serotonin. Oxytocin נבנה ממגע אישי ומאמון.","2":"יעדים, אבני דרך ובונוסים הם Dopamine, תחושת הישג. Oxytocin נבנה דרך קשר אישי.","3":"לפי Sinek אי אפשר לבנות Oxytocin במייל. צריך נוכחות ומגע אנושי אמיתי, לא עוד עדכונים."},"8":{"0":"סקר שביעות רצון הוא לא המבחן. לפי השלב, רגע הבאג מודד מנהיגות טוב יותר מכל סקר.","2":"כשכולם אומרים שהכל בסדר, זה יכול להיות סימן לפחד, כמו ישיבות הסטטוס של מיכל עם הצלחות בלבד. ביטחון פירושו שבעיות עולות.","3":"מירוץ לזהות מי אחראי הוא חיפוש אשמים. ב-Circle of Safety השאלה היא מה למדנו."},"9":{"0":"הכותרת לא עוסקת בדילוג על ארוחות. היא באה מחדרי האוכל של הנחתים, שם הקצינים הבכירים אוכלים אחרי אנשיהם.","2":"שום תקנה לא מחייבת את זה, זו תרבות. והמסר הוא דאגה לאנשים, לא היררכיה.","3":"הכותרת באה מחדרי האוכל של הנחתים, לא מישיבות. המסר שלה הוא לדאוג לאנשים שלכם קודם."},"10":{"0":"ביטחון לא מחלחל מעצמו. Sinek אומר למתוח את המעגל סביב כולם, לא רק סביב השכבה הבכירה.","2":"הגנה רק על המצטיינים משאירה את השאר להשקיע אנרגיה בהגנה עצמית. מעגל של מעטים הוא חצר.","3":"מעגל רק למי שמסכים הוא חצר. ה-PM בשלב אף מגן על דעת המיעוט בוויכוח."},"11":{"0":"הממצא הפוך: מי שנושאים באחריות הכבדה ביותר הם לא אלה שנשחקים ראשונים.","2":"המחקר מצא שהעומס הוא לא הרעל. חוסר האונים, תחושת שליטה נמוכה, הוא הרעל.","3":"המחקר עקב אחרי עובדי מדינה בריטים לפי דרגה ותחושת שליטה. הממצא עוסק בשליטה, לא בתפקידים תחרותיים."},"12":{"0":"הובלה בסמכות שאולה, ״ה-CEO אמר״, שורפת אמון, כך מזהיר השלב.","2":"שליטה במידע שוברת ביטחון: סודות הם Cortisol, והצוות ממלא את החסר בדמיון, תמיד לרעה.","3":"אצל Sinek מנהיגות היא בחירה, לא דרגה. הכפפה רשמית לא גורמת לאנשים לבחור ללכת אחריכם."},"13":{"0":"דיון גלוי בישיבה והשלכה פומבית מלמדים את כולם להסתיר את הבאג הבא. שואלים מה למדנו, לא מי אשם.","2":"הסתרת הבאג חוסמת למידה ושוברת שקיפות. להגן פירושו לקחת אחריות כלפי חוץ, לא להסתיר.","3":"דיווח על שם המפתח חושף אותו במקום להגן עליו. בפעם הבאה בעיות פשוט יוסתרו."},"14":{"0":"אבסטרקציה אצל Sinek עוסקת במרחק מאנשים, לא ביעדים מעורפלים. הסכנה היא שאנשים הופכים למספרים.","2":"מעבר ל-150 איש Sinek מעביר סמכות למטה למנהיגים מקומיים, לא מרכז אותה.","3":"Sinek אומר ההפך: מרחק הופך פגיעה לקלה. מנהיגים צריכים לפגוש את מי שההחלטות שלהם נוחתות עליו."}},"112":{"0":{"0":"כאן הנוסחה הפוכה: ה-Objective הוא הכיוון האיכותי, וה-Key Results הם המספרים שמודדים אותו.","2":"משימות שבוצעו הן פעילות, לא תוצאה. Key Results מודדים תוצאה, ולכן רשימת תוצרים לא נכנסת לנוסחה.","3":"זה תיאור של MBO, שאותו Grove שדרג: OKRs הם רבעוניים וגלויים, לא יעד שנתי שנסגר בפרטיות."},"1":{"0":"התפקידים הפוכים: ה-KPI הוא מדד הבריאות היציב, וה-OKR הוא המהלך הרבעוני שנועד לשנות מצב.","2":"OKRs רצים במחזור רבעוני, לא אחת לכמה שנים, ו-KPI נשאר יציב לאורך זמן ולא משתנה בכל Sprint.","3":"ל-OKR יש מספרים: ה-Key Results שלו כמותיים. KPI הוא מדד שוטף נפרד, לא ההוכחה שה-OKR הושג."},"2":{"0":"ההגדרות הפוכות: Committed הוא הבטחה שבה מצופה 1.0, ו-0.7 נחשב הצלחה דווקא ב-Aspirational.","2":"גם Aspirational מקבל ציון: ממוצע של 0.7 נחשב הצלחה, ולכן עוקבים אחריו לאורך כל הרבעון.","3":"החלוקה היא בין הבטחה לשאיפה, לא בין טווחי זמן. ב-Aspirational, הגעה ל-100% מעידה שכיוונו נמוך מדי."},"3":{"0":"CFR הם Conversations, Feedback, Recognition, והם רציפים. ה-Check-ins השבועיים נשארים חלק ממחזור ה-OKR.","2":"Doerr מציע את CFR כתחליף לשיחת ההערכה השנתית, וממליץ להפריד בין ציוני OKR לבונוסים.","3":"CFR לא עוסק באיסוף משוב מלקוחות: אלה Conversations, Feedback, Recognition בין מנהלים לעובדים."},"4":{"0":"כמה KRs ל-Objective זה המבנה הרגיל: לכל Objective יש 2 עד 5 Key Results.","2":"מספרים הם בדיוק מה ש-Key Result צריך. כפי שמובא בשלב בשם Marissa Mayer: אין Key Result בלי מספר.","3":"יעדים שאפתניים הם דבר רצוי: כשהכול נוחת ב-100%, זה סימן שאף אחד לא נמתח."},"5":{"0":"הבעיה שהשלב מתאר היא התנהגותית, לא תקציבית: תגמול שקשור ל-OKRs דוחף אנשים ליעדים בטוחים.","2":"האפקט הפוך: כשהבונוס תלוי בציון, אנשים מגינים על עצמם עם יעדים נמוכים שבטוח יושגו.","3":"אישור HR הוא לא העניין. הסיכון הוא פחד מכישלון, שמוביל ליעדים שמרניים ובלי חדשנות."},"6":{"0":"הכיוונים הפוכים: ב-Cascading היעדים יורדים מההנהלה, וב-Aligned הצוותים מגדירים OKRs בעצמם.","2":"ההבדל הוא בדרך קביעת היעדים, לא בגודל החברה: Cascading יורד מלמעלה ואיטי, Aligned מגיע מהצוותים.","3":"בשתי הגישות ה-OKRs גלויים. ההבדל הוא מי קובע את היעדים: ההנהלה או הצוותים עצמם."},"7":{"0":"ירוק מתחיל ב-0.7 ולא רק ב-1.0. ביעד Aspirational, ציון 0.7 כבר נחשב הצלחה מלאה.","2":"כל KR מקבל ציון בסולם 0.0 עד 1.0, לא בכוכבים, וירוק מתחיל ב-0.7.","3":"הסולם הוא 0.0 עד 1.0, והירוק מתחיל ב-0.7 ולא ב-80%. אדום הוא 0.0 עד 0.3, לא כל מה שמתחת לחצי."},"8":{"0":"הסדר הפוך: Grove פיתח את השיטה ב-Intel, ו-Doerr, שהצטרף ל-Intel ב-1974, למד אותה ממנו.","2":"Drucker טבע את MBO בשנות ה-50. מי ששדרג אותו ב-Intel לשיטה ש-Doerr הביא ל-Google היה Grove.","3":"Page ו-Brin אימצו את השיטה כש-Doerr הציג אותה ב-Google ב-1999. המקור שלה הוא Grove ב-Intel."},"9":{"0":"המטרה של השקיפות היא יישור קו ולא יריבות: רואים חפיפות ואיך העבודה של כל צוות מתחברת.","2":"פחד מכישלון הוא בדיוק מה שהשיטה מנסה להימנע ממנו: הוא דוחף ליעדים בטוחים במקום שאפתניים.","3":"דיווח למשקיעים הוא לא הסיבה. השקיפות מאפשרת לכל עובד לראות איך העבודה שלו תורמת למטרה הגדולה."},"10":{"0":"כאן הם מוחלפים: ה-Objective הוא הכיוון האיכותי, וה-Key Result הוא המספר שמראה שהגענו.","2":"משימות ופיצ׳רים הם Output. Key Result מודד תוצאה, למשל Activation שעולה מ-45% ל-60%.","3":"ה-KR לא מפרק את ה-Objective לדדליינים קטנים: הוא המדד הכמותי שבודק אם ה-Objective הושג."},"11":{"0":"OKRs הם מערכת חיה: ה-Check-in קיים כדי שאפשר יהיה לעדכן או לעצור KR שכבר לא רלוונטי.","2":"הורדת רף בשקט הורסת את הכנות שהשיטה נשענת עליה, והירוק כבר לא משקף את המציאות.","3":"KR אדום מחייב תחקיר, לא חיפוש אשמים, ואת ה-KR הזה עדיף לעצור בגלוי ולא להשאיר ככישלון."},"12":{"0":"מיקוד הוא אחת מארבע יכולות העל של השיטה: רק 3 עד 5 מטרות ו״לא״ מנומס לכל השאר.","2":"חשיפת עבודה כפולה היא חלק מיכולת ה-Align: יעדים גלויים לכולם חושפים חפיפות מוקדם.","3":"את זה OKRs כן נותנים: Key Results טובים מודדים Outcome, לא כמות פיצ׳רים ששוחררו."},"13":{"0":"יותר פיצ׳רים זה עדיין Output. עשר השקות לא מודדות טוב יותר מחמש אם החוויה השתפרה.","2":"ה-Objective אמור להיות איכותי. המספר שייך ל-Key Results, וכאן החולשה היא דווקא ב-KR.","3":"אחוז מהפיצ׳רים המתוכננים הוא עדיין Output: אפשר להשיק 80% מהתוכנית והחוויה לא תשתנה."},"14":{"0":"Stretch Goal דורש חשיבה יצירתית, לא רק עבודה קשה. שעות נוספות הן עוד מאותו דבר, לא גישה חדשה.","2":"המתיחה היא בשאפתנות של היעד, לא בתקציב: מכוונים גבוה מספיק כדי לחייב חשיבה חדשה.","3":"Stretch Goal נקבע שאפתני כבר מההתחלה, כך שציון של 60-70% נחשב אידיאלי. לא מרחיבים יעד תוך כדי."}},"113":{"0":{"0":"Flow ו-Transactive Memory הם כלים שהספר בונה על גבי המאיצים, לא מאיצים בעצמם. חסרים כאן Resonance ו-Safe Place.","2":"אף אחד מאלה אינו מאיץ של Click: המאיצים הם תנאים שיוצרים חיבור, כמו קרבה ומקום בטוח, לא תוצאות צוותיות.","3":"כריזמה והומור הן תכונות אישיות. לפי הספר כימיה אינה משהו שיש או אין, אלא תוצר של תנאים שכל אחד יכול ליצור."},"1":{"0":"פגיעות עובדת דרך אמון, לא רחמים: חשיפת חולשה מאותתת אמון ומזמינה את הצד השני להיפתח גם הוא.","2":"המנגנון הוא אמון והדדיות, לא ענווה: הצד השני נפתח בחזרה, ולא רק מפסיק להתחרות.","3":"הורדת ציפיות היא לא העניין. פגיעות מאותתת אמון, ומנהלים שמודים בטעויות נתפסים כאמינים יותר."},"2":{"0":"רקע משותף כמו אותה עיר הוא דמיון שטחי. Quick-Set Intimacy דורש חשיפה מוקדמת, מקום בטוח וחוויה אינטנסיבית משותפת.","2":"שיקוף לא מופיע במתכון. קרבה מהירה נוצרת מחשיפה הדדית והולכת ומעמיקה, בסביבה בטוחה ובחוויה אינטנסיבית.","3":"חשיפה אחת בלי קשר לסביבה מדלגת על המקום הבטוח, והקיצור שהשלב מתאר הוא חשיפה הדדית שהולכת ומעמיקה."},"3":{"0":"אף אחד לא צריך ללמוד את כל התחומים: היעילות באה מכך שכל אחד יודע מי יודע מה, בלי כפילות בידע.","2":"Transactive Memory הוא מבוזר ולא מרוכז: הידע נשאר אצל כל מומחה, וכולם יודעים את מי לשאול.","3":"המושג עוסק בידע, לא ברגשות משותפים: כל חבר צוות יודע במה האחרים מומחים."},"4":{"0":"דוחות ולוחות משתפים מידע, אבל לא יוצרים קרבה. Proximity נוצרת מראיית פנים ומשיחות לא-פורמליות.","2":"מפגש פעם בשנה הוא לא Proximity: קרבה נבנית ממגע קבוע, כמו Stand-up יומי וערוצים פתוחים.","3":"פחות מגע הוא פחות קרבה. בצוות Remote צריך ליצור קרבה במכוון, לא לצמצם אותה."},"5":{"0":"Flow עוסק במעורבות עמוקה, לא במהירות: הזמן נעלם כי שני הצדדים מקשיבים באמת, לא כי אין הפסקות.","2":"הימנעות מהבעת דעה הופכת את השיחה לחד-צדדית. Flow דורש מעורבות הדדית, ששני הצדדים בונים זה על דברי זה.","3":"הימנעות ממחלוקות היא לא Flow. מדובר בריכוז מלא ובמעורבות הדדית, לא בשמירה על אווירה קלילה."},"6":{"0":"מקום בטוח לא מחליף את שאר המאיצים: הוא מה שמאפשר פגיעות, והמאיצים פועלים יחד כמערכת.","2":"הסדר הפוך: המקום הבטוח בא קודם ומאפשר פגיעות, ולא הפגיעות היא שיוצרת אותו.","3":"מקום בטוח פירושו שמותר לטעות, לשאול ולהיות אמיתיים, לא שאין מחלוקות. תפקידו לאפשר פגיעות."},"7":{"0":"פגיעות כאן היא הודאה בחוסר ודאות לגבי הפתרון, לא סיפור אישי שאינו קשור כדי לעורר רחמים.","2":"המטרה היא לא דירוג עדין. ה-PM נפתח כדי לשמוע כאבים אמיתיים, לא תשובות מנומסות.","3":"חזון מלוטש שמבקשים לאשר מזמין הסכמה מנומסת. דווקא הודאה בחוסר ודאות היא שגורמת למשתמש להיפתח."},"8":{"0":"אותם מוסדות ואותן ערים הם דמיון שטחי. הספר מצביע על דמיון עמוק: ערכים משותפים וחוויות מעצבות.","2":"דמיון בכישורים הוא לא הדמיון שהספר מתכוון אליו. ה-PM מבליט ערכים שכבר משותפים לצוות, ולא מגייס אנשים זהים.","3":"הבלטת ערכים משותפים אינה Groupthink: לפי השלב זה בסיס משותף לעבודה יחד, שמחזק את הכימיה."},"9":{"0":"הספר טוען את ההפך: כימיה אינה משהו שיש או אין, אלא משהו שבונים.","2":"המאיצים דורשים מעורבות אישית: להודות, להיות נוכחים ולהקשיב. תפקידים וטקסים לבדם לא יוצרים קליק.","3":"לחכות לקליק בשיחה הראשונה מפספס את הרעיון: PM יוצר את התנאים לחיבור, לא מחכה שיקרה מעצמו."},"10":{"0":"רמה 3 היא המקום שבו החיבור מתחיל, לא שבו השיחה נתקעת, ואין צורך לקפוץ ישר לשיא.","2":"רגשות ברמה 4 מעמיקים את החיבור. חזרה לעובדות ניטרליות מחזירה את השיחה לרמות 1-2, שבהן לא נוצר קשר.","3":"עוד עובדות רקע נשארות ברמה 2. קשר אמיתי מתחיל רק כשמישהו משתף דעה או רגש, מרמה 3 ומעלה."},"11":{"0":"הספר דווקא ממליץ ליצור את התנאים במכוון. הסכנה היא פגיעות מבוימת, לא עצם התכנון.","2":"השלב אומר את ההפך: מנהלים שמודים בטעויות נתפסים כאמינים יותר, לא פחות.","3":"המאיצים פועלים כמערכת: מאיץ אחד נותן אפקט, כמה יחד נותנים קליק. בחירה במאיץ יחיד מחלישה את התוצאה."},"12":{"0":"Brafman שם קשרים קודם: Proximity ו-Transactive Memory דורשים זמן, והישג מהיר לא בונה אותם.","2":"תיקון תהליכים מיד מדלג על ההיכרות עם האנשים. מקום בטוח נבנה דרך קשרים, לא דרך מיפוי תהליכים.","3":"דשבורדים לא מראים מי יודע מה. Michal למדה את זה בשיחת היכרות עם כל אחד מחברי הצוות."},"13":{"0":"לענות על כל סיפור בסיפור משלכם מסיט את המוקד אליכם. Resonance היא הקשבה מלאה, לא חשיפה בתורות.","2":"Resonance היא נוכחות, לא הסכמה: אפשר להקשיב באמת בלי לתקף כל דעה ששומעים.","3":"תדירות פגישות אינה Resonance, ושום דבר לא מחליף הקשבה עמוקה: מדובר בנוכחות מלאה ברגע."},"14":{"0":"לא צריך הכשרה מיוחדת: זה מתחיל בהודאה בטעות או בבקשת עזרה. המחסום הוא אומץ, לא ידע.","2":"פגיעות היא קיצור דרך, לא תהליך ארוך: הודאה אחת של Michal בטעות שברה את השתיקה ברטרו.","3":"השלב לא מגביל את המאיץ לתרבות מסוימת. הקושי הוא הסיכון התרבותי שבתפיסה ש״מנהלים לא מודים בחולשה״."}},"114":{"0":{"0":"RICE לא נמצא במרכז השלב. העץ של Torres משווה בין דרכים להגיע ל-Outcome, במקום לדרג פיצ׳רים אחד-אחד.","2":"Gantt מתזמן משימות שכבר הוחלט עליהן. הכלי המרכזי של Torres שואל אילו הזדמנויות ופתרונות יובילו ל-Outcome.","3":"Torres משתמשת במפת חוויה כדי ליישר את הטריו לפני הראיונות, אבל זה כלי משני ולא הכלי המרכזי של הספר."},"1":{"0":"הטריו אינו הנהלה בכירה: זה צוות המוצר עצמו, השלושה שמובילים יחד את הגילוי ואת הראיונות.","2":"הטריו הוא הצוות שעושה את הגילוי, לא הלקוחות שמרואיינים. שלושתם משתתפים באותם ראיונות.","3":"הטריו הוא אנשים, לא שיטות מחקר: מוצר, עיצוב והנדסה יושבים יחד באותו ראיון."},"2":{"0":"סבב מחקר פעם ברבעון הוא בדיוק גישת הפרויקט ש-Torres מתרחקת ממנה. היא מבקשת מגע שבועי.","2":"ראיונות רק כשמתכננים פיצ׳ר הם תיקוף של פתרון שכבר נבחר. Torres מבקשת הרגל שבועי קבוע בלי קשר לפיצ׳ר.","3":"פעם בחודש זה נדיר מדי: Torres מבקשת לפחות נקודת מגע אחת עם לקוח בכל שבוע, כהרגל קבוע."},"3":{"0":"אלה ארבע הרמות של ה-OST, לא סוגי הנחות. הנחות עוסקות בשאלה אם פתרון מסוים יעבוד.","2":"Scalability ו-Urgency אינם ברשימה של Torres. מלבד הארבעה המוכרים היא מוסיפה Ethical: האם זה עלול להזיק?","3":"אלה שיקולים לבחירת הזדמנות, כמו כמה פעמים עלתה וכמה היא כואבת, לא הנחות על פתרון."},"4":{"0":"Snapshot הוא סיכום כתוב בדף אחד, לא פריים מההקלטה: ציטוט, סקיצה של מפת החוויה, הזדמנויות והפתעות.","2":"ה-Snapshot נכתב אחרי הראיון, לא נשלח לפניו. הוא הופך כל שיחה לדף בארכיון חי של הצוות.","3":"תמלול מלא הוא ההפך מ-Snapshot: הרעיון הוא דף אחד שהצוות באמת משתמש בו, לא טקסט גולמי."},"5":{"0":"השלב לא מנמק את ההשוואה במובהקות סטטיסטית. היא נועדה לרסן הטיות ולחשוף העדפות אמיתיות.","2":"השוואה לא מחליפה מיפוי הנחות: שניהם חוליות באותה שרשרת, וקודם ממפים הנחות ואז בודקים.","3":"מהירות הבנייה אינה העניין. ההשוואה הופכת ״כן או לא״ ל״מה הכי מבטיח״, כך שהראיות בוחרות את המנצח."},"6":{"0":"Torres שמה את הגילוי בידי הטריו: מוצר, עיצוב והנדסה מראיינים יחד, לא צוות מחקר נפרד.","2":"תיקוף של פתרון שנבחר הוא מה ש-Torres נמנעת ממנו: היא מתחילה מצורכי הלקוח ומשווה כמה פתרונות.","3":"ספרינט רבעוני הוא עדיין פרויקט עם התחלה וסוף. Torres מבקשת הרגל שבועי שרץ במקביל לפיתוח."},"7":{"0":"Torres מצפה לכמה פתרונות לכל הזדמנות ומשווה ביניהם. היא לא מניחה שיש פתרון נכון אחד.","2":"פיצ׳ר שלקוח מבקש הוא לעתים פתרון בתחפושת: ״צריך דשבורד״ הוא פתרון, וההזדמנות היא הצורך שמאחוריו.","3":"גם אחרי שבוחרים הזדמנות, פתרונות צריכים בדיקות הנחות: בחירת ההזדמנות לא מוכיחה שפתרון כלשהו יעבוד."},"8":{"0":"גם פיצ׳ר של מנהל בכיר עולה על העץ: Michal בדקה בקשה כזו עם חמישה לקוחות במקום לבנות אותה מיד.","2":"התשובה של Torres למחסור במשאבים היא הרגל קטן וזול, פחות משלוש שעות בשבוע, לא ויתור על הגילוי.","3":"גם מוצר שכבר הושק משנה התנהגות משתמשים, וכל מה שנוגע בחוויית המשתמש מצדיק Discovery."},"9":{"0":"ה-Engineer שותף לגילוי מההתחלה ומשתתף בראיונות, לא רק מעריך מאמץ אחרי שה-PM החליט.","2":"Usability אינה העדשה של ה-Engineer: הוא מביא את הזווית הטכנית ובודק אם אפשר לבנות את הפתרון.","3":"Viability, השאלה אם זה עובד לעסק, אינה העדשה של ה-Engineer. הוא בודק אם אפשר לבנות את זה."},"10":{"0":"זה תיאור של Roadmap עם פיצ׳רים ותאריכים. ה-OST מתחיל מ-Outcome רצוי וממפה צרכים לפני פתרונות.","2":"התחלה מבקשות לקוחות מדלגת על רמת ההזדמנויות: בקשה היא לעתים קרובות פתרון בתחפושת.","3":"הכיוון הפוך: העץ מתחיל ב-Outcome ויורד להזדמנויות ולפתרונות, לא עולה מפתרון שכבר נבחר."},"11":{"0":"נטישה היא Business Outcome, מדד מאחר שמושפע מגורמים רבים מחוץ להשפעת הטריו, ולכן זה יעד צוותי גרוע.","2":"Traction Metric כמו קליקים על כפתור אחד צר מדי ליעד צוותי ולא משאיר מקום ליצירתיות.","3":"שחרור פיצ׳רים הוא Output, לא Outcome: הטריו יכול להגיע לקו הסיום בזמן שהנטישה לא זזה."},"12":{"0":"העברת הראיונות לצוות אחר שוברת את ההרגל: הטריו עצמו צריך להחזיק מגע שבועי וישיר עם לקוחות.","2":"ריכוז הראיונות פעם ברבעון מחזיר את הגילוי למצב של פרויקט. הרעיון הוא מגע שבועי ושוטף.","3":"Power Users מחמיאים. משתמשים שנטשו, מהססים ולקוחות של מתחרה מלמדים הכי הרבה, ולכן חשוב גיוון."},"13":{"0":"שאלה מה לבנות אוספת דעות. אנשים מנבאים רע את ההתנהגות של עצמם, ולכן התשובות מטעות.","2":"״הייתם משתמשים?״ היא השערה על העתיד. בגלל ה-Say-Do Gap תשובות כאלה נשמעות טוב ומטעות.","3":"דירוג 1 עד 10 הוא עדיין דעה. הוא לא חושף הקשר, רגש ומעקפים, שמהם נולדות הזדמנויות."},"14":{"0":"פתרון יחיד לכל הזדמנות מדלג על מה ש-Torres מדגישה: לבחור הזדמנות מטרה אחת ולהשוות לה כמה פתרונות.","2":"בניית פתרון לכל 8 ההזדמנויות מפזרת את הצוות ומוותרת על השוואה בין פתרונות לאותה הזדמנות.","3":"הצבעה על פיצ׳רים נשענת על בקשות, שהן לעתים פתרון בתחפושת. את ההזדמנות בוחר הטריו לפי ראיות מהראיונות."}},"115":{"0":{"0":"הטענה של הספר הפוכה: יש יותר מדי פירוט של פיצ׳רים ותאריכים, שהופך להתחייבות, לא פחות מדי.","2":"עוד פיצ׳רים רק יעמיקו את הבעיה: רשימת פיצ׳רים מתמקדת ב-Output ומאבדת את ה״למה״.","3":"הספר דווקא ממליץ על קצב עדכון קבוע: שבועי, חודשי ורבעוני. Roadmap שלא מתעדכן הופך למוצג מוזיאוני."},"1":{"0":"קיבוץ לפי אזור מוצר הוא עדיין רשימת פיצ׳רים. Theme מתאר מטרה או בעיה, כמו שיפור שיתוף הפעולה בצוות.","2":"בקשות של לקוחות מפתח הן עדיין פיצ׳רים, ו-Roadmap שבקשות מנהלות אותו הוא ה-Anti-Pattern של Sales-Driven.","3":"איגוד פיצ׳רים להשקות הוא שאלה של תזמון שחרור. Theme מחליף פיצ׳רים ספציפיים במטרה אסטרטגית."},"2":{"0":"האופקים בכוונה לא קשורים לרבעונים מסוימים: הם מראים כמה הצוות בטוח, לא תאריכים בלוח השנה.","2":"האופקים מתארים ודאות, לא צוותים. אותו צוות עובד על Now ומתכנן את Next ואת Later.","3":"האופקים עוסקים בזמן ובוודאות, לא בסוגי לקוחות. כל אופק מתויג ברמת ביטחון גבוהה, בינונית או נמוכה."},"3":{"0":"לקוחות צריכים לקבל נושאים כלליים ו-Disclaimer, לא הבטחות, וגם בגרסה למכירות אין תאריכים.","2":"ההתאמה לקהל אינה עניין של סודיות: לקוחות רואים מה בדרך, מנוסח כבעיות שנפתרות, לא רק מה שכבר הושק.","3":"הגרסאות נבדלות במה שחשוב לכל קהל, לא בקצב הסקירה: אסטרטגיה, פירוט או כיוון כללי."},"4":{"0":"תוצאות הן לא רק כספיות: מדובר בשינוי אצל הלקוח, כמו העלאת שיעור ה-Activation.","2":"Roadmap מבוסס תוצאות קובע יעדים מראש. הוא לא מחכה לתוצאות מוכחות כדי להתעדכן.","3":"הוא נבנה מראש כתוכנית של תוצאות רצויות, לא נכתב בדיעבד על סמך מה שכבר נבנה."},"5":{"0":"עבודה עם המכירות היא לגיטימית: תובנות מהמכירות ומ-CS הן קלט חשוב. הבעיה היא כשכל בקשה נכנסת בלי סינון.","2":"הצגת יעדי מכירות היא לא הבעיה. ה-Anti-Pattern הוא שכל עסקה או בקשה רועשת הופכת לפריט ב-Roadmap.","3":"זה תיאור של ההפך. ב-Sales-Driven Roadmap יש יותר מדי בקשות לקוחות, לא פחות מדי."},"6":{"0":"פעם בשנה זה נדיר מדי: Roadmap שלא מתעדכן הופך למוצג מוזיאוני בתוך שבועות.","2":"המתנה לשינוי דרמטי משאירה את ה-Roadmap מיושן. הספר רוצה קצב קבוע, לא עדכון רק במשבר.","3":"עדכון יומי אינו הקצב שהספר מציע: מעבר קצר שבועי על Now, ובתדירות נמוכה יותר על Next ו-Later."},"7":{"0":"רמת ביטחון אומרת כמה פריט ודאי, לא כמה תקציב הוא מקבל.","2":"רמות ביטחון מתארות ודאות, לא בעלות. הן אומרות לקהל עד כמה סביר שפריט ישתנה.","3":"תיוג הביטחון נועד לניהול ציפיות: הוא מסמן מה עלול להשתנות. הוא לא דירוג שקובע את סדר הבנייה."},"8":{"0":"תאריכי שחרור מדויקים שייכים לתוכנית השחרורים, לא ל-Roadmap. ה-Roadmap עונה לאן הולכים ולמה.","2":"כאן הם הפוכים: ה-Backlog מחזיק משימות לספרינטים הקרובים, וה-Roadmap הוא הכיוון לטווח ארוך.","3":"גם כאן ההפך: ה-Backlog הוא רשימת העבודה המפורטת, לא סיכום להנהלה, וה-Roadmap הוא התמונה הרחבה."},"9":{"0":"תאריך אופטימי שנדחה הופך להבטחה שהופרה. הלקוח של Michal נופף בשקף כאילו היה חוזה חתום.","2":"סירוב משאיר את הלקוח בלי כלום. Now/Next/Later עם רמת ביטחון נותן תשובה כנה בלי להתחייב לתאריך.","3":"הפניה לצוות הפיתוח מתחמקת מהשאלה. ה-PM יכול לענות בכנות דרך Now/Next/Later ורמת ביטחון."},"10":{"0":"חשיפה ראשונה של Roadmap בפורום מלא היא הטעות הקלאסית: כל ההתנגדויות עולות שם, בשידור חי.","2":"אישור מלמעלה מדלג על בעלי העניין. Shuttle Diplomacy בונה תמיכה אצל כל אחד מהם לפני הפגישה.","3":"בנייה סביב הבקשות הנפוצות נותנת לבקשות, ולא לאסטרטגיה, לקבוע את ה-Roadmap."},"11":{"0":"הקהלים בספר הם מי שפועל לפי ה-Roadmap ביום-יום. עיתונות ושותפים אינם בין ארבעת הקהלים שהספר מונה.","2":"זה הופך את ה-Roadmap למסמך תקציב ודדליינים. תאריכים מדויקים שייכים לתוכנית השחרורים, לא ל-Roadmap.","3":"כל אלה תפקידים בתוך צוות המוצר. בין ארבעת הקהלים בספר נמצאים גם המכירות וה-CS, וגם הלקוחות."},"12":{"0":"פיצול לשתי רשימות שומר על אותו דיוק מדומה. הבעיה היא פירוט לשנה קדימה, לא מספר הפריטים במסמך.","2":"הוספת תאריכים מחייבים מחמירה את הבעיה: תאריכים מדויקים לא שייכים ל-Roadmap והופכים להתחייבות נוקשה.","3":"דירוג לא פותר את זה: רשימה מדורגת של 30 פיצ׳רים היא עדיין רשימת פיצ׳רים שתישבר כשהמציאות תשתנה."},"13":{"0":"תאריכי שחרור מדויקים נמצאים במפורש בקבוצת ה״בחוץ״: מקומם בתוכנית השחרורים, לא ב-Roadmap.","2":"גם ה-Backlog המלא נמצא בחוץ: מקומו בכלי הפיתוח, לא ב-Roadmap.","3":"פירוט ברמת משימה נמצא בחוץ: משימות שייכות לתוכנית השחרורים ולכלי הפיתוח, לא לליבת ה-Roadmap."},"14":{"0":"Dual Track אינו הפרדה בין באגים לפיצ׳רים: הוא מפריד בין חקירה של מה לבנות לבין הבנייה עצמה.","2":"Dual Track אינו פנימי מול חיצוני. גרסאות לקהלים נגזרות ממקור אמת אחד, לא מ-Roadmap סודי.","3":"החלוקה אינה לפי פלטפורמות: Dual Track מריץ Discovery ו-Delivery במקביל, וכל אחד מזין את השני."}},"116":{"0":{"0":"ערבוב פריטים טכניים ועסקיים אינו הטענה של Patton: כל פריט יכול להיות הגיוני, אבל הרשימה לא מראה מסע.","2":"מיון טוב יותר עדיין ישאיר רשימה חד-ממדית. מה שחסר הוא הקשר: איפה כל Story יושבת במסע המשתמש.","3":"קריטריונים מפורטים יותר לכל Story לא יראו את המסע. הבעיה היא היעדר ממד שני, לא חוסר בפירוט."},"1":{"0":"ה-Backbone עוסק בפעילויות המשתמש, לא בבאגים: הצעדים הגדולים שהמשתמש עושה, כמו חיפוש, צפייה ותשלום.","2":"הציר האנכי הוא עומק: פרטים, וריאציות ומקרי קצה מתחת לכל פעילות. ה-Backbone הוא השורה העליונה.","3":"בעלי עניין לא מופיעים על המפה. ה-Backbone הוא שורת הפעילויות הגדולות של המשתמש, לפי סדר התרחשותן."},"2":{"0":"Walking Skeleton באמת עובד: המשתמש משלים את כל המסע, גם אם בצורה גסה. פרוטוטייפ עיצובי בלבד לא ״הולך״.","2":"זו פרוסה עובדת של המוצר, לא מסמך דרישות: החיתוך הדק ביותר שחוצה את כל ה-Backbone.","3":"זה תיאור של פרסונה. Walking Skeleton הוא גרסה עובדת מינימלית שמאפשרת לסיים את המסע מקצה לקצה."},"3":{"0":"אלה אילוצי תכנון, לא ה-Cs של Patton. שלושת ה-Cs שלו עוסקים באופן שבו Story מסופרת, נדונה ומאושרת.","2":"זה ניתוח אסטרטגי, לא עניין של User Stories. ה-Cs ש-Patton מאמץ מגיעים מעולם ה-XP ומתארים את חיי ה-Story.","3":"אלה שלבי עבודה על פריט. ה-Cs של Patton מדגישים שהכרטיס רק מזמין שיחה, והשיחה היא העיקר."},"4":{"0":"הכרטיס אינו חסר ערך: הוא מתעד ומזמין שיחה. הנקודה היא שהוא לא יכול להחליף את השיחה.","2":"מקום על הכרטיס אינו הבעיה: גם מסמך מושלם שאף אחד לא דן בו יוצר רק אשליה של הבנה.","3":"השיחה לא נועדה לתאריכים או להתחייבויות. היא נועדה לכך שכולם יבינו את אותו דבר לגבי ה-Story."},"5":{"0":"חיתוך לפי צוותים בונה חלקים נפרדים שמתחברים רק בסוף. רצועת Release מספקת מסע שלם כבר עכשיו.","2":"בחירת ה-Stories עם הציון הגבוה אחת-אחת בונה מגדלים, לא רצועות: אפשר לקבל עגלה מפוארת בלי דרך לשלם.","3":"חיתוך לפי זמן מוערך מתעלם מהמסע. כל Release צריך לחצות את כל הפעילויות ב-Backbone."},"6":{"0":"חלוקת העבודה מפספסת את העיקר: הערך הוא בבנייה משותפת, כך שכולם מבינים את כל המסע.","2":"להרשים את ההנהלה אינו המטרה. הפלט האמיתי הוא הבנה משותפת, שמשפרת את החלטות היומיום.","3":"הבנה של החלק שלכם בלבד היא בדיוק מה שהולך לאיבוד: כשכולם מכירים את כל המסע, ההחלטות משתפרות."},"7":{"0":"אף אחת מהמפות אינה למשקיעים או מסד נתונים: Big Picture משרתת תכנון אסטרטגי ו-Releases, ו-Detailed משרתת ספרינטים.","2":"אלה שתי רמות זום: קודם מתרחקים לכל המוצר, ורק אז מתקרבים ל-Flow שבונים עכשיו.","3":"בשתי המפות יש Stories. ה-Big Picture מציג את הפעילויות הגדולות, וה-Detailed מוסיף מקרי קצה וקריטריוני קבלה."},"8":{"0":"המפה לא מחליפה את הטקס: ב-Sprint Planning הצוות עדיין בוחר Stories, רק עכשיו עם ההקשר שלהן.","2":"המפה נותנת הקשר ואת הרצועה הבאה, היא לא קובעת מראש כמה ספרינטים יידרשו לכל ה-Releases.","3":"המפה לא משבצת אנשים: היא מראה איפה כל Story נמצאת במסע, והצוות עדיין מחליט מי עושה מה."},"9":{"0":"המפה אמורה להשתנות: מפה שלא זזה היא תפאורה. העדכונים אינם הסיבה שהיא לא הפלט העיקרי.","2":"מפה חיה כן מנחה עבודה, בתכנון, ב-Refinement וב-Review. הנקודה היא שהבנייה המשותפת חשובה ממנה.","3":"Patton לא מעמיד את ה-Backlog מעל המפה. הוא אומר שהשיחה שבונה את המפה חשובה יותר מהתוצר."},"10":{"0":"זה תהליך פיתוח כללי עם שערי אישור, לא שלבי מיפוי. השלבים של Patton מתחילים במסגור הבעיה.","2":"אלה שלבי ניהול ספרינט. המיפוי בא לפני כן: קודם ממסגרים את הבעיה ופורשים את התמונה הגדולה.","3":"זה מודל של תהליך עיצוב, לא שלבי המיפוי של Patton, שמתחילים במסגור הבעיה ובתמונה הגדולה."},"11":{"0":"המפה עצמה מעלה שאלות תוך כדי הבנייה, למשל מה קורה כשעובד שוכח לדווח שבוע שלם. היא לא רשימת שאלות.","2":"מיפוי לא מחליף מחקר: אחד השלבים שלו הוא לתקף את המפה מול משתמשים אמיתיים ולספר להם את הסיפור.","3":"Story Mapping אינו כלי אנליטיקס. הגילוי בא מהשיחה בצוות, שחושפת פערים והנחות סמויות."},"12":{"0":"Patton מאפשר את שניהם: קיר פיזי או לוח דיגיטלי משותף. הכלי פחות חשוב מהבנייה המשותפת.","2":"השלב לא קובע מגבלת Stories. האזהרה היא מפירוט של הכול מראש: עומק רק איפה שבונים עכשיו.","3":"הזמנת QA ומעצבים מומלצת ולא טעות: כל הדיסציפלינות צריכות להיות בחדר."},"13":{"0":"כל מה שהתבקש הוא ההפך ממינימום. Patton שואל מה המשתמש צריך להשיג, לא כמה פיצ׳רים נכנסים ל-Release.","2":"פיצ׳ר אחד לעומק הוא מגדל, לא רצועה: מסע שנקטע אינו מסע, גם אם חלק אחד מלוטש.","3":"העתקת מתחרה היא חשיבת Output. MVP הוא הפרוסה הקטנה ביותר שנותנת ערך שלם לאורך כל ה-Backbone."},"14":{"0":"ה-Stories לא מפורטות מראש: עומק מוסיפים רק איפה שבונים עכשיו, וה-Refinement הוא המקום לכך.","2":"הציר האנכי מראה עומק, לא עדיפות. פרטים ווריאציות נמצאים למטה, לא Stories פחות חשובות.","3":"ה-Refinement נשאר: זו הישיבה שבה הצוות מפרק כרטיסים, ועם מפה מעדכנים בה גם את המפה."}},"117":{"0":{"0":"עלות היא לא ההבחנה. Output הוא מה ששוחרר, ו-Outcome הוא שינוי ההתנהגות שהוא גורם.","2":"Outcome כן מדיד: 70% מהנרשמים שמשלימים הגדרה ראשונה הוא מספר. מדידות היא קריטריון של Outcome טוב.","3":"שניהם חשובים לכל הצוות. ההבדל הוא בין מה שנבנה לבין השינוי בהתנהגות של אנשים."},"1":{"0":"עלות ו-ROI שואלים על ההשקעה, לא על אנשים. שאלת הקסם מתחילה באיזו התנהגות תשתנה.","2":"העתקה ממתחרים היא מלכודת ה-Feature Parity. השאלה היא איזו התנהגות זה ישנה אצלנו.","3":"עמידה בלוח הזמנים היא ה-Roadmap Trap: חוגגים תאריכים במקום יעדי התנהגות."},"2":{"0":"לשניהם יש תפקיד: Lagging כמו הכנסות מסכמים את התוצאה. היתרון של Leading הוא שהם משאירים זמן לפעול.","2":"ההבדל הוא בתזמון האות, לא בטווח: מדד Leading זז מוקדם, ומדד Lagging זז רק בדיעבד.","3":"שני הסוגים הם מספרים: שימוש שבועי הוא Leading, הכנסות הן Lagging, ושניהם כמותיים."},"3":{"0":"חדשנות, מראה ועלות לא אומרים דבר על התנהגות. Outcome טוב מתאר שינוי מדיד במה שאנשים עושים.","2":"אישור פורמלי לא הופך Outcome לטוב. הוא צריך להיות מדיד, בהשפעת הצוות, התנהגותי ומחובר לערך עסקי.","3":"השלב לא מגביל לספרינט אחד: Outcomes מופיעים לפי רבעון, כמו Activation מ-30% ל-50%."},"4":{"0":"המלכודת אינה איטיות: ה-Velocity גבוה והגרפים ירוקים, אבל אף אחד לא בודק אם משתמשים בפיצ׳רים.","2":"שינויי כיוון אינם המלכודת. Velocity Trap הוא לחגוג נקודות שנסגרו במקום שינוי אצל המשתמש.","3":"ישיבות אינן העניין. המלכודת היא למדוד מהירות ייצור במקום את השינוי שנוצר אצל המשתמשים."},"5":{"0":"שכבות טכנולוגיה קושרות צוות לחלק מהמערכת, לא לתוצאה. Seiden נותן לכל צוות יעד התנהגותי.","2":"פרויקטים עם תאריכים קבועים מתחייבים לפתרון. Seiden מחייב צוותים לתוצאה ונותן להם לבחור את הדרך.","3":"מחלקות מתארות היררכיה, לא תוצאות. Seiden קורא לצוותים לפי Outcome, כמו ״צוות האקטיבציה״."},"6":{"0":"Output הוא האמצעי, לא העבודה: לשחרר הכול בלי שהתנהגות זזה זה בדיוק הסיפור שפותח את הספר.","2":"בקשה של ה-CEO אינה הקריטריון. Output חשוב בפני עצמו בחוב טכני, ברגולציה ובתשתית שמאפשרת המשך.","3":"Seiden לא אומר ״אף פעם״: חוב טכני, רגולציה ותשתית שמאפשרת Outcomes עתידיים הם חריגים מוכרים."},"7":{"0":"אלה שני שלבים נפרדים בסולם: Outcome הוא התנהגות שהצוות מזיז ישירות, Impact הוא תוצאה רחבה שהוא רק תורם לה.","2":"Impact אינו מדד טכני. זו התוצאה העסקית הרחבה: הכנסות, רווחיות ונתח שוק.","3":"Output הוא השלב התחתון בסולם ו-Impact העליון: מה ששוחרר מול התוצאה העסקית הרחבה."},"8":{"0":"ההבדל הוא במה שמופיע בו, לא בטווח: רשימת Outcomes לכל רבעון במקום רשימת פיצ׳רים עם תאריכים.","2":"יש לו מסגרת זמן, Outcomes לפי רבעון. הצוות מתחייב לתוצאה, לא לפתרון מסוים.","3":"הוא מנחה את הצוותים עצמם: כל צוות מקבל יעד התנהגותי ובוחר את הדרך שלו להגיע אליו."},"9":{"0":"ה-Build Trap אינו עניין של QA. זו מדידת הצלחה לפי כמות התוצרים במקום לפי הערך שנוצר.","2":"ריבוי MVPs במקביל אינו ההגדרה. המלכודת היא מרוץ פיצ׳רים שבו אף אחד לא שואל מה השתנה.","3":"פיתוח איטי אינו המלכודת. הסימן שלה הוא שמשחררים הרבה ואף אחד לא יודע לומר איזו תוצאה עסקית זזה."},"10":{"0":"Feature Parity עוסק במתחרים, לא בתיאום פנימי: ״למתחרה יש, אז גם לנו חייב להיות״.","2":"המלכודת אינה שפיצ׳רים נראים דומים. היא העתקה ממתחרה בלי לשאול איזו התנהגות זה ישנה.","3":"בקשה של הלקוח הגדול היא לחץ אחר. Feature Parity הוא העתקה ממתחרים בלי לבדוק השפעה על Outcome."},"11":{"0":"הם משתלבים: ה-Key Results הם Outcomes התנהגותיים. Seiden רק מזהיר מפני KRs שהם רשימת משימות.","2":"OKRs לא מחליפים את ה-Outcomes, הם נושאים אותם. השיטה עובדת רק כשה-Key Results הם שינויי התנהגות.","3":"Outputs שייכים ליוזמות, לא ל-Key Results. KRs שהם תוצרים הופכים את ה-OKRs לרשימת משימות."},"12":{"0":"תקציב, מתחרים ומספר מפתחים מדלגים על העיקר: איזו התנהגות תשתנה. בלי זה מוקדם מדי לבנות.","2":"אלה מסמכי תכנון, לא שאלות על התנהגות. חמש השאלות מתחילות מהשינוי האנושי.","3":"להתחיל ב״איזה פיצ׳ר נבנה״ זו חשיבת Output. השאלה הראשונה היא איזו התנהגות תשתנה."},"13":{"0":"חיסכון בכסף אינו הסיבה. צוות Outcome בוחר את הדרך שלו, מייל או תבנית מוכנה, כדי להזיז התנהגות.","2":"גבולות ברורים אינם העיקר. היתרון הוא חופש לנסות פתרונות שונים כדי להגיע ליעד התנהגותי אחד.","3":"דוחות להנהלה אינם הסיבה. צוות שקשור לתוצאה ולא לפיצ׳ר יכול להתנסות עד שההתנהגות זזה."},"14":{"0":"לשפה אין קשר לזה. Outcome גרוע הוא Output במסווה, לא מדיד, או Impact שמחוץ להשפעת הצוות.","2":"שאפתנות אינה המבחן. ״להגדיל הכנסות ב-30%״ שאפתני אבל גרוע: זה Impact שמחוץ לשליטת הצוות.","3":"Outcome טוב נמדד במספרים, כמו Task Completion מ-60% ל-80%. מדידות היא קריטריון מרכזי."}},"118":{"0":{"0":"אלה שלבי ניהול כלליים. הפירמידה מתחילה בשוק, מי הלקוח ומה הצרכים שלא נענים, ורק מעליהם המוצר.","2":"זה משפך צמיחה, לא הפירמידה. השכבות של Olsen מתחילות מלקוח המטרה ומהצרכים, לא מרכישת משתמשים.","3":"אלה שלבים של לולאת למידה, לא שכבות הפירמידה, שעולות מלקוח המטרה ועד חוויית המשתמש."},"1":{"0":"הכלי עוסק בצרכי הלקוח, לא בצוות או בקוד: כמה צורך חשוב לו וכמה הוא מרוצה מהפתרונות הקיימים.","2":"זה לא כלי תמחור. הוא ממפה כל צורך לפי חשיבות ושביעות רצון כדי למצוא צרכים שלא נענים.","3":"הוא מודד צרכים של לקוחות, לא שביעות רצון עובדים: חשיבות גבוהה עם שביעות רצון נמוכה מסמנת הזדמנות."},"2":{"0":"כמות המשלמים אינה המדד. השאלה היא איך משתמשים ירגישו אם לא יוכלו עוד להשתמש במוצר.","2":"NPS הוא מדד נאמנות נפרד. השלב מציג אותו כהשלמה ל-Must-Have Score, לא כתחליף.","3":"עמידה בזמנים של ה-Roadmap לא אומרת דבר על התאמה לשוק. הציון נשען על תשובות המשתמשים, לא על נתוני מסירה."},"3":{"0":"Kano מסווג לפי תגובת הלקוח, לא לפי מאמץ הפיתוח: האם פיצ׳ר צפוי, ליניארי או מפתיע.","2":"קלט, עיבוד ופלט מתארים מערכת, לא ערך ללקוח. Kano ממיין פיצ׳רים לפי האופן שבו לקוחות מגיבים להם.","3":"Kano לא עוסק באופקי זמן. הוא ממיין פיצ׳רים לפי סוג שביעות הרצון שהם יוצרים אצל הלקוח."},"4":{"0":"זה רצף מסירה כללי. התהליך של Olsen מתחיל במרחב הבעיה: קודם לקוח המטרה, אחר כך הצרכים שלא נענים.","2":"הרצף מתחיל במחקר ורעיונות במקום בלקוח ובצרכים, ומגיע לפיתוח מלא לפני שבודקים מול לקוחות.","3":"אלה שלבים כלליים. הצעדים של Olsen עולים בשכבות הפירמידה, מלקוח המטרה ועד אב-טיפוס שנבדק מול לקוחות."},"5":{"0":"ספרינט אחד אינו אות. Olsen מחפש ראיות שמצטברות לאורך כמה סיבובים, כמו Must-Have Score שנשאר נמוך.","2":"Velocity מודד את קצב הצוות, לא התאמה לשוק. אותות ל-Pivot מגיעים מהמשתמשים: Retention ו-Must-Have Score.","3":"כניסת מתחרה אינה ברשימה של Olsen. האותות עוסקים במשתמשים שלכם: ציון Must-Have נמוך ו-Retention שיורד."},"6":{"0":"ממשק מלוטש בהשקעה גדולה הוא ההפך: Wizard of Oz בודק אם הפתרון עובד בלי לבנות את הטכנולוגיה.","2":"אין מאחוריו אלגוריתם אמיתי: אדם עושה את העבודה מאחורי הווילון, בזמן שהלקוח חושב שהכול אוטומטי.","3":"No-Code היא שיטת בנייה. Wizard of Oz עוסק בהסתרת עבודה ידנית מאחורי ממשק שנראה אוטומטי."},"7":{"0":"עלות אינה הסיבה. השכבות התחתונות הן השוק: אם הלקוח או הצורך שגויים, שכבות עליונות מצוינות לא יצילו.","2":"הסדר לא נובע מנוחות הפידבק. השכבות העליונות נשענות על התחתונות, ובסיס חלש מפיל את כל מה שמעליו.","3":"משקיעים אינם הסיבה. בלי הלקוח והצורך הנכונים, שום סט פיצ׳רים או UX לא ייצרו התאמה."},"8":{"0":"עקומה שעולה כל הזמן אינה הדפוס: Retention יורד באופן טבעי בהתחלה, וההתאמה ניכרת כשהוא מתייצב.","2":"עקומה שממשיכה לרדת בלי להתייצב היא אות ל-Pivot ולא סימן להתאמה, גם אם הנטישה מאטה מעט.","3":"עליות וירידות שתלויות בקמפיינים לא מראות גרעין יציב. התאמה נראית כעקומה שמתייצבת ברמה חיובית."},"9":{"0":"הם לא סותרים: השלב מציג PMF חזק עם Early Adopters כתנאי מוקדם לחציית התהום.","2":"אף אחד לא מחליף את השני: Olsen עוסק בהשגת ההתאמה, וחציית התהום באה אחריה.","3":"יש ביניהם קשר ישיר: PMF עם Early Adopters הוא נקודת הפתיחה למעבר אל המיינסטרים."},"10":{"0":"זו לא חלוקה בין מחלקות. מרחב הבעיה הוא צורכי הלקוח, ומרחב הפתרון הוא כל מה שבונים.","2":"העניין אינו תזמון: האזהרה היא מפני קפיצה לפתרון לפני שמבינים את הבעיה, בכל שלב של המוצר.","3":"מרחב הבעיה אינו אקדמי: זה מה שהלקוח מנסה להשיג, בלי מילה על טכנולוגיה."},"11":{"0":"QA אינו הסיבה. לקוח מוגדר בצמצום מאפשר להבין צרכים ספציפיים ולבנות Value Proposition מדויק.","2":"משקיעים אינם הסיבה. מי שמכוון לכולם לא פוגע באף אחד: לקוח רחב מטשטש את הצעת הערך.","3":"המטרה אינה להגיע ליותר אנשים בזול. היא הצעת ערך חדה: מתחילים מנישה ומשרתים אותה בדיוק."},"12":{"0":"Delighter מוגדר לפי תגובת הלקוח, לא לפי עלות: פיצ׳ר לא צפוי שמלהיב כשהוא קיים.","2":"Kano עוסק בלקוח, לא בצוות הפנימי: Delighter מפתיע ומשמח את המשתמשים.","3":"כדאי לבנות Delighters, במידה: אחד מצוין יוצר אהבה. עם הזמן הם הופכים ל-Must-Have, לא נעלמים."},"13":{"0":"ב-Opportunity Score אין הכנסות או הסתברות: הוא משלב כמה צורך חשוב וכמה הלקוחות מרוצים ממנו.","2":"גודל שוק הוא שאלה אחרת. הציון מדרג צורכי לקוח לפי חשיבות ושביעות רצון נוכחית.","3":"הציון אינו ממוצע של מדדי שביעות רצון. החשיבות נספרת פעמיים, פחות שביעות הרצון, כדי לאתר צרכים שלא נענים."},"14":{"0":"הסיבה אינה עלות או גודל צוות: כל סיבוב מייצר למידה שעשויה להחזיר לשכבה קודמת בפירמידה.","2":"העדפת לקוחות לשחרור הדרגתי אינה הסיבה. האיטרציה קיימת כי הבדיקות משנות את ההנחות.","3":"Olsen לא רק מתאים את עצמו ל-Agile. הלולאה קיימת כי כל בדיקה חושפת מידע שמשנה שכבות קודמות."}},"119":{"0":{"0":"התהום עוסקת בקונים, לא בארכיטקטורה: הפער בין ה-Visionaries ל-Pragmatists במחזור האימוץ.","2":"B2B מול B2C אינו הפער. התהום נמצאת בין שתי קבוצות קונים: Early Adopters ו-Early Majority.","3":"התהום נפתחת אחרי שיש מוצר ולקוחות ראשונים: היא בין קונים חזונאים לבין קונים פרגמטיים."},"1":{"0":"ההבדל הוא במוטיבציה, לא באינטליגנציה: Visionary רוצה קפיצה תחרותית, Pragmatist רוצה שיפור בטוח ומוכח.","2":"מחיר אינו קו ההפרדה. Visionary סולח לבאגים ומוותר על References, ו-Pragmatist דורש אמינות ו-References.","3":"ההפרדה היא לפי גישה, לא לפי גודל החברה: Visionary מחפש קפיצה ומקבל סיכון, Pragmatist רוצה הוכחה מעמיתים."},"2":{"0":"Whole Product אינו השלמת ה-Roadmap המקורי: הוא מוסיף תמיכה, תיעוד ואינטגרציות סביב הליבה.","2":"עוד פיצ׳רים מה-Backlog אינם העיקר. Pragmatists צריכים את הפתרון המלא סביב הליבה: תמיכה, אינטגרציות והדרכה.","3":"מעבר QA הוא חלק מליבה שעובדת. Whole Product כולל גם תמיכה, אינטגרציות ואקוסיסטם."},"3":{"0":"פנייה לשוק הגדול ביותר מפזרת את הכוח: עדיף דג גדול בבריכה קטנה מאשר דג זעיר באוקיינוס.","2":"Beachhead מתמקד בנישה אחת עם Whole Product אחד, לא במוצר נפרד לכל Segment.","3":"Enterprise אינו הכלל: ה-Beachhead הוא נישה צרה עם סיבה דחופה לקנות, שנבחרת בגלל המנוף שהיא נותנת."},"4":{"0":"זו לא ירייה אחת ותקווה: כל נישה שנכבשת מפילה במכוון את הנישה הסמוכה דרך References.","2":"המסלול עובר בין נישות סמוכות, לא רק ב-Enterprise: ה-Beachhead בדוגמה הוא צוותי R&D בחברות SaaS.","3":"לא מחליפים מוצר לכל נישה: ה-References וה-Whole Product עוברים איתכם לנישות דומות."},"5":{"0":"TAM גדול אינו המבחן: הנישה צריכה להיות קטנה מספיק כדי לנצח בה, עם סיבה דחופה לקנות.","2":"יותר לקוחות אינו המדד. הנישה צריכה להיות גדולה מספיק כדי שתהיה משמעותית, וקטנה מספיק כדי לנצח בה.","3":"לקוחות קיימים עוזרים, אבל הקריטריונים רחבים יותר: סיבה דחופה לקנות, Whole Product בר-ביצוע ומנוף לנישה הבאה."},"6":{"0":"המודל לא תולה את הכישלון בחומרה: Visionaries קנו, אבל ל-Pragmatists לא הייתה סיבה לקנות ולא Whole Product.","2":"מחיר אינו ההסבר של המודל. ל-Pragmatists לא הייתה סיבה משכנעת לקנות ולא Whole Product לחיי היומיום.","3":"מודעות לא הייתה הפער. האבחנה של המודל: אין סיבה יומיומית משכנעת לקנות ואין Whole Product."},"7":{"0":"אצל Moore מיצוב הוא כרטיס הכניסה לשוק ה-Pragmatists, לא סלוגן: למי, לאיזו בעיה, באיזו קטגוריה ובמה שונה.","2":"מיצוב אינו מסמך טכני: הוא אומר במשפט אחד למי המוצר מיועד ובמה הוא שונה מהחלופה.","3":"מחירון משווה בין חבילות. מיצוב ממקם את המוצר בקטגוריה ומול חלופה."},"8":{"0":"כשעוד אין Product-Market Fit, השלב מפנה לספרים כמו The Lean Product Playbook. התהום מגיעה אחר כך.","2":"כשכבר נמצאים בצמיחה המונית, האתגרים אחרים. הספר מתאים לשלב שבין לקוחות ראשונים למיינסטרים.","3":"סגירת מוצר אינה התהום. הספר עוסק בצמיחה מה-Early Adopters אל השוק הרחב."},"9":{"0":"תשלום אינו העניין. Early Adopters הם פלח קטן מהשוק, ו-Pragmatists לא מקבלים אותם כ-Reference.","2":"חוסר נאמנות אינו הסיבה בשלב. הבעיה היא שהאהבה של ה-Visionaries לא משכנעת Pragmatists, שרוצים References מעמיתים.","3":"היכרויות אינן הבעיה: Pragmatists מדברים בעיקר זה עם זה ולא מקבלים Visionaries כ-Reference."},"10":{"0":"המספרים שגויים: Innovators הם כ-2.5% ו-Early Adopters כ-13.5%, לא 10% ו-20%.","2":"קרוב, אבל לא מדויק: Innovators הם כ-2.5%, Early Adopters כ-13.5%, וכל אחד מהרובים 34%.","3":"כל אחד מהרובים הוא 34% ולא 40%, ו-Early Adopters הם 13.5% ולא 9%."},"11":{"0":"האנלוגיה לא נובעת משם הספר: היא ממחישה ריכוז כוח בחוף אחד לפני שמתקדמים.","2":"תקציב אינו הנקודה. הלקח הוא מיקוד: חוף נחיתה אחד, לא חמישה שווקים במקביל.","3":"האנלוגיה עוסקת במיקוד, לא באומץ: לכבוש חוף אחד עד הסוף, ורק ממנו להתקדם."},"12":{"0":"בהקשר הזה מדובר במכירות ובשיווק, לא בפיתוח: הכפלת צוות המכירות לפני ניצחון שחוזר על עצמו בנישה אחת.","2":"העלאת מחירים אינה העניין. הסכנה היא צוות מכירות גדול שמבזבז זמן על Pragmatists שלא יקנו בלי References.","3":"התרחבות גיאוגרפית אינה ההגדרה. Premature Scaling הוא הגדלת המכירות לפני שיש Beachhead יציב."},"13":{"0":"ה-PM לא כותב את כל הקוד. הוא ממפה את הפערים ומתעדף אינטגרציות ותמיכה.","2":"ה-PM עובד עם אחרים: מנסח מיצוב עם השיווק ובודק אותו מול לקוחות אמיתיים, על סמך ראיונות שטח.","3":"עוד פיצ׳רים הם הצעד הלא נכון: בזמן החצייה אינטגרציות ותמיכה קודמות לפיצ׳רים נוצצים."},"14":{"0":"עושר אינו המאפיין. Conservatives קונים רק כשהמוצר הפך לסטנדרט, ומוכרים להם דרך סטנדרטיזציה ומחיר נמוך.","2":"ה-Late Majority אינם יותר טכנולוגיים. הם Conservatives שקונים רק כשטכנולוגיה כבר הפכה לסטנדרט.","3":"הקבוצות מוגדרות לפי היחס לטכנולוגיה חדשה, לא לפי B2B או B2C."}},"120":{"0":{"0":"התמקדות רק ב-Discovery היא מה שספרים אחרים עושים. הספר הזה מכסה את כל התחום, מהגדרת התפקיד ועד הקריירה.","2":"הספר לא מיועד רק לבכירים: הוא עוסק גם בכניסה לתפקיד ובצמיחה בו, כספר לימוד לכל התחום.","3":"זה לא מדריך טכני: ה-PM אחראי על ה״למה״ וה״מה״, והמהנדסים מחליטים על ה״איך״."},"1":{"0":"אלה לא ארבעת ה-D. הלולאה מתחילה ב-Discovery, בהחלטה מה לבנות, ולא באיסוף נתונים או בתיקון באגים.","2":"הלולאה מתחילה ב-Discovery, מציאת הבעיה הנכונה, ואין בה שלב Delight: ה-Delivery מחזיר ל-Discovery.","3":"בלולאה הזו אין Done: לפי הספר אין ״סיימנו״, יש רק ״למדנו״, וה-Delivery חוזר ל-Discovery."},"2":{"0":"הספר רוצה רמה סבירה בכל שש המשפחות, לא חוזקה אחת: התפקיד של ה-PM הוא לחבר בין המומחים.","2":"PM לא חייב להיות מהנדס: המטרה היא רמה מספיקה בכל משפחה, וה״איך״ שייך למהנדסים.","3":"ויתור על המשפחה הטכנית סותר את המטרה של רמה סבירה בכל המשפחות, ודווקא שם הציון של Michal הנמוך ביותר."},"3":{"0":"HEART מודד את איכות החוויה, אבל לא מפרק את המסע לשלבים, ולכן לא יראה איפה משתמשים נושרים.","2":"OKRs מיישרים יעדים, אבל לא מראים איפה המסע נשבר. יעד הכנסות למכירות מדלג על שלבי המשפך.","3":"North Star ממקד את הצוותים במדד אחד, אבל מספר יחיד לא מאתר באיזה שלב במשפך הדברים נשברים."},"4":{"0":"הרשמות מודדות משיכה, לא את הערך שהלקוח מקבל: אפשר להירשם ולעולם לא להגיע לערך.","2":"MRR הוא תוצאה כספית מאחרת, לא הערך שהלקוח מקבל. North Star משקף את ערך הליבה שהמוצר מספק.","3":"פיצ׳רים שהושקו הם Output ולא Outcome. הם מראים מה הצוותים ייצרו, לא איזה ערך הלקוחות קיבלו."},"5":{"0":"Reach לבדו לא מכריע: RICE שוקל את ארבעת הרכיבים, וה-Effort של 4 מחלק את הציון של א׳ עד 400.","2":"Confidence נמוך מ-100% רק מקטין את הציון: ה-80% של א׳ נכנס להכפלה. הציון עדיין עובד והופך ויכוח לדיון בהנחות.","3":"כאן מכפילים ב-Effort במקום לחלק בו. החישוב הנכון לרעיון א׳ הוא 2,000×1×0.8÷4 = 400."},"6":{"0":"PM לא מחלק משימות, לא מאשר קוד ולא נותן ציונים: הוא מביא את ה״למה״ וה״מה״, והצוות אחראי על ה״איך״.","2":"ה-PM משתתף בכל ארבעת הטקסים, כולל Standup להסרת חסמים ו-Retro לשיפור התהליך.","3":"מסירת מסמכים בלי השתתפות היא מה שהספר מזהיר מפניו: מפרט בלי שיחה משאיר את הצוות בלי ה״למה״."},"7":{"0":"הביטוי לא עוסק בשכר או בהטבות. הוא מתאר אחריות להצלחת המוצר בלי סמכות פורמלית.","2":"ל-PM אין סמכות לפטר: זו בדיוק הסמכות הפורמלית שחסרה לו. ההשפעה באה מנתונים ומאמון.","3":"PM לא שולט בתקציב החברה. הרעיון הוא אחריות על התוצאה בלי סמכות פורמלית על אחרים."},"8":{"0":"הסדר מבולבל: PMF מחפשים ב-Introduction, Scaling בא ב-Growth, והמצאה מחדש היא אחת האפשרויות ב-Decline.","2":"ה-PM ממשיך להוביל בכל שלב. מה שמשתנה הוא המיקוד: מ-PMF ל-Scaling, לאופטימיזציה ולהחלטה על עתיד המוצר.","3":"התפקיד משנה צורה לפי השלב: ממציאת PMF, דרך Scaling ואופטימיזציה, ועד החלטה על עתיד המוצר."},"9":{"0":"כתיבת קוד אינה ברשימת הטעויות של הספר. הרשימה נפתחת בניסיון לרצות את כולם ובפחד מ״לא״.","2":"עבודה מהבית אינה ברשימה של הספר. הטעויות הבולטות הן ריצוי כולם והימנעות מ״לא״, שמטשטשות את המיקוד.","3":"הספר מזהיר דווקא מההפך: התעלמות מנתונים והחלטות לפי תחושת בטן בלבד היא אחת הטעויות הנפוצות."}},"121":{"0":{"0":"אלה שלבי חיים של מוצר, לא CIRCLES. השיטה נפתחת ב-Comprehend: הבנת המצב דרך שאלות הבהרה.","2":"אלה לא שבעת השלבים. CIRCLES עובר מהבנת המצב והלקוח ועד המלצה מסוכמת.","3":"הרשימה קופצת ל-Roadmap ולקוד. CIRCLES לא משיק כלום: זה מבנה תשובה שנגמר בהמלצה."},"1":{"0":"Lin טוען את ההפך: מועמדים נכשלים לא בגלל חוסר ידע, אלא בגלל חוסר מבנה.","2":"Lin לא תולה את הכישלון בניסיון. מועמד עם פריימוורק נשמע כמי שכבר חושב כמו PM.","3":"שאלות הבהרה מומלצות: Lin מבקש לפחות 2-3 לפני שפותרים. מי שמדלג עליהן נראה פזיז."},"2":{"0":"להתחיל ברשימת פתרונות זו טעות ה-Solution-First: פתרונות שלא נשענים על לקוח יוצאים גנריים.","2":"Evaluate בא מאוחר ושוקל Trade-offs בין פתרונות, לא את מה שהמראיין רוצה לשמוע.","3":"Summarize הוא השלב האחרון ונסגר בהמלצה. השלב הראשון הוא הבנת המצב."},"3":{"0":"Marketing אינו חלק מ-AARM, והסדר שגוי: המשפך עובר מ-Acquisition דרך Retention ועד Monetization.","2":"AARM עוקב אחרי מחזור החיים של המשתמש, מהחשיפה ועד הכסף. Awareness, Reach ו-Metrics אינם השלבים שלו.","3":"Aim, Act, Refine היא לולאה כללית. AARM הוא משפך: Acquisition, Activation, Retention, Monetization."},"4":{"0":"זה תיאור של מדד ה-Primary: מה שהפיצ׳ר אמור להזיז. Guardrail שומר על מה שאסור שירד.","2":"זה תיאור של ה-North Star, המדד שמיישר את כל הצוותים. Guardrail מגן על שאר המוצר.","3":"זה תיאור של מדדי Secondary, שמשלימים את התמונה. Guardrail בודק ששום דבר אחר לא נפגע."},"5":{"0":"זה נשמע כמו דוח פרויקט כללי. DIGS נפתחת ב-Dramatize, פתיחה חיה, ולא בתיאור יבש.","2":"DIGS לא נפתחת בהגדרת המצב אלא ב-Dramatize, וה-I שלה הוא Indicate alternatives.","3":"ה-D נכון, אבל I הוא Indicate alternatives ו-S הוא Summarize, לא Implement ו-Sell."},"6":{"0":"DIGS נפתחת ב-Dramatize ולא ב-Define, והתוספת שלה היא חלופות שמראות שיקול דעת, לא יעדים.","2":"DIGS לא נפתחת בתוצאה: התוצאות באות בסוף, ב-Summarize. ה-Go through מדגיש ״אני״, לא מאמץ צוותי.","3":"DIGS נפתחת ב-Dramatize ולא ב-Details, ומוסיפה Indicate alternatives, מה שחסר ב-STAR."},"7":{"0":"גודל הסגמנט אינו הנימוק: דנה בחרה לפי פוטנציאל Engagement, מקומי משתמש כל שבוע ותייר פעם בשנה.","2":"הכנסות מפרסום אינן הסיבה. הבחירה נשענת על Engagement חוזר: שימוש שבועי מול פעם בשנה.","3":"המראיין לא צמצם את השאלה: בחירת פרסונה היא העבודה של המועמד, ודנה נימקה את הבחירה בעצמה."},"8":{"0":"25 דקות על פתרונות לא משאירות זמן ללקוח ול-Trade-offs. Lin נותן ל-List כ-5 דקות.","2":"דילוג על Comprehend נראה פזיז. השלב לוקח רק 2-3 דקות ומצמצם את הבעיה.","3":"Summarize לוקח כ-3 דקות. עשרים דקות עליו לא משאירות זמן לשלבים שבונים את התשובה."},"9":{"0":"Lin קובע שמוצר לכולם הוא מוצר לאף אחד: הפתרון יוצא גנרי ולא פותר בעיה אמיתית.","2":"יעד מספרי לא יתקן את זה. הבעיה היא היעדר פרסונה, לא היעדר כמות.","3":"בחירת פרסונה אחת קורית ב-Identify, לפני ה-Cut. ה-Cut מתעדף צורך אחד של אותה פרסונה."},"10":{"0":"זו טעות קטלנית אחרת, Boil the Ocean: לפתור הכול לכולם בבת אחת.","2":"היעדר מדד הוא חולשה נפרדת. Solution-First פירושו להציע פתרון לפני שמבינים את הבעיה.","3":"זה ניהול זמן הפוך, טעות אחרת. Solution-First היא קפיצה מוקדמת מדי לפתרון."},"11":{"0":"זה סיכום של השלבים במקום המלצה. Lin רוצה המלצה ברורה עם מדד הצלחה.","2":"יש המלצה וסיבה, אבל אין KPI ראשי, Guardrail או סיכון שלפיהם נמדדת ההצלחה.","3":"השארת ההחלטה לצוות מסיימת בלי המלצה. Lin מבקש לסגור בהמלצה ברורה ובנימוק, יחד עם מדד הצלחה."},"12":{"0":"לעצור ולחשוב זה בסדר, אבל בשקט זה מסתיר את ההיגיון. המראיין רוצה לראות איך חושבים.","2":"לחשוב לפני שעונים אינו Solution-First, שהוא קפיצה לפתרון. הבעיה כאן היא השתיקה.","3":"Silent Thinking היא אחת מחמש הטעויות הקטלניות של Lin, לא עניין שולי: תהליך החשיבה הוא חלק ממה שנבחן."},"13":{"0":"החלפת פועל מעורפל באחר לא מתקנת דבר: עדיין אין מספרים ואין מסגרת זמן.","2":"גם הגדלת הכנסות מעורפלת בלי מספרים. התיקון של Lin הוא יעד מדיד, כמו Activation מ-30% ל-45%.","3":"״המשתמשים יאהבו״ מעורפל אפילו יותר. Lin דורש מספרים: ספציפי, מדיד ועם מסגרת זמן."},"14":{"0":"חדשנות אינה המנטרה: לפי Lin רעיון בינוני עם מבנה ברור מנצח רעיון גאוני בלי מבנה.","2":"מהירות אינה המסר. Lin אפילו מזהיר מפני קפיצה לפתרון כבר בשנייה העשירית.","3":"הסכמה אינה המנטרה. Lin מבקש להציף Trade-offs ולסיים בהמלצה ברורה."}},"122":{"0":{"0":"כותרת המשנה של הספר מונה 167 שאלות ותשובות אמיתיות, לא 100.","2":"250 זו הגזמה: השם המלא של הספר מבטיח 167 שאלות ותשובות אמיתיות מראיונות.","3":"500 רחוק מאוד: הספר אוסף 167 שאלות אמיתיות מראיונות PM, עם תשובות לדוגמה."},"1":{"0":"אלה תחומי הנדסה, לא קטגוריות של ראיון PM. PM לא נמדד על כתיבת קוד.","2":"אלה מחלקות בחברה, לא סוגי שאלות. הספר ממיין לפי מה שהשאלה בודקת, כמו אומדן או מדדים.","3":"אלה פונקציות עסקיות. הקטגוריות בספר הן סוגי שאלות, כמו אסטרטגיה, אומדן ושאלות התנהגותיות."},"2":{"0":"3C אינו שיטת חישוב: זו המסגרת של Ohmae שבוחנת את החברה, הלקוחות והתחרות.","2":"Cost, Capacity, Capability אינם ה-3C. ה-3C של Ohmae בוחן את היכולת שלנו, את צורך הלקוח ואת המתחרה.","3":"קרוב, אבל Cash ו-Channel לא שם: 3C הוא Company, Customers ו-Competition."},"3":{"1":"כאן הם מוחלפים: Top-Down מתחיל מנתון מאקרו כמו אוכלוסיית ישראל, ו-Bottom-Up מיחידה קטנה כמו שולחן אחד.","2":"אף אחת מהשיטות לא נותנת מספר מדויק: באומדן מכוונים לסדר הגודל הנכון, ושתי השיטות לגיטימיות.","3":"ההבדל הוא בנקודת המוצא, לא באופן הפילוח: מנתון מאקרו כלפי מטה, או מיחידה קטנה כלפי מעלה."},"4":{"1":"דיוק אינו המטרה: 1,432,500 נשמע פחות אמין מ״בערך 1.5M״. דיוק מזויף מופיע ברשימת הטעויות.","2":"הצהרה על הנחות היא כלל זהב נפרד. ה-Sanity Check בא בסוף ובודק אם התוצאה הגיונית.","3":"עיגול הוא כלל בפני עצמו. ה-Sanity Check שואל אם המספר הסופי סביר, למשל 15% מהאוכלוסייה."},"5":{"0":"הכנסות ושביעות רצון אינם הסט הנדרש, וחסר Guardrail: מה שאסור שייפגע.","1":"Leading ו-Lagging מתארים תזמון, לא את ארבעת הסוגים הנדרשים. חסרים North Star ומדד Primary.","3":"Input ו-Output אינם חלק מהסט, ואין כאן North Star, מדד Primary או Guardrail."},"6":{"1":"האסטרטגיה של יואב דווקא נמנעה מתחרות על UX, ונשענה על הקשר של Microsoft עם לקוחות Enterprise.","2":"מכירה של Teams כמוצר נפרד היא ההפך מה-Bundle שעליו נשענה האסטרטגיה של יואב.","3":"מחיר לא היה המנוף בקייס: היתרון נבנה על ה-Bundle עם Office 365 ללקוחות Enterprise."},"7":{"1":"שאלות הבהרה אינן הטעות. כלל הברזל הוא לעולם לא לזייף ידע.","2":"ניחוש בקול לפי שם המונח, עם הודאה כנה שלא מכירים, הוא בדיוק מה שהספר ממליץ. הזיוף הוא הטעות.","3":"הספר רוצה תשובות ברמת הקונספט: PM נמדד על שיחה מושכלת עם מהנדסים, לא על כתיבת קוד."},"8":{"0":"Five Forces מנתח ענף שלם, לא חברה נרכשת. להערכת חברה או רכישה השלב מפנה ל-SWOT.","2":"הכוחות אינם יכולות פנימיות: הם חיצוניים, כמו מתחרים חדשים, ספקים, לקוחות ותחליפים.","3":"מודל משפך הוא דבר אחר, כמו AARRR. הכוחות של Porter מודדים עד כמה שוק אטרקטיבי."},"9":{"0":"אלה קטגוריות השאלות הכלליות של הספר, לא שאלות התנהגותיות. שאלה התנהגותית עוסקת בחוויות שלכם.","2":"אלה התכונות שהקטגוריות בודקות, לא הקטגוריות עצמן: קונפליקט בודק שיתוף פעולה, כישלון בודק ענווה.","3":"הצלחה או קידום אינם ברשימה. הקטגוריות בודקות רגעים קשים, כמו קונפליקט, כישלון ולחץ זמן."},"10":{"0":"Awareness ו-Reach אינם ב-AARRR. המסגרת היא Acquisition, Activation, Retention, Referral, Revenue.","2":"Activity ו-Reach לא שם, והסדר שובר את מחזור החיים שמתחיל ב-Acquisition.","3":"Attention ו-Reliability אינם ב-AARRR. זו מסגרת של מחזור חיי המשתמש, לא בדיקת בריאות של המוצר."},"11":{"0":"זה מודד את ההצלחה של הפיצ׳ר עצמו, מדד Primary או Secondary. Guardrail שומר על מה שעלול להישבר במקום אחר.","2":"NPS של משתמשי הפיצ׳ר מודד את הפיצ׳ר עצמו. ה-Guardrail כאן מגן על הביצועים: זמן טעינה ו-CPU.","3":"רוחב פס ועלות שרתים אינם ה-Guardrail המוצע. הדוגמה מציינת את זמן הטעינה של הישיבה ואת שימוש ה-CPU."},"12":{"0":"״כן״ ישיר מראה שלא תפסתם את העומק: אין תשובה נכונה אחת, ולכן ההמלצה צריכה להיות מותנית.","2":"״מצד אחד, מצד שני״ בלי המלצה הוא התחמקות. ניואנס מתקבל בברכה, התחמקות לא.","3":"משתמשים בפריימוורק אחד ונותנים לו שם, לא בשלושה. ערימת פריימוורקים לא מחליפה המלצה מותנית."},"13":{"0":"כישלון אמיתי וכואב הוא בחירה נכונה, כל עוד מראים מה למדתם ומה תיקנתם אחר כך.","2":"כישלון עם לקח הוא בדיוק מה שעובד: סיפור הבטא שדילגה עליה Michal בנוי כך.","3":"גיל הכישלון אינו הבעיה שהספר מציין. הטעות המובילה היא בחירה בכישלון שולי מתוך פחד מהשאלה."},"14":{"0":"החזרת ההשקה לאחור היא מסקנה לפני אבחון. קודם מפלחים את הירידה ומפרידים בין סיבות פנימיות לחיצוניות.","1":"קמפיין החזרה לפני שהסיבה ידועה מטפל בסימפטום. האבחון בא קודם: סגמנטים, ואז סיבות.","3":"עונתיות היא סיבה חיצונית אחת שצריך לבדוק, לא תירוץ לחכות. הספר מבקש לאבחן לפני שמסיקים."}},"123":{"0":{"0":"Lin ו-Lu כתבו את The Product Manager Interview. השלב משווה את הספר הזה לספרי הפריימוורקים של Lin.","2":"Anon ו-González de Villaumbrosia כתבו את The Product Book, ספר אחר על המדף.","3":"אלה לא המחברים. השלב מייחס את הספר לצמד: מהנדסת לשעבר ב-Google שכתבה את Cracking the Coding Interview, ו-PM לשעבר."},"1":{"0":"ל-Amazon יש יותר מ-10: במשך שנים היו 14 עקרונות, וביולי 2021 נוספו עוד שניים.","1":"12 זה מעט מדי: הרשימה עמדה על 14 במשך שנים, לפני שנוספו לה שני עקרונות ב-2021.","2":"14 היה המספר במשך שנים, וזו גם הרשימה שמופיעה בפרק. ביולי 2021 הוסיפה Amazon שניים, והם 16."},"2":{"1":"Build, Use, Sustain אינם BUS. שלושת השלבים של Bavaro הם יעד עסקי, משתמשים ופתרונות.","2":"סיעור מוחות בהתחלה קופץ לרעיונות. BUS מתחיל ביעד העסקי, עובר למשתמשים ורק אז לפתרונות.","3":"BUS לא עוסק בקנייה ומכירה: זו מסגרת של שלושה שלבים לתשובה על שאלות Product Design."},"3":{"0":"3 שלבים זה מעט מדי: המשפך של McDowell עובר מסינון קו״ח ועד הצעה ב-8 שלבים.","1":"5 שלבים מפספסים כמה מסננות, כמו מטלת ה-Take-home וועדת הגיוס.","3":"12 זו הגזמה: המשפך הסטנדרטי בנוי מ-8 שלבים, מסינון קו״ח ועד הצעה ומשא ומתן."},"4":{"0":"חצי זה נדיב מדי: סינון קו״ח הוא השער הצר ביותר, ורק כ-10% עוברים סריקה של חצי דקה.","1":"30% גבוה מדי לשלב הזה. רק כ-10% עוברים, ולכן תוצאות מדידות בעמוד אחד הן קריטיות.","3":"כ-80% הוא שיעור המעבר המשוער בוועדת הגיוס, לא בסינון קו״ח, שבו עוברים רק כ-10%."},"5":{"0":"Customer Obsession ו-Frugality שייכים לעקרונות של Amazon, לא לפרופיל של Meta.","2":"חזון ארוך טווח ועולמות Enterprise מתארים את Microsoft במפת החברות של הספר.","3":"חשיבה מובנית מבוססת נתונים ורף טכני גבוה מתארים את Google, לא את Meta."},"6":{"0":"זה הפוך: ל-CIRCLES יש 7 שלבים ול-BUS שלושה. והספר רואה בשתיהן שיטות תקפות, לא אחת עדיפה.","2":"שתיהן מיועדות לשאלות Product Design. לשאלות התנהגותיות יש שיטה משלהן, כמו סיפורי DIGS.","3":"אף אחת לא קשורה לחברה מסוימת: שתיהן מסגרות כלליות לשאלות Product Design, ושתיהן תקפות."},"7":{"0":"שינון הגדרות לא מספיק: ב-Amazon מצפים להוכיח את העקרונות דרך סיפורים אישיים.","2":"המראיינים בודקים לפחות 4-5 עקרונות, אבל לא ידוע מראש אילו, ולכן שירה הכינה סיפור לכל אחד.","3":"תרגול Product Design כללי מפספס את ראיון הערכים של Amazon, שבנוי סביב סיפורים התנהגותיים."},"8":{"0":"זה מתאר את ועדת הגיוס של Google, שקוראת משובים כתובים. ה-Bar Raiser הוא מראיין עם זכות וטו.","2":"ה-Bar Raiser מגיע מחוץ לצוות, הוא לא המנהל המגייס, ותפקידו להעלות את הרף, לא למלא משרה.","3":"הרף הוא רף הגיוס, לא השכר. ה-Bar Raiser הוא מראיין מחוץ לצוות שמחזיק בזכות וטו."},"9":{"0":"תחומי אחריות הם בדיוק מה שהספר מבקש להחליף: הישגים, לא תפקידים. שם של חברה לא מראה תוצאה.","1":"הצהרה על מתודולוגיה בלי סיפור היא טעות מוכרת: תיאוריה בלי דוגמה. מספרים מראים תוצאות.","3":"שמות יחידות וראשי תיבות לא אומרים הרבה בעולם האזרחי: מתרגמים למספר אנשים, תקציב ותוצאה שכל אחד מבין."},"10":{"0":"עומק טכני הוא הדגש של Google במפת החברות. Apple מחפשת תשוקה למוצר, איכות ודיסקרטיות.","2":"פתיחות והשקות בטא ציבוריות הן ההפך מהדיסקרטיות ומהאיכות הבלתי מתפשרת של Apple.","3":"מדדים וצמיחה אינם מה שמייחד את Apple: הספר מדגיש תשוקה למוצר ותשומת לב לפרטים."},"11":{"0":"30 שעות זה בדיוק מה שהספר מזהיר מפניו: תקרה של 8-10 שעות. בודקים חשיבה, לא מצגת מושלמת.","2":"מהירות אינה מה שנבדק: התקרה היא 8-10 שעות, והחברה בוחנת את איכות תהליך החשיבה.","3":"מעבר ל-10 שעות התפוקה יורדת. הספר קובע 8-10 שעות כמקסימום, לא כמינימום."},"12":{"0":"בחירה במוצר של החברה המראיינת נראית כמו חנפנות. עדיף מוצר מוכר ממקום אחר.","2":"על מוצר שאף אחד לא מכיר קשה למראיין לעקוב. הספר ממליץ על מוצר מוכר, ועל ניתוח שלו.","3":"סוג המוצר אינו העיקר: כל מוצר מוכר מתאים, בתנאי שמנתחים משתמש יעד, כאב ופתרון."},"13":{"0":"סיכום חוזקות אינו הסיום שהספר ממליץ עליו: מועמד שלא שואל שאלות משדר חוסר עניין.","2":"על שכר מדברים בשלב ההצעה, כשהמגייס הופך לסוכן שלכם. השאלות בסוף צריכות להראות חשיבה אמיתית.","3":"ההחלטה מתקבלת אחר כך, בוועדה או ב-Debrief. הסיום נועד לשאלות חכמות על צוות, מוצר ותרבות."},"14":{"0":"פריימוורקים חשובים, אבל הטעות המובילה היא הכנה גנרית: כל חברה מודדת בקנה מידה אחר.","2":"Coding אינו הבעיה בספר: סיבת הדחייה הראשונה שלו היא אפס מחקר על החברה.","3":"דווקא מומלץ לשאול: מועמד שלא שואל משדר חוסר עניין. הטעות המובילה היא הכנה גנרית."}},"124":{"0":{"0":"Fisher ו-Ury הם מחברי הגישה הקלאסית של Win-Win, ״Getting to Yes״, ש-Voss יוצא נגדה בספר הזה.","2":"כהנמן הוא מקור המודל System 1 / System 2 ש-Voss נשען עליו; הוא מצוטט בספר, לא כתב אותו.","3":"את הספר כתב מנהל משא ומתן לשעבר בחטיפות של ה-FBI, יחד עם Tahl Raz. Cialdini אינו המחבר."},"1":{"0":"Voss אומר במפורש שאמפתיה אינה הסכמה: מראים שהבנתם, בלי לוותר על העמדה שלכם.","2":"זו הזדהות, ו-Voss שולל אותה במפורש: המטרה היא להבין את הרגש ולהראות זאת, לא לחוות אותו בעצמכם.","3":"Tactical Empathy מתמקדת ברגשות של הצד השני, לא בשלכם; הוא נפתח כי הוא מרגיש מובן, לא בתמורה לחשיפה."},"2":{"0":"Mirror הוא רק 1-3 המילים האחרונות בטון שאלה. סיכום מלא הוא כלי אחר, שנועד להגיע ל-That's right.","2":"Isopraxism הוא הבסיס, אבל ה-Mirror פועל דרך המילים ובעדינות; חיקוי גלוי של גוף וקצב אינו הטכניקה.","3":"שיום רגש ב״נשמע ש...״ הוא Labeling, כלי נפרד. Mirror מחזיר לצד השני את המילים שלו עצמו."},"3":{"0":"לפי Voss, ״Yes״ נאמר פעמים רבות מנימוס או כדי שתלכו, בלי מחויבות אמיתית מאחוריו.","2":"Voss מזהיר ש-״You're right״ הוא דרך מנומסת לסיים את השיחה, ולא סימן להסכמה אמיתית.","3":"Voss מעריך ״No״ כנקודת פתיחה שנותנת תחושת ביטחון, אבל היעד שהוא קובע הוא That's right."},"4":{"0":"Voss נמנע מ-Why: השאלה נשמעת כהאשמה ומכניסה את הצד השני לעמדת התגוננות.","2":"זו בקשת כן/לא שרודפת אחרי Yes; Voss מחליף בקשה כזו ב-״Would it be ridiculous to ask for your help?״.","3":"השאלה הזו רק מבקשת שוב את הדרישה. ה-Magic Question מחזירה אליהם את האילוץ, כדי שיסבירו איך או יורידו את הדרישה."},"5":{"0":"How היא אחת משתי המילים ש-Voss בונה עליהן שאלות Calibrated: פתוחה ולא מאשימה.","1":"What היא מילת הבסיס השנייה של שאלות Calibrated, כמו ״What about this is important to you?״.","3":"When לא מאשימה איש; החיסרון שלה הוא שהיא מוציאה רק עובדה קצרה, לא תשובה מפורטת."},"6":{"0":"ה-Audit בא מראש, לפני שהצד השני מדבר. הפרכת טענות אחרי שסיים היא בדיוק הוויכוח שהוא נועד למנוע.","2":"ב-Audit אתם אומרים את הדברים הקשים בעצמכם, בקולכם. לבקש מהצד השני לפרט התנגדויות רק נותן להן במה.","3":"ה-Audit מונה מה עלולים לומר עליכם, לא את החולשות שלהם; מטרתו לנטרל התנגדויות, לא להשיג מנוף."},"7":{"1":"החלוקה הפוכה: המילים הן הערוץ הקטן ביותר, 7%, ושפת הגוף הגדול ביותר, 55%.","2":"ה-7 אינו שניות: הכלל מחלק מסר לשלושה ערוצים, מילים 7%, טון 38% ושפת גוף 55%.","3":"Voss לא מפריך את הכלל אלא מצטט אותו; ההסתייגות היא שהוא נוגע לרגשות כשמילים וטון סותרים."},"8":{"0":"טון קליל וחיובי הוא ברירת המחדל של Voss ברוב השיחות, לא קול השדרן ששמור לרגעי מתח.","2":"הטון האסרטיבי שמור אצל Voss לקווים אדומים נדירים ומסתכן בהסלמה, ואילו קול השדרן מרגיע.","3":"קול השדרן איטי ונמוך עם ירידת טון בסוף; אנרגיה מהירה ונלהבת היא ההפך מהרוגע שהוא מפיץ."},"9":{"0":"Ackerman פותח גבוה יותר, ב-65% מהיעד; 50% אינו אחד השלבים במודל.","2":"85% הוא השלב השני במודל; מגיעים אליו רק אחרי הצעת פתיחה של 65% מהיעד.","3":"100% היא ההצעה האחרונה, במספר לא עגול ועם תוספת קטנה שאינה כספית."},"10":{"0":"זו המשמעות המקורית של Taleb; Voss משתמש במונח למידע נסתר שאפשר לחשוף בהקשבה ובשאלות.","2":"ויתור שנשמר לסוף הוא מהלך מיקוח. Black Swan הוא מידע על הצד השני שעדיין לא ידוע לכם.","3":"הצעת פתיחה היא משהו שאתם מניחים על השולחן; Black Swan הוא משהו נסתר שצריך לגלות."},"11":{"0":"הרגעה היא האינסטינקט ש-Voss דוחה: ״אין סיבה לכעוס״ מבטל את הרגש במקום לתת לו שם.","2":"זו שאלת Why, שלפי Voss נשמעת מאשימה. Label מתאר את הרגש ואז שותק.","3":"Label רק מתאר את מה שתלוי באוויר, בלי להסכים, בדיוק כמו ש-Tactical Empathy היא הבנה ולא הסכמה."},"12":{"0":"החסם לא היה עומס על הצוות: לפי ההסבר, הקוד של ה-Site Generator הישן הוא הבעיה, ופרויקט נפרד פתר אותה.","2":"אין כאן ניפוח הערכות: מה שהתגלה היה טכני, קוד Legacy ב-Site Generator הישן.","3":"לא הייתה כאן בטא או דחייה: הממצא קיצר את לוח הזמנים עצמו, מ-6 חודשים ל-2.5."},"13":{"0":"Voss רואה ב-״No״ התחלה ולא סוף: מי שאמר אותו מרגיש מוגן, ועכשיו הוא פנוי להקשיב.","2":"Voss לא רודף אחרי ״Yes״; הוא אפילו מנסח שאלות שמזמינות ״No״, כי ״Yes״ נאמר לרוב מנימוס.","3":"ויתור מהיר הוא פשרה באמצע, ש-Voss מזהיר ממנה. אחרי ״No״ ממשיכים לדבר, לא מוותרים."},"14":{"0":"Win-Win, היגיון ופשרה באמצע הם בדיוק מה ש-Voss יוצא נגדו, ומספרים עגולים נשמעים אצלו כמו ניחוש.","2":"Voss שומר טון אסרטיבי לקווים אדומים נדירים כי הוא מסתכן בהסלמה; איומים ואולטימטום אינם הכלים שלו.","3":"קבלת ההצעה הראשונה מדלגת על כל התהליך; בתרחיש השכר שירה עולה מ-35K ל-43,892 בכלים של Voss."}},"125":{"0":{"0":"Voss כתב את Never Split the Difference, ספר נפרד בקורס. את ספר השכר הזה כתב יועץ הקריירה Jack Chapman.","2":"Fisher מזוהה עם Getting to Yes והגישה של Win-Win. ערכת השטח הזו למשא ומתן על שכר היא של Jack Chapman.","3":"Lewis Lin אינו קשור לספר הזה: הוא נכתב בידי Jack Chapman, יועץ ומאמן קריירה עם 40+ שנות ניסיון."},"1":{"0":"הכותרת מדברת על הרווח שלכם: ההעלאה מחולקת בדקות שדיברתם, לא תעריף של יועץ.","2":"זה נכון ומופיע בספר, אבל זה הטיעון על ההצטברות לאורך הקריירה, לא החשבון שמאחורי הכותרת.","3":"Chapman אומר את ההפך: לא סוגרים במקום, ומבקשים 24-48 שעות לחשוב גם כשההצעה טובה."},"2":{"0":"גם טווח אישי הוא מספר שמגביל אותה, וכל מספר מוקדם הופך לתקרה; הכוח שלה גדל ככל שהתהליך מתקדם.","2":"כל מספר לפני הצעה הופך לתקרה; שכר נוכחי ועוד 10% קובע לה רף נמוך עוד לפני שרוצים אותה.","3":"גם בראיון הראשון Chapman ממליץ לדחות: קודם להבין את התפקיד. על כסף מדברים רק אחרי הצעה."},"3":{"0":"הכלל עוסק במספר השכר עצמו, העוגן; הוא לא מבקש לחכות או לשתוק בכל נושא אחר.","2":"Chapman טוען את ההפך: מי שנוקב מספר ראשון מפסיד, כי המספר שלכם הופך לתקרה שלכם.","3":"הכלל עוסק במי שנוקב מספר ראשון, לא במי שמוותר ראשון; המספר שלהם הוא הבסיס שממנו מטפסים."},"4":{"0":"Chapman מדגיש שזו לא הצגה דרמטית אלא הפסקה של הפתעה; כעס וקימה מהכיסא הם משהו אחר לגמרי.","2":"ההצעה הנגדית מגיעה אחר כך, רצוי אחרי 24-48 שעות; ה-Flinch הוא תגובת ההפתעה שקודמת לה.","3":"פני פוקר מסתירות תגובה, וה-Flinch מראה אותה בכוונה כדי לסמן שהמספר לא סגר את הסיפור."},"5":{"0":"31K נמצא מתחת ל-Walking Number שקבעה מראש, הרצפה שמתחתיה לא חותמים; הקרבה ליעד לא משנה.","2":"Walking Number הוא הרצפה, לא המקסימום. הסכום הגבוה ביותר שמבקשים הוא ה-Dream Number.","3":"חתימה מתחת לרצפה שוברת את הכלל, והעלאה דורשת תיק ראיות שנבנה לאורך זמן; לפי הספר העלאה פנימית היא רק 3-7%."},"6":{"0":"בקשה של 50-100% יותר תישמע מנותקת מהמציאות, בדיוק הסיכון ש-Chapman מזהיר ממנו בבקשה גבוהה מדי.","1":"20-30% מגזים: Chapman מזהיר שבקשה גבוהה מדי נשמעת מנותקת; על 35K, 10-15% הם כ-38.5-40K.","3":"2-5% משאיר על השולחן את רוב המרווח השמור; ההצעה הראשונה אף פעם לא סופית, ויש מקום לבקש יותר."},"7":{"0":"Chapman אומר לא לסגור במקום גם כשההצעה מצוינת; ההפסקה היא מה שמכין את הקרקע להצעה הנגדית.","2":"חתימה ברגע שזה מגיע מדלגת על זמן החשיבה ועל ההצעה הנגדית, שלפי Chapman תמיד יש לה מקום.","3":"Chapman אומר להשתמש בהצעה מבחוץ רק אם באמת מוכנים לעזוב, ולעולם לא כבלוף; הצעה שלא קיימת היא בלוף."},"8":{"0":"Chapman מסמן צרכים כמו משכנתא או משפחה כגישה הגרועה: הצד השני רוצה לדעת מה הוא מקבל.","2":"ותק ונאמנות לא אומרים דבר על תוצאות; התיק של Chapman נבנה על ראיות לערך: תוצאות, KPIs ונתוני שוק.","3":"Chapman מכנה הצעה מבחוץ טקטיקה מסוכנת שעלולה לסדוק אמון; משתמשים בה רק אם באמת מוכנים לעזוב."},"9":{"0":"המספרים הפוכים: לפי Chapman העלאה פנימית מביאה 3-7%, ומעבר עבודה מביא 10-30%.","2":"Chapman אומר לגשת להעלאה כמו לפרויקט: לבנות תיק ולבקש בפגישה ייעודית, לא לחכות שישימו לב.","3":"העלאות במקום הנוכחי, כולל ב-Review, הן לפי הספר המסלול של 3-7%; הקפיצה הגדולה באה ממעבר עבודה."},"10":{"0":"השכר הנוכחי הוא עדיין מספר אישי, וכל מספר שאתם נוקבים הופך לעוגן ולתקרה שלכם.","2":"מספר מדויק הוא עדיין מספר אישי; גם תחת לחץ, התשובה של Chapman נוקבת רק בטווח שוק.","3":"Walking Number הוא הרצפה שלכם; לומר אותו בקול מוסר להם את הסכום הנמוך ביותר שתסכימו לו."},"11":{"0":"בונוס שנתי נגזר מהבסיס, ולכן כשהבסיס נעול גם הבונוס תקוע; בטבלה של Chapman הוא בדרגת קושי בינונית.","2":"Chapman מדרג קיצור Vesting כקשה להשגה, ואילו מענק חתימה חד-פעמי הוא הקל ביותר ברשימה שלו.","3":"Chapman מדרג RSU כ״קשה אבל אפשרי״, והן משתחררות לאורך שנים; תשלום חד-פעמי בכניסה קל בהרבה לאישור."},"12":{"0":"עם Cliff אין הבשלה חודשית מהיום הראשון: עד חודש 12 אף יחידה לא משתחררת.","2":"ה-25% השנתיים ניתנים רק על שנה שהושלמה; עזיבה בחודש 10 היא לפני ה-Cliff, ולכן שום דבר לא מבשיל.","3":"ל-Cliff אין קשר למחיר המניה: זו התקופה הראשונה של ה-Vesting, שבה שום דבר לא משתחרר."},"13":{"0":"~30K הוא רק מענק החתימה החד-פעמי; הבסיס, הבונוס וה-RSU הוסיפו עוד, כ-120K בסך הכול.","2":"~5K נמוך אפילו מרכיב אחד בעסקה; הבסיס לבדו עלה בכ-60K בשנה.","3":"המשא ומתן הרב-ממדי של דניאל הוסיף בסיס, מענק חתימה, בונוס, RSU ו-5 ימי חופשה, בתוך 30 דקות שיחה."},"14":{"0":"לפי Chapman ״לא״ אינו סופי; קבלה שקטה מוותרת על ההזדמנות להפוך אותו ל״מתי ובאילו תנאים״.","2":"Chapman מציע לבקש מהמנהל להמליץ עליכם בפני מי שמחליט, לא לעקוף אותו.","3":"Chapman מכנה איום בעזיבה מסוכן: מנהלים עלולים לראות בו חוסר נאמנות ולהתחיל לחפש מחליף."}},"126":{"0":{"0":"הפשרה הזו היא בדיוק האמונה שהספר בודק ומוצא הפוכה: הצוותים המהירים גם נכשלו פחות והתאוששו מהר יותר.","2":"הספר מוצא קשר, לא חוסר תלות: בקבוצות החזקות גם הקצב וגם היציבות היו טובים יותר.","3":"לפי הספר איטי אינו בטוח: יציבות נבנית מאצוות קטנות ופריסות תכופות, לא מהקפאות ארוכות."},"1":{"0":"ויתור על בדיקות יכול לקרות כתופעת לוואי, אבל הסיכון הישיר הוא שהמספר עולה והמציאות לא.","1":"גיוס SRE אינו מה שהיעד מעורר; מדד שהופך ליעד מזמין משחק במספר, וזה הסיכון.","2":"אין שום נתון שהמדד כבר גבוה בכל הצוותים; הסכנה האמיתית הפוכה: מספר שמנופח באופן מלאכותי."},"2":{"1":"עוד בדיקות ידניות משאירות את אותה אצווה גדולה ומאחרות אותה עוד; פרוסה קטנה קלה יותר לבדיקה ולביטול.","2":"שחרור בלילה משאיר את אותה אצווה גדולה ומוסיף צוות עייף; הוא לא מקטין את הסיכון שבשינוי עצמו.","3":"לפי המחקר, ועדת אישור חיצונית מאטה את המסירה, ולא נמצא שהיא מפחיתה כשלים."},"3":{"0":"המחקר מצא אחרת: אישור חיצוני נקשר למסירה איטית ולא נמצא שהוא מפחית כשלים; עוד חברים רק מוסיפים עיכוב.","1":"המחקר לא עוסק באורך הישיבה; מה שהוא קושר למסירה איטית הוא עצם האישור החיצוני.","3":"דווקא צוות שפורס כל יום נפגע במיוחד משער שבועי; הספר מעדיף סקירת עמית, בדיקות אוטומטיות וניטור."},"4":{"0":"מידע שעובר רק בערוצים רשמיים הוא התרבות הבירוקרטית לפי Westrum, זו שמכוונת לכללים.","1":"מידע שנשמר אצל מעטים ושליחים שנענשים מתארים את התרבות הפתולוגית, זו שמכוונת לכוח.","3":"השאלה של Westrum היא איך זורם מידע; תרבות גנרטיבית מעבירה אותו למי שצריך, לא מפסיקה לשתף."},"5":{"1":"שיחה אישית עדיין מתייחסת לזה כאשמה של אדם אחד; הספר שואל מה בתהליך ובכלים אפשר את התקלה.","2":"אישור מנהל הוא אישור חיצוני, שהמחקר קשר למסירה איטית ולא מצא שהוא מפחית כשלים.","3":"העברת הפריסות לצוות אחר מענישה את הצוות; תגובה של אשמה מלמדת אנשים להסתיר בעיות."},"6":{"0":"השוואה לצוותים אחרים לא אומרת דבר על הצלחת המוצר, ורק מזמינה משחק במספרים.","1":"המתנה לא תשנה דבר: מדדי מסירה מודדים כמה מהר ובטוח מגיעים ללקוח, לא אם הלקוח קיבל ערך.","2":"דוח זמינות הוא עוד מבט על יציבות; גם הוא לא אומר אם לקוחות באמת משתמשים ב-Timeline."},"7":{"0":"זמן עד שינוי של יומיים, מה-Commit לייצור, אומר שהפריסה כבר מהירה; השבועות לא הולכים שם.","2":"התאוששות קורית אחרי שחרור; היא לא מסבירה חודשיים של המתנה לפיצ׳ר שעוד לא יצא.","3":"הבדיקות האוטומטיות נכללות ביומיים האלה, ולכן הן כבר מהירות; השבועות החסרים קודמים להן."},"8":{"1":"העלות של איסוף הנתונים אינה הטענה של הספר; הבעיה היא שהמספרים האלה סופרים פעילות, לא תוצאה.","2":"הספר לא דוחה אותם לפי גודל צוות; הוא דוחה אותם בכל מקום, כי הם מתגמלים כמות עבודה ולא הישג.","3":"התנודתיות אינה הבעיה; ברגע שמתגמלים עליהם הם מתנפחים, כמו Velocity שהופך ליעד."},"9":{"0":"תרבות חשובה, אבל כאן החסם מבני: תלויות בקוד ובסביבות מחייבות חלון פריסה משותף.","1":"ניטור עוזר לתפוס תקלות מהר, אבל הבעיה כאן קודמת לפריסה: הצוות לא יכול לפרוס לבד.","3":"מגבלת WIP מקצרת תורים בתוך הצוות; היא לא מבטלת את הצורך לתאם חלון עם שני צוותים אחרים."},"10":{"0":"היצמדות לאפיון רק כי תוכנן מבזבזת ספרינט על משהו שכבר ידוע שלא עובד.","1":"היכולת היא חופש לשנות את האפיון בלי אישור חיצוני; בקשת אישור מההנהלה על כל שינוי היא בדיוק אותו אישור.","2":"עצירת הספרינט כולו למחקר מלא היא תגובה מוגזמת; אפשר לעדכן את האפיון ולבדוק אותו מיד."},"11":{"0":"סדנת לחץ מטפלת בסימפטום; הספר מייחס את הכאב לאופן הפריסה, ושם הוא מתקן אותו.","2":"לפי הספר אפשר להפחית כאב פריסה בפריסות קטנות ואוטומטיות בשעות העבודה; זה לא מחיר קבוע של B2B.","3":"שום דבר לא מצביע על גודל הצוות; הספר קושר לילות לבנים לכאב פריסה, שנפתר בפריסות קטנות ואוטומטיות."},"12":{"0":"הספר נשען על סקרים, לא על ניסויים מבוקרים; הוא טוען לניבוי, ומבקרים מציינים שהחץ עשוי להתהפך.","1":"הקשר לביצועים עסקיים הוא לב הספר: רווחיות, נתח שוק ופרודוקטיביות, כפי שדווחו בסקרים.","3":"השלב לא מזכיר הגבלה כזו לחברות ציבוריות או לגודל; ובכל מקרה הנתונים מראים קשר, לא הוכחה."},"13":{"1":"דירוג צוותים הופך את המדדים ליעדים ומזמין משחק במספרים; השלב אומר במפורש לא לדרג צוותים.","2":"קישור לבונוס מתגמל אנשים על המספרים, והספר מזהיר שמספרים מתוגמלים מתנפחים.","3":"צוותים שונים, כמו צוות שתלוי בשותפים חיצוניים, לא אמורים להיראות זהים; יעד אחיד הופך למספר שמשחקים בו."},"14":{"0":"חלוקה לשכבות נראית מסודרת, אבל אף שכבה לא מביאה ערך או משוב עד שכולן מוכנות, אז האצווה נשארת גדולה.","2":"הכול בבת אחת הוא בדיוק האצווה הגדולה שהספר יוצא נגדה; שבוע בדיקות נוסף רק מאחר עוד יותר.","3":"חלוקה לפי מפתחים נותנת לכל אחד חלק, אבל אף חלק לא מגיע לבד ללקוח ומחזיר משוב."}},"127":{"0":{"0":"פגישות ומסמכים הם פעילות; גרוב סופר אותם רק אם הם מזיזים את מה שיוצא מהצוותים.","1":"תשובה מהירה בצ׳אט היא פעילות, לא תפוקה; גרוב שואל מה באמת יצא מהצוותים שהיא מנהלת ומשפיעה עליהם.","3":"רשימה אישית מתעלמת מהנוסחה: התפוקה של מנהל היא של הצוות שלו ושל הצוותים השכנים שהוא משפיע עליהם."},"1":{"1":"עשרים תשובות בצ׳אט מרגישות יעילות, אבל כל אחת משרתת אדם אחד לרגע אחד, וזה מינוף נמוך.","2":"ליטוש עיצוב המצגת לא משנה את העבודה של איש; מינוף גבוה נוגע בהרבה אנשים או משפיע לאורך חודשים.","3":"האזנה בלבד אוספת מידע אבל לא מזיזה דבר, בזמן שהחלטה שארבעה צוותים מחכים לה נשארת פתוחה."},"2":{"0":"זהירות נשמעת אחראית, אבל צוות שלם משלם עליה; החלטה שתקועה אצל אדם אחד היא מינוף שלילי.","1":"צוואר הבקבוק הוא ההחלטה שלה, לא הצוות; העברת האחריות אליהם משאירה את המינוף השלילי במקומו.","2":"עוד שבועיים או שלושה יעצרו את הצוות עוד יותר; גרוב מציע להחליט עם מה שידוע ולקבוע מועד לבחינה מחדש."},"3":{"0":"העסקאות נתקעות בסקירת האבטחה, לא בפיתוח; האצת שלב אחר רק מאריכה את התור שלפניה.","2":"עוד עסקאות בצנרת רק יצטברו מול אותה סקירה איטית; השלב המגביל לא משתנה.","3":"הסקירה שומרת על אמון הלקוח ואי אפשר לוותר עליה; גרוב בונה את התוכנית סביב השלב המגביל, לא מדלג עליו."},"4":{"1":"אחרי הפיתוח אותה אי-הבנה עולה ספרינט, לא שיחה, כי המוצר כבר שווה יותר.","2":"פיילוט מראה שימוש אמיתי, אבל הוא מגיע אחרי שהעבודה כבר נעשתה, ושם טעות בדרישות כבר יקרה.","3":"אחרי ההשקה הטעות עולה גם זמן פיתוח וגם אמון של לקוחות, השלב היקר ביותר לתפוס אותה."},"5":{"0":"גודל הקטלוג לא מושפע מהדחיפה, ולכן לא יגלה מה עלה המאמץ להגדיל את החיבורים.","1":"זמן במסך ההגדרות אינו תופעת הלוואי הצפויה; חיבורים שבורים מופיעים כפניות סנכרון לתמיכה.","3":"הרשמות לפי ערוץ מודדות את ראש המשפך, ולא אומרות דבר על המחיר של דחיפת החיבורים."},"6":{"0":"את הסטטוס אפשר להעביר לכתב, אבל ביטול מוחק גם את הזמן שנועד לבעיות ולדילמות של יערה.","1":"בדיקת לו״ז של עשר דקות היא עדיין פגישת סטטוס; גרוב מפנה את ה-1:1 לבעיות ולדילמות של העובדת.","2":"אם מיכל קובעת את סדר היום, זו הופכת לפגישה שלה; אצל גרוב ה-1:1 שייך לעובדת, והיא מביאה את הנושאים."},"7":{"0":"לפגישת משימה מזמינים רק את מי שנחוץ; הזמנת כל המושפעים מייקרת אותה ומקשה להחליט.","2":"גרוב אומר לסכם מראש מה מחליטים, עד מתי ומי צריך לשמוע; דיון פתוח בלי הכנה לא מבטיח החלטה.","3":"קצב קבוע הוא מה שמגדיר פגישת תהליך; פגישת משימה מתכנסת פעם אחת, לתוצר אחד מסוים."},"8":{"1":"קישור לדשבורד לבד לא יוצר דיון; הסקירה עובדת כשצוותים מסבירים סטיות ומבקשים החלטות.","2":"סקירה של הצלחות בלבד מסתירה בדיוק את מה שצריך לתקן; הלמידה נמצאת בסטיות.","3":"דיווח אישי על מה כל אחד עשה הוא פעילות, לא תוצאות; הסקירה משווה את המספרים של כל צוות מול התוכנית."},"9":{"0":"הדיון הפתוח הסתיים; ויכוח חוזר בכל פורום שוחק את ההחלטה עוד לפני שנבחנה.","1":"תמיכה בפומבי לצד הבטחות הפוכות ללקוחות היא תמיכה למראית עין, והיא מערערת את ההחלטה.","3":"לחכות שזה ייכשל אינו תמיכה; גרוב מצפה למחויבות לביצוע, גם ממי שהתנגד."},"10":{"0":"לפי גרוב, מסמך מלוטש על העתיד שלא משנה אף פעולה השבוע אינו תוכנית.","2":"תחזית חתומה אומרת מה עשוי לקרות; התוכנית של גרוב היא הפעולה שסוגרת את הפער, והיא מתחילה עכשיו.","3":"רשימת יוזמות היא רק חומר גלם; התכנון מחליט אילו פעולות מתחילות היום כדי לסגור את הפער."},"11":{"0":"בשלות נמדדת משימה אחר משימה: ותיקה בראיונות, חדשה במדד; רמה אחת לשתיהן תפספס באחת מהן.","1":"הנחיה צמודה בראיונות שכבר שולטת בהם מבזבזת מינוף ומלמדת לחכות; בשלות נקבעת לפי משימה, לא לפי ותק.","2":"חופש מלא במשימה חדשה לגמרי הוא נטישה, לא האצלה; בשלות נמוכה דורשת מבנה."},"12":{"1":"העברה לשרון מדלגת על השאלה הראשונה של גרוב, לא יכולה או לא רוצה, שהתשובה עליה בוחרת את הכלי.","2":"לקחת את המצגת מציל את הסקירה הבאה, אבל משאיר את יערה בלי המיומנות ואת מיכל עם עוד עבודה.","3":"התראה היא לחץ, ולחץ לא פותר חוסר יכולת; השלב מציין שהרבה ממה שיערה עושה, היא עושה לראשונה."},"13":{"0":"הדרכה אינה דרך לצאת מהעבודה היומיומית; המינוף שלה בא מכך שכמה שעות משפרות כמה אנשים לאורך חודשים.","1":"הדרכה לא מחליפה פגישות 1:1, שמשרתות מטרה אחרת; לא משם מגיע המינוף שלה.","3":"מה שההנהלה רואה הוא תופעת לוואי, לא הסיבה; המינוף הוא התפוקה של כמה אנשים לאורך חודשים."},"14":{"0":"״מי שביקש ראשון״ משאיר את הקונפליקט על הכתפיים של יערה; המבנה ההיברידי עובד רק כשחלוקת ההחלטות כתובה.","2":"מעבר מלא לעידו מבטל את הבית המקצועי שלה, שאחראי על המקצוע, הסטנדרטים וההערכה.","3":"במבנה ההיברידי הצוות קובע את סדר העבודה היומי; הכרעה אוטומטית לצד אחד מרוקנת את המבנה מתוכן."}},"128":{"0":{"0":"שיוך חברי צוות לרביעים הוא בדיוק התיוג ש-Scott מזהירה ממנו: הוא מקבע אנשים ופוטר אתכם משינוי.","1":"הרביעים מתארים כל שיחה, ו-Scott שואפת לצוות שבו עמיתים נותנים משוב זה לזה ישירות.","3":"לראות ברביע סגנון קבוע זה ההפך מהעיקרון: הוא מתאר רגע, שיכול להשתנות כבר בשיחה הבאה."},"1":{"1":"Ruinous Empathy נובעת מאכפתיות, לא מאדישות; מנהל שלא אכפת לו נוחת ברביעים התחתונים.","2":"השלב לא מאשים שום מדיניות; הסיבה אנושית: שתיקה מרגישה טוב עכשיו והמחיר מגיע אחר כך.","3":"הספר מייחס את זה לפחד של המנהל מרגע לא נעים, לא לבקשה של העובדים שיחסכו מהם ביקורת."},"2":{"0":"גם הצוות עלול לשלם, אבל המחיר העיקרי נופל על יערה: אף אחד לא אומר לה, ולכן היא לא משתפרת.","2":"קשיחות יתר היא הבעיה ההפוכה; כאן לא נאמר דבר בכלל, וזו Ruinous Empathy.","3":"אין סימן שמיכל מכירה את התחום פחות; הבעיה אינה איכות המסמך אלא שליערה לא אומרים דבר."},"3":{"0":"קבלת ״הכול טוב״ משאירה את התשובה המנומסת על כנה; שאלה כללית מזמינה בדיוק תשובה כזו.","1":"סקר ארוך מדלג על השיחה הישירה שבונה אמון; הספר מציע שאלה ספציפית אחת ואז לחכות.","2":"מתווכת מדלגת על השיחה הישירה; מי שמעביר הודעות בין אנשים הופך לצוואר בקבוק של אמון."},"4":{"1":"התגוננות במקום מלמדת את רונן לא לטרוח בפעם הבאה; הספר מציע שאלות המשך, לא הסברים.","2":"תודה בלי המשך אומרת לו שהמילים שלו לא שינו דבר, ואז פחות סביר שידבר שוב.","3":"מסמך תגובה ארוך הוא עדיין התגוננות; תגמול כנות הוא תודה ושינוי שרואים בפועל."},"5":{"0":"״המעצבת הכי טובה שיש לנו״ היא קביעה כללית על האדם; היא לא אומרת לנועה מה לעשות יותר.","1":"״כל הכבוד״ לא מלמד דבר; שבח טוב אומר מה עבד ולמה, וזה קופץ ישר למסך הבא.","3":"שבח שגולש ל״אם כי״ נשמע כעטיפה לביקורת, ו״מסך יפה״ לא מציין שום דבר מסוים."},"6":{"0":"משוב נמדד לפי איך שהתקבל, לא לפי הכוונה; כוונה טובה לא מתקנת את מה שאלעד שמע.","2":"חזרה מהמשוב היא Ruinous Empathy: משנים את הדרך, לא את האמת.","3":"העברה דרך המנהלת שלו מוסיפה מתווכת לשיחה שצריכה להיות ישירה."},"7":{"0":"העברת המסר הופכת את מיכל למתווכת, והמסר מאבד פרטים בדרך.","1":"העלאה בסקירה פומבית הופכת בעיה שאפשר לתקן לביקורת מול כולם.","2":"שתיקה כאן אינה ניטרלית: הבעיה נמשכת, והצעד הראשון לפי Scott הוא לשאול את אורי אם אמר לנועה בעצמו."},"8":{"0":"דחיפה לניהול כ״פרס״ עלולה לעלות לצוות PM מצוין ולתת לו מנהל שלא רצה.","1":"צמיחה יציבה היא מסלול, לא פגם; לסמן אותו כחסר שאפתנות מתעלם ממה שהוא רוצה כרגע.","3":"Rock Star רוצה להעמיק במה שהוא עושה; העברה לתחום חדש בכל רבעון חוסמת בדיוק את זה."},"9":{"1":"הבעיה אינה מי קובע את התווית אלא שהיא קבועה; מסלול משתנה עם החיים, וצריך לשאול שוב.","2":"Rock Stars לא חייבים להפוך ל-Superstars; שני המסלולים לגיטימיים, וצוות צריך את שניהם.","3":"שום דבר לא מגביל את המונחים למהנדסים; האזהרה היא שכל תווית קבועה עוצרת אתכם מלשאול שוב."},"10":{"0":"פתיחה מחדש של ויכוח שהוכרע כראוי מערערת את ההחלטה; המחזור ממשיך לשלב השכנוע.","1":"בקשת אישור חוזר מדני מערערת החלטה שהתקבלה כראוי, ולא מסבירה דבר למי שלא היה בחדר.","2":"קפיצה לבנייה מדלגת על שלב השכנוע, סיבה נפוצה לכך שהחלטות נפתחות מחדש בהמשך."},"11":{"0":"דוגרי הוא ישיר, אבל לא תמיד מראה אכפתיות, ובארה״ב הוא נשמע לעיתים קרובות כמו Obnoxious Aggression.","2":"ויתור על הביקורת יהיה Ruinous Empathy; האמת נשארת, רק הדרך משתנה.","3":"קהל גדול יותר רק מחמיר; ביקורת נאמרת ביחידות, לא בעוד ערוץ פומבי."},"12":{"1":"עקיפה דרך פגישת ההנהלה הופכת בעיית עבודה להתקפה; בלי סמכות, אמון הוא הכלי היחיד שלה.","2":"שתיקה ודחיסה שקטה הן Ruinous Empathy כלפי גיא, ויקרות לתוכנית של הצוות.","3":"רשימת טעויות עבר עוסקת בדפוס ובאופי, לא במקרה הזה; היא הופכת בעיית עבודה אחת להתקפה."},"13":{"0":"Radical Candor דורשת אכפתיות ואתגר יחד; טון לועג מוותר על חצי האכפתיות של המפה.","1":"Scott שואפת שעמיתים ייתנו משוב זה לזה ישירות; הבעיה היא הלעג, לא התפקיד שלו.","3":"כתיבה אינה חובה, והספר אף מזהיר שטון נעלם בכתב; הבעיה היא האכפתיות החסרה."},"14":{"0":"״הכול מצוין״ מעובדת כפופה משקף לרוב את פער הכוח, לא היעדר דברים לומר; מפסיקים לשאול ומפסידים.","2":"בירור אצל עידו מאחורי הגב של יערה שובר בדיוק את האמון שמיכל צריכה כדי שיערה תדבר.","3":"שאלה רק של שרון מפספסת את מה שרק עובדת כפופה יכולה לראות במיכל כמנהלת."}},"129":{"0":{"1":"Story Points לרשימת פיצ׳רים מלאה מתחילים מפתרון קבוע ושואלים כמה זמן, בדיוק ההרגל שה-Appetite מחליף.","2":"הוספת מפתחים כדי לעמוד בתאריך עדיין מקבעת את הפתרון; ה-Appetite משאיר את הזמן קבוע ומגמיש את ההיקף.","3":"פיצ׳ר משנה שעברה ועוד מרווח הוא הערכה, ניחוש שנוטה להימתח; Appetite שואל כמה הבעיה שווה."},"1":{"0":"אף אחד מהם אינו מעוצב כנדרש: אחד מפורט מדי וכולא את הצוות, והשני עמום מכדי להציב גבול.","1":"סקיצות ברמת פיקסל כולאות את הצוות, והוספת Acceptance Criteria לא מתקנת את רמת הפירוט של אף אחד מהם.","3":"כרטיס של שורה לא מציב גבולות, ובדיקת משתמשים לא תתקן סקיצות שלא משאירות לצוות מקום."},"2":{"0":"אב-טיפוס מעוצב מושך את הדיון לפרטים חזותיים מוקדם מדי, ההפך מלהסכים קודם על הזרימה.","2":"גאנט מפרק משימות של עבודה שעוד לא עוצבה; הוא לא אומר דבר על מסכים ופעולות.","3":"רשימת User Stories מפרקת עבודה לפני שעוצבה, ולא מראה מה מחובר למה."},"3":{"0":"השארה לצוות פירושה להמר על לא-ידוע, שעלול לבלוע שבועות באמצע המחזור.","1":"הוספת זמן סותרת את ה-Appetite; ה-Shapers מנטרלים את הבור, לא מותחים את הפרויקט סביבו.","2":"ב-Shape Up אין Backlog מרכזי לחנות בו, והשאלה הפתוחה הייתה נשארת בתוך ה-Pitch."},"4":{"0":"סיכונים טכניים מטופלים כ-Rabbit Holes ומנוטרלים ב-Shaping; No-gos הם דברים שבכוונה לא בונים.","2":"No-gos עוסקים בגבולות של הפתרון הזה, לא ברישום של בקשות לקוחות שנדחו.","3":"חלקים שאפשר לחתוך מסומנים בטילדה בזמן הבנייה; זה Scope Hammering, לא No-gos."},"5":{"1":"הספר לא אומר שבקשות לא חשובות; רעיון חשוב חוזר כ-Pitch, ובלי תיעוד אותות מהשטח הולכים לאיבוד.","2":"ה-Betting Table בוחר בין כמה Pitches מעוצבים בכל Cool-down; הוא לא מחזיק Backlog מרכזי.","3":"הצוות אחראי על איך לבנות, אבל מה בונים נבחר ב-Betting Table, לא בצוות לבדו."},"6":{"0":"״כבר השקענו שישה שבועות״ הוא טיעון העלות השקועה שה-Circuit Breaker נועד לעצור.","1":"העברה לצוות אחר היא הארכה בתחפושת; ברירת המחדל היא לעצור ולשאול מה השתבש ב-Shaping.","3":"הארכת המחזור לכולם שוברת את הזמן הקבוע בכל הצוותים; פרויקט שלא הסתיים פשוט לא מקבל הארכה."},"7":{"0":"נקודה תקועה היא בקשת עזרה, לא האשמה; דיווח יומי לא יענה על שאלה שעוד אין לה תשובה.","1":"כל Scope זז בנפרד; צד עולה פירושו שעוד לא ברור איך לפתור אותו, רחוק מ״כמעט גמור״.","2":"שאר ה-Scopes יורדים, אז הכמות אינה הבעיה; Hill Chart מודד ודאות, ודווקא כאן היא חסרה."},"8":{"1":"זה לא ״משיקים ומתקנים אחר כך״: מה שיוצא חייב לעבוד טוב, רק בלי מקרי קצה שלא משנים את התמונה.","2":"הטיעון של מיכל הוא ההשוואה לגיליון של היום, לא הצרכים של לקוח גדול אחד.","3":"מיכל עצמה מכריעה כאן בשאלת איכות, בהשוואה למה שיש ללקוחות היום; היא לא נשארת בצד."},"9":{"0":"עבודה בסוף שבוע שוברת את ה-Appetite; Scope Hammering חותך את מה שנחמד שיהיה, כדי שהמחזור לא יימתח.","2":"פיצול למשימות קטנות והערכה של כל אחת לא מקטינים את ההיקף בכלל.","3":"דחיית ההשקה שוברת את הזמן הקבוע; ההיקף הוא המשתנה, ולכן שואלים אם הגרירה חיונית."},"10":{"0":"רשימה שהוכנה מראש היא ניחוש, והערכה של 40 כרטיסים הופכת את הצוות למבצעי כרטיסים.","1":"פירוק של חלק בלבד עדיין מוסר לצוות משימות שפורקו מראש; הספר נותן לו את הפרויקט כולו.","3":"ה-Betting Table מהמר על Pitches מעוצבים, לא על רשימות כרטיסים; ורוב המשימות מתגלות רק כשהעבודה מתחילה."},"11":{"0":"בנייה בשכבות נפרדות דוחה לסוף המחזור את הגילוי של מה שלא עובד.","1":"שום דבר כאן לא מראה שה-Shaping נכשל; הבעיה היא סדר הבנייה, ופרוסה אחת שעובדת מקצה לקצה פותרת אותה.","2":"תרחישי בדיקה לא עוזרים כשעוד שום דבר לא מחובר; מה שחסר הוא פרוסה עובדת, לא בדיקות."},"12":{"0":"איחוד הקטנים והגדול יוצר פרויקט אחד מטושטש; הספר מפריד בין Small Batch ל-Big Batch.","2":"״אם יישאר זמן״ הוא בדיוק סוג החשיבה שה-Appetite מחליף; כל בעיה מקבלת את הזמן שלה מראש.","3":"ב-Cool-down אין תוכנית מחייבת: הוא לבאגים, ניקיון וחקירה, לא לפרויקטים מתוכננים."},"13":{"1":"דווקא כשיש תאריך, זמן קבוע הוא יתרון; Shape Up מתאים לכך יותר ממה שנראה.","2":"הבטחת כל הפיצ׳רים היא Roadmap שנכתב בידי עסקאות; ההיקף משתנה, ולכן מבטיחים את הבעיה.","3":"אין צורך לחכות: קובעים את ה-Appetite לפי מועד הדמו ומבטיחים את הבעיה שתיפתר."},"14":{"0":"צוות קטן ובכיר על המוצר של החברה עצמה הוא בדיוק המצב שהשיטה נבנתה בשבילו.","1":"צוות שכל ההחלטות בידיו הוא בדיוק האוטונומיה שהשיטה מניחה, ולכן היא מתאימה כאן.","3":"בעיה ברורה שנכנסת בשישה שבועות מתאימה בדיוק למחזור אחד; זה המגרש הביתי של השיטה."}},"130":{"0":{"0":"המחיר הוא סימפטום: במסגרת של ״עוזר AI״ גם מחיר נמוך יותר נמדד מול צ׳אטבוטים.","1":"היכרות טובה יותר עם המוצר לא תעזור כל עוד המסגרת עצמה שולחת את הקונים לרשימת הבדיקה של צ׳אטבוטים.","3":"אין שום נתון שהמודל חלש יותר; המסגרת הופכת את המודל לשאלה, ושם Velox לא בולטת."},"1":{"1":"הסיסמה נגזרת מהמיצוב בהמשך; המיצוב הוא ההחלטה על ההקשר, שקודמת לכל מילה.","2":"המיתוג בא אחרי המיצוב; לוגו וצבעים לא קובעים למה לקוחות משווים את המוצר.","3":"רשימת פיצ׳רים בלי הקשר לא אומרת ללקוחות למה הפיצ׳רים חשובים להם; הספר מתחיל מהחלופות."},"2":{"0":"ראש בראש היא בחירה מכוונת להילחם על קריטריונים קיימים; כאן איש לא בחר, המסגרת הישנה פשוט נשארה.","2":"תת-פלח נבחר בכוונה; המסגרת הזו לא נבחרה מחדש אף פעם, גם אחרי שהמוצר והלקוחות השתנו.","3":"אין כאן שום מגמה; הבעיה היא המסגרת מ-2021 שנשארה גם כשנוספו Enterprise ו-Autopilot."},"3":{"0":"רשימת המפה היא מבט מבפנים; ייחוד מקבל משמעות רק מול מה שהלקוחות היו עושים בלעדיכם.","1":"הקטגוריה היא החוליה האחרונה בשרשרת; היא נגזרת מהחלופות, מהיכולות ומהערך, לא קודמת להם.","2":"סיסמה היא מסר, שנגזר מהמיצוב; התחלה ממנה מדלגת על כל השרשרת."},"4":{"1":"השוואת פיצ׳ר מול פיצ׳ר עם Asana עונה על שאלה שהלקוחות האלה בכלל לא שואלים.","2":"גיליון הוא חלופה אמיתית גם כשהוא חינמי; הספר סופר את מה שהלקוחות היו עושים בפועל.","3":"ייבוא הוא רעיון לפיצ׳ר, לא תשובה על ייחוד; היתרון מוגדר מול הגיליון והשיחה."},"5":{"0":"לוגו בלי שימוש לא מוכיח ערך; הספר בונה סביב הלקוחות שמפיקים מהמוצר הכי הרבה.","1":"הרבה לידים הם כמות, לא סימן שהערך בוער שם; שימוש כבד ושימור הם הסימן.","3":"ממוצע מטשטש בדיוק את מה שמבדל את המוצר; היעד הוא מי שהערך הכי חשוב לו."},"6":{"0":"ראש בראש פירושו לשחק לפי הכללים של מי שהגדיר את הקטגוריה, והקריטריונים האלה לא לטובת Velox.","2":"קטגוריה חדשה דורשת שנים של חינוך שוק ותקציב, הימור קשה ב-ARR של כ-$7M כשתת-פלח עובד.","3":"Velox מפסידה ל-Linear בחוויית מפתחים; השלב אומר להשאיר ל-Linear את המגרש שלו, לא להפוך לכלי מפתחים."},"7":{"0":"דומיין פנוי הוא פרט משני, שרלוונטי רק אחרי שברור שיצירת קטגוריה הגיונית בכלל.","1":"הטעם של אנליסטים הוא משני; קודם שואלים אם מסגרת קיימת כבר מבליטה את הערך.","2":"חשש מהעתקה הוא שאלה מאוחרת; השאלה הראשונה היא אם קטגוריה חדשה מוצדקת בכלל."},"8":{"1":"גודל העסקה חשוב להחלטה, אבל לא עונה מה המודול עושה למיצוב.","2":"גם עלות הבנייה חשובה, אבל היא לא אומרת אם Gantt כבד מושך את Velox למגרש של כלי PMO.","3":"העתקה של מה שיש ל-Monday ול-Asana מקרבת את Velox לחלופה במקום לחדד את הייחוד שלה."},"9":{"0":"זה הופך את הסדר: סיסמה שקובעת את המיצוב מובילה לכך שכל ערוץ מספר סיפור אחר.","1":"כשמצגת ממציאה מיצוב משלה, כל איש מכירות מספר סיפור אחר; המצגת נגזרת מהמסרים.","3":"בדיקת A/B יכולה לבחור בין ניסוחים, אבל לא להחליף את ההחלטה על ההקשר."},"10":{"0":"תיבת צ׳אט ריקה מלמדת את הלקוחות לראות ב-Velox צ׳אטבוט, בדיוק המסגרת שהמיצוב התרחק ממנה.","2":"חלונית לא מתקנת חוויה שמספרת סיפור אחר; המסכים עצמם צריכים להוביל לערך.","3":"מיצוב הוא החלטה של המוצר כולו, והמסכים הראשונים הם המקום שבו לקוחות פוגשים אותו; אי אפשר להעביר את זה הלאה."},"11":{"0":"תרגום מילולי מתעלם מכך שבארה״ב משווים את Velox לדברים אחרים, כמו Asana ו-Copilot.","1":"מיצוב נפרד לגמרי לכל שוק מפצל את המוצר ואת המסרים; הבסיס נשאר אחד.","2":"קונים בארה״ב צריכים הוכחות שמתאימות להם, כמו לקוח אמריקאי כרפרנס."},"12":{"1":"מגמה שהופכת לקטגוריה מפסיקה לבדל, כי כולם נתלים בה.","2":"מגמה בכל מסר כבר אינה תבלין; מוחקים את המילה, ואם לא נשאר כלום, היא עשתה את כל העבודה.","3":"מגמה עדיין יכולה להסביר למה עכשיו, כל עוד היא קשורה לערך; הסיכון הוא להישען עליה, לא להשתמש בה."},"13":{"0":"בחינה בכל ספרינט היא כמו לא לבחור אף פעם; מיצוב שמשתנה כל הזמן שווה למיצוב שאין.","1":"מיתוג מחדש עוסק במראה; המיצוב חוזר לשולחן כשהמוצר, הקהל או ההשוואות משתנים.","3":"הקפאה לתמיד מובילה ישר למלכודת מיצוב ברירת המחדל, שאליה Velox נפלה."},"14":{"0":"המתנה לאלף לקוחות משאירה את המוצר במיצוב ברירת מחדל; השערה אפשר לבדוק הרבה קודם.","2":"המיצוב של Velox נבנה מהלקוחות המתאימים של Velox; למוצר חדש יש חלופות משלו שצריך לגלות.","3":"סדנה רק עם ההנהלה היא תיאטרון הסכמה שהביקורת מזהירה ממנו; היא צריכה ראיות מלקוחות."}},"131":{"0":{"1":"Minivation היא הצעה צנועה וזולה מדי; כאן ההצעה עמוסה ויקרה, הבעיה ההפוכה.","2":"Hidden Gem בכלל לא מגיע לשוק; המודול הזה הושק, ונתקע אצל הלקוחות.","3":"Undead פירושו שאין צורך בכלל; כאן יש צורך, אבל הוא קבור תחת עומס יכולות ומחיר."},"1":{"0":"מעט מדי יכולות יכול להזיק, אבל לא מסביר Feature Shock, שבו יש יותר מדי.","1":"הערכות אופטימיות משפיעות על לוח הזמנים, לא על התמחור; השורש המשותף הוא שאלת מחיר שנשאלת מאוחר מדי.","3":"שיווק חלש לא מסביר למה מוצר טוב מתומחר נמוך מדי, כמו ב-Minivation."},"2":{"0":"שאלת מחיר ישירה בפתיחה מזמינה ניחוש מנומס, לא עובדה; הטווח נשאל רק בסוף.","2":"עמוד מחירים מוכן הופך את השיחה לתגובה לרעיון שלכם, במקום עובדות על הכאב שלהם.","3":"השארת המחיר לאחרי ההשקה היא בדיוק הטעות שהספר מזהיר ממנה; אז כבר אי אפשר לשנות את המוצר."},"3":{"0":"עוד מדרגות גודל הן עדיין תיאור חיצוני; שתי חברות באותו גודל יכולות לקנות מסיבות הפוכות.","1":"גם תעשייה היא תיאור חיצוני; הספר מפלח קודם לפי צורך וערך, ורק אחר כך בודק את הפרופיל.","2":"ויתור על פילוח מחזיר להצעה אחת שלא מתאימה לאף אחד, וכל פלח משלם על מה שלא צריך."},"4":{"1":"יכולת שמרתיעה קונים יכולה להוריד את מה שישלמו על כל החבילה; במדרגה העליונה היא פוגעת דווקא בה.","2":"תוסף מתאים ליכולת שמעטים מעריכים מאוד, לא ליכולת שמעטים רוצים וחלק אף דוחים.","3":"בכל החבילות, יכולת מרתיעה מורידה את הנכונות לשלם בכולן, במקום להעלות את הערך."},"5":{"0":"קוני Plus מדרגים אותו נמוך, ולכן הוא מייקר להם את המדרגה על משהו שלא רוצים: Feature Shock בקטן.","1":"בכל החבילות הוא ניתן לרבים שלא צריכים אותו, בזמן שהמיעוט היה משלם עליו: זו Minivation.","3":"המתנה לכל הפלחים מתעלמת מהמיעוט שכבר מעריך אותו מאוד ומוכן לשלם עליו עכשיו."},"6":{"0":"חיוב על כל 1,200 המשתמשים מכפיל פי ארבעה את החשבון על אותו ערך, וצפוי להיתקע ברכש.","2":"סכום קבוע לא גדל עם הלקוח, אף שהערך גדל עם כל אדם שנכנס לתוכנית.","3":"חיוב רק על תרחישי AI מתעלם מהמקום שבו נמצא רוב הערך: התכנון של האנשים עצמם."},"7":{"0":"פלח קטן שמעריך מאוד, עם מתחרים רחוקים, מתאים ל-Skimming: מתחילים גבוה ויורדים בהדרגה.","1":"המחיר שממקסם הכנסה לפי נתוני WTP הוא אסטרטגיית Maximize, ברירת המחדל, לא חדירה.","2":"לקוחות ראשונים שמוכנים לשלם יותר מצביעים על Skimming; חדירה מוותרת בכוונה על השוליים האלה."},"8":{"0":"עיגון לגיטימי רק עם אפשרויות אמיתיות; מדרגה שאי אפשר לקנות ומגבלות מוסתרות הן הטעיה.","2":"אין צורך לוותר על כל מסגור: הצגה ברורה של אפשרויות אמיתיות היא חלק מעבודה טובה.","3":"מגבלות מוסתרות פוגעות באמון כשהלקוח מגלה אותן בחשבונית; מה שלא מוכנים להסביר ללקוח, לא עושים."},"9":{"1":"מחיר אפס בעסקאות הראשונות הופך למחיר השוק של התוסף, וקשה מאוד להעלות אותו אחר כך.","2":"שמירה על המחיר אינה ״אף פעם״: חריגה מתוכננת ומוגבלת בזמן תמורת התחייבות מגינה על המחיר ועל העסקה.","3":"החלטה של כל איש מכירות לבד היא בדיוק מה שמפזר את המחירים, והמחיר השחוק הופך למחיר האמיתי."},"10":{"0":"תרחישים ללא הגבלה חושפים את שולי הרווח, בדיוק כמו השימוש הכבד ב-Autopilot בשלב הדירקטוריון.","1":"העלאת מחיר לכולם מעמיסה את העלות של מעטים כבדים על הרבים.","2":"המתנה לדירקטוריון פירושה לגלות את בעיית השוליים אחרי שכבר פגעה; שואלים מראש על המשתמש הכבד."},"11":{"0":"נכונות לשלם שנאמרה היא נקודת פתיחה, לא קנייה; בשאלה היפותטית אנשים נוטים להגזים.","1":"״נשמע הוגן״ לא מוכיח שהמחיר נמוך; זו השערה לבדיקה, לא סיבה לשנות מיד.","3":"גם לזרוק את זה טעות: השיחות מצמצמות את הטווח שבודקים אחר כך בהתנהגות."},"12":{"1":"Conjoint לא תמיד מעריך ביתר; הסיכון הזה עולה כשהמתחרים חסרים בסימולציה.","2":"השלב לא מעלה סיכון של דליפה; הביקורת עוסקת בסדר: קודם להוכיח שמישהו צריך, ואז ללטש מחיר.","3":"תקציב השיווק אינו העניין; מחקר מחיר מתוחכם פשוט לא עונה אם צריכים את המוצר."},"13":{"0":"שיעור צירוף שהצוות ״מקווה לו״ הוא ניחוש מלמעלה, לא נתוני לקוחות, והוא מסתיר איזו הנחה חלשה.","2":"עלות ועוד רווח מתעלמת מהערך: היא אומרת מה עלה לבנות, לא כמה כל פלח ישלם.","3":"המחיר של מתחרה מתעלם מהפלחים שלכם ומהנכונות שלהם לשלם, ומניח שכל לקוח יקנה."},"14":{"0":"התלהבות מנומסת אינה נתון, ובשיחות עם קונים בארה״ב היא נפוצה; ליד צריך עובדות על הוצאה ותקציב.","1":"סקר רק יחזור על אותה דעה במספרים; עובדות על הוצאה בעבר הן מה שעוזר.","3":"הנחה מיידית מוותרת על המחיר עוד לפני שיש עסקה, ונשענת על התלהבות שעוד אינה אות קנייה."}},"132":{"0":{"0":"הוספה לבקלוג עונה על הבקשה כמו שנוסחה, עוד לפני שמישהו הבין את הבעיה שמאחוריה.","2":"סירוב מיידי מדלג גם הוא על הצורך; לעיתים קרובות דוח קיים כבר פותר את מה שהלקוח מחפש.","3":"הערכת זמן מתמחרת פתרון שאיש עוד לא בדק; קודם שואלים מה הלקוח עושה עם הקובץ."},"1":{"0":"אורך הפגישות אינו הסיבה; טריקים נכשלים כי הצד השני יכול לבדוק כמעט כל טענה לבד.","1":"זה נכון גם ללקוחות ותיקים ולעמיתים; טריק שנחשף עולה באמון מול כל מי שיכול לבדוק.","2":"אין כאן איסור רשמי; פשוט ייפוי האמת כבר לא משתלם כשהקונה יכול לבדוק."},"2":{"1":"״אף פעם״ הוא הסבר קבוע ואישי; הוא לא משאיר מה לתקן, ולכן קשה לחזור עם הצעה.","2":"האשמה עצמית הופכת את ה״לא״ לקבוע ואישי; סיבה זמנית ומסוימת מצביעה על מה שאפשר לשנות.","3":"השלב מציין ש״הם לא מבינים מוצר״ אינו אחת האפשרויות; עקיפת ההנהלה שורפת אמון לפעם הבאה."},"3":{"0":"רשימת יכולות בלי קשר ל-Burn ול-Runway נשמעת כמו בקשה כללית לכסף.","1":"ציטוט יכול לעזור בהמשך, אבל הוא לא מדבר אל מה שבאחריות ענבל: Burn, Runway ותשואה.","3":"השוואת מחירים למתחרים לא עונה על מה שחשוב ל-CFO כאן: העלות והסיכון של הניסוי."},"4":{"0":"חזרה על הפתרון שלה עד שישתכנע היא ״כן, אבל״; היא סוגרת את השיחה במקום לבנות על הרעיון שלו.","1":"ויתור מלא נראה נדיב, אבל מאבד את האחיזה בבעיה שהפתרון צריך לפתור.","3":"העברה לשרון סוגרת את השיחה; ״כן, ו...״ משאיר אותה פתוחה בין מיכל לרונן."},"5":{"1":"קל לזכור לא הופך את זה לנכון; כשקונים יכולים לבדוק, טענה שלא נמדדה מסכנת אמון.","2":"כוכבית קטנה לא הופכת טענה בלי ביסוס לטענה כנה, וזה אף עלול להיות בעיה משפטית.","3":"ה-PM הוא מי שמביא את ההוכחה, ולכן טענה שלא נמדדה היא בדיוק התחום שלה."},"6":{"0":"הממצא בא בעיקר ממחקר שדה אחד על נציגי מוקד טלפוני; לקרוא לו חוק זה למתוח אותו רחוק מדי.","1":"מדיניות גיוס שנשענת על מחקר צר אחד מותחת את הממצא הרבה מעבר למה שהוא מראה.","2":"עצה לשנות אישיות לפני פגישות חורגת בהרבה ממחקר אחד על נציגי מוקד טלפוני."},"7":{"0":"סגירה בכל מחיר יוצרת התנגדות; פיץ׳ טוב פותח את השיחה הבאה, לא סוגר אותה.","2":"הצגת הכול מראש היא בדיוק המצגת של 20 שקפים שענתה על הכול חוץ מהשאלה החשובה.","3":"תשובה מוכנה לכל התנגדות נשמעת כמו נאום, לא כמו שיחה על המצב שלהם."},"8":{"1":"התחייבות מהירה נראית כמו עזרה לגיא, אבל מסכנת את מפת הדרכים ואת האמון בחידוש.","2":"סירוב מיידי מוותר על העסקה בלי לבדוק; ייתכן שהלקוח צריך משהו קטן יותר שכבר קיים.","3":"הערכה מתמחרת את הבקשה כפי שנוסחה; קודם מבררים מה Corvane צריכה, ואולי זה כבר קיים."},"9":{"0":"עיצוב מחדש של הכול הוא תשובה גדולה לשאלה שאיש עוד לא שאל; קודם מוצאים את הרגע והמסך המדויקים.","1":"לקוח שעזב הוא מידע, לא רעש; כדאי למצוא את הרגע המדויק שבו זה הסתבך.","3":"הנחה מטפלת בסימפטום ולא בסיבה; המוצר נשאר מסובך בדיוק כמו קודם."},"10":{"0":"מכירת רישיונות ישירה שייכת בעיקר למכירות; המכירה היומיומית של PM לא כוללת קנייה בכלל.","2":"משא ומתן על מחירים מול רכש הוא בעיקר עבודת המכירות, לא השכנוע היומיומי של ה-PM.","3":"חומרי שיווק שייכים ל-PMM; ה-PM מביא את ההוכחות, אבל זה לא רוב המכירה של היום."},"11":{"0":"דני כבר אישר; אישור נחוץ, אבל הוא לא מחליף את האמונה של מי שבונה.","1":"גיא אינו החסם; הפרויקט יאט אם אורי, שבונה אותו, לא שותף לו.","2":"החלטת הנהלה בלי אמונה של הצוות הופכת לפרויקט שמתקדם לאט ובשקט."},"12":{"1":"בחירה מטעה של נתונים נכונים עדיין פוגעת באמון, והלקוחות כנראה ימצאו את ההשוואה בעצמם.","2":"לקוחות לא יכולים לבקש נתון שהם לא יודעים שקיים; הסתרת מה שנדרש להחלטה היא מניפולציה.","3":"הגבול כאן נוגע לאמון, לא רק לחוק: אישור משפטי לא הופך בחירה מטעה לכנה."},"13":{"0":"הסכמה מאשרת את ההסבר הקבוע והאישי שלו, מהסוג שגורם לאנשים להפסיק לנסות.","1":"התעלמות מההפסד לא מלמדת דבר; תחקיר הופך אותו למשהו זמני ומסוים שאפשר לתקן.","2":"עוד מצגת לא מטפלת במה שחסר בעסקה המסוימת הזו, ומשאירה את ״אני לא טוב״ שלו על כנו."},"14":{"0":"עוד שקפים של יכולות לא עונים על החשש של ההנהלה, שהוא גודל הסיכון.","1":"בקשה גדולה יותר מגדילה את הסיכון של מי שמאשר; בקשה קטנה עם תנאי עצירה מזיזה יותר.","3":"פנייה מעל ראש ההנהלה פוגעת בדיוק באמון שנחוץ ל״כן״ הבא."}},"133":{"0":{"0":"שום דבר לא מצביע על דמו ארוך מדי; הלקוח אהב אותו, פשוט לא למד ממנו שום דבר חדש על העסק שלו.","1":"המחיר לא עלה בכלל; הלקוח אהב את הדמו, ועדיין לא קיבל סיבה חדשה לפעול עכשיו.","3":"בעסקה מורכבת הקשר האישי הוא דמי כניסה, לא סיבה לקנות; הלקוח נהנה ועדיין מחכה."},"1":{"1":"מקור חיצוני מוכר לא מספיק אם הוא מוביל באותה מידה לכל ספק; אז זה שיווק חינם למתחרים.","2":"תובנה שנועדה רק להפחיד היא כבר טענה מטעה, וחוצה קו אתי ומשפטי.","3":"תיאור יכולות מסביר את המוצר; תובנה מלמדת את הלקוח משהו חדש על העסק שלו."},"2":{"0":"ניסוח דרמטי לא מוסיף הוכחה; תובנה שלא עומדת בבדיקה של ה-CFO או של המחלקה המשפטית שורפת אמון.","2":"הפצה מהירה נראית יעילה, אבל שליחת תובנה שלא נבדקה לכל אנשי המכירות מכפילה את הסיכון.","3":"הערכה עגולה מחליפה נתון שאפשר להוכיח בניחוש; התובנה צריכה מקור שאפשר להציג."},"3":{"0":"שקף אחד לכולם מוותר על התאמה: כל תפקיד שואל על משהו אחר, עיכובים, עלות או סיכון.","1":"גם מנהלת התפעול וראש ה-IT משפיעים על ההחלטה; התעלמות מהם משאירה את העסקה חשופה.","2":"התאמה משנה דגש, לא עובדות; ברגע שהקהלים משווים ביניהם, האמינות נעלמת."},"4":{"0":"הסכמה שומרת על האווירה רק עד שההבטחה נשברת, ואז ה-CS פוגש את האכזבה.","1":"סירוב בלי הסבר נוטש את השיחה במקום להוביל אותה לדרך קדימה.","2":"הבטחה בעל פה היא עדיין הבטחה לתאריך שלא במפת הדרכים המאושרת; PM לא נותן הבטחות כאלה."},"5":{"0":"הובלה משרתת את ההחלטה של הלקוח; לחץ משרת את הרבעון של המוכר, וזה כל ההבדל.","2":"מועד אחרון קשיח נראה כמו שליטה, אבל משרת את הרבעון של המוכר, לא את הלקוח.","3":"הובלה אינה עניין של זמן דיבור; ריאן הוביל בשאלה אחת ונתן ללקוח לחשוב."},"6":{"1":"הקשרים של ריאן כבר חזקים; קשר אישי הוא דמי כניסה, לא תשובה ל״למה עכשיו״.","2":"הנחה נותנת סיבה שנקנתה בכסף; היא שוחקת את המחיר ולא משנה את ההבנה של הבעיה.","3":"מצגת פיצ׳רים מסבירה את המוצר, לא את מחיר ההמתנה עבור הלקוח, וזה מה ש״למה עכשיו״ צריך."},"7":{"0":"נתונים גולמיים נשמעים יסודיים, אבל בלי פרשנות הם לא יגיעו לשיחת המכירה.","1":"סרטון ארוך של כל המסכים מסביר את המוצר, לא את התובנה, ההוכחה שלה או הגבולות שלה.","3":"סיסמה אחת שחוזרים עליה מילה במילה מוותרת על ההתאמה לכל תפקיד בקבוצת הקנייה."},"8":{"0":"הסכמה בלי שאלות פירושה בדרך כלל שלא נאמר דבר חדש, ההפך ממסגור מחדש.","2":"המבחן משווה את ה״לפני״ וה״אחרי״ של הלקוח, לא איך אתם נשמעים ליד המתחרים.","3":"מספר שקפים הוא עניין של פורמט; המבחן שואל אם הלקוח רואה עכשיו את הבעיה אחרת."},"9":{"0":"האורך אינו הבעיה; נתון בלי מקור עלול להטעות, לא משנה כמה הוא קצר.","1":"בקמפיין או בשיחה, הבעיה זהה: טענה בלי מקור שאפשר להוכיח היא סיכון משפטי וסיכון לאמון.","2":"המקום בשיחה אינו העניין; העניין הוא האמת שמאחורי הנתון, ובלי מקור אי אפשר להוכיח אותה."},"10":{"0":"הגישה נבנתה לעסקאות מורכבות עם כמה מקבלי החלטות, לא לשדרוג עצמי דרך האתר.","1":"בשדרוג עצמי, עמוד מחירים ברור ו-Onboarding טוב הם השיחה; אין צורך בשיחה מלמדת.","3":"״לא שווים את המאמץ״ מפספס את העיקר: הלקוחות חשובים, פשוט הכלי לא מתאים למכירה הזו."},"11":{"1":"להאשים את הלקוחות שלא הבינו מתעלם מהמקור: שיחת המכירה ציירה מוצר גדול יותר.","2":"הטלת האחריות על ה-Onboarding מטפלת בסימפטום; כל תובנה שנמכרה היא הבטחה שה-CS פוגש אחרי החתימה.","3":"התאמה אינה הבעיה שתוארה; הם ציפו ליותר ממה ש-Autopilot עושה, כי זה מה שנמכר להם."},"12":{"0":"המחקר עסק באנשי מכירות בעסקאות מורכבות, לא בחברות קטנות; המגבלה שלו היא מתאם, לא סוג המדגם.","2":"השלב לא אומר דבר על שיחות טלפון בלבד; המגבלה היא שסקרים ודירוגי מנהלים מראים מתאם בלבד.","3":"הספר עוסק דווקא בעסקאות מורכבות, לא במוצרי צריכה; החולשה שלו היא שהוא מראה מתאם, לא סיבה."},"13":{"1":"סגירת עסקאות היא תפקיד ה-AE, שאחראי על הלקוח ועל התחזית; ה-PM מביא ידע.","2":"מה שלא במפת הדרכים המאושרת לא נכנס לשיחה כהבטחה; זו לא הסיבה שה-PM שם.","3":"עמלה רק תעוות את שיקול הדעת של ה-PM; הערך הוא ידע שזורם לשני הכיוונים."},"14":{"0":"התלהבות של איש קשר אחד לא מספיקה כששבעה אנשים קונים; הוא צריך תובנה מותאמת שיוכל להציג לבד.","1":"קפיצה להנהלה נשמעת כמו קיצור דרך, אבל משאירה את שאר קבוצת הקנייה בחוץ.","2":"המתנה להסכמה מוותרת על השיחה; איש הקשר צריך כלים כדי לבנות את ההסכמה מבפנים."}},"134":{"0":{"0":"שורה בעמוד הבית עוזרת, אבל בלי מי שאחראי על הסיפור גם ההשקה הבאה תתפספס.","1":"היכולת כבר קיימת; הפער הוא שאף אחד לא סיפר לשוק, ויכולת חדשה תיפול לאותו פער.","2":"הבעיה אינה מי מריץ את הדמו; אף איש מכירות לא הודרך, וההשקה הסתכמה בפסקה אחת בניוזלטר."},"1":{"0":"זה מתאר את Product-Market Fit הרגיל; Market-Product Fit הופך את הכיוון ושואל אם השוק יכול לקנות עכשיו.","2":"מחירי המתחרים הם שאלה אחרת; ההתאמה הזו עוסקת בתקציב, בהרגלים ובתהליך הקנייה.","3":"בנייה בזמן היא המוכנות של הצוות; המושג בוחן את המוכנות של השוק לקלוט את המוצר."},"2":{"0":"מחיר נמוך יותר לא מקצר תהליך אישור שהבנק קבע לעצמו; המחיר לא היה הבעיה.","1":"ויתור על מגזר שלם בגלל תהליך מוותר על לקוחות שאהבו את המוצר; עדיף לתכנן לפי לוח הזמנים של הקנייה.","3":"יכולות אבטחה נוספות עשויות לעזור בהמשך, אבל לא יקצרו את תהליך האישור שהבנק קבע לעצמו."},"3":{"1":"השקה גדולה עכשיו עושה רעש מול לקוחות שהתקציב שלהם כבר נסגר, ושעדיין לא יכולים לקנות.","2":"דחייה מלאה בשקט מבזבזת חודשיים של למידה והוכחות מלקוחות קיימים.","3":"הלקוחות הרלוונטיים הם PMO בארה״ב; השקה בישראל לא פותרת את התקציב הסגור שלהם."},"4":{"1":"עיתונות והרצאות בכנסים אינן תפקיד השגריר; השגריר מביא את קול השוק אל תוך ההחלטות.","2":"בחירת העמדה בשוק היא הכובע של האסטרטג; השגריר מזין אותו בתובנות מעסקאות שנסגרו ושאבדו.","3":"גיוס לקוחות שיספרו על המוצר הוא הכובע של האוונגליסט; השגריר מקשיב ומעביר פנימה."},"5":{"0":"תיקון האתר בלבד מטפל בסימפטום הזה; נקודות מגע אחרות עלולות לשאת פער דומה.","1":"כשהאתר והמוצר מספרים סיפורים שונים, לקוחות מאמינים לגרוע מהשניים, גם בלי לספור לחיצות.","3":"בקשה מהתמיכה להסביר משאירה את ההבטחה השבורה במקומה; צריך לסגור את הפער עצמו."},"6":{"0":"רשימת יכולות מתוכננות הופכת כל תוכנית להבטחה שקשה לעמוד בה.","2":"כל הנתונים הטכניים לא אומרים לריאן איפה עובר הגבול; ״מה לא מבטיחים״ הוא החלק החסר.","3":"יכולת בפיתוח עלולה להשתנות או להתעכב; הבטחה עליה מסכנת את אמון הלקוח ואת מפת הדרכים."},"7":{"0":"ציטוט שנכתב בשמם לפני שאישרו עלול לפגוע באמון ואף להפר את החוזה.","1":"פוסט בלי תיאום תוכן מדלג על ההסכמה ועל האישור המשפטי למה שמותר לפרסם.","2":"להיות לקוח אינו הסכמה; לוגו שמוצג בלי אישור עלול לפגוע באמון ולהפר את החוזה."},"8":{"0":"דרגת ההשקה היא החלטה של ה-PMM; מיכל מספקת את אמת המוצר שעליה היא נבנית.","1":"המסרים שייכים ל-PMM, ונבנים על החומר של ה-PM על הבעיה וההוכחות.","3":"הדרכת המכירות נמצאת בצד של ה-PMM בחוזה; ה-PM מספק את העובדות שמאחוריה."},"9":{"1":"צוות השיווק בדרך כלל לא כותב את מסכי המוצר; בדיוק לכן המסך הראשון הוא נקודת מגע שנשכחת.","2":"זה לא המקום היחיד; לקוחות מרכיבים את התמונה גם מהאתר, מהדמו, מעמוד המחירים ומהמיילים.","3":"עיצוב לא מחליף מסרים; המסך הראשון חשוב כי הוא עוד נקודת מגע שמספרת את הסיפור."},"10":{"0":"המתנה לגיוס מעכבת את הלמידה, ובינתיים השוק ממלא את הסיפור בעצמו.","1":"העברת הכול למכירות משאירה את הסיפור אצל מי שנמדד על סגירת עסקאות, לא על המוצר.","2":"איכות פותחת את הדלת אבל לא מסבירה לאן היא מובילה; מוצר חזק מפסיד למוצר שהשוק מבין."},"11":{"0":"יכולת דומה כבר קיימת; לבנות אותה מחדש זו הדרך היקרה ביותר לפתור אי-הבנה.","2":"ניסיון אנשי המכירות אינו הבעיה שתוארה; לקוחות מבקשים את מה שקיים כי לא סיפרו להם שהוא קיים.","3":"אין סימן לבעיית התאמה; הם ביקשו משהו שכבר יש ב-Velox, וזה מצביע על הסיפור."},"12":{"0":"החגים בישראל חשובים לצוות, אבל הם קובעים מתי אתם מוכנים, לא מתי הלקוחות בארה״ב יכולים לקנות.","1":"סוף הספרינט הוא תאריך מוכנות, לא תאריך השקה; לוח השנה של השוק קודם לו.","3":"תאריך של כנס גדול לא אומר דבר על כך שהתקציבים והחידושים של הלקוחות מאפשרים לקנות אז."},"13":{"0":"צוותים מתחילים ב״מה״ כי זה מה שבנו, ואז מגלים שהשיקו בדיוק כשאיש לא יכול היה לקנות.","2":"״למה״ היא השאלה השנייה; היא באה אחרי ״מתי הלקוחות מוכנים לקנות בכלל״.","3":"התחלה ב״איך״ מדלגת גם על ״מתי״ וגם על ״למה״; ההשקה מתחילה מלוח השנה של הלקוח."},"14":{"1":"הספר מניח PMM ייעודי; עם PMM אחד לכמה קווים אי אפשר להפעיל אותו בדיוק כמו שהוא כתוב.","2":"הרעיונות עובדים גם בחברה קטנה; ויתור עליהם מוותר על הכלים שחברה קטנה צריכה יותר מכול.","3":"Velox מוכרת ל-B2B, וכל השלב מראה שיווק מוצר בפעולה שם, מערכת המכירות ועד העסקה עם הבנק."}},"135":{"0":{"1":"הפתיחה הזו מתחילה בגאווה של Velox, כך שהלקוח פוגש קודם את החברה ולא את הבעיה שלו.","2":"ארכיטקטורה מעמידה את הטכנולוגיה במרכז; הקורא צריך לעזוב את הבעיה שלו כדי לעקוב.","3":"חצי שנה של עבודת צוות היא הסיפור של Velox; הלקוח אמור להיות הגיבור, והפתיחה הזו משאירה אותו בחוץ."},"1":{"0":"האורך אינו הבעיה, אלה שתי מילים בלבד; הבעיה היא שהיא לא אומרת מה הלקוח מקבל.","1":"שם המוצר אינו הבעיה; כותרת צריכה לומר מה הלקוח מקבל, וזו לא אומרת.","3":"אין חובה להזכיר מתחרים; הבעיה היא כותרת שאפשר להדביק על כל מוצר, כי היא לא אומרת דבר מסוים."},"2":{"0":"רשימת יכולות מלאה מוסיפה עומס בדיוק כשהלקוח צריך צעד הבא אחד.","1":"שני כפתורים שווים מקשים על הבחירה; בפועל, שני כפתורים שווים הם אפס כפתורים.","2":"״אין עדיין פרויקטים״ נכון אבל לא מועיל: הוא משאיר את הלקוח בלי צעד הבא."},"3":{"0":"איום בלי מקור מטעה ופוגע באמון; הצגת מחיר אמיתי היא כנות, ניפוח פחד אינו.","2":"מחיקת כל סיכון משאירה סיפור בלי סיבה לפעול; הלקוח צריך לראות מה עומד על הכף.","3":"העברת השורה לא מתקנת את העובדה שאין לה בסיס; היא נשארת איום מטעה."},"4":{"0":"כשהמוצר הוא הגיבור, הלקוח הופך לניצב בסיפור של מישהו אחר ומאבד עניין.","2":"מדריך אינו ניטרלי: הוא מראה אמפתיה לבעיה וסמכות לעזור, לא רק עובדות.","3":"המכשול הוא הבעיה של הלקוח, כמו משימה תקועה; המוצר הוא מה שעוזר לו לעבור אותה."},"5":{"0":"ההגדרות חשובות למי שכבר השתכנע; פתיחה שם מאבדת את הלקוח לפני שהסיפור התחיל.","1":"רשימת לקוחות היא הוכחה שעובדת טוב יותר אחרי שהבעיה ברורה, לא בפתיחה.","2":"איך המודל עובד חשוב למי שכבר השתכנע; זה מעמיד את הטכנולוגיה במרכז, לא את הלקוח."},"6":{"0":"אישור המנכ״ל לא הופך אותו לברור; המבחן הוא אם אנשים יכולים לחזור עליו בשיחות.","1":"משפט שמכיל את כל היכולות כבר אינו משפט אחד, ואיש לא יוכל לחזור עליו.","3":"מקוריות אינה המטרה; המשפט שעובד נשמע לעיתים קצת משעמם למי שכתב אותו."},"7":{"1":"הכשרה יכולה לעזור, אבל השורש הוא ידיעה עמוקה מדי: כבר לא רואים את המוצר בעיניים של פעם ראשונה.","2":"בית המסרים לא פותר את זה; בלי בדיקה מול אנשים חדשים, ידע עמוק עדיין מסתיר את הבסיס.","3":"עוד זמן עוזר, אבל הבעיה נשארת: מי שמכיר כל פינה מדלג על ההסבר הבסיסי."},"8":{"0":"סרטון ארוך בהתחלה דוחה את הרגע שבו הלקוח רואה ערך לראשונה.","1":"סיור קצר יותר עדיין מסביר את המוצר, במקום להוביל לתוצאה.","2":"שליחת הסיור במייל אחר כך משאירה אותו סיור, רק מאוחר יותר; עדיין אין דרך קצרה לערך."},"9":{"0":"הארכיטקטורה שייכת לנספח; בלי הבעיה קודם, היא פירוט בלי סיבה מאחוריו.","2":"רשימת פיצ׳רים מדלגת על למה זה חשוב; ההנהלה קוראת כמו לקוח עסוק ומחליטה בשתי דקות.","3":"לוח זמנים מפורט הוא התוכנית; הוא בא אחרי הבעיה ומה שעומד על הכף, לא לפניהם."},"10":{"1":"המסר לראשי הצוותים עובד, ולכן לא כותבים אותו מחדש; מוסיפים סיפור שמתאים למנהלת ה-IT.","2":"הורדת מחיר לא עונה על הבעיה והחששות של מנהלת ה-IT; היא צריכה סיפור והוכחות משלה.","3":"כל תפקיד בקבוצת הקנייה רוצה סיפור משלו; מנהלת ה-IT פשוט צריכה סיפור אחר."},"11":{"0":"חזרה לרשימת פיצ׳רים מוותרת על הבהירות; הבעיה היא הדמיון, לא הגישה עצמה.","1":"העתקת המוביל רק מגדילה את הדמיון, שהוא כבר הבעיה; מיצוב הוא מה שמבדל.","3":"שום דבר לא אומר שהתבנית מתאימה רק למוצרים זולים; העיקר הוא שבהירות לבד לא מבדלת."},"12":{"0":"ציטוט אנונימי מוסיף תחושה, אבל לא מראה מה השתנה בפועל.","1":"תמונת צוות מראה אנשים, לא את השינוי של לפני ואחרי שמדריך צריך כהוכחה.","2":"לוגו מוסיף תחושת אמינות, אבל לא מראה מה השתנה ובאיזה נתון."},"13":{"0":"שתי פעולות שוות מחייבות בחירה, ולעיתים קרובות הקורא לא בוחר בכלל.","1":"צבעים שונים לא פותרים את ההיסוס עצמו; פעולה ראשית אחת ולצידה אפשרות רכה וקטנה כן.","3":"כפתור שלישי רק מוסיף לבחירה; הפתרון הוא פעולה ראשית אחת, לא עוד אפשרויות."},"14":{"0":"תיאור טכני של ה-API משרת את המעטים שממשיכים לקרוא; הפתיחה היא השינוי עבור הלקוח.","2":"רשימת באגים שייכת ל-Changelog, שבא אחר כך; הפתיחה אומרת מה הלקוח יכול לעשות מהיום.","3":"תודה לצוות מעמידה את Velox במרכז; היא יכולה לבוא אחר כך, אם בכלל."}}}};
